window.PACK={"book":{"id":"risala-shafii","title":"الرسالة","type":"usulbook","ilm":"usul","author":"الإمام الشافعي (ت ٢٠٤هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"مكتبه الحلبي، مصر","optional":true,"packVersion":"eb2f7a05dce6"},"items":[{"id":"risala-shafii:1","bookId":"risala-shafii","type":"section","seq":1,"chapter":"مقدمة","title":"مقدمة","page":"ص0","text":"الرسالة\nللإمام المطلبي محمد بن ادريس الشافعي 150 - 204\nعن أصل بخط الربيع بن سلمان كتبه في حياة الشافعي\n((لما نظرت الرسالة للشافعي أذهلتني، لانني رأيت رجل عاقل فصيح ناصح، فإني لأكثر الدعاء له.))\nعبد الرحمن بن مهدي\nبتحقيق وشرح أحمد محمد شاكر\nهذا السفر القيم يضم بين دفتيه:"},{"id":"risala-shafii:2","bookId":"risala-shafii","type":"section","seq":2,"chapter":"مقدمة","title":"1- المقدمة","page":"ص0","text":"المقدمة"},{"id":"risala-shafii:3","bookId":"risala-shafii","type":"section","seq":3,"chapter":"مقدمة","title":"2- السماعات","page":"ص0","text":"السماعات"},{"id":"risala-shafii:4","bookId":"risala-shafii","type":"section","seq":4,"chapter":"مقدمة","title":"3- اللوحات المصورة","page":"ص0","text":"اللوحات المصورة"},{"id":"risala-shafii:5","bookId":"risala-shafii","type":"section","seq":5,"chapter":"مقدمة","title":"4- كتاب الرسالة مشروحا محققا","page":"ص0","text":"كتاب الرسالة مشروحا محققا:\nالجزء الاول ص 005 - 203\nالجزء الثاني 204 - 387\nالجزء الثالث 389 - 601"},{"id":"risala-shafii:6","bookId":"risala-shafii","type":"section","seq":6,"chapter":"مقدمة","title":"5- الاستدراك 603 - 608","page":"ص0","text":"الاستدراك 603 - 608"},{"id":"risala-shafii:7","bookId":"risala-shafii","type":"section","seq":7,"chapter":"مقدمة","title":"6- جريدة المراجع 609 - 610","page":"ص0","text":"جريدة المراجع 609 - 610"},{"id":"risala-shafii:8","bookId":"risala-shafii","type":"section","seq":8,"chapter":"مقدمة","title":"7- مفاتيح الكتاب","page":"ص0","text":"مفاتيح الكتاب:"},{"id":"risala-shafii:9","bookId":"risala-shafii","type":"section","seq":9,"chapter":"مقدمة","title":"1- فهرس الايات 612 - 620","page":"ص0","text":"فهرس الايات 612 - 620"},{"id":"risala-shafii:10","bookId":"risala-shafii","type":"section","seq":10,"chapter":"مقدمة","title":"2- فهرس الابواب 621 - 623","page":"ص0","text":"فهرس الابواب 621 - 623"},{"id":"risala-shafii:11","bookId":"risala-shafii","type":"section","seq":11,"chapter":"مقدمة","title":"3- فهرس الاعلام 624 - 646","page":"ص0","text":"فهرس الاعلام 624 - 646"},{"id":"risala-shafii:12","bookId":"risala-shafii","type":"section","seq":12,"chapter":"مقدمة","title":"4- فهرس الاماكن 647 - 648","page":"ص0","text":"فهرس الاماكن 647 - 648"},{"id":"risala-shafii:13","bookId":"risala-shafii","type":"section","seq":13,"chapter":"مقدمة","title":"5- فهرس الاشياء 649 - 654","page":"ص0","text":"فهرس الاشياء 649 - 654"},{"id":"risala-shafii:14","bookId":"risala-shafii","type":"section","seq":14,"chapter":"مقدمة","title":"6- فهرس المفردات 655 - 658","page":"ص0","text":"فهرس المفردات 655 - 658"},{"id":"risala-shafii:15","bookId":"risala-shafii","type":"section","seq":15,"chapter":"مقدمة","title":"7- فهرس الفوائد اللغوية 659 - 662","page":"ص0","text":"فهرس الفوائد اللغوية 659 - 662"},{"id":"risala-shafii:16","bookId":"risala-shafii","type":"section","seq":16,"chapter":"مقدمة","title":"8- الفهرس العلمي 663 - 670 — بسم الله الرحمن الرحيم الحمد لله رب العالمين","page":"ص0","text":"الفهرس العلمي 663 - 670\nبسم الله الرحمن الرحيم الحمد لله رب العالمين.\nوصلى الله على محمد وعلى آله وصحبه وسلم تسليما.\nهذا ال"},{"id":"risala-shafii:17","bookId":"risala-shafii","type":"section","seq":17,"chapter":"كتاب (الرسالة","title":"كتاب (الرسالة","page":"ص0","text":"للشافعي.\nوكفى الشافعي مدحا أنه الشافعي.\nوكفى (الرسالة) تقريظا أنها تأليف الشافعي.\nوكفاني فخرا أن أنشر بين الناس علم الشافعي.\n[مع إعلامهم نهيه عن تقليده وتقليد غيره] (1) .\nولو جاز لعالم أن يقلد عالما كان أولى الناس عندي أن يقلد -: الشافعي.\nفإني أعتقد - غير غال ولا مسرف - أن هذا الرجل لم يظهر مثله في علماء الاسلام، في فقه الكتاب والسنة، ونفوذ النظر فيهما ودقة الاستنباط.\nمع قوة العارضة، ونور البصيرة، والايداع في إقامة الحجة وإفحام مناظره.\nفصيح اللسان، ناصع البيان، في الذروة العليا من البلاغة.\nتأدب بأدب البادية، وأخذ العلوم والمعارف عن أهل الحضر، حتى سما عن كل عالم قبله وبعده.\nنبغ في الحجاز، وكان الى علمائه مرجع الرواية والسنة، وكانوا أساطين العلم في فقه القران،\nولم يكن الكثير منهم أهل لسن وجدل، وكادوا يعجزون عن مناظرة أهل الرأي، فجاء هذا الشاب يناظر وينافح، ويعرف كيف يقوم بحجته، وكيف يلزم أهل الرأي وجوب اتباع السنة، وكيف يثبت لهم الحجة في خبر الواحد، وكيف\nيفصل للناس طرق فهم الكتاب على ما عرف من بيان العرب وفصاحتهم، وكيف يدلهم على الناسخ والمنسوخ من الكتاب والسنة، وعلى الجمع بين ما ظاهره التعارض فيهما أو في أحدهما.\nحتى سماه أهل مكة \" ناصر الحديث \".\nوتواترت أخباره إلى علماء الاسلام في عصره، فكانوا يفدون إلى مكة للحج، يناظرونه ويأخذون عنه في حياة شيوخه، حتى إن أحمد بن حنبل جلس معه مرة، فجاء أحد إخوانه يعتب عليه أن ترك مجلس ابن عيينة - شيخ الشافعي -.\nويجلس إلى هذا الاعرابي! فقال له أحمد: \" اسكت، إنك إن فاتك حديث بعلو وجدته بنزول، وإن فاتك عقل هذا أخاف أن لا تجده، ما رأيت أحدا أفقه في كتاب الله من هذا الفتى \".\nوحتى يقول داود بن علي الظاهري الامام في كتاب مناقب الشافعي: \" قال لي إسحق بن راهويه: ذهبت أنا وأحمد بن حنبل الى الشافعي بمكة فسألته عن أشياء، فوجدته فصيحا حسن الادب، فلما فارقناه أعلمني جماعة من أهل الفهم بالقرآن أنه كان أعلم الناس في زمانه بمعاني القرآن، وأنه قد أوتي فيه فهما، فلو كنت عرفته للزمته.\nقال داود: ورأيته يتأسف على ما فاته منه \".\nوحتى يقول أحمد بن حنبل: \" لولا الشافعي ما عرفنا فقه الحديث \".\nويقول أيضا: \" كانت أقضيتنا في أيدي أصحاب أبي حنيفة ما تنزع، حتى رأينا الشافعي، فكان أفقه الناس في كتاب الله، وفي سنة رسول الله \".\nثم يدخل العراق، دار الخلافة وعاصمة الدولة (1) ، فيأخذ عن أهل\nالرأي علمهم ورأيهم، وينظر فيه، ويجادلهم ويحاجهم، ويزداد بذلك بصرا\nبالفقه ونصرا للسنة، حتى يقول أبو الوليد المكي الفقيه موسى بن أبي الجارود: \" كنا نتحدث نحن وأصحابنا من أهل مكة أن الشافعي أخذ كتب ابن جريح (1) عن أربعة أنفس: عن مسلم بن خالد، وسعيد بن سالم، وهذان فقيهان، وعن عبد المجيد بن عبد العزيز بن أبي رواد، وكان أعلمهم بابن جريح، وعن عبد الله بن الحرث المخزومي، وكان من الاثبات، وانتهت رياسة الفقه بالمدينة إلى مالك بن أنس، رحل إليه ولازمه وأخذ عنه، وانتهت رياسة الفقه بالعراق إلى أبي حنيفة، فأخذ عن صاحبه محمد بن الحسن جملا ليس فيها شئ إلا وقد سمعه عليه، فاجتمع له علم أهل الرأي وعلم أهل الحديث، فتصرف في ذلك، حتى أصل الاصول، وقعد القواعد، وأذعن له الموافق والمخالف، واشتهر أمره، وعلا ذكره، وارتفع قدره، حتى صار منه ما صار \".\nثم دخل مصر في سنة 199 فأقام بها إلى أن مات، يعلم الناس السنة وفقه السنة والكتاب، ويناظر مخالفيه ويحاجهم، وأكثرهم من أتباع شيخه مالك بن أنس، وكانوا متعصبين لمذهبه، فبهرهم الشافعي بعلمه وهديه وعقله، رأوا رجلا لم تر الاعين مثله، فلزموا مجلسه، يفيدون منه علم الكتاب وعلم الحديث، ويأخذون عنه اللغة والانساب والشعر، ويفيدهم في بعض وقته في الطب، ثم يتلعمون منه أدب الجدل والمناظرة، ويؤلف الكتب بخطه، فيقرؤن عليه ما ينسخونه منها، أو يملي عليهم بعضها إملاء، فرجع أكثرهم عما\nكانوا يتعصبون له، وتعلموا منه الاجتهاد ونبذ التقليد، فملا الشافعي طباق الارض علما.\nومات ودفن بمصر، وقبره معروف مشهور إلى الان.\nوعاش 54 سنة،\nولد سنة 150 بغزة، ومات ليلة الجمعة وذفن يوم الجمعة بعد العصر آخر يوم من رجب سنة 204 (1) (الجمعة 29 رجب سنة 204 يوافق 19 يناير سنة 820 ميلادية، 23 طوبة سنة 536 قبطية) .\nوليس الشافعي ممن يترجم له في أوراق أو كراريس، وقد ألف العلماء الائمة في سيرته كتبا كثيرة وافية، وجد بعضها وفقد أكثرها.\nولعلنا نوفق إلى أن نجمع ما تفرق من أخباره في الكتب والدواوين، في سيرة خاصة به، إن شاء الله.\nوقد يفهم بعض الناس من كلامي عن الشافعي أني أقول عن تقليد أو عصبية، لما نشأ عليه أكثر أهل العلم من قرون كثيرة، من تفرقهم شيعا وأحزابا علمية، مبنية على العصبية المذهبية، مما أضر بالمسلمين وأخرهم عن سائر الامم، وكان السبب الاكبر في زوال حكم الاسلام عن بلاد المسلمين، حتى صاروا يحكمون بقوانين تخالف دين الاسلام، خنعوا لها واستكانوا، في حين كان كثير من علمائهم يأبون الحكم بغير المذهب الذي يتعصبون له ويتعصب له الحكام في البلاد.\nومعاذ الله أن أرضى لنفسي خلة أنكرها على الناس، بل أبحث وأجد، وأتبع الدليل الصحيح حيثما وجد.\nوقد نشأت في طلب العلم وتفقهت على مذهب أبي حنيفة، ونلت شهادة العالمية من الازهر الشريف حنفيا، ووليت القضاء منذ عشرين سنة أحكم كما يحكم إخواني بما أذن لنا في الحكم به من مذهب الحنفية.\nولكني بجوار هذا بدأت دراسة السنة النبوية أثناء طلب العلم، من نحو ثلاثين سنة، فسمت كثيرا وقرأت كثيرا، ودرست\nأخبار العلماء والائمة، ونظرت في أقوالهم وأدلتهم، لم أتعصب لواحد منهم، ولم أحد عن سنن الحق فيما بدا لي، فان أخطأت فكما يخطئ الرجل، وإن أصبت فكما يصيب الرجال.\nأحترم رأيي ورأي غيري، وأحترم ما أعتقده حقا قبل كل شئ وفوق كل شئ.\nفعن هذا قلت ما قلت واعتقدت ما أعتقد في الشافعي، رحمه الله ورضى عنه."},{"id":"risala-shafii:18","bookId":"risala-shafii","type":"section","seq":18,"chapter":"كتاب الرسالة","title":"كتاب الرسالة","page":"ص0","text":"ألف الشافعي كتبا كثيرة، بعضها كتبه بنفسه وقرأه على الناس أو قرؤه عليه، وبعضها أملاه إملاء، وإحصاء هذه الكتب عسير، وقد فقد كثير منها.\nفألف في مكة، وألف في بغداد، وألف في مصر.\nوالذي في أيدي العلماء من كتبه الان ما ألفه في مصر، وهو كتاب (الام) الذي جمع فيه الربيع بعض كتب الشافعي، وسماه بهذا الاسم، بعد أن سمع منه هذه الكتب، وما فاته سماعه بين ذلك، وما وجده بخط الشافعي ولم يسمعه بينه أيضا، كما يعلم ذلك أهل العلم ممن يقرؤن كتاب (الام) .\nو (كتاب اختلاف الحديث) وقد طبع بمطبعة بولاق بحاشية الجزء السابع من الام.\nو (كتاب الرسالة) .\nوهما مما روى الربيع عن الشافعي منفصلين، ولم يدخلهما في كتاب (الام) .\nولمناسبة الكلام عن كتب الشافعي وكتاب الام خاصة، يجدر بنا أن نقول كلمة فيما أثاره صديقنا الاديب الكبير الدكتور زكي مبارك حول كتاب (الام) منذ بضعة أعوام، فقد تعرض للجدل في هذا الكتاب، عن غير بينة ولا دراسة منه لكتب المتقدمين وطرق تأليفهم، ثم طرق رواية المتأخرين عنهم لما سمعوه، فأشبهت عليه بعض الكلمات في (الام) فظنها دليلا\nعلى أن الشافعي لم يؤلف هذه الكتب.\nواستند إلى كلمة رواها أبو طالب المكي في أخذه الربيع بعد موته فادعاه لنفسه.\nثم جادل الدكتور زكي مبارك في هذا جدالا شديدا، وألف فيه كتابا صغيرا، أحسن ما فيه أنه مكتوب بقلم كاتب بليغ، والحجج على نقض كتابه متوافرة في كتب الشافعي نفسها.\nولو صدقت هذه الرواية لارتفعت الثقة بكل كتب العلماء، بل لارتفعت الثقة بهؤلاء العلماء أنفسهم، وقد رووا لنا العلم والسنة، بأسانيدهم الصحيحة الموثوق بها، بعد أن نقد علماء الحديث سير الرواة وتراجمهم، ونفوا رواية كل من حامت حول صدقه أو عدله شبهة، والربيع المرادي من ثقات الرواة عند المحدثين، وهذه الرواية فيها تهمة له بالتلبيس والكذب، وهو أرفع قدرا وأوثق أمانة من أن نظن به أنه يختلس كتابا ألفه البويطي ثم ينسبه لنفسه، ثم يكذب على الشافعي في كل ما يروى أنه من تأليف الشافعي، بل لو صح عنه بعض هذا كان من أكذب الوضاعين وأجرئهم على الفرية! ! وحاش لله أن يكون الربيع الا ثقة أمينا.\nوقد رد مثل هذه الرواية أبو الحسين الرازي الحافظ محمد بن عبد الله بن جعفر المتوفى سنة 347، وهو والد الحافظ تمام الرازي، فقال: \" هذا لا يقبل، بل\nالبويطي كان يقول: الربيع أثبت في الشافعي مني، وقد سمع أبو زرعة الرازي كتب الشافعي كلها من الربيع قبل موت البويطي بأربع سنين \".\nانظر التهذيب للحافظ ابن حجر (3: 246) .\nوقد يظن بعض القارئين أني أقسو في الرد على الدكتور، ومعاذ الله أن أقصد إلى ذلك، وهو الاخ الصادق الود، ولكن ماذا أصنع؟ وهو يرمي أوثق رواة كتب الشافعي - الربيع المرادي - بالكذب على الشافعي، ثم ينتصر لرأيه، ويسرف في ذلك، ويخونه قلمه، حتى ينقل عن الام نقلا غير صحيح، ينتهي به إلى أن يرمي الشافعي نفسه بالكذب! ! فيزعم في كتابه أن عبارة \" أخبرنا \" لا تدل على السماع في الرواية، وأن الاخبار معناه أحيانا النقل والرأي، ثم ينقل عن الام أن الشافعي قال في (ج 1 ص 117) \" أخبرنا هشيم \" ويقول:\n\" إن الشافعي لم يلق هشيما، فقد توفي هشيم ببغداد سنة 183 والشافعي إنما دخل إلى بغداد سنة 195 \".\nوأصل هذا الاستدراك للسراج البلقيني، وهو مذكور بحاشية الام، ولكن تعليقا، وذلك أن يروي الرجل عمن لم يلقه من الشيوخ شيئا فيذكر اسمه فقط على تقدير \" قال \"، أو يقول صريحا \" قال فلان \".\nوليس بهذا بأس، بل هو أمر معروف مشهور، ولا مطعن على الراوي به.\nولذلك بين البلقيني الامر، فان لكلامه بقية حذفها الدكتور، وهي: \" فلسكونه لم يسمع منه يقول بالتعليق: هشيم، يعني: قال هشيم \".\nولكن الدكتور زكي مبارك فاته معنى هذا عند علماء المصطلح، فحذفه.\nثم زاد فيما نقل عن الشافعي كلمة \" أخبرنا \" ليؤيد بها رأيه الذي اندفع في الاحتجاج له.\n* فائدة: أخطأ السراج البلقيني في هذا الموضع، في إيهامه أن الشافعي لم يدخل بغداد إلا سنة 195 لانه ثبت أنه دخلها سنة 184 وسمع من محمد بن الحسن كثيرا من العلم.\nكما أخطأ أيضا في حاشية أخرى كتبها بعد هذا الموضع (الام 1: 118) عند قول الشافعي \" أخبرنا ابن مهدي \" قال: \" هكذا وقع في نسخة الام أن الشافعي يقول: أخبرنا ابن مهدي، والشافعي لم يجتمع بابن مهدي \".\nووجه الخطأ أن الشافعي وابن مهدي تعاصرا، وكلاهما دخل بغداد، والغالب أن ابن المهدي كان يدخل الحجاز، والمعروف البديهي عند علماء الحديث أن الراوي العدل إذا قال \" حدثنا \" أو \" أخبرنا \" كان الحديث متصلا، وأنه إذا قال \" عن فلان \" لمن ثبت لقاؤه إياه ولو مرة واحدة حمل على الاتصال أيضا، لا يخالف أحد منهم في ذلك.\n(انظر الرسالة رقم 1032) وإنما اختلفوا فيمن يقول \" عن فلان \" لشخص عاصره ولم يثبت أنه لقيه ولو مرة، فالبخاري لا يحمله على الاتصال، ومسلم وأكثر أهل العلم يجعلونه متصلا أيضا، وهو الراجح الصحيح.\nولا يخالف أحد من العلماء في أن الرواي الذي يقول \" حدثنا \" أو \" أخبرنا \" لما لم يسمع فانما هو كذاب وضاع، فالشافعي الصادق الامين إذا قال \" أخبرنا ابن مهدي \" فقد أخبره، لا يجوز فيه غير هذا.\nو (كتاب الرسالة) ألفه الشافعي مرتين.\nولذلك يعده العلماء في فهرس مؤلفاته كتابين: الرسالة القديمة، والرسالة الجديدة.\nأما الرسالة القديمة فالراجح\nعندي أنه ألفها في مكة، إذ كتب إليه عبد الرحمن بن مهدي (1) \" وهو شاب أن يضع له كتابا فيه معاني القران.\nويجمع قبول الاخبار فيه، وحجة الاجماع وبيان الناسخ والمنسوخ من القران والسنة.\nفوضع له كتاب الرسالة \" (2) وقال علي بن المديني: \" قلت لمحمد بن أدريس الشافعي أجب عبد الرحمن بن مهدي عن كتابه، فقد كتب إليك يسألك، وهو متشوق إلى جوابك.\nقال: فأجابه الشافعي، وهو كتاب الرسالة التي كتبت عنه بالعراق، وإنما هي رسالته إلى عبد الرحمن بن مهدي \" (3) .\nوأرسل الكتاب إلى ابن مهدي مع الحرث بن سريج النقال الخوارزمي ثم البغدادي، وبسبب ذلك سمي \" النقال \" (4) .\nوالظاهر عندي أن عبد الرحمن بن مهدي كان إذ ذلك في بغداد، دخلها سنة 180، ولكن الفخر الرازي يقول في كتاب مناقب الشافعي (ص 57) : \" اعلم أن الشافعي رضى الله عنه صنف كتاب الرسالة ببغداد، ولما رجع إلى مصر أعاد تصنيف كتاب الرسالة، وفي كل واحد منهما علم كثير \".\nوأياما كان فقد ذهبت الرسالة القديمة، وليس في أيدي الناس الان إلا الرسالة الجديدة، وهي هذا الكتاب.\nوقد تبين لنا من استقراء كتب الشافعي الموجودة التي ألف بمصر أنه ألف هذه الكتب من حفظه، ولم تكن كتبه كلها معه.\nانظر إليه يقول في كتاب الرسالة (رقم 1184) .\n\" وغاب عني بعض كتبي، وتحققت بما يعرفه أهل العلم مما حفظت، فاختصرت خوف طول الكتاب، فأتيت\nببعض ما فيه الكفاية، دون تقصي العلم في كل أمره \".\nويقول في كتاب اختلاف الحديث (ص 252) : \" وقد حدثني الثقة أن الحسن كان يدخل بينه وبين عبادة حطان الرقاشي، ولا أدري أدخله عبد الوهاب بينهما فزال من كتابي حين حولته من الاصل أم لا؟ والاصل يوم كتبت هذا الكتاب غائب عني \".\nوالظاهر عندي أيضا أنه أعاد تأليف كتاب الرسالة بعد تأليف أكثر كتبه التي في (الام) ، لانه يشير كثيرا في الرسالة إلى مواضع مما كتب هناك، فيقول مثلا (رقم 1173) : \" وقد فسرت هذا الحديث قبل هذا الموضع \".\nوهذه إشارة إلى ما في الام (6: 77) .\nوالراحج أنه أملى (كتاب الرسالة) على الربيع إملاء، كما يدل على ذلك قوله في (337) : \" فخفف فقال: علم أن سيكون منكم مرضى.\nقرأ إلى: فاقرؤا ما تيسر منه \".\nفالذي يقول \" قرأ \" هو الربيع، يسمع الاملاء ويكتب، فإذا بلغ إلى آية من القران كتب بعضها ثم يقول \" الاية \" أو \" إلى كذا \"، فيذكر ما سمع الانتهاء إليه منها، ولكن هنا صرح بأن الشافعي قرأ إلى قوله \" فاقرؤا ما تيسر منه \".\nوالشافعي لم يسم \" الرسالة \" بهذا الاسم، إنما يسميها (الكتاب) أو يقول \" كتابي \" أو \" كتابنا \".\nوانظر الرسالة (رقم 96، 418، 420، 573، 625، 709، 953) وكذلك يقول في كتاب (جماع العلم) مشيرا إلى الرسالة \" وفيما وصفنا ههنا وفي (الكتاب) قبل هذا \".\n(الام 7: 253) .\nويظهر\nأنها سميت \" الرسالة \" في عصره، بسبب إرساله إياها لعبد الرحمن بن مهدي (1) .\nوهذا كتاب (الرسالة) أول كتاب ألف في (أصول الفقه) بل هو أول كتاب ألف في (أصول الحديث) أيضا.\nقال الفخر الرازي في مناقب الشافعي (ص 57) : \" كانوا قبل الامام الشافعي يتكلمون في مسائل أصول الفقه، ويستدلون ويعترضون، ولكن ما كان لهم قانون كلي مرجوع إليه في معرفة دلائل الشريعة، وفي كيفية معرضاتها وترجيحاتها، فاستنبط الشافعي علم أصول الفقه، ووضع للخلق قانونا كليا يرجع إليه في معرفة مراتب أدلة الشرع.\nفثبت أن نسبة الشافعي إلى علم الشرع كنسبة أرسطا طاليس إلى علم العقل \".\nوقال بدر الدين الزركشي في كتاب البحر المحيط في الاصول (مخطوط) : \" الشافعي أول من صنف في أصول الفقه، صنف فيه كتاب الرسالة، وكتاب أحكام القران، واختلاف الحديث، وإبطال الاستحسان، وكتاب جماع العلم، وكتاب القياس \".\nوأقول: إن أبواب الكتاب ومسائله، التي عرض الشافعي فيها للكلام على حديث الواحد والحجة فيه، وإلى شروط صحة الحديث وعدالة الرواة، ورد الخبر المرسل والمنقطع، إلى غير ذلك مما يعرف من الفهرس العلمي في آخر الكتاب -: هذه المسائل عندي أدق وأغلى ما كتب العلماء في أصول الحديث، بل إن المتفقه في علوم الحديث يفهم أن ما كتب بعده إنما هو فروع منه، وعالة عليه، وأنه جمع ذلك وصنفه على غير مثال سبق، لله أبوه.\nو (كتاب الرسالة) بل كتب الشافعي أجمع، كتب أدب ولغة وثقافة،\nقبل أن تكون كتب فقه وأصول، ذلك أن الشافعي لم تهجنه عجمة، ولم تدخل على لسانه لكنة، ولم تحفظ عليه لحنة أو سقطة.\nقال عبد الملك بن هشام النحوي صاحب السيرة: \" طالت مجالستنا للشافعي فما سمعت منه لحنة قط، ولا كلمة غيرها أحسن منها \".\nوقال أيضا: \" جالست الشافعي زمانا، فما\nسمعته تكلم بكلمة إلا إذا أعتبرها المعتبر لا يجد كلمة في العربية أحسن منها \".\nوقال أيضا: \" الشافعي كلامه لغة يحتج بها \".\nوقال الزعفراني: \" كان قوم من أهل العربية يختلفون إلى مجلس الشافعي معنا، ويجلسون ناحية، فقلت لرجل من رؤسائهم: إنكم لا تتعاطون العلم فلم تختلفون معنا؟ قالوا: نسمع لغة الشافعي \".\nوقال الاصمعي: \" صححت أشعار هذيل على فتى من قريش، يقال له محمد بن إدريس الشافعي \".\nوقال ثعلب: \" العجب أن بعض الناس يأخذون اللغة عن الشافعي، وهو من بيت اللغة! والشافعي يجب أن يؤخذ منه اللغة، لا أن يؤخذ عليه اللغة \".\nيعني يجب أن يحتجوا بألفاظه نفسها، لا بما نقله فقط.\nوكفى بشهادة الجاحظ في أدبه وبيانه (1) ، يقول: \" نظرت في كتب هؤلاء النبغة (2) الذين نبغوا في العلم، فلم أر أحسن تأليفا من المطلبي، كأن لسانه ينظم الدر \".\nفكتبه كلها مثل رائعة من الادب العربي النقي، في الذروة العليا من البلاغة، يكتب على سجيته، ويملي بفطرته، لا يتكلف ولا يتصنع، أفصح نثر تقرؤه بعد القران والحديث، لا يساميه قائل، ولا يدانيه كاتب.\nوإني أرى أن هذا الكتاب (كتاب الرسالة) ينبغي أن يكون من الكتب المقرؤة في كليات الازهر وكليات الجامعة، وأن تختار منه فقرات لطلاب الدراسة الثانوية في المعاهد والمدارس، ليفيدوا من ذلك علما بصحة النظر وقوة الحجة، وبيانا لا يرون مثله في كتب العلماء وآثار الادباء.\nوقد عني أئمة العلماء السابقين بشرح هذا الكتاب، كما ظهر لنا من\nتراجم بعضهم ومن كتاب (كشف الظنون) ، والذين عرفت أنهم شرحوه خمسة نفر: 1 - أبو بكر الصديق محمد بن عبد الله، كان يقال: إنه أعلم خلق الله بالاصول بعد الشافعي، تفقه على ابن سريج، مات سنة 330 ذكر شرحه في كشف الظنون وطبقات الشافعية (2: 169 - 170) والزركشي في خطبة البحر."},{"id":"risala-shafii:19","bookId":"risala-shafii","type":"section","seq":19,"chapter":"كتاب الرسالة","title":"2- أبو الوليد النيسابوري الامام الكبير حسان بن محمد بن أحمد بن هرون القرشي الاموي","page":"ص0","text":"أبو الوليد النيسابوري الامام الكبير حسان بن محمد بن أحمد بن هرون القرشي الاموي، تلميذ ابن سريج، وشيخ الحاكم أبي عبد الله، وصاحب المستخرج على صحيح مسلم، ولد بعد سنة 270 ومات ليلة الجمعة 5 ربيع الاول سنة 349 (الطبقات 2: 191 - 192) ولم يذكر شرحه، وذكره الزركشي وكشف الظنون."},{"id":"risala-shafii:20","bookId":"risala-shafii","type":"section","seq":20,"chapter":"كتاب الرسالة","title":"3- القفال الكبير الشاشي","page":"ص0","text":"القفال الكبير الشاشي، محمد بن علي بن إسماعيل، ولد سنة 291 ومات في آخر سنة 365 ذكره الزركشي وكشف الظنون والطبقات (2: 176 - 178) ."},{"id":"risala-shafii:21","bookId":"risala-shafii","type":"section","seq":21,"chapter":"كتاب الرسالة","title":"4- أبو بكر الجوزقي النيسابوري الامام الحافظ محمد بن عبد الله الشيباني","page":"ص0","text":"أبو بكر الجوزقي النيسابوري الامام الحافظ محمد بن عبد الله الشيباني، تلميذ الاصم وأبي نعيم، وشيخ الحاكم أبي عبد الله، وصاحب المسند على صحيح مسلم، مات في شوال سنة 388 وله 82 سنة (الطبقات 2: 169) ولم يذكر شرحه، وذكره كشف الظنون."},{"id":"risala-shafii:22","bookId":"risala-shafii","type":"section","seq":22,"chapter":"كتاب الرسالة","title":"5- أبو محمد الجويني الامام","page":"ص0","text":"أبو محمد الجويني الامام، عبد الله بن يوسف، والد إمام الحرمين، مات سنة 438 (الطبقات 3: 208 - 219) ولم يذكر الشرح، وذكره الزركشي وكشف الظنون.\nولعل غيرهم شرحه ولم يصل خبره إلي.\nولكن هذه الشروح التي عرفنا أخبارها لم أسمع عن وجود شرح منها في أية مكتبة من مكاتب العالم في هذا العصر."},{"id":"risala-shafii:23","bookId":"risala-shafii","type":"section","seq":23,"chapter":"كتاب الرسالة","title":"نسخ الكتاب","page":"ص0","text":"لم أر نسخة مخطوطة من (كتاب الرسالة) إلا"},{"id":"risala-shafii:24","bookId":"risala-shafii","type":"section","seq":24,"chapter":"كتاب الرسالة","title":"أصل الربيع","page":"ص0","text":"ونسخة ابن جماعة.\nولكنا نجد في السماعات - التي سيراها القارئ - أن أكثر الشيوخ وكثيرا من السامعين كانت لهم نسخ يصححونها على أصل الربيع، وأن نسخة ابن جماعة قوبلت على أصول مخطوطة عديدة، فأين ذهبت كل هذه الاصول؟ ! لا أدري.\nوقد طبع الكتاب في مصر ثلاث مرات:"},{"id":"risala-shafii:25","bookId":"risala-shafii","type":"section","seq":25,"chapter":"كتاب الرسالة","title":"1- الاولى بالمطبعة العلمية سنة 1312 بتصحيح","page":"ص0","text":"الاولى بالمطبعة العلمية سنة 1312 بتصحيح (يوسف صالح محمد الجزماوي) ، في (160 صفحة) بقطع الثمن، وهي طبعة مملوءة بالاغلاط.\nوهي التي نشير إليها بحرف (ج) ."},{"id":"risala-shafii:26","bookId":"risala-shafii","type":"section","seq":26,"chapter":"كتاب الرسالة","title":"2- الثانية بالمطبعة الشرفية سنة 1315 في","page":"ص0","text":"الثانية بالمطبعة الشرفية سنة 1315 في (144 صفحة) بقطع الربع، وقد طبعت عن أصل الربيع بالواسطة، نقلها أولا (محمد مصطفى الكاتب بالكتبخانة الخديوية سنة 1308 ثم نسخت عنها نسخة فرغ منها كاتبها (في يوم الاحد 14 صفر سنة 1310) على ذمة ناشرها (الشيخ سليم سيد أحمد أبراهيم شرارة القباني) ، وهذه النسخة أقل من سابقتها أغلاطا في الجزء الاول من تقسيم الربيع، ثم يظهر أن مصححها عارض بنسخ أخرى أو بالطبعة السابقة، فكثرت مخالفته لاصل الربيع، وكثرت فيها الاغلاط، ولكن ميزتها أن فيها كل السماعات التي على الاصل، وإن أخطأ الناسخ في قراءة كثير منها، وهو في ذلك معذور.\nوهي التي نشير إليها بحرف (ش) ."},{"id":"risala-shafii:27","bookId":"risala-shafii","type":"section","seq":27,"chapter":"كتاب الرسالة","title":"3- الثالية بمطبعة بولاق سنة 1321 عل نفقة السيد أتحمد بك الحسيني المحامي رحمه الله","page":"ص0","text":"الثالية بمطبعة بولاق سنة 1321 عل نفقة السيد أتحمد بك الحسيني المحامي رحمه الله، في (82 صفحة) بالقطع الكبير، وهي مملوءة بالاغلاط أيضا، ومخالفة في كثير من المواضع لاصل الربيع، ولا أدري عن أي النسخ طبعت، وإن كنت أظن أن مصححي مطبعة بولاق رجعوا كثيرا إلى نسخة ابن جماعة.\nوهي التي نشير إليها بحرف (ب) .\nوقد ذكرنا في تعليقنا على الرسالة مواضع مخالفة هذه النسخ للاصل، ليكون\nالقارئ على بينة من أمرها، فلا يظن أننا أخطأنا في مخالفتها، أو قصرنا في المقابلة، وليوقن أن هذه الطبعة أصح الطبعات وأجودها.\nويجمل بي في هذه المناسبة أن أنوه بفضل إخواني (أنجال المرحوم السيد مصطفى البابي الحلبي) إذ ساروا على الخطة المثلى، خطة أبيهم رحمه الله، في إحياء الكتب العربية القيمة، وإخراجها للناس تملا العين وتسر القلب، محافظين على آثار سلفنا الصالح رضي الله عنهم، فبذلوا ما بذلوا من جهد ومال، في سبيل إخراج هذا الكتاب، فكان لي من تشجيعهم وأناتهم عون كبير في تحقيقه وشرحه، حتى سلخت في ذلك نحو ثلاث سنين، والحمد لله على توفيقه."},{"id":"risala-shafii:28","bookId":"risala-shafii","type":"section","seq":28,"chapter":"كتاب الرسالة","title":"أصل الربيع","page":"ص0","text":"من أول يوم قرأت في أصل الربيع من (كتاب الرسالة) أيقنت أنه مكتوب كله بخط الربيع، وكلما درسته ومارسته ازددت بذلك يقينا، فتوقيع الربيع في آخر الكتاب بخطه بإجازة نسخه إذ يقول: \" أجاز الربيع بن سليمان صاحب الشافعي نسخ كتاب الرسالة، وهي ثلاثة أجزاء في ذي القعدة سنة خمس وستين ومائتين، وكتب الربيع بخطه \" (1) -: نفهم منه أنه كان ضنينا بهذا الاصل، لم يأذن لاحد في نسخه من قبل، حتى أذن في سنة 265 بعد أن جاوز التسعين من عمره، وعبارة الاجازة تدل على ذلك، لمخالفتها المعهود في الاجازات، إذ يجيز العلماء لتلاميذهم الرواية عنهم، أما إجازة نسخ الكتاب فشئ نادر، لا يكون إلا لمعنى خاص، وعن أصل حجة لا تصل إليه كل يد.\nوالخابر بالخطوط القديمة يجزم بأن هذه الاجازة كتبتها اليد التي كتبت الاصل، وأن الفرق بين الخطين إنما فرق السن وعلوها، فاضطربت يد\nالكاتب بعد أن جاوز التسعين، بما لم يوجد في خطه في فتوته لم يجاوز الثلاثين (2) ، وقد خشيت أن أثق برأيي وحدي في ذلك، فأردت أن أتثبت، فاستشرت أحد إخواني ممن لهم خبرة بينة وعلم بالخطوط، فوافقني على أن كاتب الاجازة وكاتب الاصل وكاتب عناوين الاجزاء الثلاثة شخص واحد، لا فرق بينها إلا أنه كتب العناوين بالخط الكوفي، وكتب الاجازة وهو شيخ كبير.\nوأنا أرجج ترجيحا قريبا من اليقين أن الربيع كتب هذه النسخة من إملاء الشافعي، لما بينت فيما مضى، ولانه لم يذكر الترحم على الشافعي في أي موضع جاء اسمه فيه، ولو كان كتبها بعد موته لدعا له بالرحمة ولو مرة واحدة، كعادة العلماء وغيرهم.\nوقد حاول الدكتور (ب.\nموريتس (1)) أن يدخل الشك على تاريخ هذه النسخة، فادعى في كتاب الخطوط العربية أنها مكتوبة سنة 350 تقريبا.\nفعن ذلك تردد بعض إخواني ممن تحدثت إليهم في أن الربيع كتبها، وزعموا أنها نسخة مكتوبة بعد الربيع بدهر، وأن ناسخها نقلها ونقل نص الاجازة، ثم لم يبين أنه نقلها! ! وهذا رأى لا يثبت على النقد، لان المعروف في نقل الكتب أن الناسخ إذا نسخ الكتاب وتاريخ كتابته وما كتب عليه من إجازة أو سماع مثلا -: أثبت أن هذا نص ما كان على النسخة التي ينقل منها.\nثم الذي ينقضه نقضا ارتعاش القلم الظاهر في كتابة الاجازة، فلو كانت منقولة عن نسخة أخرى ما افترق خطها عما قبلها، ولكان الجميع على نسق واحد.\nوكان مما احتجوا به لرأيهم ورأي الدكتور موريتس أنها مكتوبة على الورق، أن الورق لم يكن معروفا في ذلك العهد كثيرا، بل كان جل الكتابة على\nالبردي.\nوهذا مردود بأن الورق كثر وفشا في القرن الثاني من الهجرة.\n(انظر مثلا صبح الاعشى 2: 486) .\nواحتجوا أيضا بأن خطها ليس بالقلم الكوفي، الذي كان يكتب به أهل القرن الثاني والثالث.\nومن العجب أن هذه الشبهة عرضت أيضا لبعض العلماء الاقدمين، وردها القلقشندي قال: \" ذكر صاحب\nإعانة المنشئ أن أول ما نقل الخط العربي من الكوفي إلى ابتداء هذه الاقلام المستعملة الان -: في أواخر خلافة بني أمية، وأوائل خلافة بني العباس: قلت: على أن الكثير من كتاب زماننا يزعمون أن الوزير أبا علي بن مقلة (1) هو أول من ابتدع ذلك.\nوهو غلط، فانا نجد من الكتب بخط الاولين فيما قبل المائتين ما ليس على صورة الكوفي، بل يتغير عنه إلى نحو هذه الاوضاع المستقرة، وإن كان هو إلى الكوفي أميل لقربه من نقله عنه \" (صبح الاعشي 3: 15) وكأن القلقشندي بهذا يصف نسخة الرسالة، ففي حروفها شبه بالخط الكوفي، ولم يكن الخط الكوفي مهجورا في تلك العصور، بل كانوا يكتبون به المهارق والوثائق، وكانوا يتأنقون به في كتابة المصحف وغيرها، ولذلك نرى الربيع يكتب في عناوين الاجزاء الثلاثة كلمات (الجزء الاول.\nالجزء الثاني.\nالجزء الثالث) بالخط الكوفي، ويكتب تحتها كلمات (من الرسالة رواية الربيع بن سليمان عن محمد بن إدريس الشافعي) بخط وسط بين الكوفي وبين خطه في داخل الكتاب (انظر اللوحات رقم 3، 4، 5 مقارنا برقم 6، 7، 8، 9) .\nوالخطوط العربية القديمة التي وجدت في دور الكتب ودور الاثار تدل على أن هذا الخط كان معروفا في القرن الثاني، قبل ابن مقلة، كما قال القلقشندي.\nومن مثل ذلك أن من الاوراق البردية الموجودة بدار الكتب المصرية ورقة مؤرخة سنة 195 يشبه خطها خط كتاب الرسالة، بل إن الشبهة بينهما قريب جدا، حتى ليكاد المطلع عليهما أن يظن أن كاتبيهما تعلما الخط على معلم واحد، وهذه الورقة منشورة في الجزء الاول من كتاب (أوراق البردي العربية) الذي ألفه المستشرق جروهمان وترجمه الدكتور حسن إبراهيم، وطبع بدار الكتب\nسنة 19 وهي (برقم 51 في اللوحة رقم 8) وقد صورناها، وصورنا قطعة من (ص 36 من الاصل) ووضعناهما متجاورتين في صفحة واحدة (لوحة رقم 10، 11) ليسهل على القارئ المقارنة بينهما، ورسمنا سهما أمام تاريخ ورقة البردي (سنة 195) .\nومما لا شك فيه أن خط الربيع يعتبر من خط أهل القرن الثاني، لانه ولد سنة 174 والشافعي دخل مصر في أواخر سنة 199 فاتخذ الربيع خادما له وتلميذا خاصا، وكان الشافعي يقول له: \" أنت راوية كتبي \".\nوحين قدم الشافعي مصر كان الربيع مؤذنا بالمسجد الجامع بفسطاط مصر - جامع عمرو بن العاص - وكان يقرأ بالالحان، معنى هذا أنه كان كاتبا قارئا في أواخر القرن الثاني، فقد تعلم الخط والقراءة صغيرا كما يتعلم الناس.\nثم يرفع كل شك في نسب هذه النسخة احتفال العلماء العظماء، والائمة الحفاظ الكبار بها، منذ سنة 394 إلى سنة 656 وإثبات خطوطهم عليها وسماعاتهم، بل إثبات أنهم صححوا نسخهم وقابلوها عليها، كما ترى فيما يأتي من السماعات والتوقيعات، ويحرصون على إثبات سماعهم فيها طلابا صغارا، ثم إسماعهم إياها لغيرهم شيوخا كبارا.\nوترى الاسر العلمية الكبيرة يتسابقون\nإلى سماعها، فيسجلون أسماءهم عليها.\nفانك ترى - مثلا - من أئمة الحفاظ الكبار من أهل العلم، الذين سمعوا الكتاب في هذه النسخة -: الحافظ الحميدي صاحب الجمع بين الصحيحين، وصديقه الحافظ الامير ابن ماكولا (في السماعات رقم 8 - 11) والحافظ أبا الفتيان الدهستاني (في رقم 12) والحافظ الكبير ابن عساكر صاحب تاريخ دمشق (في رقم 18، 21) والحافظ عبد القادر الرهاوي (في رقم 22، 23)\nوالحافظ تاريخ الدين القرطبي (في رقم 24، 26، 27) والحافظ زكي الدين البرزالي (في رقم 27، 28) .\nوترى أن أسرة الحافظ ابن عساكر سمع منها في هذه النسخة أحد عشر رجلا: الحافظ ابن عساكر علي بن الحسن بن هبة الله، وأخواه محمد وأحمد، وابناه: القاسم والحسن ابنا علي، وحفيداه: محمد وعلي ولدا القاسم، وأبناء أخيه: عبد الله وعبد الرحمن ونصر الله وعبد الرحيم: أبناء محمد بن الحسن (انظر السماعات 18، 19، 21، 24، 25) .\nوأسرة الخشوعي سمع منها سبعة نفر: أولهم طاهر بن بركات بن إبرهيم الخشوعي، ثم ابنه إبرهيم، ثم بركات بن إبرهيم، ثم أولاده: إبرهيم وأبو الفضل وعبد الله أبناء بركات بن إبرهيم، ثم عثمان بن عبد الله بن بركات (انظر السماعات 12، 16، 18، 22 - 28) .\nثم الحافظ ابن عساكر لا يكفيه أن يسجل اسمه في السماعات، فيكتب بخطه أربع مرات على النسخة: \" سمع جميعه وعارض بنسخته علي بن الحسن بن هبة الله \" (انظر التوقيع رقم 39) .\nوكذلك غيره من الحفاظ والعلماء، مما يظهر من التوقيعات (32 - 45) .\nثم يثلج الصدر ويملؤه يقينا أن نجد شهادة بخط أحد العلماء الحفاظ\nالاثبات القدماء، يسجل فيها أن هذه النسخة بخط الربيع، فنرى هبة الله بن أحمد بن محمد بن الاكفاني (المتوفى في 6 محرم سنة 524 عن 80 سنة) يكتب بخطه ثلاثة عناوين للاجزاء الثلاثة، يسوق فيها إسناده إلى الربيع، ثم يكتب فوق عنوان الاول منها ما نصه: \" الجزء الاول من الرسالة لابي عبد الله الشافعي بخط الربيع صاحبه \".\nويكتب فوق عنوان الثالث ما نصه: \" الجزء الثالث\nمن الرسالة بخط الربيع صاحب الشافعي \".\nوأما عنوان الجزء الثاني ففوقه: \" الثاني من الرسالة \" ويظهر أن باقي الكلام ممحو بعارض من عاديات الزمان.\nوتجد صورة عنوان الجزء الاول في (اللوحة رقم 1) فترى فيها في الزاوية العليا اليمنى خط الحافظ ابن عساكر، وبجواره خط شيخه ابن الاكفاني.\nوقد ظننت أول الامر أن هذه الشهادة بخط ابن عساكر، ثم تبين لي من دراسة خطوط السماعات والعناوين أنها خط ابن الاكفاني.\nثم نرى أيضا أن هؤلاء العلماء - وهم أقرب منا عهدا بالربيع - يتلكفون النص في السماعات كلها أو أكثرها على اسم مالك النسخة، إشارة الى شدة العناية بها، وإشادة بما لمالكها من ميزة وفخر، أن حاز هذا الاثر الجليل النفيس.\nأفيظن ظان أو يتوهم متوهم أنهم يصنعون كل هذا لنسخة مزيفة مزورة؟ ! أو يخفى عليهم من شأنها ما لم يخف على الدكتور موريتس، وهم أخبر بالخطوط وأعلم بالعلم، وهم يروون الكتاب بأسانيدهم رواية سماع وقراءة؟ ! وكثيرا ما عجبت: لماذا عين تاريخها الذي زعم، سنة 350 تقريبا، ثم تبينت من أين الوهم.\nفوجدت في حاشية نسخة العماد ابن جماعة بجوار الفقرة (126 من الكتاب) ما نصه: \" بلغ مقابلة على أصل سمع مرات، تاريخه\nمن حين نسخ ثلاثمائة وثمان وخمسون سنة \" ثم كتب بحاشيتها في مواضع أخر: \" بلغ مقابلة على النسخة المذكورة \".\nفرجحت من هذا أنه رأى هذه الكتابة، وليس بدار الكتب نسخ قديمة من الرسالة غير أصل الربيع ونسخة ابن جماعة، فظن أن نسخة ابن جماعة قوبلت على نسخة الربيع، وأن هذا يدل على أن نسخة الربيع كتبت حول سنة 350 ولكن هذا النص\nلا يؤدي هذا المعنى، فإن نسخة ابن جماعة نرجح أنها كتبت له قبيل قراءتها على جده سنة 856 وقوبلت على نسخة مضى عليها من حين كتابتها إلى حين مقابلة نسخة ابن جماعة عليها 358 سنة، أي أنها كتبت قبيل سنة 500 فالرقم (358) هو عدد السنين التي تفرق بين النسختين، لا تاريخ الاولى، فهي غير نسخة الربيع يقينا."},{"id":"risala-shafii:29","bookId":"risala-shafii","type":"section","seq":29,"chapter":"كتاب الرسالة","title":"وصف النسخة","page":"ص0","text":"عدد أوراقها 78 ورقة، منها 62 ورقة هي أصل الذي بخط الربيع، والباقي أوراق زيدت في أوله وآخره ووسطه، كتبت فيها السماعات وغيرها، وغلفت النسخة بجلد قديم، لا أستطيع الجزم بتاريخه، ولعله في القرن السادس أو السابع الهجري.\nوطول الورقة من أصل الكتاب (8 و 25 سنتيمتر) وعرضها (14 س) والكتابة تملا الصفحة تقريبا، فإن طول السطر الواحد (5 و 12 س) وعدد السطور يختلف في الصفحات ما بين (27، 30) سطرا، تشغل من طولها نحو (8 و 24 س) .\nوقد صورنا صورا منها مصغرة قليلا إلى نحو الثلين، حتى تتسع لها مساحة الورق الذي تطبع عليه، وهي اللوحات (رقم 6 - 9) .\nوالخط مقروء واضح لمن خبر هذه الخطوط القديمة، إلا في بعض المواضع النادرة، مما يتبين لقارئ الكتاب بما علقنا به عليه.\nوقواعد الرسم التي كتبت بها تختلف كثيرا عن القواعد التي يكتب بها المتأخرون، وإحصاء ذلك لا تسعه هذه المقدمة، ولكنا نذكر بعض أنواعها.\nفمن ذلك أنه يكتب كل ما ينطق ألفا في أواخر الكلمات بالالف، وإن كان مما يكتب بالياء، إلا كلمة، \" هكذا \" وحرفي \" إلى \" وعلى \" فبالياء، فيكتب مثلا\n\" حتى \" بالالف \" حتا \".\nو\" حكى \" \" حكا \".\nو\" مستغنى \" \" مستغنا \".\nو\" سوى \" \" سوا \" الخ.\nوإذا كانت الكلمة تنطق بإمالة الالف لم يكتبها ألفا، بل كتبها ياء، إشارة إلى الامالة، مثل \" هؤلاء \" كتبها \" هاولى \" وكذلك \" الايلاء \" كتبها \" الايلى \".\nويحذف ألف \" ابن \" مطلقا، وإن لم تكن بين علمين، فيكتب مثلا \" عن بن عباس \".\nويكتب كلمة \" ههنا \" \" هاهنا \".\nوكلمة \" هكذا \" برسمين: الاكثر: \" ها كذى \" والبعض: \" هكذى \".\nويقسم الكلمة الواحدة في سطرين إذا لم يسعها اخر السطر، فمثلا كلمة \" استدللنا \" كتب الالف وحدها في سطر وباقيها في السطر الاخر (ص 44 من الاصل س 10، 11) وكلمة \" زوجها \" الزاي والواو في سطر والباقي في سطر (ص 50 س 18، 19) .\nوهذا كثير فيها.\nوأما الثقة بها فما شئت من ثقة، دقة في الكتابة، ودقة في الضبط، كعادة المتقنين من أهل العلم الاولين.\nفإذا اشتبه الحرف المهمل بين الاهمال والاعجام، ضبطه بإحدى علامتي الاهمال: إما أن يضع تحته نقطة، وإما أن يضع فوقه رسم هلال صغير، حتى لا يشبه فيتصحف على القارئ.\nومن أقوى الادلة على عنايته بالصحة والضبط، أنه وضع كسرة تحت النون في كلمة \" النذارة \" (رقم 35 ص 14 من الاصل) وهي كلمة نادرة، لم أجدها في المعاجم إلا في القاموس، ونص على أنها من الامام الشافعي.\nوهي تؤيد ما ذهبت إليه من الثقة بالنسخة، وتدل على أن الربيع كان يتحرى نطق الشافعي ويكتب عنه\nعن بينة.\nومن الطرائف المناسبة هنا أنى عرضت هذه الكلمة على أستاذنا الكبير العلامة أمير الشعراء على بك الجارم، فيما كنت أعرض عليه من عملي في الكتاب، فقال لي: كأنك بهذه الكلمة جئت بتوقيع الشافعي على النسخة.\nوقد صدق حفظه الله.\nومما يلاحظ في النسخة أن الصلاة على النبي لم تكتب عند ذكره في كل مرة، بل كتبت في القليل النادر، بلفظ \" صلى الله عليه \".\nوهذه طريقة العلماء المتقدمين، في عصر الشافعي وقبله، وقد شدد فيها المتأخرون، وقالوا: ينبغي المحافظة على كتابة الصلاة والتسليم، بل زادوا أنه لا ينبغي للناسخ أن يتقيد بالاصل إذا لم توجد فيه.\nوقد ثبت عن أحمد بن حنبل أنه كان لا يكتب الصلاة، وأجابوا عن ذلك بأنه كان يصلي لفظا، أو بأنه كان يتقيد بما سمع من شيخه فلا يزيد عليه.\nوالذي أختاره أن يتقيد الناسخ بالاصل الذي يعتمد عليه في النقل، أما إذا كتب لنفسه فهو مخير، وليس معنى هذا أن يفعل كما يفعل الكتاب \" المجد دون! ! \" في عصرنا، إذ يذكرون النبي باسمه \" محمد \" صلى الله عليه وسلم، ولا يكتبون الصلاة عليه، بل يذكره بصفد النبوة أو الرسالة أو نحوهما، لان الله سبحانه نهانا عن مخاطبته باسمه: (لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا) ولان الله لم يذكره في القران إلا بصفة النبوة أو الرسالة، أو باسمه الكريم مقرونا بإحداهما.\nوانظر شرح العراقي على مقدمة ابن الصلاح (ص 174 - 175) وتدريب الرواي (ص 153) وشرحنا على ألفية السيوطي (ص 151) وشرحنا على مختصر علوم الحديث لابن كثير ص (158 - 159) وشرحنا على الترمذي (2: 354 - 355) ."},{"id":"risala-shafii:30","bookId":"risala-shafii","type":"section","seq":30,"chapter":"كتاب الرسالة","title":"أصحاب النسخة","page":"ص0","text":"تتبعت السماعات الاتية، وعرفت منها أكثر مالكي النسخة من أواخر القرن الرابع الى منتصف القرن السابع.\nفأول مالكيها فيما أظن الاخوان: علي وإبراهيم ابنا محمد بن إبرهيم بن الحسين الحناني أو أحدهما، إذ سمعا فيها الكتاب\nمن عبد الرحمن بن عمر بن نصر في سنتي (394 و 401) ولكن لم ينص في سماعاتهما على ذلك (رقم 1 - 6) .\nوإنما ظننت ذلك لان ابني أخيهما الحسين بن محمد الحنائي، وهما عبد الله وعبد الرحمن -: سمعا فيها على أبي بكر الحداد سنة 457 ونص في السماعات على أنهما صاحبا الكتاب (رقم 8 - 11) فظننت من هذا أن الكتاب كان في ملك عميهما علي وإبرهيم، ثم انتقل إليهما بالميراث أو غيره.\nولكن سرعان ما انتقل من ملكهما إلى ملك الحافظ هبة الله بن الاكفاني، فسمع فيه على أبي بكر الحداد سنة 460 ويظهر أن النسخة بقيت في ملكه إلى حين وفاته سنة 524 أو على الاقل إلى آخر مجلس سمعت فيه عليه سنة 519 (رقم 19) .\nثم لم يتبين لي في ملك من كانت إلى شهر رجب سنة 566 فقد كتب الفقيه العالم ضياء الدين علي بن عقيل بن علي التغلبي (المولود سنة 537) أنه سمع الكتاب من أبي المكارم عبد الواحد بن هلال في سنة 563 وأنه نقل سماعه إلى هذه النسخة في رجب سنة 566 (رقم 20) ثم سمعه مرة أخرى على الحافظ ابن عساكر سنة 567 ونص في مجلس السماع على أنه صاحب النسخة (رقم 21) ثم كذلك سمعه هو ابنه الحسن في سنة 571 على أبي المعالي السلمي وأبي طاهر الخشوعي (رقم 22، 23) .\nثم لم يتبين أيضا في ملك من كانت، إلى أن ذكر في سنة 635 أنها في ملك الامام الحافظ تاج الدين القرطبي، وتاج الدين القرطبي سمع الكتاب هو وأخوه إسمعيل قبل ذلك بثمان وخمسين سنة، فقد سمعاه على أبي الطاهر الخشوعي في سنة 587\n(رقم 24 - 27) فإما أن يكون أبوهما أبو جعفر القرطبي (ولد سنة 528 ومات سنة 596) ملك الكتاب فأسمعهما فيه على أبي طاهر، وإما أن يكون تاج الدين\nنفسه ملكها بعد ذلك ثم سمعت عليه.\nثم ثبت ملكها بعد في سنة 656 للقاضي محيي الدين عمر بن موسى بن جعفر (رقم 28) .\nوكل هؤلاء الذين ملكوها كانوا في دمشق، ولم نعرف ما كان من أمرها قبل ذلك من عهد الربيع (المتوفى سنة 270) إلى عصر عبد الرحمن بن نصر في اخر القرن الرابع.\nولم نعرف أيضا ما كان من أمرها بعد القاضي محيي الدين بن جعفر، إلى أن دخلت في ملك الامير مصطفى باشا فاضل، وانتقلت مع مكتبته كلها إلى دار الكتب المصرية، فعادت إلى بلدها الذي فيه ألفت وكتبت وألقت عصاها واستقر بها النوى * كما قر عينا بالاياب المسافر"},{"id":"risala-shafii:31","bookId":"risala-shafii","type":"section","seq":31,"chapter":"كتاب الرسالة","title":"نسخة ابن جماعة","page":"ص0","text":"لو انفردت لكانت أصلا جيدا للكتاب، ولكنها جاءت بجوار أصل الربيع، فكانت فرعا ضئيلا، إذ خالفته في مواضع كثيرة، وكان الاصل هو الاصل، وأين الثرى من الثريا.\nعنى كاتبها بتجويد الخط، ثم عنى صاحبها بمقابلتها وقراءتها، ولكنه لم يتقن ذلك.\nولعل عذره أن النسخة التي قابل عليها لم تكن عمدة، وكتب بحاشيتها تقسيمها إلى أجزاء سبعة، ولكنه نسى من التقسيم الاول والخامس! فذكر عند الفقرة (551) \" آخر الجزء الثاني \" وعند (827) \" آخر الجزء الثالث \" وعند (1128) \" آخر الجزء الرابع \" وعند (1462) \" آخر الجزء السادس \".\nوكتب بلاغات بالمقابلات على النسخة القديمة عند الفقرات (126، 275، 383، 511، 758) وسمعت على الجمال ابن جماعة، جد العماد، في ستة مجالس، كتبت بلاغات أربعة منها بالحاشية\nأمام الفقرات (208، 569، 863، 1173) ولم يكتب الخامس، وأما السادس فينتهي بآخر الكتاب.\nوهي مكتوبة على ورق جيد، بخط نسخي جميل واضح، مضبوطة مشكولة في الاكثر.\nوعدد أوراقها 124 ورقة، في الصفحة منها 19 سطرا، وطول السطر (11 س) وتشغل السطور من طول الورقة (5 و 18 س) وطول الورقة (7 و 24 س) وعرضها (5 و 17 س) .\nوكانت أوراقها أكبر من ذلك، ولكن لا ندري من الذي أعطاها لاحد المجلدين، فانتقص من أطرافها، حتى أضاع بعض ما كتب في حاشيتها.\nوقد صورنا منها الصفحة الاولى والاخيرة مصغرتين، في اللوحتين (12، 13) وبعد: فلست بمستطيع أن أختم هذه المقدمة قبل أن أؤدي ما وجب علي من الشكر لاخواني الذين أثقلوا كاهلي بفضلهم، بما لقيت من معونتهم في إخراج هذا الاثر الجليل، والسفر النفيس: ابن عمتي السيد محمد السنوسي الانصاري.\nوالاخ المخلص البار، صديقي وزميلي من أول طلب العلم، العالم المتقن المتفنن، الشيخ محمد خميس هيبة، وقد قرأت عليه الكتاب حرفا حرفا، ورجعت إليه في كل مشكل عرض لي فيه.\nوالاخوان العالمان الجليلان: الشيخ محمد نور الحسن، والشيخ محمد محيي الدين عبد الحميد، أستاذا العربية بكلية اللغة بالازهر، وقد عرضت عليهما كثيرا من مشكلات العربية في الكتاب.\nثم القائمون على نشر الكتاب (أنجال المرحوم السيد مصطفى الحلبي) وقد أتاحوا لي فرصة إخراجه وتحقيقه وشرحه، فكانت منة لهم علي وعلى كل قارئ ومستفيد.\nواليد البيضاء التي لا تنسى، ما لقيت من معونة أستاذنا العظيم، العلامة الفيلسوف (الدكتور منصور فهمي بك) المدير العام لدار الكتب المصرية، فقد\nأمر حفظه الله بأن تصور لي نسخة الربيع كلها، وأمر بإعارتي نسخة ابن جماعة، وبأن يسهل لي كل ما أريد من مصادر ومراجع.\nأحسن الله جزاءه، ووفقه لخدمة العلم والدين.\nونسأل الله المبتدئ لنا بنعمه قبل استحقاقها، المديمها علينا، مع تقصيرنا في الاتيان على ما أوجب به من شكره بها، الجاعلنا في خير أمة أخرجت للناس: أن يرزقنا فهما في كتابه، ثم سنة نبيه، وقولا وعملا يؤدى به عنا حقه، ويوجب لنا نافلة مزيدة (1) .\nونسأله سبحانه العصمة والتوفيق.\nعن كوبرى القبة ضحوة الجمعة (18 ذي القعدة سنة 1358) (29 ديسمبر سنة 1939) كتب أبو الاشبال أحمد محمد شاكر"},{"id":"risala-shafii:32","bookId":"risala-shafii","type":"section","seq":32,"chapter":"كتاب الرسالة","title":"السماعات وما ألحق بها","page":"ص0","text":"السماعات المثبتة في"},{"id":"risala-shafii:33","bookId":"risala-shafii","type":"section","seq":33,"chapter":"كتاب الرسالة","title":"أصل الربيع","page":"ص0","text":"تبدأ من سنة 394 وتنتهي في سنة 656 وهي متتالية متصلة بالاسانيد، أعني أن الشيوخ الذين يقرأ عليهم الكتاب أو يسمع منهم نجدهم سمعوه قبل ذلك من شيوخهم، وهكذا إلى عبد الرحمن بن عمر بن نصر الشيباني، أقدم الشيوخ الذين أثبت إسماعهم للكتاب.\nثم نسخة ابن جماعة فيها سماع واحد، سنة 856 متصل الاسناد بسماعات الاصل، كما سيتبين القارئ.\nوقد جعلت لها أرقاما متتالية يشار إليها بها.\nوسماعات الاصل ثبت بعضها على عناوين الاجزاء الثلاثة التي بخط الربيع\n(لوحة رقم 3، 4، 5) وباقيها كتبت في أوراق ألصقت بالاصل وألحقت به في أوائل الاجزاء وأواخرها.\nوأكثرها تكرر إثباته ثلاث مرات في الاجزاء الثلاثة.\nوقد أثبتت كل السماعات مرتبة ترتيب وقوعها التاريخي، الاقدم فالاقدم.\nوتوخيا للاختصار ذكرت من كل سماع متكرر واحدا منه، مع الاشارة إلى غيره وما فيه من زيادة فائدة إن وجدت.\nولم أستثن من ذلك إلا السماعات التي بخط عبد الرحمن بن نصر، لقيمتها التاريخية أولا، ولانها مصورة في اللوحات على عناوين الربيع ثانيا، ولان صيغتها مختصرة ثالثا.\nواستثنيت أيضا بعض السماعات حين وجدت ضرورة لذلك.\nوالسماعات هي (رقم 1 - 28) ومن السماعات الاسانيد، وهي أسانيد كاتبيها من العلماء إلى الربيع راوي الكتاب رقم (29 - 31) ومن السماعات أيضا نوع مختصر، يسجل أحد العلماء فيه سماعه بخطه، كأن يقول \" سمعه فلان \" أو \" سماع لفلان \" ونحو ذلك.\nوكل الذين كتبوا ذلك ذكرت أسماؤهم في مجالس السماع إلا واحدا، هو أبو القاسم البورى هبة الله بن\nمعد الدمياطي المتوفى سنة 599 (انظر رقم 43) .\nوقد جمعتها كلها من ثنايا السماعات، وحذفت المكرر منها مع الاشارة إليه.\nورتبتها الاقدم فالاقدم، وسميتها \" التوقيعات \" (رقم 32 - 45) .\nومما ألحق بالسماعات في أصل الربيع، مما كتب العلماء بخطوطهم -: أحاديث وآثار رووها بأسانيدهم، ذكرتها أيضا بنصها (رقم 46 - 59) .\nثم يتلو ذلك ما كتب على نسخة العماد ابن جماعة، من أسانيد وفوائد وسماعه على جده (رقم 60 - 68) .\nوالاعلام المذكورون في هذه السماعات وما ألحق بها يزيدون على ثلاثمائة\nنفس، أحصيتهم كلهم في فهرس في آخر هذه المقدمة.\nفأما الذين ذكروا في أسانيد الاحاديث والاثار فلم أقصد إلى ذكر تراجمهم، خشية الاطالة، ولانه لا صلة بينهم وبين رواية الكتاب.\nوأما الاخرون: المذكورون في السماعات والتوقيعات فقد بذلت الوسع في البحث عن تراجمهم، فمن وجدت منه ترجمته، أشرت إليها بإيجاز، وأحلت القارئ إلى موضعها، ومن لم أجد سكت عنه، ولا أدعي في ذلك غاية الكمال، فما ذلك لاحد من الناس، ولكني اجتهدت وتحريت، وحسبي هذا أداء للواجب علي.\nوقد تكون ترجمة الرجل ممن لم أجد على طرف الثمام مني، ثم أخطها من حيث لا أدري.\nومن وجدت ترجمته وضعت صورة نجم بجوار اسمه في الفهرس.\nوقد رمزت لكتب التراجم التي رجعت إليها بحروف طلبا للاختصار، وها هو اصطلاحي فيها: ع تاريخ دمشق للحافظ ابن عساكر المتوفى سنة 599.\nمخطوط بمكتبة تيمور باشا بدار الكتب المصرية.\nمع مختصر هذا التاريخ للمرحوم الشيخ عبد القادر بدران طبع منه 7 أجزاء بدمشق ش شذرات الذهب لابن العماد الحنبلي المتوفى سنة 1089 طبع مصر 8 أجزاء ك البداية والنهاية للحافظ ابن كثير المتوفى سنة 774 طبع منه بمصر 13 جزءا ح تذكرة الحفاظ للحافظ الذهبي المتوفى سنة 748 طبع الهند 4 أجزاء ذ ذيول تذكرة الحفاظ للحسيني وابن فهد والسيوطي طبع مصر 1 ق طبقات القراء لابن الجزري المتوفى سنة 833 طبع مصر 2 خ الوفيات لابن خلكان المتوفى سنة 681 طبع بولاق 2 ط طبقات الشافعية لابن السبكي المتوفى سنة 771 طبع مصر 6 ل لسان الميزان للحافظ ابن حجر المتوفى سنة 852 طبع الهند 6\nدر الدرر الكامنة للحافظ ابن حجر طبع الهند 4 ض الضوء اللامع للسخاوي المتوفى سنة 902 طبع مصر 12 نس الانساب للحافظ السمعاني المتوفى سنة 562 طبع تصوير بأوربة"},{"id":"risala-shafii:34","bookId":"risala-shafii","type":"section","seq":34,"chapter":"كتاب الرسالة","title":"أصل الربيع","page":"ص0","text":"السماعات (1) 1 - سماع علي بن عبد الرحمن بن عمر بن نصر بخطه سنة 394 في الجزء الاول يقول عبد الرحمن بن عمر بن نصر بن محمد (2) : إن علي بن محمد بن إبرهيم بن الحسين الحنائي (3) ، بارك الله فيه، سمع مني هذا الجزء، وهو سماعي من أبي علي الحسن بن حبيب بن عبد الملك الحصري (4) ، عن الربيع بن سليمان المرادي، في شعبان من سنة أربع وتسعين وثلاثمائة، نفعنا الله بالعلم في الدنيا والاخرة، ولا جعله حجة، وحسبنا الله وحده، بقراءتي عليه من أصل كتابي."},{"id":"risala-shafii:35","bookId":"risala-shafii","type":"section","seq":35,"chapter":"كتاب الرسالة","title":"2- سماع آخر عليه بخطه سنة 401 في الجزء الاول وسمع هذا الجزء مني أبو عبد الله أحمد بن علي الشر","page":"ص0","text":"سماع آخر عليه بخطه سنة 401 في الجزء الاول وسمع هذا الجزء مني أبو عبد الله أحمد بن علي الشرابي، وإبرهيم بن محمد بن إبرهيم بن الحسين الحنائي (5) ، بقراءة أبي بكر محمد بن محمد بن عبد الله الشاشي،\nحفظهم الله.\nوكتب عبد الرحمن بن عمر بن نصر بن محمد، في شهر رمضان من سنة إحدى وأربعمائة.\nوسمع هذا الجزء مني أيضا ظفر بن المظفر الناصري (1) حفظه الله (2) ."},{"id":"risala-shafii:36","bookId":"risala-shafii","type":"section","seq":36,"chapter":"كتاب الرسالة","title":"3- سماع في الجزء الثاني بخطه أيضا سنة 394 يقول عبد الرحمن بن عمر بن نصر بن محمد","page":"ص0","text":"سماع في الجزء الثاني بخطه أيضا سنة 394 يقول عبد الرحمن بن عمر بن نصر بن محمد: إن علي بن محمد بن إبرهيم الحنائي نفع الله به سمعه مني مع ما قبله، بما حدثني أبو علي الحسن بن حبيب بن عبد الملك الحصري عن الربيع، وذلك في شعبان من سنة أربع وتسعين وثلاثمائة، وأنا قرأته عليه وعارضه بأصل كتابي."},{"id":"risala-shafii:37","bookId":"risala-shafii","type":"section","seq":37,"chapter":"كتاب الرسالة","title":"4- سماع في الجزء الثاني بخطه سنة 401 سمع هذا الجزء وما قبله أبو عبد الله أحمد بن علي الشرابي","page":"ص0","text":"سماع في الجزء الثاني بخطه سنة 401 سمع هذا الجزء وما قبله أبو عبد الله أحمد بن علي الشرابي، وإبرهيم بن محمد بن إبرهيم الحنائي، وعلي بن الحسين بن صدقة الشرابي، وعبد الله بن أحمد بن الحسن النيسابوري، وأحمد بن إبرهيم النيسابوري، بقراءة الشيخ أبي بكر محمد بن محمد بن عبد الله الشاشي، في شهر رمضان من سنة إحدى وأربعمائة.\nوكتب عبد الرحمن بن عمر بن نصر بن محمد بخطه.\nوسمع هذا الجزء أيضا ظفر بن المظفر الناصري، ومحمد بن علي الحداد (3) ، حفظهما الله، وكتب بخطه (4)"},{"id":"risala-shafii:38","bookId":"risala-shafii","type":"section","seq":38,"chapter":"كتاب الرسالة","title":"5- سماع في الثالث بخطه","page":"ص0","text":"سماع في الثالث بخطه (بدون تاريخ والمفهوم أنه سنة 394) سمع هذا الكتاب من أوله إلى آخره، بقراءتي ومعارضة كتابي بهذا الكتاب: أبو علي الحسين بن علي بن إبرهيم الاهوازي (1) حفظه الله، وعلي بن محمد بن إبرهيم الحنائي، نفعه الله بالعلم، ومحمد بن علي النصيبي كلاه الله، والحمد لله كثيرا، والصلاة على نبيه محمد وآله وسلم كثيرا، وحسبن الله وحده.\nوكتب عبد الرحمن بن عمر بن نصر بن محمد بخطه."},{"id":"risala-shafii:39","bookId":"risala-shafii","type":"section","seq":39,"chapter":"كتاب الرسالة","title":"6- سماع بخطه على الثالث سنة 401 وسمع هذا الكتاب من أوله إلى آخره أبو عبد الله أحمد بن علي الش","page":"ص0","text":"سماع بخطه على الثالث سنة 401 وسمع هذا الكتاب من أوله إلى آخره أبو عبد الله أحمد بن علي الشرابي، وعبد الله بن أحمد النيسابوري الخفاف، وأحمد بن إبرهيم النيسابوري وأبو إسحق إبرهيم بن محمد بن إبرهيم الحنائي، بقراءة الشيخ أبي بكر محمد بن محمد بن عبد الله الشاشى، في شهر رمضان، من سنة إحدى وأربعمائة، وحسبنا الله وحده.\nوسمع ظفر بن المظفر الناصري هذا الكتاب من أوله إلى آخره (2)"},{"id":"risala-shafii:40","bookId":"risala-shafii","type":"section","seq":40,"chapter":"كتاب الرسالة","title":"7- سماع علي أبي الحسن الحنائي بخط حمزة القلانسى سنة 416 سمع جميعه من الشيخ أبي الحسن على بن م","page":"ص0","text":"سماع علي أبي الحسن الحنائي بخط حمزة القلانسى سنة 416 سمع جميعه من الشيخ أبي الحسن على بن محمد الحنأ، رضي الله عنه، حمزة بن أحمد بن حمزة القلانسي (1) ، وذلك في ربيع الاول من سنة ست عشرة وأربعمائة.\nوالحمد لله وحده، وصلواته على محمد رسوله وعبده، وعلى أئمة الهدى من بعده، وحسبنا الله ونعم الوكيل.\nثم كرر هذا بنحوه في (ص 103 أصل) وزاد في آخره (بعد القراءة والمعارضة بالاصل) .\nوتاريخه (جمادى الاخرة سنة 416) .\nثم كرر ثالثا في (ص 111 أصل) ولكن ضاع أكثره وبقي منه سطران."},{"id":"risala-shafii:41","bookId":"risala-shafii","type":"section","seq":41,"chapter":"كتاب الرسالة","title":"8- سماع علي أبي بكر الحداد السلمي في سنة 457 بقراءة الحميدي سمع هذا الجزء من أوله إلى آخره عل","page":"ص0","text":"سماع علي أبي بكر الحداد السلمي في سنة 457 بقراءة الحميدي سمع هذا الجزء من أوله إلى آخره على الشيخ الجليل أبو بكر محمد بن علي السلمي الحداد: أصحابه أبو الحسن عبد الله (2) ، وأبو الحسين عبد الرحمن، بقراءة\nالشيخ أبو عبد الله محمد بن أبي نصر الحميدي (1) ، الرئيس أبو نصر هبة الله بن علي البغدادي (2) ، والشيخ أبو محمد عبد الله بن الحسن بن طلحة التنيسي (3) ، وولداه محمد وطلحة، وعبد الملك بن علي الحصري، ومعضاد بن علي الداراني، وحسين بن محمد المحوزي، وعبد الله بن أحمد السمرقندي (4) وحيدرة بن عبد الرحمن الدربندي، ومحمد بن محمد بن علي الطرسوسي، ومحمد بن أبي الوفاء السمرقندي.\nوذلك في سلخ صفر سنة سبع وخمسين وأربعمائة.\nوهو سماعه من تمام (5) وعبد الرحمن بن عمر بن نصر، جميعا عن ابن حبيب الحصائري، عن الربيع، في التاريخ المذكور والمدة."},{"id":"risala-shafii:42","bookId":"risala-shafii","type":"section","seq":42,"chapter":"كتاب الرسالة","title":"9- سماع آخر عليه في سنة 457 بقراءة الحافظ الحميدي وبخطه سمع جميعه من الشيخ أبو بكر محمد بن عل","page":"ص0","text":"سماع آخر عليه في سنة 457 بقراءة الحافظ الحميدي وبخطه سمع جميعه من الشيخ أبو بكر محمد بن علي الحداد: أصحابه، وهم عبد الله وعبد الرحمن ابنا الحسين بن محمد الحنائي، والرئيس أبو نصر علي بن هبة الله البغدادي، بقراءة محمد بن أبي نصر بن عبد الله الحميدي، وأبو محمد عبد الله بن الحسن بن طلحة التنيسي، وولداه محمد وطلحة، ومعضاد بن علي الداراني.\nوهو سماعه من عبد الرحمن بن نصر وتمام بن محمد، عن الحسن بن حبيب.\nوذلك في جمادى الاولى من سنة سبع وخمسين وأربعمائة."},{"id":"risala-shafii:43","bookId":"risala-shafii","type":"section","seq":43,"chapter":"كتاب الرسالة","title":"10- سماع آخر عليه في سنة 457 بقراءة الحميدي بخطين مختلفين","page":"ص0","text":"سماع آخر عليه في سنة 457 بقراءة الحميدي بخطين مختلفين، ولكن كنى فيه (أبو عبد الله) سمع هذا الجزء من أوله إلى آخره على الشيخ أبو عبد الله محمد بن علي بن موسى السلمي الحداد، بقراءة الشيخ أبو عبد الله محمد بن أبي نصر الحميدي: الشيخان أبو الحسين عبد الرحمن، وأبو الحسن عبد الله، والشيخ الرئيس أبي نصر علي بن هبة الله البغدادي.\nوذلك في شهر ربيع الاول من سنة سبع وخمسين وأربعمائة.\nوهو رواية الشيخ أبي عبد الله محمد بن علي بن موسى السلمي الحداد عن أبي القاسم تمام بن محمد الرازي وأبي القاسم عبد الرحمن بن عمر بن نصر جميعا عن الحسن بن حبيب، عن الربيع بن سليمان، عن الشافعي."},{"id":"risala-shafii:44","bookId":"risala-shafii","type":"section","seq":44,"chapter":"كتاب الرسالة","title":"11- سماع الكتاب علي ابن الحداد بخطه نفسه سنة 457 سمع مني هذا الجزء وما قبله من الاجزاء","page":"ص0","text":"سماع الكتاب علي ابن الحداد بخطه نفسه سنة 457 سمع مني هذا الجزء وما قبله من الاجزاء، وهي رسالة أبي عبد الله الشافعي رحمه الله، وهي روايتي عن الشيخين المذكورين المسميين أمام خطى هذا وعارض الشيخين (1) ... صاحباه أبو الحسن عبد الله، وأبو الحسين عبد الرحمن ابنا محمد الحنائي، والشيخ الرئيس أبي نصر علي بن هبة الله بن علي، بقراءة الشيخ أبي عبد الله محمد بن أبي نصر الحميدي.\nوذلك في ربيع الاول سنة سبع وخمسين وأربعمائة.\nحامدا لله ومصليا على رسوله وآله وسلم."},{"id":"risala-shafii:45","bookId":"risala-shafii","type":"section","seq":45,"chapter":"كتاب الرسالة","title":"12- سماع عليه أيضا بخط ظاهر بن بركات الخشوعي سنة 460 سمع جميعه علي الشيخ الحافظ محمد بن علي بن","page":"ص0","text":"سماع عليه أيضا بخط ظاهر بن بركات الخشوعي سنة 460 سمع جميعه علي الشيخ الحافظ محمد بن علي بن محمد الحداد السلمي: صاحبه أبو محمد هبة الله بن أحمد الاكفاني (2) ، بقراءة أبي الفتيان عمر بن أبي الحسن الدهستاني (3) ، وعبد العزيز بن علي الكازروني (4) ، وعبد الله بن أحمد السمرقندي، وأبو الكرم الخضر بن عبد المحسن الفراء (5) ، وكاتب الاسماء طاهر\nبن بركات بن إبرهيم الخشوعي (1) .\nوسمع من أول الجزء إلى الزكاة إبرهيم بن حمزة الجرجرائي، وحيدرة بن عبد الرحمن الدربندي، ومحمد بن أحمد الدرابجردي، في شهر ربيع الاخر سنة ستين وأربعمائة.\nثم كرر هذا السماع بنحوه (ص 62 من الاصل) بخط طاهر الخشوعي في التاريخ المذكور، ولم يذكر فيه \" إبرهيم بن حمزة \" ومن بعده.\nثم كرر أيضا بنحوه في (ص 109 من الاصل) بخط طاهر، في جمادى الاولى سنة 460 وزيد فيه بين السطور: (وسمع مع الجماعة عبد الله بن أبي بكر السمرقندي بالتاريخ) لانه لم يذكر فيه.\nثم كتب تحته بخط ابن الاكفاني (وعبد الله بن أحمد السمرقندي سمع مع الجماعة في التاريخ.\nوكتب هبة الله بن أحمد الاكفاني، وصح وثبت) ."},{"id":"risala-shafii:46","bookId":"risala-shafii","type":"section","seq":46,"chapter":"كتاب الرسالة","title":"13- سماع علي هبة الله بن الاكفاني بخط عبد الرحمن بن صابر السلمي سنة 495 سمع جميع ما في هذا الج","page":"ص0","text":"سماع علي هبة الله بن الاكفاني بخط عبد الرحمن بن صابر السلمي سنة 495 سمع جميع ما في هذا الجزء، وهو ما في الورقة البيضاء وعلى وجهها (الجزء الاول من رسالة محمد بن إدريس الشافعي رحمه الله (2) علي الشيخ الفقيه الامين أبي محمد هبة الله بن أحمد بن محمد الاكفاني رضي الله عنه -: الشيخ الفقيه أبو الفتح نصر الله بن محمد بن عبد القوي المصيصي (3) ، وأبو المحاسن محمد بن الحسين\nبن الحسن الشهرستاني، بقراءة كاتب الاسماء عبد الرحمن بن أحمد بن علي بن صابر السلمي (1) ، في سنة خمس وتسعين وأربعمائة، في المسجد الجامع بدمشق."},{"id":"risala-shafii:47","bookId":"risala-shafii","type":"section","seq":47,"chapter":"كتاب الرسالة","title":"14- سماع عليه بخط محمد بن الحسين الشهرستاني سنة 496 سمع هذا الجزء","page":"ص0","text":"سماع عليه بخط محمد بن الحسين الشهرستاني سنة 496 سمع هذا الجزء، وهو الجزء الثاني من كتاب الرسالة، علي الشيخ الفقيه الامين جمال الامناء أبو محمد هبة الله بن أحمد بن محمد الاكفاني، بقراءة الشيخ أبو محمد عبد الرحمن بن أحمد بن علي بن صابر السلمي، والشيخ الفقيه الامام أبو الفتح نصر الله بن محمد بن عبد القوي المصيصي، وكاتب السماع محمد بن الحسين بن الحسن القفنهي الشهرستاني.\nوذلك في التاسع والعشرين من رجب سنة ست وتسعين وأربعمائة، وصح وثبت.\nوسمع مع الجماعة علي بن الحسن بن أحمد الحوراني القطان، في تاريخه."},{"id":"risala-shafii:48","bookId":"risala-shafii","type":"section","seq":48,"chapter":"كتاب الرسالة","title":"15- سماع عليه أيضا بخط علي بن الحسن المري سنة 499 سمع جميع هذا الجزء من أوله إلى آخره علي الشي","page":"ص0","text":"سماع عليه أيضا بخط علي بن الحسن المري سنة 499 سمع جميع هذا الجزء من أوله إلى آخره علي الشيخ الفقيه الامين أبي محمد هبة الله بن أحمد بن محمد الاكفاني رضي الله عنه -: الشيخ الفقيه الامام أبي الفتح\nنصر الله بن محمد بن عبد القوي المصيصي، بقراءة أبي محمد عبد الرحمن بن أحمد\nبن علي بن صابر السلمي، وأبو المعالي سعيد (1) بن الحسن بن المحسن الشهرستاني، وأبو المفضل محمد (2) ، وأبو المكارم عبد الواحد (3) ، ابنا محمد بن المسلم بن هلال، وأبو منصور عبد الباقي بن محمد بن عبد الباقي التميمي، وأبو القاسم عبد الرحمن بن أحمد بن الحسن بن زرعة، ومحمد بن عبيد بن منصور الهلالي، وسمع جميعه كاتب الاسماء علي بن الحسن بن أحمد بن عبد الوهاب المري.\nوذلك في شهر ربيع الاخر، وفي العشر الاول من جمادي الاولى سنة تسع وتسعين.\nوسمع النصف الاخير أبو الحسن أحمد بن عبد الباقي بن الحسين القيسي مع الجماعة في التاريخ المذكور.\nثم كتب تحته بخط آخر: وسمع جميع الجزء مع الجماعة القاضي أبو المحاسن محمد بن الحسين بن الحسن الشهرستاني، وعارض بنسخته."},{"id":"risala-shafii:49","bookId":"risala-shafii","type":"section","seq":49,"chapter":"كتاب الرسالة","title":"16- سماع آخر عليه بخط عبد الباقي بن محمد التميمي سنة 509 سمع جميع ما في هذا الجزء","page":"ص0","text":"سماع آخر عليه بخط عبد الباقي بن محمد التميمي سنة 509 سمع جميع ما في هذا الجزء، وهو ما في الورقة البيضاء وعلى وجهها (الجزء الاول من رسالة أبي عبد الله محمد بن إدريس الشافعي) على الشيخ الفقيه الاجل الامين جمال الامناء أبي محمد هبة الله بن أحمد بن محمد الاكفاني رضي الله عنه، بقراءة الشيخ أبي محمد عبد الرحمن بن أحمد بن علي بن صابر السلمي -: ابنه أبو المعالي عبد الله (4) ، والشيوخ أبو الفضل محمد، وأبو المكارم عبد الواحد،\nابنا محمد بن المسلم بن الحسن بن هلال، وأبو البركات الخضر بن شبل بن الحسين\nالحارثي (1) ، وأبو طاهر إبرهيم بن الحسن بن طاهر بن الحصني، وأبو إسحق إبرهيم بن طاهر بن بركات الخشوعي (2) ، وأبو طالب بن محسن بن علي المطاردي، وتمام بن محمد بن عبد الله بن أبي جميل، وكاتب السماع عبد الباقي بن محمد بن عبد الباقي بن محمد التميمي الموصلي.\nوسمع مع الجماعة أبو المعالي عبد الصمد بن الحسين بن أحمد بن تميم التميمي (3) .\nوسمع من (الفرائض المنصوصة التي سن رسول الله صلى الله عليه معها) القاضي أبو الفوارس مطاعن بن مكارم بن عمار بن عجرمة الحارثي، وأبو الحسين أحمد بن راشد بن محمد القرشي، وأبو القاسم نصر بن المسلم بن مصر النجار، وابنه عبد الرزاق (4) ، وتمام (5) بن حيدرة الانصاري.\nوذلك في جمادي الاخرى سنة تسع وخمسمائة، بدمشق، حماها الله تعالى ورسوله.\nوالحمد لله، وصلى الله على سيدنا محمد وآله وسلم.\nوسمع الجماعة المذكورون بأعلى ظهر الجزء الاول أيضا في التاريخ المذكور، والحمد لله وحده.\nوسمع من (باب فرض الله طاعة رسول الله مقرونة بطاعة الله ومذكورة وحدها) إلى آخر الجزء -:\nأبو محمد عبد الهادي بن عبد الله الاتابكي (1) ، وأبو عبد الله محمد بن شبل بن الحسين الحارثي، في التاريخ المذكور.\nوالحمد لله، وصلى الله على سيدنا محمد نبيه وآله وسلم.\nهذا السماع مكرر بنحوه في الجزء الثاني (ص 59 أصل) بخط أحمد بن راشد بن محمد القرشي في نفس التاريخ، وفيه (وسيدهم بن حيدرة الانصاري) وسيأتي الكلام عليه في السماع بعده.\nثم كرر في الثالث كذلك (ص 109 أصل) وفيه زيادة (وأبو تمام كامل بن أحمد بن محمد بن أبي جميل) ."},{"id":"risala-shafii:50","bookId":"risala-shafii","type":"section","seq":50,"chapter":"كتاب الرسالة","title":"17- سماع آخر عليه بخط أحمد بن راشد القرشي سنة 509 سمع من أول هذا الجزء إلى آخره","page":"ص0","text":"سماع آخر عليه بخط أحمد بن راشد القرشي سنة 509 سمع من أول هذا الجزء إلى آخره (الفرائض المنصوصة التي سن رسول الله صلى الله عليه معها) على الشيخ الفقيه الامين جمال الامناء أبي محمد هبة الله\nبن أحمد بن محمد الاكفاني، صان الله قدره ورضي عنه، بقراءة الشيخ أبي محمد عبد الرحمن بن أحمد بن علي بن صابر السلمي، أبو الرضا سيدهم بن تمام بن حيدرة الانصاري (2) ، وأبو المجد عبد الواحد بن مهذب التنوخي (3) ، وأبو بكر محمد بن الفقيه أبي الحسن علي بن المسلم السلمي (4) ، وكاتب الاسماء أحمد بن\nراشد بن محمد القرشي المكبري، في رجب سنة تسع وخمسمائة.\nوكمل له سماع الجزء جميعه."},{"id":"risala-shafii:51","bookId":"risala-shafii","type":"section","seq":51,"chapter":"كتاب الرسالة","title":"18- سماع آخر على سنة 518 بخط عبد الكريم بن الحسين الحصني سمع جميع هذا الجزء","page":"ص0","text":"سماع آخر على سنة 518 بخط عبد الكريم بن الحسين الحصني سمع جميع هذا الجزء، وهو الجزء الاول، على الشيخ الفقيه الامين جمال الامناء أبي محمد محمد هبة الله بن أحمد بن محمد الاكفاني رضي الله عنه، وعورض به نسخة فيها ذكر سماعه -: الفقيه الاجل الاوحد أبو الحسن علي بن المسلم بن محمد بن الفتح السلمي (1) ، وولده أبو بكر، وسمع الشيوخ أبو القاسم النجيب\nيحيى بن علي بن محمد بن زهير السملي (2) ، وأبو علي الحسن بن مسعود بن الوزير (3) ، وأبو القاسم علي بن الحسن بن هبة الله بن عبد الله (4) ، وأبو عبد الله الحسين بن الخضر بن الحسين بن عبدان، وأبو التمام كامل بن محمد بن كامل التميمي، وأبو بكر محمد بن علي بن أحمد بن منصور الغساني (5) ،\nوأبو القاسم الحسين بن أحمد بن عبد الواحد (1) الاسكندراني، وأبو الثناء محمود بن معالي بن الحسن بن الخضر الانصاري النجار، وأبو بكر عبد الرحمن بن أحمد بن الحسين القيسي (2) ، وكاتب السماع عبد الكريم بن الحسن بن طاهر بن يمان الحصني ثم الحموي (3) ، بقراءة الفقيه أبي القاسم وهب بن سلمان بن\nأحمد السلمي (4) ، وذلك في العشر الثاني من رمضان سنة ثمان عشرة وخمسمائة.\nوسمع مع الجماعة المذكورين أبو محمد إسمعيل بن إبرهيم بن محمد أحمد (5) القيسي، وعيسى بن نبهان الضرير البرداني، وأبو طاهر يونس بن سلمان بن أحمد السلمي، وبركات بن إبرهيم بن طاهر الخشوعي (6) ، وعمر بن ناصر النجار، وأبو عمر عثمان بن علي بن الحسن اليوسي الربعي، في التاريخ."},{"id":"risala-shafii:52","bookId":"risala-shafii","type":"section","seq":52,"chapter":"كتاب الرسالة","title":"19- سماع عليه بخط عبد الكريم أيضا سنة 519 وسمع جميعه مع الجماعة المذكورة الشيخ الفقيه أبو القا","page":"ص0","text":"سماع عليه بخط عبد الكريم أيضا سنة 519 وسمع جميعه مع الجماعة المذكورة الشيخ الفقيه أبو القاسم علي بن الحسن بن الحسن الكلابي (1) ، والشيخ أبو العباس أحمد بن أبي القاسم بن منصور في العشر الثاني من ربيع الثاني من سنة تسع عشرة وخمسمائة.\nوسمع من أوله إلى أول (باب الناسخ والمنسوخ الذي تدل عليه السنة بالاجماع) أبو عبد الله محمد، وأبو الفضل أحمد، ابنا الحسن بن هبة الله بن عبد الله (2) في التاريخ.\nهذا السماع والذي قبله تكرر في مجلس واحد في الجزء الثاني (ص 60 أصل) بخط عبد الكريم الحصني أيضا في العشر الاخير من رمضان سنة 518 وفي آخره: أن محمدا وأحمد ابنا الحسن بن هبة الله، وهما أخوا الحافظ ابن عساكر، سمعا نصف الجزء الثاني فقط، فيظهر أنهما سمعاه على الشيخ ثم سمعا في السنة التالية بعض الجزء الاول.\nونص أول هذا السماع: \" سمع جميع ما في هذا الجزء على الشيخ الفقيه الامين جمال الامناء أبي محمد هبة الله بن أحمد بن محمد بن الاكفاني رضي الله عنه، وهو الجزء الثاني من الرسالة، بعد وقوفه على ذكر سماعه من أبي بكر السلمي الحداد: الشيوخ الفقيه الاجل الامام جمال الاسلام أبو الحسن علي بن المسلم بن محمد بن الفتح السلمي وولده أبو بكر محمد \" الخ وزيد من السامعين \" أبو القاسم علي بن محمد بن أبي العلاء المصيصي، وعيسى بن قحطان بن عبد الله الشرواني، وأبو محمد عبد الله بن عثمان السقلي، وأبو بكر وأخوه عمر ابنا ناصر النجار، ومحمد بن بريعس (3) الوزيري، وأبو الفضل بن صرمة بن علي بن محمد الحراني التاجر، وأبو محمد عبد الرحمن بن عبد الواحد بن مرة \".\nثم كرر مختصرا في الثالث (ص 109 أصل) بخط \" وهب بن سلمان بن أحمد السلمي \" في شهر ربيع الاخر سنة 519."},{"id":"risala-shafii:53","bookId":"risala-shafii","type":"section","seq":53,"chapter":"كتاب الرسالة","title":"20- سماع على أبي المكارم عبد الواحد بن هلال بخط علي بن عقيل بن علي سنة 563 وكتب سنة 570 قرأت ج","page":"ص0","text":"سماع على أبي المكارم عبد الواحد بن هلال بخط علي بن عقيل بن علي سنة 563 وكتب سنة 570 قرأت جميع كتاب رسالة الشافعي رحمه الله على الشيخ الامام أبي المكارم عبد الواحد بن محمد بن المسلم بن هلال، بحق سماعه من ابن الاكفاني، فسمع ابنه أبو البركات، وحفيده أبو الفضل.\nوكتب علي بن عقيل بن علي بن هبة الله الشافعي (1) ، وذلك في مجالس، آخرها يوم الاحد تاسع عشر جمادي الاخرة سنة ثلاث وستين وخمسمائة، بدار الشيخ بدمشق.\nوصح وثبت.\nونقلت سماعي إلى هنا في رجب سنة ستين وست وخمسمائة (2) .\nهذا السماع كرر بنصه تقريبا بنفس الخط في (ص 103 أصل) ."},{"id":"risala-shafii:54","bookId":"risala-shafii","type":"section","seq":54,"chapter":"كتاب الرسالة","title":"21- سماع علي الحافظ ابن عساكر بخط عبد الرحمن بن أبي منصور سنة 567 سمع جميع هذا الجزء على سيدنا","page":"ص0","text":"سماع علي الحافظ ابن عساكر بخط عبد الرحمن بن أبي منصور سنة 567 سمع جميع هذا الجزء على سيدنا الشيخ الفقيه الامام العالم الحافظ الثقد ثقة الدين صدر الحفاظ ناصر السنة محدث الشأم أبي القاسم علي بن الحسن بن هبة الله\nالشافعي أيده الله: - صاحبه الشيخ الفقيه الامام العالم ضياء الدين أبو الحسن علي بن عقيل بن علي (1) الشافعي نفعه الله بالعلم (2) ، وحافده (3) أبو طاهر محمد بن الشيخ الفقيه أبي محمد القاسم، وبنو أخيه أبو المظفر عبد الله (4) ، وأبو منصور عبد الرحمن (5) ، وبو المحاسن نصر الله، وأبو نصر عبد الرحيم (6) ، بنو أبي عبد الله محمد بن الحسن (7) ، بقراءة القاضي بهاء الدين أبي المواهب الحسن (8) ، وأخوه الشيخ الفقيه أبو القاسم الحسين، ابنا القاضي أبي الغنائم هبة الله بن محفوظ بن صصري (9) ، والشيخ الفقيه أبو محمد عبد الله بن محمد بن سعد الله الحنفي، والامير أبو الحرث عبد الرحمن بن محمد بن مرشد بن منقذ\nالكناني (1) ، وأبو عبد الله محمد بن شيخ الشيوخ أبي حفص عمر بن أبي الحسن الحموي (2) ، وأبو الحسين عبد الله بن محمد بن هبة الله، والفقيه أبو نصر محمد بن هبة الله بن محمد (3) ، الشيرازيان، وخالد بن منصور بن إسحق الاشنهي، وعبد الرحمن بن عبد الله (4) ، وأبو عبد الله الحسين بن عبد الرحمن بن الحسين بن عبدان، وأبو العليان الحسين بن محمد بن أبي نصر الهداري (5) ، والحسن بن علي بن عبد الله الباعيثاني (6) ، والخطيب بن عبد الوهاب بن أحمد بن عقيل السلمي، وعلي بن خضر بن يحيى الارموي، وأبو بكر محمد بن الشيخ (7) الامين أبي الفهم عبد الوهاب بن عبد الله الانصاري (8) ، والوجيه أبو القاسم بن محمد بن معاذ الحرقاني (9) ، ومسعود بن أبي الحسن بن عمر التفليسي، وإسمعيل بن\nعمر بن أبي القاسم الاسفند ابادي (1) ، وموسى بن علي بن عمر الهمداني، وعبد الرحمن بن علي بن محمد الجويني، الصوفيون، وحسن بن إسمعيل بن حسن الاسكندراني، وفضالة بن نصر الله بن حواش العرضي، وعيسى بن أبي بكر بن أحمد الضرير (2) ، وأبو بكر بن محمد بن طاهر (3) البروجردي، ومكارم بن عمر بن أحمد (4) ، وحمزة بن إبرهيم بن\nعبد الله، وأبو الحسين بن علي بن خلدون، وبركاسنا بن فرجاوز بن فريون الديلمي، وعثمان بن محمد بن أبي بكر الاسفرايني، وعبد الله بن ياسين بن عبد الله اليمني، وفارس بن أبي طالب بن نجا، وفضائل بن طاهر بن حمزة، وإسحق بن سليمان بن علي، وأحمد بن أبي بكر بن الحسين البصري، وأحمد بن ناصر بن طعان البصراوي (5) ، وإبرهيم بن مهدي بن علي الشاغوري، وعبد القادر، وعبد الرحمن، ابنا أبي عبد الله محمد بن الحسن العراقي (6) ، وعبد الرحمن بن أبي رشيد بن أبي نصر الهمداني (7) وعثمان بن إبراهيم بن الحسين، وكاتب الأسماء عبد الرحمن بن أبي منصور\nبن نسيم بن الحسين بن علي الشافعي.\nوذلك في يومي الخميس والاثنين ثامن\nصفر سنة سبع وستين وخمسمائة، بالمسجد الجامع بدمشق حرسها الله تعالى، وحده، وصلواته على محمد وآله.\nكرر هذا السماع في الجزء الثاني (ص 60 أصل) بتارخ (الخميس والاثنين حادي عشر وخامس عشر صفر) .\nثم كرر في الجزء الثالث (ص 110 أصل) بتاريخ (الخميس والاثنين ثامن عشر وثاني وعشرين صفر) من السنة المذكورة، وكلاهما بخط الكاتب نفسه.\nوقد بينا الفروق بينهما وبين سماع الجزء الاول هذا في الحاشية."},{"id":"risala-shafii:55","bookId":"risala-shafii","type":"section","seq":55,"chapter":"كتاب الرسالة","title":"22- سماع علي أبي المعالي عبد الله بن عبد الرحمن بن صابر السلمي وأبي طاهر بركات بن إبرهيم الخشو","page":"ص0","text":"سماع علي أبي المعالي عبد الله بن عبد الرحمن بن صابر السلمي وأبي طاهر بركات بن إبرهيم الخشوعي بخط عبد القادر الرمادي؟ سنة 571 سمع جميع هذا الجزء، وهو الاول من (كتاب الرسالة) وما في بطن القائمة البيضاء التي على أول الجزء (1) ، على الشيخ أبي المعالي عبد الله بن عبد الرحمن بن أحمد بن علي بن صابر السلمي، بروايته عن الامين أبي محمد هبة الله الاكفاني في سنة تسع وخمسمائة، وعلى الشيخ أبي طاهر بركات بن إبرهيم الخشوعي -: الجزء دون الورقة التي في أوله البيضاء (2) ، بروايته عن الشيخ الامين أبي محمد هبة الله في سنة ثماني عشرة وخمسمائة،\nبقراءة صاحب النسخة الشيخ الاجل الامين ضياء الدين أبي الحسن علي بن\nعقيل بن علي التغلبي -: ولده أبو عبد الله الحسن جبره الله، والشريف إدريس بن حسن بن علي الادريسي، وعبد الخالق بن حسن بن هياج، وأبو إسحق إبرهيم بن علي بن إبرهيم الاسكندراني، وإبرهيم بن بركات بن إبرهيم الخشوعي (1) ، وأحمد بن علي بن يعلى السلمي، وأحمد بن عساكر بن عبد الصمد، وأبو الحسن علي بن عسكر الحموي المعروف بابن زين النجار، وكاتب السماع عبد القادر بن عبد الله الرهاوي (2) .\nوصح ذلك في جامع دمشق، في العشر الاوسط من شهر رمضان إحدى وسبعين وخمسمائة.\nوالحمد لله رب العالمين حمدا كثيرا.\nثم كرر هذا السماع على الجزء الثاني (ص 103 أصل) بخط الكاتب في التاريخ، ولكنه أخطأ فيه فجعل الشيخ أبا طاهر بركات الخشوعي أحد السامعين، مع أنه أحد الشيخين اللذين قرئ عليهما الكتاب.\nثم كرر ثالثا بزيادات، فرأينا إثباته بنصه، وهو: 23 - سماع على أبى المعالي وأبي طاهر بخط عبد القادر الرهاوي سنة 571 سمع جميع هذا الجزء على الشيخ أبى المعالي عبد الله بن عبد الرحمن بن أحمد بن علي بن صابر السلمي بحق سماعه فيه من الامين أبي محمد هبة الله\nالاكفاني في سنة تسع وخمسمائة، وعلى الشيخ أبي طاهر بركات بن إبرهيم بن\nطاهر الخشوعي، بحق سماعه فيه من الامين أبي محمد هبة الله سنة تسع عشرة وخمسمائة -: أبو عبد الله الحسن، بن صاحب النسخة الشيخ الاجل الامين أبي الحسن علي بن عقيل بن علي التغلبي جبره الله، وإبرهيم، وأبو الفضل، ابنا بركات بن طاهر الخشوعي، وعبد الكريم بن محمد بن محلى الكفرطابي (1) ، وإبرهيم بن علي بن إبرهيم الاسكندراني، والشريف إدريس بن حسن بن علي الادريسي، وعبد الخالق بن حسن بن هياج، وجامع بن باقي بن عبد الله التميمي، وأحمد بن علي بن يعلى السلمي، وعبد الغني بن سليمان بن عبد الله المغربي، وأحمد بن عساكر بن عبد الصمد، وكاتب السماع عبد القادر بن عبد الله الرهاوي، بقراءته.\nوصح ذلك بجامع دمشق، في العشر الاوسط من شهر رمضان من سنة إحدى وسبعين وخمسمائة.\nوكذلك سمع أبو عبد الله بن ضياء الدين أبي الحسن علي بن عقيل الجزءين اللذين قبل هذا، وصح الاول بقراءة أبيه، والثاني بقراءة الرهاوي في التاريخ المذكور."},{"id":"risala-shafii:56","bookId":"risala-shafii","type":"section","seq":56,"chapter":"كتاب الرسالة","title":"24- سماع علي بن أبي طاهر الخشوعي بخط بدل بن أبي المعمر سنة 587 سمع جميع هذا الجزء","page":"ص0","text":"سماع علي بن أبي طاهر الخشوعي بخط بدل بن أبي المعمر سنة 587 سمع جميع هذا الجزء، وهو الاول، على الشيخ الامين أبي طاهر بركات بن إبرهيم بن طاهر القرشي الخشوعي، بحق سماعه فيه من ابن الاكفاني، بقراءة الفقيه أبي محمد عبد القوي بن عبد الخالق بن وحشي، وأبو القاسم علي\nبن الامام الحافظ أبي محمد القاسم علي بن الحسن بن هبد الله\nبن عبد الله الشافعي (1) ، وأبو الحسن محمد، وأبو الحسين إسمعيل، ابنا الشيخ أبي جعفر أحمد بن علي بن أبي بكر بن إسمعيل القرطبي (2) ، والفقيه أبو الفضل جعفر بن عبد الله بن طاهر، ومثبت السماع بدل بن أبي المعمر بن إسمعيل التبريزي (3) ، وآخرون بفوات.\nوذلك في شهور سنة سبع وثمانين وخمسمائة، بجامع دمشق حرسها الله تعالى، وصح.\nوسمع جميع هذا الجزء مع الجماعة في التاريخ أبو إسحق إبرهيم بن محمد بن أبي بكر بن محمد القفصي (4) .\nثم كرر هذا السماع في الجزء الثاني (ص 103 أصل) بخط بدل بن أبي المعمر (في مجالس آخرها في صفر سنة ثمان وثمانين وخمسمائة) وفيه (بحق إجازته) بدل (بحق سماعه فيه) ثم كرر في الثالث بزيادات، فرأينا إثبات نصه، وهو:"},{"id":"risala-shafii:57","bookId":"risala-shafii","type":"section","seq":57,"chapter":"كتاب الرسالة","title":"25- سماع علي بن أبي طاهر الخشوعي بخط بدل سنة 588 سمع جميع هذا الجزء","page":"ص0","text":"سماع علي بن أبي طاهر الخشوعي بخط بدل سنة 588 سمع جميع هذا الجزء، وهو الثالث، على الشيخ الامين أبي طاهر بركات بن إبرهيم بن طاهر القرشي الخشوعي، بحق سماعه فيه من ابن الاكفاني، بقراءة الشيخ أبي محمد عبد القوي بن عبد الخالق بن وحشي السلمي -: أبو القاسم علي بن الامام الحافظ أبي محمد القاسم بن أبي القاسم علي بن الحسن بن هبد الله بن عبد الله، وأبو الحسن محمد، وأبو الحسين إسمعيل، ابنا الامام جعفر بن علي بن أبي بكر القرطبي، والفقيه أبو بكر بن حرز الله بن حجاج، وأبو عبد الله محمد بن أبي بكر بن محمد القفصي، وابنه إبرهيم، ومثبت السماع بدل بن أبي المعمر بن إسمعيل التبريزي.\nوسمع الجزء سوى خمس قوائم من أوله: أبو منصور بن أحمد بن محمد صصري، وأبو عبد الله محمد بن راشد بن عبد الكريم بن الهادي، وآخرون بفوات.\nوذلك في شهر صفر سنة ثمان وثمانين وخمسمائة، بدمشق.\nوفي هذا السماع من الفوائد: أن إبرهيم بن محمد بن أبي بكر القفصي سمع الاجزاء الثلاثة، ولكن أباه محمد بن أبي بكر لم يسمع إلا الجزء الثالث.\nوأن الكاتب سمى أوراق الكتاب (قوائم) ."},{"id":"risala-shafii:58","bookId":"risala-shafii","type":"section","seq":58,"chapter":"كتاب الرسالة","title":"26- سماع على تاج الدين محمد بن أبي جعفر القرطبي","page":"ص0","text":"سماع على تاج الدين محمد بن أبي جعفر القرطبي، وعز الدين\nالاربلي، وإبرهيم بن أبي طاهر الخشوعي، وزكي الدين البرزالي بخط عبد الجليل الابهري سنة 635 سمع جميع هذا الجزء من (رسالة الشافعي رضي الله عنه) على المشايخ الاجلة الثقات، صاحب الكتاب الامام العالم الحافظ تاج الدين أبي الحسن محمد بن\nأبي جعفر بن علي القرطبي، والفقيه الامام عز الدين أبي محمد عبد العزيز بن عثمان بن أبي طاهر الاربلي، وزكي الدين أبي إسحق إبرهيم بن بركات بن إبرهيم الخشوعي، بسماع الخشوعي فيه من والده ومن ابن صابر كما ترى (1) ، وبسماع الامام تاج الدين القرطبي وعز الدين الاربلي من أبي طاهر بركات حسب، بقراءة الامام الحافظ زكي الدين أبي عبد الله محمد بن يوسف بن محمد البرزالي (2) -: الولد تقي الدين أبو بكر محمد بن الامام تاج الدين المسمع المبدوء بذكره، والحاج أبو علي حسن بن أبي عبد الله بن صدقة الصقلي (3) ، وأبو المرجا سالم بن تمام بن عنان العرضي، وابنه عبد الله، وعبد الرحمن اليونسي بن يونس بن إبرهيم، وآباء عبد الله: محمد بن يوسف بن أحمد النحاني (4) ومحمد بن علي بن محمد اليمني، ومحمد بن صديق بن بهرام الصفار، ومحمد بن يوسف بن يعقوب الاربلي (5) ، وأبو الفضل يوسف بن محمد بن عبد الرحمن الناسخ، وإبرهيم بن داود بن ظافر الفاضلي (6) ، ومخلص بن المسلم بن عبد الرحمن التكروري، والشمس أبو محمد\nعبد الواسع بن عبد الكافي بن عبد الواسع الابهري (1) ، وابن عمه كاتب السماع عبد الجليل بن عبد الجبار بن عبد الواسع الابهري (2) ، عفا الله عنه.\nوسمع ربيبه إبرهيم بن عبد الوهاب بن علي الهمداني، والعماد أحمد بن يحيى بن عبد الرزاق، جميعه سوى الجلس العاشر، وهو معلم في الحاشية بخط الامام تاج الدين المسمع، أوله (باب النهي عن معنى دل عليه معنى) .\nوسمع الشرف يوسف بن الحسن بن بدر النابلسي (3) ، والضياء أبو الحسن علي بن محمد بن علي البالسي (4) ، ومحمد بن سيد بن إبرهيم الحلاوي: جميعه سوى من أول المجلس الثاني عشر إلى آخر الجزء، وهو ... (5) وفات البيضاء البالسي المجلس السابع أيضا، وهو معلم أيضا بخط الامام تاج الدين.\nوسمع ... (6) وصح لهم ذلك في مجالس، آخرها في جمادي الاخرة سنة خمس وثلاثين وستمائة بالاشرفية.\nهذا السماع مذكور في الجزء الاول (ص 51 أصل) ولكن آخره ضاع بتأكل الكتابة في ذيل الصفحة، ولذلك اكتفينا باثباته من الجزءين الثاني والثالث.\nوفي الجزء الاول زيادة بعد \" محمد بن تاج الدين القرطبي \": (ويوسف بن الامام زكي الدين البرزالي القارئ) وزيادة (عبد الرحيم بن) مخلص بن المسلم، بعد ذكر أبيه.\nثم كرر في الثالث ورأينا إثبات نصه، وهو:\nسماع على المشايخ الاربعة أنفسهم بخط عبد الجليل الابهري سنة 635 سمع جميع هذا الجزء الثالث من (كتاب الرسالة، للامام المعظم الشافعي المطلبي رضي الله عنه) على المشايخ الثلاثة الاجلة الامناء: صاحب النسخة الامام العالم الحافظ تاج الدين شرف الحفاظ أبي الحسن محمد بن أبي جعفر بن علي القرطبي،\nوالفقيه الامام عز الدين أبي محمد عبد العزيز بن عثمان بن أبي طاهر الاربلي، وزكي الدين أبي إسحق إبرهيم بن بركات بن إبرهيم الخشوعي، بحق سماعهم من أبي طاهر بركات الخشوعي، وبسماع ولده أيضا من أبي المعالي بن صابر، بسماعهما عن ابن الاكفاني، بقراءة الامام العالم الحافظ زكي الدين أبي عبد الله محمد بن يوسف بن محمد البرزالي -: الولد النجيب تقي الدين أبو بكر محمد بن الامام تاج الدين القرطبي، أحد المسمعين المبدوء بذكر اسمه، والحاج أبو علي حسن بن أبي عبد الله بن صدقة الصقلى، وأبو القاسم عبد الرحمن اليونسي بن يونس بن إبرهيم، وأبو الفضل يوسف بن محمد بن عبد الرحمن المصري الناسخ، والشمس أبو عبد الله محمد بن يوسف بن أحمد بن خلف المحاني، والعماد أحمد بن يحيى بن عبد الرزاق المقدسي، وأبو عبد الله محمد بن يوسف بن يعقوب الاربلي، ابن ابن أخي الشيخ عز الدين الاربلي أحد المسمعين، ومحمد بن صديق بن بهرام الصفار، وأبو إسحق إبرهيم بن داود بن ظافر الفاضلي، والشمس أبو محمد عبد الواسع بن عبد الكافي بن عبد الواسع الابهري، وابن عمه كاتب السماع عبد الجليل بن عبد الجبار الابهري عفا الله عنه.\nوسمع ربيبه إبرهيم بن عبد الوهاب بن علي الهمداني من أوله إلى آخره المجلس الرابع عشر،\nوهو معلم بخط الامام تاج الدين، وهو خمسة أوراق من أوله.\nوسمع سالم بن تمام بن عنان العرضي وابنه عبد الله جميعه سوى أربعة أوراق من آخره، وهو المجلس التاسع عشر، المجلس الاخير.\nوسمع عثمان بن أبي محمد بن بركات الخشوعي (1) سوى خمسة أوراق من أوله، مثل ما سمع إبرهيم الهمداني.\nوسمع مخلص بن المسلم بن عبد الرحمن التكروري وولده عبد الرحيم من أوله إلى آخر المجلس السابع عشر المعلم بخط الامام تاج الدين، وسمع الشهاب أبو عبد الله\nمحمد بن علي بن محمد اليمني جميعه سوى المجلسين الخامس عشر والسادس عشر.\nوبلاغ المجالس كلها معلم في الاجزاء الثلاثة بخط الامام الحافظ تاج الدين القرطبي أدام الله توفيقه، يكشف منه عدد المجالس لاصحاب الفوات.\nوقراءة الكتاب كله في تسعة عشر مجلسا، آخرها يوم الجمعة ثامن عشر شهر شعبان المبارك سنة خمس وثلاثين وستمائة، بالكلاسة بزاوية الحديث الاشرفيه الفاضلية بجامع دمشق المحروسة.\nوصح."},{"id":"risala-shafii:59","bookId":"risala-shafii","type":"section","seq":59,"chapter":"كتاب الرسالة","title":"28- سماع على إسمعيل بن شاكر التنوخي","page":"ص0","text":"سماع على إسمعيل بن شاكر التنوخي، وشرف الدين الاربلي، وشمس الدين بن مكتوم، وعبد الله بن بركات الخشوعي بخط علي بن المظفر الكندي سنة 656 سمع جميع هذا الكتاب على المشايخ الاربعة: الامام تقي الدين أبي محمد إسمعيل بن إبرهيم بن أبي اليسر شاكر بن عبد الله التنوخي (2) ، والامام\nالاديب شرف الدين أبي عبد الله الحسين بن إبرهيم بن الحسين الاربلي (1) ، والمقرئ شمس الدين أبي الحجاج يوسف بن مكتوم بن أحمد القيسي (2) ، والاصيل أبي محمد عبد الله بن بركات بن إبرهيم الخشوعي (3) ، بسماعهم لجميعه، سوى الاربلي فإن سماعه من الجزء الثالث من الاصل، من أبي طاهر الخشوعي وهو محدد فيه -: صاحبه الامام العالم القاضي الزاهد محيي الدين أبو حفص عمر بن موسى بن عمر بن موسى بن محمد بن جعفر الشافعي، والامام العالم\nالمفتي شمس الدين أبو الحسن علي بن محمود بن علي الشهرزوزي (4) ، وابناه محمد وأحمد، والامام سيف الدين داود بن عيسى بن عمر الهكاري، بعضه بقراءته وأكثره بقراءتي، والامام العالم الحافظ فخر الدين أبو عبد الله محمد بن يوسف بن محمد النوفلي المعروف بالكنجي (5) ، وابنه جعفر حاضر، والمفيد شرف الدين؟ أبو عبد الله محمد بن أبي القاسم بن أبي طالب الانصاري، وشمس الدين محمد (6) ، ومحيي الدين يحيى، ابنا كمال الدين أحمد بن نعمة بن أحمد المقدسي، وعبد اللطيف بن الامام المفتي تقي الدين محمد بن رزين الحموي (7) ، وجمال الدين\nأحمد بن عبد الله بن الحسين، وإبرهيم بن المسمع الاول (1) ، وأحمد\nوعبد الكريم، ابنا الامام كمال الدين عبد الواحد الزملكاني (2) ، وعبد القادر بن مجد الدين يحيى بن يحيى الخياط، وأخوه لامه يوسف بن الامام شمس الدين محمد بن إبرهيم (3) ، أسباط المسمع الاول، ومحمد بن مجد الدين بن عبد الله بن الحسين، وأبو بكر بن محمد بن أبي الفضل الاخلاطي، الشافعيون، والفقيهان أبو العباس أحمد بن سليمان الزواوي، وأبو محمد عبد الله بن نصرون بن أبي الوليد الاندلسي، المالكيان، ومحمود بن علي بن أبي الغنائم المعروف بابن الغسال الحنبلي، وآخرون أسماؤهم على نسخة الامام فخر الدين، منهم كاتب السماع علز بن المظفر بن إبرهيم الكندي، وصح ذلك في مجالس، آخرها في يوم الاثنين سادس عشر رمضان سنة ست وخمسين وستمائة، بجامع دمشق، تحت قبة النسر، وأجاز المسمعون لمن سمى مالهم روايته."},{"id":"risala-shafii:60","bookId":"risala-shafii","type":"section","seq":60,"chapter":"كتاب الرسالة","title":"29- إسناد في عنوان الجزء الاول بخط هبة الله بن الاكفاني وهو مصور في اللوحة رقم","page":"ص0","text":"إسناد في عنوان الجزء الاول بخط هبة الله بن الاكفاني وهو مصور في اللوحة رقم (1) وقد سمع منه سنة 458 كما سيأتي برقم (34) وسنة 460 كما مضى برقم (12) الجزء الاول من كتاب الرسالة عن أبي عبد الله محمد بن إدريس بن العباس الشافعي رحمة الله عليه، رواية أبي محمد الربيع بن سليمان المرادي المؤذن عنه، رحمهما الله، مما أخبرنا به الشيخ أبو بكر محمد بن علي بن محمد بن موسى السلمي الحداد رضي الله عنه، عن أبوى القاسم تمام بن محمد بن عبد الله بن جعفر الرازي الحافظ، وعبد الرحمن بن عمر بن نصر بن محمد الشيباني، رضي الله عنهما، كلاهما عن أبي علي الحسن بن حبيب بن عبد الملك الفقيه الحصائري رحمه الله، عن الربيع بن سليمان المرادي، عن أبي عبد الله محمد بن إدريس الشافعي رحمه الله، سماع لهبة الله بن أحمد بن محمد بن هبة الله الاكفاني، نفعه الله بالعلم.\nثم كتب ابن الاكفاني بخطه في الذيل الايمن من الصفحة ما نصه: توفى شيخنا أبو بكر محمد بن علي بن محمد السلمي الحداد رحمه الله ليلة الاحد، وصلى عليه يوم الاحد الظهر في الجامع، وذلك في اليوم العاشر من شهر رمضان من سنة ستين وأربعمائة، ودفن في باب الصغير، زحمه الله ورضي عنه.\nوقد تكرر العنوان وحده بهذا الاسناد في الجزءين الثاني والثالث بخطه أيضا (ص 58\nو108 أصل) وكتب على بن عقيل بن علي تحت السطر الاخير من عنوان الجزء الثالث ما نصه: (مما أخبرنا به عنه الشيخ الامين أبو المكارم عبد الواحد بن محمد بن المسلم بن هلال) ثم كتب تحت ذلك: (سماع منه لعلي بن عقيل بن علي نفع به آمين) .\nوعلي بن عقيل سمع الكتاب من عبد الواحد بن هلال سنة 563 كما مضى بخطه في السماع رقم (20) ثم سجل سماعه أيضا بخطه في (ص 11 أصل) كما سيأتي برقم (30) ثم كتب\nبخطه أيضا عنوانا للجزء الثاني وآخر للجزء الثالث كما سيأتي برقم (31) وأرجح أنه كتب كل هذا بعد أن ملك النسخة في سنة 566 كما بينته في حاشية السماع (رقم 20) وانظر ما يأتي برقم (42) ."},{"id":"risala-shafii:61","bookId":"risala-shafii","type":"section","seq":61,"chapter":"كتاب الرسالة","title":"30- إسناد الكتاب بخط علي بن عقيل بن علي بسم الله الرحمن الرحيم","page":"ص0","text":"إسناد الكتاب بخط علي بن عقيل بن علي بسم الله الرحمن الرحيم.\nإسناد الرسالة: أنا الشيخ الامين أبو المكارم عبد الواحد بن محمد بن هلال، قال: أخبرنا الشيخ الامين أبو محمد هبة الله بن أحمد بن محمد بن هبة الله الانصاري الاكفاني رحمه الله، قراءة عليه في سنة تسع وخمسمائة، قال: أخبرنا أبو بكر محمد بن علي بن محمد بن موسى السلمي الحداد، قراءة عليه، في شهر ربيع الاخر من سنة ستين وأربعمائة قال: أخبرنا أبو القاسم تمام بن محمد بن عبد الله بن جعفر الرازي الحافظ، قراءة عليه في بيته في سنة ست وأربعمائة، وأبو القاسم عبد الرحمن بن عمر بن نصر بن محمد الشيباني، قراءة عليه في سنة ثمان وأربعمائة، قالا: حدثنا أبو علي الحسن بن حبيب بن عبد الملك الفقيه الحصايري، قال: حدثنا الربيع بن سليمان المرادي المؤذن، قال: أخبرنا الامام أبو عبد الله محمد بن إدريس بن العباس بن عثمان الشافعي رضي الله عنه."},{"id":"risala-shafii:62","bookId":"risala-shafii","type":"section","seq":62,"chapter":"كتاب الرسالة","title":"31- إسناد في عنوان الجزء الثاني بخط علي بن عقيل الجزء الثاني من كتاب الرسالة","page":"ص0","text":"إسناد في عنوان الجزء الثاني بخط علي بن عقيل الجزء الثاني من كتاب الرسالة.\nعن أبي عبد الله محمد بن إدريس الشافعي المطلبي.\nرواية الربيع بن سليمان المرادي عنه.\nرواية أبي علي الحسن بن حبيب بن عبد الملك الفقيه عنه.\nرواية أبوى القاسم تمام بن محمد بن عبد الله الرازي.\nوعبد الرحمن بن عمر بن نصر بن محمد الشيباني.\nكليهما عنه.\nرواية أبي بكر محمد بن علي بن محمد بن موسى السلمي الحداد عنهما.\nرواية الامين أبي محمد هبة الله بن أحمد الاكفاني عنه.\nأخبرنا به عنه الشيخ الامين أبو المكارم عبد الواحد بن محمد بن هلال.\nوالامام العالم الحافظ أبو القاسم علي بن الحسن بن هبة الله الشافعي.\nسماع منهما لعلي بن عقيل بن علي الشافعي نفع به آمين.\nوكرر هذا العنوان أيضا في الجزء الثالث بخطه (ص 106 أصل) ويظهر من هذا أنهما كتبا بعد سماع علز بن عقيل من الحافظ ابن عساكر علي بن الحسن بن هبة الله سنة 567 كما مضى في السماع (رقم 21) .\nوقد كتب الحسن بن علي بن عقيل تحت خط أبيه في الجزءين سماعه أيضا بما نصه: (ولابنه الحسن بن علي من الشيخ أبي المعالي عبد الله بن عبد الرحمن بن صابر بن علي الاكفاني) والحسن سمع مع أبيه في سنة 571 كما مضى برقم (22 و 23) ."},{"id":"risala-shafii:63","bookId":"risala-shafii","type":"section","seq":63,"chapter":"كتاب الرسالة","title":"التوقيعات","page":"ص0","text":"نريد بالتوقيعات السماعات المختصرة التي يكتبها السامعون من العلماء بخطهم تسجيلا لسماعهم على الكتاب، وهذه مثلها مرتبة ترتيبا تاريخيا، الاقدم فالاقدم: 32 - \" رواية أبي القاسم عبد الرحمن بن عمر الحنفي عن أبي علي الحسن بن حبيب عنه.\nسماع لعلي وإبرهيم ابني محمد بن إبرهيم الحنائي، نفعهما الله بالعلم \".\nهذا التوقيع مكتوب تحت عنوان الثالث الذي يخط الربيع (ص 112 أصل، لوحة رقم 5) والظاهر أنه بخط أحد هذين السامعين، وقد سمع أولهما من عبد الرحمن بن عمر بن نصر في سنة 394، والثاني في سنة 401 كما مضى في السماعات (1 - 6) وقد كتب نحوه في (ص 12 أصل، لوحة رقم 3) ."},{"id":"risala-shafii:64","bookId":"risala-shafii","type":"section","seq":64,"chapter":"كتاب الرسالة","title":"33- \" سمع الكتاب كاملا محمد السمرقندي \" هذا التوقيع مكتوب في","page":"ص0","text":"\" سمع الكتاب كاملا محمد السمرقندي \" هذا التوقيع مكتوب في (ص 12 أصل، لوحة رقم 3) ، وهو محمد بن أبي الوفاء السمرقندي، مضى سماعه برقم (8) سنة 457."},{"id":"risala-shafii:65","bookId":"risala-shafii","type":"section","seq":65,"chapter":"كتاب الرسالة","title":"34- \" بلغت سماعا وطاهر بن بركات الحشوعي وسلمان بن حمزة الحداد وأخواه هبة الله وعبد الكريم","page":"ص0","text":"\" بلغت سماعا وطاهر بن بركات الحشوعي وسلمان بن حمزة الحداد وأخواه هبة الله وعبد الكريم (1) .\nوذلك في رجب من سنة ثمان وخمسين وأربعمائة.\nوصح \" هذا التوقيع في (ص 9 أصل) وكلها بخط هبة الله بن الاكفاني."},{"id":"risala-shafii:66","bookId":"risala-shafii","type":"section","seq":66,"chapter":"كتاب الرسالة","title":"35- \" سماع لهبة الله بن أحمد الاكفاني نفعه الله به","page":"ص0","text":"\" سماع لهبة الله بن أحمد الاكفاني نفعه الله به، من الشيخ أبي بكر محمد بن علي الحداد، رضى الله عنه \".\nهذا التوقيع بخط هبة الله بن الاكفاني الذي سمع الكتاب سنة 460 كما مضى برقم (12) وقد كتبه على عناوين الاجزاء الثلاثة بخط الربيع، وهي (ص 12، 62 و 112 أصل، لوحات 3، 4، 5) ."},{"id":"risala-shafii:67","bookId":"risala-shafii","type":"section","seq":67,"chapter":"كتاب الرسالة","title":"36- \" فرغ من جميعه نسخا وسماعا وعرضا عبد الرحمن بن أحمد بن علي بن صابر \"","page":"ص0","text":"\" فرغ من جميعه نسخا وسماعا وعرضا عبد الرحمن بن أحمد بن علي بن صابر \".\nهذا التوقيع مكتوب على الجزء الثالث (ص 112 أصل، لوحة رقم 5) وكتب أيضا على الجزءين الاول والثاني (ص 12، 62 أصل، لوحة رقم 3، 4) ولكن ضاع بعضه فيهما، وعبد الرحمن بن صابر سمع سنة 495 كما مضى في رقم (13) ."},{"id":"risala-shafii:68","bookId":"risala-shafii","type":"section","seq":68,"chapter":"كتاب الرسالة","title":"37- \" سمع جميعه وعارض بنسخته محمد بن محمد بن المسلم بن هلال \" — هذا التوقيع مكتوب على الصفحات","page":"ص0","text":"\" سمع جميعه وعارض بنسخته محمد بن محمد بن المسلم بن هلال \"\nهذا التوقيع مكتوب على الصفحات (12، 62، 112 أصل، لوحات 3، 4، 5) وسماعه في سنة 499 وقد مضى برقم (15) ."},{"id":"risala-shafii:69","bookId":"risala-shafii","type":"section","seq":69,"chapter":"كتاب الرسالة","title":"38- \" سمع جميعه وعارض بنسخته محمد بن علي بن المسلم بن الفتح السلمي \"","page":"ص0","text":"\" سمع جميعه وعارض بنسخته محمد بن علي بن المسلم بن الفتح السلمي \".\nوهذا مكتوب في (ص 62 أصل، لوحة رقم 4) ومكرر في (ص 12، 112 أصل) بشئ من الاختصار.\nوسماعه سنة 509 وقد مضى برقم (17) ."},{"id":"risala-shafii:70","bookId":"risala-shafii","type":"section","seq":70,"chapter":"كتاب الرسالة","title":"39- \" سمع جميعه وعارض بنسخته علي بن الحسن بن هبة الله \" هو الحافظ ابن عساكر","page":"ص0","text":"\" سمع جميعه وعارض بنسخته علي بن الحسن بن هبة الله \" هو الحافظ ابن عساكر، وقد كتب هذه العبارة بخطه أربع مرات: على عنوان الاول والثاني اللذين بخط ابن الاكفاني، وعلى العنوانين اللذين بخط الربيع (ص 4، 12، 58، 62 من الاصل) ولكن ليس في الاخيرة لفظ \" جميعه \"، ولم يكتبها على عنواني الثالث، أو لعله كتبها على طرف الصفحة ثم محاها البلى، وانظر اللوحات (رقم 1، 3، 4) ."},{"id":"risala-shafii:71","bookId":"risala-shafii","type":"section","seq":71,"chapter":"كتاب الرسالة","title":"40- \" سمع جميع هذا الجزء من أوله إلى آخره على الشيخ الفقيه الامين أبي محمد هبة الله بن أحمد ال","page":"ص0","text":"\" سمع جميع هذا الجزء من أوله إلى آخره على الشيخ الفقيه الامين أبي محمد هبة الله بن أحمد الاكفاني وهب بن سلمان بن أحمد السلمي بقراءته في آخرين، في شهر رمضان ... \" هذا التوقيع مكتوب في (ص 62 أصل، لوحة رقم 4) وتاريخ السنة غير واضح، ولكنه مذكور في السماع الذى مضى برقم (18) وأنه في سنة 518 41 - \" سمع أكثره وعارض نسخته محمد بن الحسن به هبة الله \".\nهذا أخو الحافظ ابن عساكر، وهو مكتوب في (ص 12 أصل، لوحة رقم 3) وقد مضى سماعه برقم (19) في سنة 519"},{"id":"risala-shafii:72","bookId":"risala-shafii","type":"section","seq":72,"chapter":"كتاب الرسالة","title":"42- \" سماع لعلي بن عقيل بن علي نفع به \" وهذا مكتوب على العنوان الاول الذي بخط الاكفاني","page":"ص0","text":"\" سماع لعلي بن عقيل بن علي نفع به \" وهذا مكتوب على العنوان الاول الذي بخط الاكفاني (ص 4 أصل، لوحة رقم 1 وقد كرره في عنواني الثاني والثالث، وزاد في الثالث \" آمين \" (ص 18، 108 أصل) وله توقيعات أخرى أشرنا إليها في (رقم 29، 31) ."},{"id":"risala-shafii:73","bookId":"risala-shafii","type":"section","seq":73,"chapter":"كتاب الرسالة","title":"43- \" سمع هذا الكتاب وقابل به نسخة أبو القاسم هبة الله بن معد بن عبد العزيز بن عبد الكريم القر","page":"ص0","text":"\" سمع هذا الكتاب وقابل به نسخة أبو القاسم هبة الله بن معد بن عبد العزيز بن عبد الكريم القرشي الدمياطي \".\nكتب هذا التوقيع في (ص 12 أصل، لوحة رقم 3) ولم يبق ذكر هبة الله هذا في السماعات، فهو فائدة جديدة.\nوهبة الله بن معد فقيه شافعي عرف بابن البورى، نسبة إلى \" بورة \" وهي بلد قرب دمياط، ينسب إليها السمك البورى، تفقه علي ابن أبي عصرون وابن الخل، ثم استقر بالاسكندرية، ودرس بمدرسة السلفي \" ومات سنة 599 وله ترجمة في (ش 4: 348) (ط 4: 322) ولم يذكر اسم جده \" عبد العزيز \" فيستفاد من خطه هنا."},{"id":"risala-shafii:74","bookId":"risala-shafii","type":"section","seq":74,"chapter":"كتاب الرسالة","title":"44- \" سمعه وما بعده على غير واحد","page":"ص0","text":"\" سمعه وما بعده على غير واحد، وله نسخة: محمد بن يوسف بن محمد النوفلي القرشي المعروف بالكنجي، وحضر ابني أبو الفضل جعفر جبره الله \".\nهذا التوقيع مكتوب في الجزء الاول (ص 4 أصل، لوحة رقم 1) وقد كتب أيضا بنحوه في (ص 62، 112 أصل، لوحة رقم 4، 5) وسماعه مضى برقم (28) سنة 656 45 - \" الله خير حافظا وهو أرحم الراحمين (1) .\nإنا نحن نزلنا الذكر وإنا له لحافظون.\nالحافظ الله.\nنعم القادر الله.\nفقدرنا فنعم القادرون.\nوديعة محمد بن أبي جعفر، كتب الله سلامته \".\nهذه العبارة مكتوبة في رأس (ص 8 أصل) وهي بخط الامام تاج الدين محمد بن أبي جعفر القرطبي المتوفي سنة 643، وقد سمع الكتاب في سنتي 578، 588 ثم سمع عليه بعد دخول الاصل في ملكه في سنة 635، كما مضى في السماعات (24 - 27) ويظهر من هذه العبارة أنه كتبها عند دخول الاصل في ملكه، أي قبل سنة 635"},{"id":"risala-shafii:75","bookId":"risala-shafii","type":"section","seq":75,"chapter":"كتاب الرسالة","title":"الأحاديث والآثار","page":"ص0","text":"(1)\nأحاديث رواها أحد السامعين من عبد الرحمن بن نصر عنه في سنة 401 46 - حدثنا أبو القاسم بن نصر، قال: ثنا أبو علي الحسن بن حبيب قال: ثنا ابن أبي سفيان بقيسارية، قال: ثنا الفريابي، قال: نا إسرائيل عن سماك بن حرب بن عبد الرحمن بن عبد الله بن مسعود عن أبيه قال رسول الله صلى الله عليه وسلم: \" نضر الله وجه امرئ سمع منا حديثا فبلغه كما سمعه، فرب مبلغ أوعى من سامع \" (2) ."},{"id":"risala-shafii:76","bookId":"risala-shafii","type":"section","seq":76,"chapter":"كتاب الرسالة","title":"47- وقال","page":"ص0","text":"وقال: أخبرنا عبد الرحمن بن حبيش بن شيخ الفرغاني، قال: حدثنا زكريا بن يحيى السجزي، قال: حدثنا وهب بن جرير بن حازم، قال: حدثنا شعبة، قال الشيخ: حدثني أبو يوسف يعقوب بن المبرك (3) ، قال: حدثنا\nعبد الرحمن بن إسحق المكي، قال: حدثنا وهب بن جرير، قال: حدثنا شعبة عن علي بن مدرك، قال: سمعت أبا زرعة يحدث عن خرشة عن أبي ذر الغفاري قال: قال رسول الله صلى الله عليه: \" ثلاثة لا ينظر الله إليهم يوم القيامة، قلت: من هم يا رسول الله؟ خابوا وخسروا، قال: المسبل إزاره، والمنان والمختال \" (1) 48 - وقرئ على الشيخ: حدثكم أبو إسحق إبرهيم بن أبي ثابت، قال: حدثنا الحسن بن عرفة، قال: حدثنا أبو بكر بن عياش عن عاصم عن زر بن حبيش عن ابن مسعود قال: \" كنت أرعى غنما لعقبة بن أبي معيط، فمر بي رسول الله صلى الله عليه وأبو بكر، فقال: يا غلام؟ هل من لبن؟ قال: نعم، ولكني مؤتمن، فقال: هل من شاة لم ينز عليها فحل؟ فأتيته بها، فمسح ضرعها، فنزل اللبن، فشرب وسقى أبا بكر، ثم قال: للضرع: اقلص، فقلص، فأتيته بعد هذا فقلت له: يا رسول الله، علمني من هذا القول، فمسح يده على رأسي، وقال: يرحمك الله، إنك لغليم معلم \" (2) هذه الاحاديث الثلاثة مكتوبة في الصفحة التي فيها عنون الجزء الثالث المكتوب بخط الربيع (ص 112 أصل، لوحة رقم 5) ، وهي بخط أحد الرواة عن أبي القاسم عبد الرحمن بن عمر بن نصر، كما هو ظاهر، وكتب الكاتب بعدها: (قرئ على الشيخ جميعه، وسمع من بلغ له بخطه في الثاني) .\nثم كتب تحتها هبة الله بن الاكفاني بخطه ما نصه: (سماع لهبة الله بن أحمد\nبن محمد الاكفاني من الشيخ أبي بكر محمد بن علي الحداد رضي الله عنه) .\nفالظاهر من هذا ومن مقارنة الخط بخط أبي بكر الحداد في السماع الماضي برقم (11) (ص 111 أصل) أن هذه الاحاديث بخط أبي بكر الحداد، وأنه هو الذي سمعها من عبد الرحمن بن نصر مع من سمع منه في السماع الثاني سنة 401 كما مضى في السماعات (رقم 2، 4، 6) خصوصا وقد ثبت من السماعات أن ابن الاكفاني لم يسمع الكتاب في هذا الاصل إلا من ابن الحداد وحده.\nأثران رواهما أحد السامعين في السماع (رقم 8 سنة 457) 49 - حدثنا الشيخ أبو محمد عبد العزيز بن أحمد الكتاني رضي الله عنه لفظا.\nقال: أخبرنا أبو المعمر المسدد بن علي بن عبد الله الاملوكي إمام جامع حمص قدم علينا، إجازة، قال: حدثنا القاضي أبو بكر محمد بن عبد الرحمن بن عمرو الرحبي سنة ثمان وستين وثلاثمائة، قال: حدثنا أبو العباس أحمد بن منصور بن محمد الشيرازي، قال: سمعت أبا جعفر محمد بن عبد الله الفرغاني بنيسابور يقول: سمعت أبا بكر الشافعي يقول: رأيت النبي صلى الله عليه وسلم\nفي المنام، فقلت: يا رسول الله، بما جوزي الشافعي عن ذكره لك في كتاب الرسالة؟ قال: جوزي ألا يوقف للحساب."},{"id":"risala-shafii:77","bookId":"risala-shafii","type":"section","seq":77,"chapter":"كتاب الرسالة","title":"50- ثنا أبو العباس الشيرازي","page":"ص0","text":"ثنا أبو العباس الشيرازي (1) ، قال: حدثنا عبد الواحد بن الحباب، قال: سمعت أبا الحسن بن أبي صغير يقول: سمعت المزني يقول: سمعت الشافعي يقول: من تعلم القران عظمت قيمته، ومن كتب الحديث قويت حجته، ومن نظر في الفقه نبل مقداره، ومن نظر في اللغة رق طبعه، ومن لم يصن نفسه لم ينفعه علمه."},{"id":"risala-shafii:78","bookId":"risala-shafii","type":"section","seq":78,"chapter":"كتاب الرسالة","title":"51- وحدثني بعض فقهاء الشافعيين أن هذه رسالة الشافعي إلى عبد الرحمن بن مهدي سأله فيها","page":"ص0","text":"وحدثني بعض فقهاء الشافعيين أن هذه رسالة الشافعي إلى عبد الرحمن بن مهدي سأله فيها.\nهذه الاثار الثلاثة مكتوبة في (53 أصل) وتحتها السماع على أبي بكر الحداد سنة 457 الذى مضى برقم (8) ويظهر أنها كلها بخط كاتب السماع في ذلك المجلس.\nوالشيخ المروي عنه هذه الاثار هو الحافظ عبد العزيز بن أحمد بن محمد بن علي التميمي الصوفي \" الامام المحدث مفيد دمشق ومحدثها \" كما وصفه الذهبي في التذكرة، وهو من شيوخ عبد الكريم بن حمزة السلمي الحداد الذي سمع الرسالة سمة 458 كما مضى برقم (34) وهبة الله بن الاكفاني الذي سمعها سنة 460 كما مضى برقم (12) وحدث عنه أيضا الخطيب البغدادي والامير ابن ماكولا.\nولد سنة 389 ومات في جمادى الاخرة سنة 466 وله ترجمة في تذكرة الحفاظ (3: 342) والانساب للسمعاني (ورقة 475) والشذرات (3: 325) .\nوالاثر الاول روى نحوه ابن السبكي في الطبقات (1: 98) باسناده عن ابن بيان الاصبهاني أنه رأى مناما مثله.\nوالاثر الثاني سيأتي نحوه باسناد آخر رواه ابن الاكفاني عن الخطيب البغدادي (برقم 55)\nونقل الحافظ ابن حجر في (توالى التأسيس ص 72 طبعة بولاق) نحوه بدون إسناد، وكذلك ابن السبكي في الطبقات (1: 241) .\nآثار مكتوبة في (ص 9 أصل) بخط هبة الله بن الاكفاني 52 - بسم الله الرحمن الرحيم.\nحدثنا الشيخ الامام أبو بكر أحمد بن علي بن ثابت الخطيب من لفظه في رجب من سنة ثمان وخمسين وأربعمائة، قال أخبرنا أبو الحسن محمد بن أحمد بن محمد بن رزقويه، قال: أخبرنا دعلج بن أحمد قال: سمعت جعفر بن أحمد الشاماتي (1) يقول: سمعت جعفر بن أخي أبي ثور يقول: سمعت عمي (2) يقول: كتب عبد الرحمن بن مهدي إلى الشافعي وهو شاب أن يضع له كتابا فيه معاني القران، ويجمع قبول الاخبار فيه، وحجة\nالاجماع، وبيان الناسخ والمنسوخ من القران والسنة، فوضع له كتاب الرسالة.\nقال عبد الرحمن بن مهدي: ما أصلي صلاة إلا وأدعوا للشافعي رحمه الله فيها."},{"id":"risala-shafii:79","bookId":"risala-shafii","type":"section","seq":79,"chapter":"كتاب الرسالة","title":"53- أخبرنا محمد","page":"ص0","text":"أخبرنا محمد، قال: أنا دعلج، قال أخبرنا الحسن بن سفيان، قال: ثنا الحرث بن سريج النقال، قال: سمعت عبد الرحمن بن مهدي يقول: ما أصلي صلاة إلا وأدعو الله تعالى فيها للشافعي رحمه الله تعالى."},{"id":"risala-shafii:80","bookId":"risala-shafii","type":"section","seq":80,"chapter":"كتاب الرسالة","title":"54- أخبرنا محمد","page":"ص0","text":"أخبرنا محمد، قال: أخبرنا دعلج، قال: سمعت جعفر الشاماتي يقول: سمعت المزني يقول: كتبت كتاب الرسالة منذ زيادة على أربعين سنة، وأنا أقرأه وأنظر فيه ويقرأ على، فما من مرة قرأت أو قرئ على إلا واستفدت\nمنه شيئا لم أكن أحسنه ثم كتب ابن الاكفاني التوقيع الذي مضى برقم (34) بعد هذا، ثم كتب: 55 - وحدثنا الشيخ الامام الحافظ أبو بكر أحمد بن علي بن ثابت الخطيب قراءة من لفظه، قال: أخبرني أبو القاسم الازهري، قال: ثنا الحسن بن أحمد الصوفي، قال: ثنا النيسابوري، وهو عبد الله بن محمد بن زياد، قال: سمعت المزني، ح وحدثنا أبو طالب يحيى بن علي بن الطيب الدسكري لفظا بحلوان، قال: ثنا أبو عروبة محمد بن جعفر النصيبي بجرجان، قال: ثنا عبد الله بن أبي سفيان بالموصل، قال: سمعت المزني يقول: سمعت الشافعي يقول: من تعلم القران عظمت قيمته، ومن نظر في الفقه نبل مقداره، ومن تعلم اللغة - وقال الدسكري: من نظر في اللغة - رق طبعه، ومن نظر في الحساب - وقال الازهري: ومن تعلم الحساب - تجزل رأيه، ومن كتب الحديث قويت حجته، ومن لم يصن نفسه لم ينفعه علمه.\nبلغت سماعا والحمد لله وحده، وصح."},{"id":"risala-shafii:81","bookId":"risala-shafii","type":"section","seq":81,"chapter":"كتاب الرسالة","title":"56- ونا الشيخ الامام الحافظ أبو بكر أحمد بن علي بن ثابت من لفظه في التاريخ","page":"ص0","text":"ونا الشيخ الامام الحافظ أبو بكر أحمد بن علي بن ثابت من لفظه في التاريخ، قال: أنا أبو الحسن محمد بن أحمد بن رزقويه، قال: سمعت أبا بكر\nأحمد بن علي بن محمد بن الفامي النيسابوري يقول: سمعت غسان بن أحمد يقول: سمعت الربيع يقول: سمعت الشافعي يقول: أردت مالك بن أنس، وقد حفظت الموطأ، فقدمت عليه، فقال لي، اطلب من يقرأ لك، فقلت له: إن أعجبك قراءتي؟ فقرأت عليه الموطأ كله حفظا."},{"id":"risala-shafii:82","bookId":"risala-shafii","type":"section","seq":82,"chapter":"كتاب الرسالة","title":"57- وبه قال سمعت الشافعي يقول","page":"ص0","text":"وبه قال سمعت الشافعي يقول: إذا قرأت على العالم فقل أخبرنا، وإذا قرأ عليك فقل حدثنا.\n[وسمع] (1) الجماعة المسمون أعلى هذا، وصح.\nهذه الاثار كلها في (ص 9 أصل) بخط هبة الله بن الاكفاني، سمعها من الخطيب البغدادي صاحب التاريخ من كتاب (تاريخ بغداد) وقد بحثت عنها فوجدت الاثر الاول منها، وهو (رقم 52) في ترجمة الشافعي (ج 2 ص 64 - 65) ووجدت أيضا (رقم 56) في ترجمة ابن الفامي (ج 4 ص 313) ولم أحد باقيها، ولعلها مفرقة في مواضع منه يطول البحث عنها.\nوالاثر (56) نقل نحوه ابن حجر في توالي التأسيس (ص 51) عن أبن أبي حاتم عن الربيع.\nكلمة لابي حاتم (ص 4 من الاصل) 58 - قال أبو حاتم إذا قال الشافعي رحمه الله في كتبه \" أخبرني الثقة عن ابن أبي ذئب \" فهو ابن أبي فديك.\nوإذا قال \" أخبرني الثقة عن الليث بن سعد \" فهو يحيى بن حسان.\nوإذا قال \" أخبرنا الثقة عن الوليد بن كثير \" فهو عمرو (2) بن أبي سلمة.\nوإذا قال \" أخبرنا الثقة عن ابن جريج \" فهو مسلم بن خالد الزنجي.\nوإذا قال \" أنا الثقة عن صالح مولى التوأمة \" فهو إبرهيم بن [أبي] يحيى (3) .\nهذه الفائدة مكتوبة فوق عنوان الاصل الذي بخط ابن الاكفاني، وأظنها بخطه أيضا، وقد نقلها العلماء عن أبي حاتم وغيره، ونقلوا نحوها معم بعض اختلاف، وانظر تدريب الرواي للسيوطي (ص 113 - 114) .\nشعر للصنوبري في مدح أبي الحسن بن يزيد الحلبي"},{"id":"risala-shafii:83","bookId":"risala-shafii","type":"section","seq":83,"chapter":"كتاب الرسالة","title":"59- علي بن محمد بن إسحق بن يزيد الحلبي أبو الحسن الفقيه","page":"ص0","text":"علي بن محمد بن إسحق بن يزيد الحلبي أبو الحسن الفقيه (1) قرات بخط الحافظ أبي القاسم بن عساكر: أنا الشيخ الامام أبو السعود أحمد بن علي بن المجلي (2) ، أنا الشيخ أبو منصور عبد المحسن بن محمد بن علي (3) قراءة من لفظه، في المحرم سنة سبع وستين وأربعمائة، أنشدني أبو الحسن بن يزيد الحلبي (4) لابي بكر الصنوبري (5) فيه يمدحه: يزيد الفقه والفقهاء حبا * * إلى [قلبي] (6) ففيه بني يزيد تناهى ثم زاد عن التناهى * * وأشرف أن يزيد على المزيد أبا الحسن ابتدى عمرا مداه * * مدى لبد وليس مدى لبيد وعش عيشا جديدا كل يوم * * قرير العين بالعمر المديد فكم من مستفاد منه علما (7) * * يمد إليك كف المستفيد هذه القطعة مكتوبة في الاصل في (ص 8) ولم أعرف كاتبها، وقد أجبت دعوة الشاعر للعالم، فعاش مائة سنة."},{"id":"risala-shafii:84","bookId":"risala-shafii","type":"section","seq":84,"chapter":"كتاب الرسالة","title":"نسخة العماد بن جماعة","page":"ص0","text":"(1)"},{"id":"risala-shafii:85","bookId":"risala-shafii","type":"section","seq":85,"chapter":"كتاب الرسالة","title":"60- عنوان النسخة","page":"ص0","text":"عنوان النسخة (لوحة رقم 12) كتاب الرسالة من تصانيف الامام الشافعي رضي الله عنه.\nرواية حرملة بن يحيى التجيبي (2) ، والربيع بن سليمان المؤذن المصري، رحمهما الله، عنه."},{"id":"risala-shafii:86","bookId":"risala-shafii","type":"section","seq":86,"chapter":"كتاب الرسالة","title":"61- إسناد العماد إسمعيل بن جماعة بالكتاب","page":"ص0","text":"إسناد العماد إسمعيل بن جماعة بالكتاب (لوحة رقم 12) أخبرنا بها إجازة معينة المسند عبد الرحيم بن محمد المصري (3) ، بإجازته المعينة لها من الحافظ أبي عمر عبد العزيز بن محمد بن جماعة (4) ، بروايته لها\nعن أبي المحاسن يوسف بن محمد بن إبرهيم الدمشقي (1) مشافهة، قال: أنا الحسين بن إبرهيم الاربلي، ويوسف بن مكتوم القيسي، وعبد الله بن بركات القرشي، وإسمعيل بن إبرهيم التنوخي، قالوا: أنا أبو طاهر بركات بن إبرهيم الخشوعي سماعا، قال الاربلي: خلا الجزء الاول فإجازة منه، بسنده باطنها، إسمعيل بن جماعة."},{"id":"risala-shafii:87","bookId":"risala-shafii","type":"section","seq":87,"chapter":"كتاب الرسالة","title":"62- إسناد آخر له وأخبرني جدي عبد الله بن جماعة عن جمع من أصحاب البدر بن جماعة عنه","page":"ص0","text":"إسناد آخر له وأخبرني جدي عبد الله بن جماعة عن جمع من أصحاب البدر بن جماعة عنه (2) ، أنا الحسين بن إبرهيم التنوخي، عن بركات الخشوعي، بسنده."},{"id":"risala-shafii:88","bookId":"risala-shafii","type":"section","seq":88,"chapter":"كتاب الرسالة","title":"63- إسناد آخر له وأخبرني به الحافظ برهان الدين سبط ابن العجمي إجازة","page":"ص0","text":"إسناد آخر له وأخبرني به الحافظ برهان الدين سبط ابن العجمي إجازة (3) ، بسماعه\nللنصف الثاني منه من العلامة بهاء الدين أحمد بن حمدان الاذرعي (4) ، أنا عبد المؤمن\nبن عبد العزيز الحارثي، أنا إسمعيل بن إبرهيم التنوخي، ويوسف بن مكتوم بسندهما."},{"id":"risala-shafii:89","bookId":"risala-shafii","type":"section","seq":89,"chapter":"كتاب الرسالة","title":"64- إسناد آخر له وأخبرني به جمع عن ابن أميلة","page":"ص0","text":"إسناد آخر له وأخبرني به جمع عن ابن أميلة (1) ... عن أبي الحسن علي بن أحمد بن البخاري (2) إجازة، بإجازة من أي طاهر بركات بن إبرهيم، بسنده.\nالعنوان (رقم 6) مكتوب بخط نسخي هو خط كاتب النسخة، ولم أعرفه، ولم يذكر تاريخ كتابتها، والراجح عندي أنها كتبت للعماد إسمعيل بن جماعة ليقرأها على جده الحافظ عبد الله بن محمد بن جماعة، وسيأتي مجلس السماع (برقم 68) وأما الاسانيد (رقم 61 - 64) فانها كلها بخط العماد إسمعيل (لوحة رقم 12) ."},{"id":"risala-shafii:90","bookId":"risala-shafii","type":"section","seq":90,"chapter":"كتاب الرسالة","title":"65- فائدة مكتوبة على العنوان","page":"ص0","text":"فائدة مكتوبة على العنوان (لوحة رقم 12)\nقال: أبو القاسم عثمان بن سعيد الانماطي أخذ الفقه عن المزني والربيع، وأخذ عنه ابن سريج، وكان سبب نشاط الناس في كتب الشافعي.\nقال عن المزني: أنا أنظر في كتاب الرسالة عن الشافعي منذ خمسين سنة، ما أعلم أنى نظرت فيه مرة إلا وأنا أستفيد منه شيئا لم أكن عرفته.\nفائدة مكتوبة بقلم ثخين، وأظنها بخط إسمعيل بن جماعة أيضا، لقرب الشبه بين خطها وخط ما قبلها مع اختلاف القلم.\nوأبو القاسم الانماطي المذكور مات ببغداد في شوال سنة 288 وهذه الفائدة مذكورة بنصها تقريبا في ترجمته (خ 1: 392) وله ترجمة أيضا في تاريخ بغداد (11: 292) وفي (ش 2: 198) .\nصورة أول النسخة 66 - بسم الله الرحمن الرحيم.\nوهو حسبنا ونعم الوكيل.\nأخبرنا الامين الثقة أبو طاهر بركات بن إبرهيم بن طاهر الخشوعي قراءة عليه، قال: أخبرنا الشيخ الامين أبو محمد هبة الله بن أحمد الاكفاني قراءة عليه وأنا أسمع، في شهور سنة ثمان عشرة وخمسمائة، قال: أخبرنا الشيه أبو بكر محمد بن علي بن محمد\nبن موسى السلمي الحداد قراءة عليه في شهر ربيع الاخر سنة ستين وأربعمائة، قال: أخبرنا الحافظ أبو القاسم تمام بن محمد بن عبد الله بن جعفر الرازي قراءة عليه في بيته سنة ست وأربعمائة، وأبو القاسم عبد الرحمن بن عمر بن نصر بن محمد الشيباني قراءة عليه سنة ثمان وأربعمائة، قالا: أخبرنا أبو علي الحسن بن حبيب بن عبد الملك الفقيه الحصايري، قال: أخبرنا الربيع بن سليمان المرادي، قال: حدثنا الشافعي رضي الله عنه قال.\nهذا الاسناد مكتوب في أول الصفحة الثانية من النسخة عند بدء الكتاب، كعادة المتقدمين في ذكر أسانيدهم إلى المؤلفين في أوائل الكتب، ويظهر من هذا أن هذه النسخة كتبت عن نسخة لاحد السامعين من أبي طاهر الخشوعي، ممن وصل إسمعيل بن جماعة إسناده بهم، في الاسانيد الماضية (رقم 61 - 64) .\nوهذا الاسناد مصدق كل التصديق للسماعات المذكورة على أصل الربيع، فانظر سماع أبي طاهر من ابن الاكفاني سنة 518 (رقم 18) وسماع ابن الاكفاني من أبي بكر الحداد سنة 460 (رقم 12) وسماع أبي بكر من تمام وعبد الرحمن سنتي 406 و 408 (رقم 4، 30) .\nإسناد آخر 67 - طريق آخر، بسم الله الرحمن الرحيم.\nأنا الشيخ أبو غالب أحمد بن الحسن بن أحمد بن البنا الفقيه (1) رحمه الله قراءة عليه وأنا أسمع، في جمادي الاخرة سنة إحدى وعشرين [وخمسمائة] ، قيل له: أخبركم الشيخ أبو الحسن محمد بن أحمد بن محمد الابنوسي (2) قراءة عليه وأنت تسمع فأقر به، قال: أخبرنا أبو حفص عمر بن إبرهيم بن أحمد الكتاني المقرئ (3) ، قال: أنا أبو الحسن موسى بن جعفر بن محمد بن قرين العثماني (4) ، قال: أنا الربيع بن سليمان المرادي، قال أنا الامام أبو عبد الله محمد بن إدريس الشافعي رضي الله عنه.\nهذا الاسناد مكتوب بحاشية الاسناد الذي قبله في النسخة، وكلمة \" وخمسمائة \" مكتوبة\nفوق السطر بالحمرة.\nوهو إسناد لا يتصل بأسانيد أصل الربيع، بل في طريق مغاير لها."},{"id":"risala-shafii:91","bookId":"risala-shafii","type":"section","seq":91,"chapter":"كتاب الرسالة","title":"السماع على الجمال ابن جماعة","page":"ص0","text":"سنة 856 (لوحة رقم 13)"},{"id":"risala-shafii:92","bookId":"risala-shafii","type":"section","seq":92,"chapter":"كتاب الرسالة","title":"68- الحمد لله وحده","page":"ص0","text":"الحمد لله وحده. قرأت جميع (كتاب الرسالة) هذا، على مولانا شيخ الاسلام الخطيبي الجمالي أبي محمد عبد الله بن جماعة (1) ، فسح الله في مدته، وأخبر به قراءة عن العلامة أبي إسحق إبرهيم بن أحمد بن عبد الواحد الشامي (2) ، والشرف أبي بكر بن الحافظ عز الدين عبد العزيز بن جماعة (3) إجازة، قالا: أنا قاضي القضاة بدر الدين محمد بن إبرهيم بن جماعة (4) ، أنا الحسين بن إبرهيم الاربلي،\nوإسمعيل بن إبرهيم التنوخي، إجازة، قالا: أنا أبو طاهر بركات بن إبرهيم الخشوعي، بسنده في أوله (1) .\nفسمع جميع الكتاب والدى الخطيبى الامامي العالمي برهان الدين أبو إسحق إبرهيم ابن المسمع (2) ، وأخواه محمد وموسى، والاخوان العلامي النجمي محمد (3) ، ومحب الدين أحمد (4) ، والفضلاء زين الدين عبد الكريم بن أبي الوفاء، وشمس الدين محمد بن الجمال يوسف بن الصفي المصري (5) ، وزين الدين عمر بن عبد المؤمن الحلبي (6) ، وعلي بن خليل\nبن أبي قيس، وسمع مفوتا جماعة، فسمع الاخر عز الدين من أوله، وكذلك ناصر الدين محمد بن غرس الدين خليل الترجمان، إلى (باب العلل في الاحاديث) ، والعز عبد العزيز فقط من (باب الاجتهاد) إلى آخر الكتاب، وزين الدين\nعبد الرحمن بن أحمد بن غازي (1) من (باب الصنف الذي يبين سياقه معناه) إلى آخر الكتاب، وكذلك علي حسن بن الوزان، وغرس الدين خليل بن الشهاب\nأحمد بن مطسا (2) [سمع الكتاب خلا (3) ] من قوله في (باب الحجة بتثبيت خبر الواحد) : \" قال الشافعي ثنا سفيان \" فذكر حديث عمر \" أذكر الله امرءا سمع من النبي صلى الله عليه وسلم في الجنين شيئا \" الحديث، إلى حديث سعيد بن جبير \" قال قلت لابن عباس إن نوفا البكالي يزعم أن موسى صاحب الخضر ليس موسى بني إسرائيل \" الحديث، ويوسف وإيرهيم ولدا تاج الدين عبد الوهاب قاضي الصلت (4) ، من (باب كيف البيان) إلى (باب الصنف الذي يبين سياقه معناه) ، وسمع إبرهيم فقط من (باب العلل في الاحاديث) إلى (باب الاجتهاد) ، وشرف الدين موسى بن شيخ التنكزية من (باب النهي عن معنى أوضح من معنى قبله) إلى (باب الاجتهاد) ، وعلاء الدين علي بن إبرهيم الغزى (5) من أول الكتاب إلى (باب الصنف الذي يبين سياقه معناه) ،\nوزين الدين عبد القادر بن قطلوشاه من حديث ابن عمر (1) \" أذكر الله امرءا سمع\nمن النبي صلى الله عليه وسلم في الجنين شيئا) إلى آخر الكتاب.\nوأجازهم المسمع رواية الكتاب وما يجوز له روايته، لافظا قوله عقب القراءة، وكان في ستة مجالس، آخرها نهار الخميس سابع عشر صفر سنة 856 قاله وكتبه إسمعيل بن جماعة والمحلق على الهامش [سمع الكتاب خلا] صحيح إسمعيل بن جماعة.\nثم كتب الشيخ المسمع بخطه تحت ذلك ما نصه: \" صحيح ذلك.\nكتبه عبد الله بن محمد بن جماعة، غفر الله تعالى له \".\nهذا مجلس السماع المثبت بخط إسمعيل بن جماعة في آخر نسخته المقروءة على جده الجمال بن جماعة، وتحته خط جده إثباتا لصحته، وهو المصور هنا (لوحة رقم 13) .\nلوحة رقم - 1 (ص 4 من الاصل) وهو عنوان الجزء الاول بخط هبة الله بن الاكفاني المتوفى سنة 524 وعليه بخطه أيضا شهادته بأن الاصل بخط الربيع\nلوحة رقم - 2 (ص 7 من الاصل) وفيها السماعات (رقم 18، 19، 21)\nلوحة رقم - 3 (ص 12 من الاصل) وهو عنوان الجزء الاول بخط الربيع\nلوحة رقم - 4 (ص 62 من الاصل) وهو عنوان الجزء الثاني بخط الربيع\nلوحة رقم - 5 (ص 112 من الاصل) وهي عنوان الجزء الثالث بخط الربيع\nلوحة رقم - 6 (ص 13 من الاصل) وهي أول الجزء الاول من الكتاب بعد العنوان\nلوحة رقم - 7 (ص 63 من الاصل) وهي أول الجزء الثاني من الكتاب بعد العنوان\n(ص 113 من الاصل) وهي أول الجزء الثالث من الكتاب بعد العنوان\nلوحة رقم - 9 (ص 154 من الاصل) وهي آخر صفحة من الكتاب وعليها إجازة الربيع وتوقيعه\nلوحة رقم - 10 قطعة من الزاوية اليمنى من (ص 36 من الاصل) لمقارنة خطها بخط اللوحة رقم - 11 المصورة عن ورقة من البردي لوحة رقم - 11 الصورة رقم (51) من اللوحة (رقم 7) من الجزء الاول من (كتاب الاوراق البردية) وهي قطعة من مكتوب مؤرخ سنة 195\nلوحة رقم - 12 عنوان نسخة ابن جماعة\nلوحة رقم - 13 الصفحة الاخيرة من نسخة ابن جماعة\nوفيها ثبت السماع في مجالس آخرها نهار الخميس 17 صفر سنة 856.\nالرسالة للإمام المطلبي\nمحمد بن ادريس الشافعي 150 - 204\n((لما نظرت الرسالة للشافعي أذهلتني، لانني رأيت كلام رجل عاقل فصيح ناصح، فإني لاكثر الدعاء له)) . عبد الرحمن بن مهدي\nبتحقيق وشرح: أبي الاشبال أحمد محمد شاكر\nكان الشافعي كالشمس للدنيا، وكالعافية للناس.\nفانظر هل لهذين من خلف، أو منهما عوض؟ ! (الامام أحمد بن حنبل)\nطالت مجالستنا للشافعي، فما سمعت منه لحنة قط. ولا كلمة غيرها أحسن منها. (عبد الملك بن هشام النحوي صاحب السيرة)\nالشافعي كلامه لغة يحتج بها. (ابن هشام أيضا)\nألم تر آثار ابن إدريس بعده ... دلائلها في المشكلات لوامع\nمعالم يفنى الدهر وهي خوالد ... وتنخفض الاعلام وهي فوارع\nمناهج فيها للهدى متصرف ... موارد فيها للرشاد شرائع\nفمن يك علم الشافعي إمامه ... فمرتعه في باحة العلم واسع\n(أبو بكر بن دريد صاحب الجمهرة)\nكتب عبد الرحمن بن مهدي إلى الشافعي، وهو شاب، أن يضع له كتابا فيه معاني القرآن، ويجمع قبول الأخبار فيه، وحجة الإجماع، وبيان الناسخ والمنسوخ من القرآن والسنة: فوضع له كتاب \" الرسالة \".\nقال عبد الرحمن بن مهدي: ما أصلى صلاة إلا وأنا أدعو للشافعي فيها.\nوقال أيضا: لما نظرت \" الرسالة \" للشافعي أذهلتني، لانني رأيت كلام رجل عاقل فصيح ناصح، فإني لأكثر الدعاء له.\nقال المزني [أبو إبرهيم إسمعيل بن يحيى، صاحب الشافعي، مات سنة 264] : قرأت كتاب \"الرسالة\" للشافعي خمسمائة مرة، ما من مرة منها إلا واستفدت فائدة جديدة لم أستفدها في الأخرى.\nوقال أيضا: أنا أنظر في كتاب \"الرسالة\" عن الشافعي منذ خمسين سنة، ما أعلم أني نظرت فيه من مرة إلا وأنا أستفيد شيئا لم أكن عرفته."},{"id":"risala-shafii:93","bookId":"risala-shafii","type":"section","seq":93,"chapter":"الجزء الأول","title":"الجزء الأول","page":"ج1 ص4","text":"من الرسالة\nرواية الربيع بن سليمان عن محمد بن إدريس الشافعي\nهذا العنوان صورة من عنوان الجزء الأول من الأصل وهو بخط الربيع بن سليمان صاحب الشافعي\nرموز نسخ الرسالة\nالأصل: نسخة الربيع بن سليمان، مخطوطة بدار الكتب المصرية، وهي أقدم الكتب الثابت تاريخها.\nوقد كتب الربيع بخطه في آخرها إذنا بنسخها في ذي القعدة سنة 265 وأنا أجزم بأنها كلها بخط الربيع، وأنه كتبها في حياة الشافعي، أي قبل آخر رجب سنة 204\nس: نسخة مطبوعة بمصر بالمطبعة الشرفية في سنة 1315 عن نسخة منقولة عن أصل الربيع.\nج: نسخة مطبوعة بمصر بالمطبعة العلمية في سنة 1312\nب: نسخة مطبوعة بمصر بالمطبعة الأميرية ببولاق في سنة 1321 مع كتاب \" الأم \" للشافعي.\nقران (اللغة التي استعملها الإمام الشافعي) : انظر \"قرآن\" (وهو الهجاء حسب المصطلح العصري)\nبسم الله الرحمن الرحيم\n. . . الربيع بن سليمان قال:\nبسم الله الرحمن الرحيم\nأخبرنا أبو عبد الله محمد بن إدريس بن العباس بن عثمان بن شافع بن السائب بن عبيد بن عبد يزيد بن هاشم بن المطلب بن عبد مناف المطلبي، ابن عم رسول الله صلى الله عليه وسلم.\nالحمد لله الذي خلق السماوات والأرض، وجعل الظلمات والنور، ثم الذين كفروا بربهم يعدلون.\nوالحمد لله الذي لا يؤدى شكر نعمة من نعمه؛\nإلا بنعمة منه توجب على مؤدي ماضي نعمه بأدائها نعمة حادثة، يجب عليه شكره بها.\nولا يبلغ الواصفون كنه عظمته. الذي هو كما وصف نفسه، وفوق ما يصفه به خلقه.\nأحمده حمدا كما ينبغي لكرم وجهه وعز جلاله.\nوأستعينه استعانة من لا حول له ولا قوة إلا به.\nوأستهديه بهداه الذي لا يضل من أنعم به عليه.\nوأستغفره لما أزلفت وأخرت: استغفار من يقر بعبوديته، ويعلم أنه لا يغفر ذنبه ولا ينجيه منه إلا هو.\nوأشهد أن لا إله إلا الله وحده لا شريك له، وأن محمدا عبده ورسوله.\nبعثه والناس صنفان:\nأحدهما: أهل كتاب بدلوا من أحكامه، وكفروا بالله، فافتعلوا كذبا صاغوه بألسنتهم، فخلطوه بحق الله الذي أنزل إليهم.\nفذكر تبارك وتعالى لنبيه من كفرهم، فقال: (وإن منهم لفريقا يلوون ألسنتهم بالكتاب، لتحسبوه من الكتاب، وما هو من الكتاب، ويقولون هو من عند الله، وما هو من عند الله، ويقولون على الله الكذب وهم يعلمون.) (سورة آل عمران / 78)\nثم قال: (فويل للذين يكتبون الكتاب بأيديهم، ثم يقولون: هذا من عند الله، ليشتروا به ثمنا قليلا، فويل لهم مما كتبت أيديهم، وويل لهم مما يكسبون) .\nوقال تبارك وتعالى: (وقالت اليهود: عزير ابن الله، وقالت النصارى: المسيح ابن الله. ذلك قولهم بأفواههم. يضاهئون قول الذين كفروا من قبل. قاتلهم الله! أنى يؤفكون؟! اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح ابن مريم. وما أمروا إلا ليعبدوا إلها واحدا لا إله إلا هو، سبحانه عما يشركون) (التوبة 30 - 31) .\nوقال تبارك وتعالى: (ألم تر إلى الذين أوتوا نصيبا من الكتاب يؤمنون بالجبت والطاغوت، ويقولون للذين كفروا:\nهؤلاء أهدى من الذين آمنوا سبيلا أولئك الذين لعنهم الله، ومن يلعن الله فلن تجد له نصيرا) (النساء 50 - 52)\nوصنف كفروا بالله، فابتدعوا ما لم يأذن به الله، ونصبوا بأيديهم حجارة وخشبا، وصورا استحسنوا، ونبزوا أسماء افتعلوا، ودعوها آلهة عبدوها، فإذا استحسنوا غير ما عبدوا منها، ألقوه ونصبوا بأيديهم غيره، فعبدوه: فأولئك العرب.\nوسلكت طائفة من العجم سبيلهم في هذا، وفي عبادة ما استحسنوا من حوت، ودابة، ونجم، ونار، وغيره.\nفذكر الله لنبيه جوابا من جواب بعض من عبد غيره من هذا الصنف، فحكى جل ثناؤه عنهم قولهم: إنا وجدنا آباءنا على أمة، وإنا على آثارهم مقتدون.\nوحكى تبارك وتعالى عنهم: (لا تذرن آلهتكم، ولا تذرن ودا ولا سواعا، ولا يغوث ويعوق ونسرا، وقد أضلوا كثيرا) (نوح 23 - 24)"},{"id":"risala-shafii:94","bookId":"risala-shafii","type":"section","seq":94,"chapter":"الجزء الأول","title":"ص: 11","page":"ج1 ص9","text":"وقال تبارك وتعالى: (واذكر في الكتاب إبراهيم. إنه كان صديقا نبيا إذ قال لأبيه: يا أبت! لم تعبد ما لا يسمع، ولا يبصر، ولا يغني عنك شيئا؟!) (مريم 41 - 42)\nوقال: (واتل عليهم نبأ إبراهيم إذ قال لأبيه وقومه: ما تعبدون؟ قالوا: نعبد أصناما فنظل لها عاكفين. قال: هل يسمعونكم إذ تدعون أو ينفعونكم، أو يضرون؟!) (الشعراء 69 - 70)\nوقال في جماعتهم، يذكرهم من نعمه، ويخبرهم ضلالتهم عامة، ومنه على من آمن منهم: (واذكروا نعمة الله عليكم إذ كنتم أعداء فألف بين قلوبكم، فأصبحتم بنعمته إخوانا، وكنتم على شفا حفرة من النار فأنقذكم منها. كذلك يبين الله لكم آياته لعلكم تهتدون) (آل عمران 103)\nقال: فكانوا قبل إنقاذه إياهم بمحمد صلى الله عليه وسلم أهل كفر في تفرقهم، واجتماعهم. يجمعهم أعظم الأمور: الكفر بالله، وابتداع ما لم يأذن به الله. تعالى عما يقولون علوا كبيرا. لا إله غيره، وسبحانه، وبحمده رب كل شيء وخالقه."},{"id":"risala-shafii:95","bookId":"risala-shafii","type":"section","seq":95,"chapter":"الجزء الأول","title":"ص: 12","page":"ج1 ص9","text":"من حي منهم فكما وصف حاله حيا: عاملا قائلا بسخط ربه مزدادا من معصيته.\nومن مات فكما وصف قوله وعمله: صار إلى عذابه.\nفلما بلغ الكتاب أجله فحق قضاء الله بإظهار دينه الذي اصطفى بعد استعلاء معصيته التي لم يرض: فتح أبواب سماواته برحمته، كما لم يزل يجري - في سابق علمه عند نزول قضائه في القرون الخالية -: قضاؤه.\nفإنه تبارك وتعالى يقول: (كان الناس أمة واحدة فبعث الله النبيين مبشرين ومنذرين) (البقرة 213)\nفكان خيرته المصطفى لوحيه، المنتخب لرسالته المفضل على جميع خلقه، بفتح رحمته، وختم نبوته، وأعم ما أرسل به مرسل قبله المرفوع ذكره مع ذكره في الأولى، والشافع المشفع في الأخرى، أفضل خلقه نفسا، وأجمعهم لكل خلق رضيه في دين ودنيا. وخيرهم نسبا ودارا محمدا عبده ورسوله."},{"id":"risala-shafii:96","bookId":"risala-shafii","type":"section","seq":96,"chapter":"الجزء الأول","title":"ص: 13","page":"ج1 ص9","text":"وعرفنا وخلقه (1) نعمه الخاصة، العامة النفع في الدين والدنيا.\nفقال: (لقد جاءكم رسول من أنفسكم، عزيز عليه ما عنتم، حريص عليكم، بالمؤمنين رءوف رحيم) (التوبة 128)\nوقال: (لتنذر أم القرى ومن حولها) (الشورى 7) ، وأم القرى: مكة، وفيها قومه.\nوقال: (وأنذر عشيرتك الأقربين) (الشعراء 214)\nوقال: (وإنه لذكر لك ولقومك وسوف تسألون) (الزخرف 44)\nقال الشافعي: أخبرنا ابن عيينة عن ابن أبي نجيح عن مجاهد في قوله: (وإنه لذكر لك ولقومك) قال: يقال: ممن الرجل؟ فيقال: من العرب. فيقال: من أي العرب؟ فيقال: من قريش."},{"id":"risala-shafii:97","bookId":"risala-shafii","type":"section","seq":97,"chapter":"الجزء الأول","title":"ص: 14","page":"ج1 ص10","text":"قال الشافعي: وما قال مجاهد من هذا بين في الآية مستغنى فيه بالتنزيل عن التفسير.\nفخص جل ثناؤه قومه وعشيرته الأقربين في النذارة، وعم الخلق بها بعدهم، ورفع بالقرآن ذكر رسول الله، ثم خص قومه بالنذارة إذ بعثه فقال: (وأنذر عشيرتك الأقربين)"},{"id":"risala-shafii:98","bookId":"risala-shafii","type":"section","seq":98,"chapter":"الجزء الأول","title":"ص: 15","page":"ج1 ص10","text":"وزعم بعض أهل العلم بالقرآن (1) أن رسول الله قال: يا بني عبد مناف! إن الله بعثني أن أنذر عشيرتي الأقربين، وأنتم عشيرتي الأقربون. (2)"},{"id":"risala-shafii:99","bookId":"risala-shafii","type":"section","seq":99,"chapter":"الجزء الأول","title":"ص: 16","page":"ج1 ص10","text":"قال الشافعي: أخبرنا بن عيينة عن ابن أبي نجيح عن مجاهد في قوله: (ورفعنا لك ذكرك) قال: لا أذكر إلا ذكرت معي: أشهد أن لا إله إلا الله، وأشهد أن محمدأ رسول الله.\nيعني - والله أعلم - ذكره عند الإيمان بالله، والآذان. ويحتمل ذكره عند تلاوة الكتاب، وعند العمل بالطاعة، والوقوف عن المعصية.\nفصلى الله على نبينا كلما ذكره الذاكرون، وغفل عن ذكره الغافلون، وصلى عليه في الأولين والآخرين، أفضل وأكثر وأزكى ما صلى على أحد من خلقه. وزكانا وإياكم بالصلاة عليه أفضل ما زكى أحدا من أمته بصلاته عليه، والسلام عليه ورحمة الله وبركاته، وجزاه الله عنا أفضل ما جزى مرسلا عن من أرسل إليه؛ فإنه أنقذنا به من الهلكة، وجعلنا في خير أمة أخرجت للناس، دائنين بدينه الذي ارتضى، واصطفى به ملائكته ومن أنعم عليه من خلقه. فلم تمس بنا نعمة ظهرت ولا بطنت، نلنا بها حظا في دين ودنيا أو دفع بها عنا مكروه فيهما، وفي واحد منهما: إلا ومحمد صلى الله عليه سببها، القائد إلى خيرها، والهادي إلى رشدها، الذائد عن الهلكة وموارد السوء في خلاف الرشد، المنبه للأسباب التي تورد الهلكة، القائم بالنصيحة في الإرشاد والإنذار فيها. فصلى الله على محمد وعلى آل محمد كما صلى على إبراهيم وآل إبراهيم إنه حميد مجيد."},{"id":"risala-shafii:100","bookId":"risala-shafii","type":"section","seq":100,"chapter":"الجزء الأول","title":"ص: 17","page":"ج1 ص10","text":"وأنزل عليه كتابه فقال: (وإنه لكتاب عزيز. لا يأتيه الباطل من بين يديه، ولا من خلفه. تنزيل من حكيم حميد) (فصلت 41 - 42) فنقلهم من الكفر والعمى إلى الضياء والهدى، وبين فيه ما أحل: منا بالتوسعة على خلقه، وما حرم: لما هو أعلم به من حظهم في الكف عنه في الآخرة والأولى. وابتلى طاعتهم بأن تعبدهم بقول، وعمل وإمساك عن محارم حماهموها، وأثابهم على طاعته من الخلود في جنته، والنجاة من نقمته: ما عظمت به نعمته جل ثناؤه."},{"id":"risala-shafii:101","bookId":"risala-shafii","type":"section","seq":101,"chapter":"الجزء الأول","title":"ص: 18","page":"ج1 ص10","text":"وأعلمهم ما أوجب لأهل طاعته.\nووعظهم بالأخبار عمن كان قبلهم، ممن كان أكثر منهم أموالا وأولادا، وأطول أعمارا، وأحمد آثارا، فاستمتعوا بخلاقهم في حياة دنياهم، فأذاقهم عند نزول قضائه مناياهم دون آماله، ونزلت بهم عقوبته عند انقضاء آجالهم، ليعتبروا في أنف الأوان، ويتفهموا بجلية التبيان، ويتنبهوا قبل رين الغفلة، ويعملوا قبل انقطاع المدة حين لا يعتب مذنب، ولا تؤخذ فدية، و (تجد كل نفس ما عملت من خير محضرا وما عملت من سوء تود لو أن بينها وبينه أمدا بعيدا) (آل عمران 30)"},{"id":"risala-shafii:102","bookId":"risala-shafii","type":"section","seq":102,"chapter":"الجزء الأول","title":"ص: 19","page":"ج1 ص10","text":"فكل ما أنزل في كتابه - جل ثناؤه - رحمة وحجة، علمه من علمه، وجهله من جهله، لا يعلم من جهله، ولا يجهل من علمه.\nوالناس في العلم طبقات، موقعهم من العلم بقدر درجاتهم في العلم به.\nفحق على طلبة العلم بلوغ غاية جهدهم في الاستكثار من علمه، والصبر على كل عارض دون طلبه، وإخلاص النية لله في استدراك علمه نصا واستنباطا، والرغبة إلى الله في العون عليه، فإنه لا يدرك خير إلا بعونه.\nفإن من أدرك علم أحكام الله في كتابه نصا واستدلالا، ووفقه الله للقول والعمل بما علم منه: فاز بالفضيلة في دينه ودنياه، وانتفت عنه الريب، ونورت في قلبه الحكمة، واستوجب في الدين موضع الإمامة.\nفنسأل الله المبتدئ لنا بنعمه قبل استحقاقها، المديمها علينا مع تقصيرنا في الإتيان إلى ما أوجب به من شكره بها، الجاعلنا في خير أمة أخرجت للناس: أن يرزقنا فهما في كتابه، ثم سنة نبيه، وقولا وعملا يؤدي به عنا حقه، ويوجب لنا نافلة مزيدة."},{"id":"risala-shafii:103","bookId":"risala-shafii","type":"section","seq":103,"chapter":"الجزء الأول","title":"ص: 20","page":"ج1 ص13","text":"قال الشافعي: فليست تنزل بأحد من أهل دين الله نازلة إلا وفي كتاب الله الدليل على سبيل الهدى فيها.\nقال الله تبارك وتعالى: (كتاب أنزلناه إليك لتخرج الناس من الظلمات إلى النور بإذن ربهم إلى صراط العزيز الحميد) (إبراهيم 1)\nوقال: (وأنزلنا إليك الذكر لتبين للناس ما نزل إليهم ولعلهم يتفكرون) (النحل 44)\nوقال: (ونزلنا عليك الكتاب تبيانا لكل شيء وهدى ورحمة وبشرى للمسلمين) (النحل 89)\nوقال: (وكذلك أوحينا إليك روحا من أمرنا، ما كنت تدري ما الكتاب، ولا الإيمان، ولكن جعلناه نورا نهدي به من نشاء من عبادنا، وإنك لتهدي إلى صراط مستقيم) (الشورى 52)"},{"id":"risala-shafii:104","bookId":"risala-shafii","type":"section","seq":104,"chapter":"الجزء الأول","title":"باب: كيف البيان؟","page":"ج1 ص19","text":"قال الشافعي: والبيان اسم جامع لمعاني مجتمعة الأصول، متشعبة الفروع:\nفأقل ما في تلك المعاني المجتمعة المتشعبة: أنها بيان لمن خوطب بها ممن نزل القرآن بلسانه، متقاربة، الاستواء عنده، وإن كان بعضها أشد تأكيد بيان من بعض. ومختلفة عند من يجهل لسان العرب.\nقال الشافعي: فجماع ما أبان الله لخلقه في كتابه، مما تعبدهم به، لما مضى من حكمه جل ثناؤه: من وجوه.\nفمنها ما أبانه لخلقه نصا. مثل جمل فرائضه، في أن عليهم صلاة وزكاة وحجا وصوما وأنه حرم الفواحش، ما ظهر منها، وما بطن، ونص الزنا (1) والخمر، وأكل الميتة والدم، ولحم الخنزير، وبين لهم كيف فرض الوضوء، مع غير ذلك مما بين نصا.","bab":"باب: كيف البيان؟"},{"id":"risala-shafii:105","bookId":"risala-shafii","type":"section","seq":105,"chapter":"الجزء الأول","title":"ص: 22","page":"ج1 ص21","text":"ومنه: ما أحكم فرضه بكتابه، وبين كيف هو على لسان نبيه؟ مثل عدد الصلاة، والزكاة، ووقتها، وغير ذلك من فرائضه التي أنزل من كتابه.\nومنه: ما سن رسول الله صلى الله عليه وسلم مما ليس لله فيه نص حكم، وقد فرض الله في كتابه طاعة رسوله صلى الله عليه وسلم، والانتهاء إلى حكمه، فمن قبل عن رسول الله فبفرض الله قبل.\nومنه: ما فرض الله على خلقه الاجتهاد في طلبه، وابتلى طاعتهم في الاجتهاد، كما ابتلى طاعتهم في غيره مما فرض عليهم.\nفإنه يقول تبارك وتعالى: (ولنبلونكم حتى نعلم المجاهدين منكم والصابرين، ونبلو أخباركم) (محمد 31)","bab":"باب: كيف البيان؟"},{"id":"risala-shafii:106","bookId":"risala-shafii","type":"section","seq":106,"chapter":"الجزء الأول","title":"ص: 23","page":"ج1 ص21","text":"وقال: (وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم) (آل عمران 154)\nوقال: (عسى ربكم أن يهلك عدوكم، ويستخلفكم في الأرض فينظر كيف تعملون؟) (الأعراف 129)\nقال الشافعي: فوجههم بالقبلة إلى المسجد الحرام، وقال لنبيه: (قد نرى تقلب وجهك في السماء، فلنولينك قبلة ترضاها، فول وجهك شطر المسجد الحرام، وحيث ما كنتم فولوا وجوهكم شطره) (البقرة 144)\nوقال: (ومن خرجت فول وجهك شطر المسجد الحرام، وحيث ما كنتم فولوا وجوهكم شطره، لئلا يكون للناس عليكم حجة) (البقرة 150) .\nفدلهم جل ثناؤه إذا غابوا عن عين المسجد الحرام على صواب الاجتهاد، مما فرض عليهم منه، بالعقول التي ركب فيهم، المميزة بين الأشياء، وأضدادها، والعلامات التي نصب لهم دون عين المسجد الحرام الذي أمرهم بالتوجه شطره.","bab":"باب: كيف البيان؟"},{"id":"risala-shafii:107","bookId":"risala-shafii","type":"section","seq":107,"chapter":"الجزء الأول","title":"ص: 24","page":"ج1 ص21","text":"فقال: (وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر) (الأنعام 97) ، وقال: (وعلامات وبالنجم هم يهتدون) (النحل 16)\nفكانت العلامات جبالا وليلا ونهارا، فيها أرواح (2) معروفة الأسماء، وإن كانت مختلفة المهاب. وشمس وقمر، ونجوم معروفة المطالع والمغارب، والمواضع من الفلك.\nففرض عليهم الاجتهاد بالتوجه شطر المسجد الحرام، مما دلهم عليه مما وصفت، فكانوا ما كانوا مجتهدين غير مزايلين أمره جل ثناؤه. ولم يجعل لهم إذا غاب عنهم عين المسجد الحرام أن يصلوا حيث شاؤوا","bab":"باب: كيف البيان؟"},{"id":"risala-shafii:108","bookId":"risala-shafii","type":"section","seq":108,"chapter":"الجزء الأول","title":"ص: 25","page":"ج1 ص21","text":"وكذلك أخبرهم عن قضائه فقال: (أيحسب الإنسان أن يترك سدى) (القيامة 36) والسدى: الذي لا يؤمر ولا ينهى.\nوهذا يدل على أنه ليس لأحد دون رسول الله أن يقول إلا بالاستدلال بما وصفت في هذا، وفي العدل، وفي جزاء الصيد، ولا يقول بما استحسن، فإن القول بما استحسن شيء يحدثه لا على مثال سبق\nفأمرهم أن يشهدوا ذوي عدل، والعدل: أن يعمل بطاعة الله، فكان لهم السبيل إلى علم العدل والذي يخالفه.\nوقد وضع هذا في موضعه، وقد وضعت جملا منه رجوت أن تدل على ما وراءها مما في مثل معناها.","bab":"باب: كيف البيان؟"},{"id":"risala-shafii:109","bookId":"risala-shafii","type":"section","seq":109,"chapter":"الجزء الأول","title":"باب البيان الأول","page":"ج1 ص21","text":"قال الله تبارك وتعالى في المتمتع: (فمن تمتع بالعمرة إلى الحج فما استيسر من الهدي فمن لم يجد فصيام ثلاثة أيام في الحج، وسبعة إذا رجعتم. تلك عشرة كاملة. ذلك لمن لم يكن أهله حاضري المسجد الحرام) (البقرة 196)\nفكان بينا عند من خوطب بهذه الآية أن صوم الثلاثة في الحج، والسبع في المرجع عشرة أيام كاملة.\nقال الله: (تلك عشرة كاملة) فاحتملت أن تكون زيادة في التبيين، واحتملت أن يكون أعلمهم أن ثلاثة إذا جمعت إلى سبع كانت عشرة كاملة.","bab":"باب البيان الأول"},{"id":"risala-shafii:110","bookId":"risala-shafii","type":"section","seq":110,"chapter":"الجزء الأول","title":"ص: 27","page":"ج1 ص26","text":"وقال الله: (وواعدنا موسى ثلاثين ليلة، وأتممناها بعشر، فتم ميقات ربه أربعين ليلة) (الأعراف 142)\nفكان بينا عند من خوطب بهذه الآية أن ثلاثين، وعشرا أربعون ليلة.\nوقوله: (أربعين ليلة) يحتمل ما احتملت الآية قبلها: من أن تكون: إذا جمعت ثلاثون إلى عشر كانت أربعين، وأن تكون زيادة في التبيين.\nوقال الله: (كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون. أياما معدودات، فمن كان منكم مريضا، أو على سفر فعدة من أيام أخر) (البقرة 183 - 184)\nوقال: (شهر رمضان الذي أنزل فيه القرآن هدى للناس وبينات من الهدى والفرقان، فمن شهد منكم الشهر فليصمه، ومن كان مريضا أو على سفر، فعدة من أيام أخر) (البقرة 185)\nفافترض عليهم الصوم، ثم بين أنه شهر، والشهر عندهم ما بين الهلالين، وقد يكون ثلاثين، وتسعا وعشرين.","bab":"باب البيان الأول"},{"id":"risala-shafii:111","bookId":"risala-shafii","type":"section","seq":111,"chapter":"الجزء الأول","title":"ص: 28","page":"ج1 ص26","text":"فكانت الدلالة في هذا كالدلالة في الآيتين، وكان في الآيتين قبله: في ابن جماعة ((زيادة تبين جماع العدد)) .\nوأشبه الأمور بزيادة تبيين جملة العدد في السبع، والثلاث، وفي الثلاثين والعشر: أن تكون زيادة في التبيين؛ لأنهم لم يزالوا يعرفون هذين العددين وجماعة، كما لم يزالوا يعرفون شهر رمضان.","bab":"باب البيان الأول"},{"id":"risala-shafii:112","bookId":"risala-shafii","type":"section","seq":112,"chapter":"الجزء الأول","title":"باب البيان الثاني","page":"ج1 ص26","text":"قال الله تبارك وتعالى: (إذا قمتم إلى الصلاة، فاغسلوا وجوهكم وأيديكم إلى المرافق، وامسحوا برءوسكم وأرجلكم إلى الكعبين، وإن كنتم جنبا فاطهروا) (المائدة 6)\nوقال: (ولا جنبا إلا عابري سبيل) (النساء 43)","bab":"باب البيان الثاني"},{"id":"risala-shafii:113","bookId":"risala-shafii","type":"section","seq":113,"chapter":"الجزء الأول","title":"ص: 29","page":"ج1 ص28","text":"فأتى كتاب الله على البيان في الوضوء دون الاستنجاء بالحجارة، وفي الغسل من الجنابة.\nثم كان أقل غسل الوجه، والأعضاء مرة مرة، واحتمل ما هو أكثر منها، فبين رسول الله الوضوء مرة، وتوضأ ثلاثا، ودل على أن أقل غسل الأعضاء يجزئ، وأن أقل عدد الغسل واحدة. وإذا أجزأت واحدة فالثلاث اختيار.\nودلت السنة على أنه يجزئ في الاستنجاء ثلاثة أحجار، ودل النبي على ما يكون منه الوضوء، وما يكون منه الغسل، ودل على أن الكعبين والمرفقين مما يغسل؛ لأن الآية تحتمل أن يكونا حدين للغسل، وأن يكونا داخلين في الغسل. ولما قال رسول الله ((ويل للأعقاب من النار)) دل على أنه غسل لا مسح.\nقال الله: (ولأبويه لكل واحد منهما السدس مما ترك إن كان له ولد، فإن لم يكن له ولد وورثه أبواه، فلأمه الثلث، فإن كان له أخوة فلأمه السدس) (النساء 11)","bab":"باب البيان الثاني"},{"id":"risala-shafii:114","bookId":"risala-shafii","type":"section","seq":114,"chapter":"الجزء الأول","title":"ص: 30","page":"ج1 ص28","text":"وقال: (ولكم نصف ما ترك أزواجكم إن لم يكن لهن ولد، فإن كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها أو دين، ولهن الربع مما تركتم إن لم يكن لكم ولد، فإن كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها أو دين، وإن كان رجل يورث كلالة أو امرأة، وله أخ أو أخت فلكل واحد منهما السدس، فإن كانوا أكثر من ذلك، فهم شركاء في الثلث من بعد وصية يوصى بها أو دين غير مضار وصية من الله، والله عليم حليم) (النساء 12)\nفاستغني بالتنزيل في هذا عن خبر غيره، ثم كان لله فيه شرط أن يكون بعد الوصية والدين، فدل الخبر على أن لا يجاوز بالوصية الثلث.","bab":"باب البيان الثاني"},{"id":"risala-shafii:115","bookId":"risala-shafii","type":"section","seq":115,"chapter":"الجزء الأول","title":"باب البيان الثالث","page":"ج1 ص28","text":"قال الله تبارك وتعالى: (إن الصلاة كانت على المؤمنين كتابا موقوتا) (النساء 103)\nوقال: (وأقيموا الصلاة، وآتوا الزكاة) (البقرة 43)\nوقال: (وأتموا الحج والعمرة لله) (البقرة 196)\nثم بين على لسان رسوله عدد ما فرض من الصلوات، ومواقيتها وسننها، وعدد الزكاة ومواقيتها، وكيف عمل الحج والعمرة، وحيث يزول هذا ويثبت، وتختلف سننه وتاتفق (1) ، ولهذا أشباه كثيرة في القرآن والسنة.","bab":"باب البيان الثالث"},{"id":"risala-shafii:116","bookId":"risala-shafii","type":"section","seq":116,"chapter":"الجزء الأول","title":"باب البيان الرابع","page":"ج1 ص31","text":"قال الشافعي: كل ما سن رسول الله مما ليس فيه كتاب، وفيما كتبنا في كتابنا هذا، من ذكر ما من الله به على العباد من تعلم الكتاب والحكمة: دليل على أن الحكمة سنة رسول الله.\nمع ما ذكرنا مما افترض الله على خلقه من طاعة رسوله، وبين من موضعه الذي وضعه الله به من دينه: الدليل على أن البيان في الفرائض المنصوصة في كتاب الله من أحد هذه الوجوه.\nمنها: ما أتى الكتاب على غاية البيان فيه، فلم يحتج مع التنزيل فيه إلى غيره\nومنها: ما أتى على غاية البيان في فرضه وافترض طاعة رسوله، فبين رسول الله عن الله كيف فرضه؟ وعلى من فرضه؟ ومتى يزول بعضه ويثبت ويجب؟","bab":"باب البيان الرابع"},{"id":"risala-shafii:117","bookId":"risala-shafii","type":"section","seq":117,"chapter":"الجزء الأول","title":"ص: 33","page":"ج1 ص32","text":"ومنها: ما بينه عن سنة نبيه بلا نص كتاب.\nوكل شيء منها بيان في الكتاب الله.\nفكل من قبل عن الله فرائضه في كتابه: قبل عن رسول الله سننه بفرض الله طاعة رسوله على خلقه، وأن ينتهوا إلى حكمه، ومن قبل عن رسول الله، فمن الله قبل لما افترض الله من طاعته.\nفيجمع القبول لما في كتاب الله، ولسنة رسول الله: القبول لكل واحد منهما عن الله، وإن تفرقت فروع الأسباب التي قبل بها عنهما، كما أحل وحرم، وفرض وحد بأسباب متفرقة، كما شاء جل ثناؤه، (لا يسأل عما يفعل، وهم يسألون) (الأنبياء 23)","bab":"باب البيان الرابع"},{"id":"risala-shafii:118","bookId":"risala-shafii","type":"section","seq":118,"chapter":"الجزء الأول","title":"باب البيان الخامس","page":"ج1 ص32","text":"قال الله تبارك وتعالى: (ومن حيث خرجت فول وجهك شطر المسجد الحرام، وحيث ما كنتم فولوا وجوهكم شطره) (البقرة 150)\nففرض عليهم حيث ما كانوا أن يولوا وجوههم شطره، وشطره جهته في كلام العرب. إذا قلت أقصد شطر كذا، معروف أنك تقول: أقصد قصد عين كذا، يعني قصد نفس كذا، وكذلك ((تلقاءه)) جهته، أي أستقبل تلقاءه، وجهته، وإن كلها معنى واحد، وإن كانت بألفاظ مختلفة.\nوقال خفاف بن ندبة:\nألا من مبلغ عمرا رسولا ... وما تغني الرسالة شطر عمرو","bab":"باب البيان الخامس"},{"id":"risala-shafii:119","bookId":"risala-shafii","type":"section","seq":119,"chapter":"الجزء الأول","title":"ص: 35","page":"ج1 ص34","text":"وقال ساعدة بن جؤية:\nأقول لأم زنباع أقيمي ... صدور العيس شطر بني تميم\nوقال لقيط الأيادي:\nوقد أظلكم من شطر ثغركم ... هول له ظلم تغشاكم قطعا\nوقال الشاعر:\nإن العسير بها داء مخامرها ... فشطرها بصر العينين مسحور","bab":"باب البيان الخامس"},{"id":"risala-shafii:120","bookId":"risala-shafii","type":"section","seq":120,"chapter":"الجزء الأول","title":"ص: 36","page":"ج1 ص34","text":"قال الشافعي: يريد تلقاءها بصر العينين، ونحوها: تلقاء جهتها.\nوهذا كله - مع غيره من أشعارهم - يبين أن شطر الشيء قصد عين الشيء: إذا كان معاينا فبالصواب، وإذا كان مغيبا فبالاجتهاد بالتوجه إليه، وذلك أكثر ما يمكنه فيه.","bab":"باب البيان الخامس"},{"id":"risala-shafii:121","bookId":"risala-shafii","type":"section","seq":121,"chapter":"الجزء الأول","title":"ص: 38","page":"ج1 ص34","text":"وقال الله: (جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر) (الأنعام 97)\n(وعلامات وبالنجم هم يهتدون) (النحل 16)\nفخلق لهم العلامات، ونصب لهم المسجد الحرام، وأمرهم أن يتوجهوا إليه. وإنما توجههم إليه بالعلامات التي خلق لهم، والعقول التي ركبها فيهم، التي استدلوا بها على معرفة العلامات. وكل هذا بيان، ونعمة منه جل ثناؤه.\n(وأشهدوا ذوي عدل منكم) (الطلاق 2) ، وقال: (ممن ترضون من الشهداء) (البقرة 282)\nأبان أن العدل العامل بطاعته، فمن رأوه عاملا بها كان عدلا، ومن عمل بخلافها كان خلاف العدل.\nوقال جل ثناؤه: (لا تقتلوا الصيد وأنتم حرم، ومن قتله منكم متعمدا، فجزاء مثل ما قتل من النعم، يحكم به ذوا عدل منكم هديا بالغ الكعبة) (المائدة 95)","bab":"باب البيان الخامس"},{"id":"risala-shafii:122","bookId":"risala-shafii","type":"section","seq":122,"chapter":"الجزء الأول","title":"ص: 39","page":"ج1 ص34","text":"فكان المثل - على الظاهر - أقرب الأشياء شبها في العظم من البدن. واتفقت مذاهب من تكلم في الصيد من أصحاب رسول الله على أقرب الأشياء شبها من البدن. فنظرنا ما قتل من دواب الصيد: أي شيء كان من النعم أقرب منه شبها فديناه به.\nولم يحتمل المثل من النعم القيمة فيما له مثل في البدن من النعم: إلا مستكرها باطنا. فكان الظاهر الأعم أولى المعنيين بها. وهذا الاجتهاد الذي يطلبه الحاكم بالدلالة على المثل.\nوهذا الصنف من العلم: دليل على ما وصفت قبل هذا على أن ليس لأحد أبدا أن يقول في شيء حل ولا حرم إلا من جهة العلم. وجهة العلم الخبر: في الكتاب، أو السنة، أو الإجماع، أو القياس.\nومعنى هذا الباب معنى القياس؛ لأنه يطلب فيه الدليل على صواب القبلة، والعدل، والمثل.","bab":"باب البيان الخامس"},{"id":"risala-shafii:123","bookId":"risala-shafii","type":"section","seq":123,"chapter":"الجزء الأول","title":"ص: 40","page":"ج1 ص34","text":"والقياس ما طلب بالدلائل على موافقة الخبر المتقدم، من الكتاب أو السنة؛ لأنهما علم الحق المفترض طلبه، كطلب ما وصفت قبله، من القبلة والعدل والمثل.\nوموافقته تكون من وجهين:\nأحدهما: أن يكون الله أو رسوله حرم الشيء منصوصا، أو أحله لمعنى، فإذا وجدنا ما في مثل ذلك المعنى فيما لم ينص فيه بعينه كتاب ولا سنة: أحللناه أو حرمناه؛ لأنه في معنى الحلال أو الحرام.\nأو نجد الشيء يشبه الشيء منه، والشيء من غيره، ولا نجد شيئا أقرب به شبها من أحدهما: فنلحقه بأولى الأشياء شبها به، كما قلنا في الصيد.\nقال الشافعي: وفي العلم وجهان: الإجماع والاختلاف. وهما موضوعان في غير هذا الموضع.\nومن جماع علم كتاب الله: العلم بأن جميع كتاب الله إنما نزل بلسان العرب.","bab":"باب البيان الخامس"},{"id":"risala-shafii:124","bookId":"risala-shafii","type":"section","seq":124,"chapter":"الجزء الأول","title":"ص: 41","page":"ج1 ص34","text":"والمعرفة بناسخ كتاب الله، ومنسوخة، والفرض في تنزيله، والأدب، والإرشاد، والإباحة.\nوالمعرفة بالموضع الذي وضع الله به نبيه من الإبانة عنه، فيما أحكم فرضه في كتابه، وبينه على لسان نبيه. وما أراد بجميع فرائضه؟ ومن أراد: أكل خلقه أم بعضهم دون بعض؟ وما افترض على الناس من طاعته، والانتهاء إلى أمره.\nثم معرفة ما ضرب فيها من الأمثال الدوال على طاعته المبينة لاجتناب معصيته، وترك الغفلة عن الحظ، والازدياد من نوافل الفضل.\nفالواجب على العالمين أن لا يقولوا إلا من حيث علموا.\nوقد تكلم في العلم من لو أمسك عن بعض ما تكلم فيه منه لكان الإمساك أولى به، وأقرب من السلامة له إن شاء الله.\nفقال منهم قائل: إن في القرآن عربيا وأعجميا","bab":"باب البيان الخامس"},{"id":"risala-shafii:125","bookId":"risala-shafii","type":"section","seq":125,"chapter":"الجزء الأول","title":"ص: 42","page":"ج1 ص34","text":"والقرآن يدل على أن ليس من كتاب الله شيء إلا بلسان العرب.\nووجد قائل هذا القول من قبل ذلك منه تقليدا له، وتركا للمسألة عن حجته، ومسألة غيره ممن خالفه.\nوبالتقليد أغفل من أغفل منهم، والله يغفر لنا ولهم.\nولعل من قال: إن في القرآن غير لسان العرب، وقبل ذلك منه ذهب إلى أن من القرآن خاصا يجهل بعضه بعض العرب.\nولسان العرب: أوسع الألسنة مذهبا، وأكثرها ألفاظا، ولا نعلمه يحيط بجميع علمه إنسان غير نبي، ولكنه لا يذهب منه شيء على عامتها، حتى لا يكون موجودا فيها من يعرفه.\nوالعلم به عند العرب كالعلم بالسنة عند أهل الفقه، لا نعلم رجلا جمع السنن فلم يذهب منها عليه شيء.","bab":"باب البيان الخامس"},{"id":"risala-shafii:126","bookId":"risala-shafii","type":"section","seq":126,"chapter":"الجزء الأول","title":"ص: 43","page":"ج1 ص34","text":"فإذا جمع علم عامة أهل العلم بها أتى على السنن، وإذا فرق علم كل واحد منهم ذهب عليه الشيء منها، ثم ما كان ذهب عليه منها موجودا عند غيره.\nوهم في العلم طبقات منهم الجامع لأكثره، وإن ذهب عليه بعضه، ومنهم الجامع لأقل مما جمع غيره.\nوليس قليل ما ذهب من السنن على من جمع أكثرها: دليلا على أن يطلب علمه عند غير طبقته من أهل العلم، بل يطلب عن نظرائه ما ذهب عليه حتى يؤتى على جميع سنن رسول الله - بأبي هو وأمي - فيتفرد جملة العلماء بجمعها، وهم درجات فيما وعوا منها.","bab":"باب البيان الخامس"},{"id":"risala-shafii:127","bookId":"risala-shafii","type":"section","seq":127,"chapter":"الجزء الأول","title":"ص: 44","page":"ج1 ص34","text":"وهكذا لسان العرب عند خاصتها وعامتها. لا يذهب منه شيء عليها، ولا يطلب عند غيرها، ولا يعلمه إلا من قبله عنها، ولا يشركها فيه إلا من اتبعها في تعلمه منها، ومن قبله منها فهو من أهل لسانها.\nوإنما صار غيرهم من غير أهله بتركه، فإذا صار إليه صار من أهله.\nوعلم أكثر اللسان في أكثر العرب أعم من علم أكثر السنن في العلماء.\nفإن قال قائل: فقد نجد من العجم من ينطق بالشيء من لسان العرب؟\nفذلك يحتمل ما وصفت من تعلمه منهم، فإن لم يكن ممن تعلمه منهم فلا يوجد ينطق إلا بالقليل منه، ومن نطق بقليل منه، فهو تبع للعرب فيه.\nولا ننكر إذ كان اللفظ قيل تعلما، أو نطق (45) به موضوعا: أن يوافق لسان العجم، أو بعضها قليلا من لسان العرب، كما ياتفق القليل من ألسنة العجم المتباينة في أكثر كلامها، مع تنائي ديارها، واختلاف لسانها، وبعد الأواصر بينها وبين من وافقت بعض لسانه منها.\nفإن قال قائل: ما الحجة في أن كتاب الله محض بلسان العرب، لا يخلطه فيه غيره؟\nفالحجة فيه كتاب الله قال الله: (وما أرسلنا من رسول إلا بلسان قومه) (إبراهيم 4)\nفإن قال قائل: فإن الرسل قبل محمد كانوا يرسلون إلى قومهم خاصة، وإن محمدا بعث إلى الناس كافة، فقد يحتمل أن يكون بعث بلسان قومه خاصة، ويكون على الناس كافة أن يتعلموا لسانه، وما أطاقوا منه، ويحتمل أن يكون بعث بألسنتهم: فهل من دليل على أنه بعث بلسان قومه خاصة دون ألسنة العجم؟","bab":"باب البيان الخامس"},{"id":"risala-shafii:128","bookId":"risala-shafii","type":"section","seq":128,"chapter":"الجزء الأول","title":"ص: 46","page":"ج1 ص34","text":"فإن كانت الألسنة مختلفة بما لا يفهمه بعضهم عن بعض، فلا بد أن يكون بعضهم تبعا لبعض، وأن يكون الفضل في اللسان المتبع على التابع.\nوأولى الناس بالفضل في اللسان من لسانه لسان النبي. ولا يجوز - والله أعلم - أن يكون أهل لسانه أتباعا لأهل لسان غير لسانه في حرف واحد، بل كل لسان تبع للسانه، وكل أهل دين قبله فعليهم اتباع دينه.\nوقد بين الله ذلك في غير آية من كتابه:\nقال الله: (وإنه لتنزيل رب العالمين. نزل به الروح الأمين على قلبك لتكون من المنذرين بلسان عربي مبين) (الشعراء 192 - 193)\nوقال: (وكذلك أنزلناه حكما عربيا) (الرعد 37)\nوقال: (وكذلك أوحينا إليك قرآنا عربيا لتنذر أم القرى، ومن حولها) (الشورى 7)","bab":"باب البيان الخامس"},{"id":"risala-shafii:129","bookId":"risala-shafii","type":"section","seq":129,"chapter":"الجزء الأول","title":"ص: 47","page":"ج1 ص34","text":"وقال: (حم. والكتاب المبين. إنا جعلناه قرآنا عربيا لعلكم تعقلون) (الزخرف 1 - 3)\nوقال: (قرآنا عربيا غير ذي عوج لعلهم يتقون) (الزمر 28)\nقال الشافعي: فأقام حجته بأن كتابه عربي في كل آية ذكرناها، ثم أكد ذلك بأن نفى عنه - جل ثناؤه - كل لسان غير لسان العرب في آيتين من كتابه.\nفقال تبارك وتعالى: (ولقد نعلم أنهم يقولون: إنما يعلمه بشر. لسان الذي يلحدون إليه أعجمي، وهذا لسان عربي مبين) (النحل 103)\nوقال: (ولو جعلناه أعجميا لقالوا: لولا فصلت آياته، أعجمي وعربي؟!) (فصلت 44)\nقال الشافعي: وعرفنا نعمه بما خصنا به من مكانه، فقال: (لقد جاءكم رسول من أنفسكم، عزيز عليه ما عنتم، حريص عليكم، بالمؤمنين رؤف رحيم) [التوبة 128]\nوقال: \" هو الذي بعث في الأميين رسولا منهم يتلو عليهم آياته، ويزكيهم، ويعلمهم الكتاب والحكمة، وإن كانوا من قبل لفي ضلال مبين (2) \" [الجمعة] .\nوكان مما عرف الله نبيه من إنعامه، أن قال: \" وإنه لذكر لك ولقومك (44) \" [الزخرف] ، فخص قومه بالذكر معه بكتابه.\nوقال: \" وأنذر عشيرتك الأقربين (214) \" [الشعراء] ، وقال: \" لتنذر أم القرى ومن حولها (7) \" [الشورى] ، وأم القرى: مكة، وهي بلده وبلد قومه، فجعلهم في كتابه خاصة، وأدخلهم مع المنذرين عامة، وقضى أن ينذروا بلسانهم العربي، لسان قومه منهم خاصة.\nفعلى كل مسلم أن يتعلم من لسان العرب ما بلغه جهده، حتى يشهد به أن لا إله إلا الله، وأن محمدا عبده ورسوله، ويتلو به كتاب الله، وينطق بالذكر فيما افترض عليه من التكبير، وأمر به من التسبيح، والتشهد، وغير ذلك.","bab":"باب البيان الخامس"},{"id":"risala-shafii:130","bookId":"risala-shafii","type":"section","seq":130,"chapter":"الجزء الأول","title":"ص: 49","page":"ج1 ص34","text":"وما ازداد من العلم باللسان، الذي جعله الله لسان من ختم به نبوته، وأنزل به آخر كتبه: كان خيرا له. كما عليه يتعلم (1) الصلاة والذكر فيها، ويأتي البيت، وما أمر بإتيانه، ويتوجه لما وجه له. ويكون تبعا فيما افترض عليه، وندب إليه، لا متبوعا.","bab":"باب البيان الخامس"},{"id":"risala-shafii:131","bookId":"risala-shafii","type":"section","seq":131,"chapter":"الجزء الأول","title":"ص: 50","page":"ج1 ص34","text":"وإنما بدأت بما وصفت، من أن القرآن نزل بلسان العرب دون غيره: لأنه لا يعلم من إيضاح جمل علم الكتاب أحد، جهل سعة لسان العرب، وكثرة وجوهه، وجماع معانيه، وتفرقها. ومن علمه انتفت عنه الشبه التي دخلت على من جهل لسانها.\nفكان تنبيه العامة على أن القرآن نزل بلسان العرب خاصة: نصيحة للمسلمين. والنصيحة لهم فرض، لا ينبغي تركه، وإدراك نافلة خير لا يدعها إلا من سفه نفسه، وترك موضع حظه. وكان يجمع مع النصيحة لهم قياما بإيضاح حق. وكان القيام بالحق، ونصيحة المسلمين من طاعة الله. وطاعة الله جامعة للخير.\nأخبرنا \"سفيان\" عن \"زياد بن علاقة\"، قال: سمعت \"جرير بن عبد الله\" يقول: \" بايعت النبي على النصح لكل مسلم \" (1) .","bab":"باب البيان الخامس"},{"id":"risala-shafii:132","bookId":"risala-shafii","type":"section","seq":132,"chapter":"الجزء الأول","title":"ص: 51","page":"ج1 ص47","text":"أخبرنا \"ابن عيينة\" عن \"سهيل ابن أببي صالح\"، عن \"عطاء بن يزيد\" عن \"تميم الداري\"، أن النبي قال: \" إن الدين النصيحة، إن الدين النصيحة، إن الدين النصيحة: لله، ولكتابه، ولنبيه، ولأئمة المسلمين، وعامتهم \" (2) .\nقال \"الشافعي\": فإنما خاطب الله بكتابه العرب","bab":"باب البيان الخامس"},{"id":"risala-shafii:133","bookId":"risala-shafii","type":"section","seq":133,"chapter":"الجزء الأول","title":"ص: 52","page":"ج1 ص50","text":"بلسانها، على ما تعرف من معانيها، وكان مما تعرف من معانيها: اتساع لسانها، وأن فطرته أن يخاطب بالشيء منه عاما، ظاهرا، يراد به العام، الظاهر، ويستغنى بأول هذا منه عن آخره. وعاما ظاهرا يراد به العام، ويدخله الخاص، فيستدل على هذا ببعض ما خوطب به فيه؛ وعاما ظاهرا، يراد به الخاص. وظاهرا يعرف في سياقه أنه يراد به غير ظاهره. فكل هذا موجود علمه في أول الكلام، أو وسطه، أو آخره.\nوتبتدئ الشيء من كلامها يبين أول لفظها فيه عن آخره. وتبتدئ الشيء يبين آخر لفظها منه عن أوله.\nوتكلم بالشيء تعرفه بالمعنى، دون الإيضاح باللفظ، كما تعرف الإشارة، ثم يكون هذا عندها من أعلى كلامها، لانفراد أهل علمها به، دون أهل جهالتها.\nوتسمي الشيء الواحد بالأسماء الكثيرة، وتسمي بالاسم الواحد المعاني الكثيرة.\nوكانت هذه الوجوه التي وصفت اجتماعها في معرفة أهل العلم منها به - وإن اختلفت أسباب معرفتها -: معرفة (1) واضحة","bab":"باب البيان الخامس"},{"id":"risala-shafii:134","bookId":"risala-shafii","type":"section","seq":134,"chapter":"الجزء الأول","title":"ص: 53","page":"ج1 ص50","text":"عندها، ومستنكرا عند غيرها، ممن جهل هذا من لسانها، وبلسانها نزل الكتاب، وجاءت السنة، فتكلف القول في علمها تكلف ما يجهل بعضه.\nومن تكلف ما جهل، وما لم تثبته معرفته: كانت موافقته للصواب - إن وافقه من حيث لا يعرفه - غير محمودة، والله أعلم؛ وكان بخطئه غير معذور، وإذا ما نطق فيما لا يحيط علمه بالفرق بين الخطأ والصواب فيه.","bab":"باب البيان الخامس"},{"id":"risala-shafii:135","bookId":"risala-shafii","type":"section","seq":135,"chapter":"الجزء الأول","title":"باب: بيان ما نزل من الكتاب عاما يراد به العام، ويدخله الخصوص.","page":"ج1 ص50","text":"قال الله تبارك وتعالى: \" الله خالق كل شيء وهو على كل شيء وكيل (62) \" [الزمر] ، وقال تبارك وتعالى: \" الله الذي خلق السماوات","bab":"باب: بيان ما نزل من الكتاب عاما يراد به العام، ويدخله الخصوص."},{"id":"risala-shafii:136","bookId":"risala-shafii","type":"section","seq":136,"chapter":"الجزء الأول","title":"ص: 54","page":"ج1 ص53","text":"والأرض (32) \" [إبراهيم] ، وقال: \" وما من دابة في الأرض إلا على الله رزقها (6) \" [هود] ، فهذا عام، لا خاص فيه.\nقال \"الشافعي\": فكل شيء، من سماء وأرض وذي روح وشجر وغير ذلك: فالله خلقه، وكل دابة فعلى الله رزقها، ويعلم مستقرها ومستودعها.\nوقال الله: \" ما كان لأهل المدينة ومن حولهم من الأعراب أن يتخلفوا عن رسول الله ولا يرغبوا بأنفسهم عن نفسه (120) \" [التوبة] .\nوهذا في معنى الآية قبلها، وإنما أريد به من أطاق الجهاد من الرجال، وليس لأحد منهم أن يرغب بنفسه عن نفس النبي: أطاق الجهاد، أو لم يطقه؛ ففي هذه الآية الخصوص والعموم.\nوقال: \" والمستضعفين من الرجال والنساء والولدان الذين يقولون ربنا أخرجنا من هذه القرية الظالم أهلها (75) \" [النساء] .","bab":"باب: بيان ما نزل من الكتاب عاما يراد به العام، ويدخله الخصوص."},{"id":"risala-shafii:137","bookId":"risala-shafii","type":"section","seq":137,"chapter":"الجزء الأول","title":"ص: 55","page":"ج1 ص54","text":"وهكذا قول الله: \" حتى إذا أتيا أهل قرية استطعما أهلها فأبوا أن يضيفوهما (77) \" [الكهف] .\nوفي هذه الآية دلالة على أن لم يستطعما كل أهل قرية، فهي في معناهما.\nوفيها، وفي: \" القرية الظالم أهلها (75) \" [النساء] : خصوص، لأن كل أهل القرية لم يكن ظالما، قد كان فيهم المسلم، ولكنهم كانوا فيها مكثورين، وكانوا فيها أقل.\nوفي القرآن نظائر لهذا، يكتفى بها إن شاء الله منها، وفي السنة له نظائر، موضوعة مواضعها.","bab":"باب: بيان ما نزل من الكتاب عاما يراد به العام، ويدخله الخصوص."},{"id":"risala-shafii:138","bookId":"risala-shafii","type":"section","seq":138,"chapter":"الجزء الأول","title":"باب: بيان ما أنزل من الكتاب عام الظاهر، وهو يجمع العام والخصوص.","page":"ج1 ص55","text":"قال الله تبارك وتعالى: \" إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبا وقبائل لتعارفوا. إن أكرمكم عند الله أتقاكم (13) \" [الحجرات] ،\nوقال تبارك وتعالى: \" كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون (183) أياما معدودات فمن كان منكم مريضا أو على سفر فعدة من أيام أخر (184) \" [البقرة] ،\nوقال: \" إن الصلاة كانت على المؤمنين كتابا موقوتا (103) \" [النساء] ،\nقال: فبين في كتاب الله، أن في هاتين الآيتين العموم والخصوص:","bab":"باب: بيان ما أنزل من الكتاب عام الظاهر، وهو يجمع العام والخصوص."},{"id":"risala-shafii:139","bookId":"risala-shafii","type":"section","seq":139,"chapter":"الجزء الأول","title":"ص: 57","page":"ج1 ص19","text":"فأما العموم منهما، ففي قول الله: \" إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبا وقبائل لتعارفوا (13) \" [الحجرات] ، فكل نفس خوطبت بهذا، في زمان رسول الله، وقبله وبعده، مخلوقة من ذكر وأنثى، وكلها شعوب وقبائل.\nوالخاص منها في قول الله: \" إن أكرمكم عند الله أتقاكم (13) \" [الحجرات] ؛ لأن التقوى تكون على من عقلها، وكان من أهلها من البالغين من بني آدم، دون المخلوقين من الدواب سواهم، ودون المغلوبين على عقولهم منهم، والأطفال الذين لم يبلغوا وعقل التقوى منهم.\nفلا يجوز أن يوصف بالتقوى وخلافها إلا من عقلها وكان من أهلها، أو خالفها فكان من غير أهلها.\nوالكتاب يدل على ما وصفت، وفي السنة دلالة","bab":"باب: بيان ما أنزل من الكتاب عام الظاهر، وهو يجمع العام والخصوص."},{"id":"risala-shafii:140","bookId":"risala-shafii","type":"section","seq":140,"chapter":"الجزء الأول","title":"ص: 58","page":"ج1 ص19","text":"عليها، قال رسول الله: \" رفع القلم عن ثلاثة: النائم حتى يستيقظ، والصبي حتى يبلغ، والمجنون حتى يفيق \" (1) .\nوهكذا التنزيل في الصوم والصلاة: على البالغين العاقلين، دون من لم يبلغ، ومن بلغ ممن غلب على عقله، ودون الحيض في أيام حيضهن.","bab":"باب: بيان ما أنزل من الكتاب عام الظاهر، وهو يجمع العام والخصوص."},{"id":"risala-shafii:141","bookId":"risala-shafii","type":"section","seq":141,"chapter":"الجزء الأول","title":"باب: بيان ما نزل من الكتاب عام الظاهر، يراد به كله الخاص.","page":"ج1 ص56","text":"وقال الله تبارك وتعالى: \" الذين قال لهم الناس: إن الناس قد جمعوا لكم، فاخشوهم، فزادهم إيمانا، وقالوا حسبنا الله ونعم الوكيل (173) \" [آل عمران] .","bab":"باب: بيان ما نزل من الكتاب عام الظاهر، يراد به كله الخاص."},{"id":"risala-shafii:142","bookId":"risala-shafii","type":"section","seq":142,"chapter":"الجزء الأول","title":"ص: 59","page":"ج1 ص58","text":"قال \"الشافعي\": فإذ كان من مع رسول الله ناس (1) ، غير من جمع لهم من الناس، وكان المخبرون لهم ناس غير من جمع لهم، وغير من معه ممن جمع عليه معه، وكان الجامعون لهم ناسا، فالدلالة بينة مما وصفت من أنه إنما جمع لهم بعض الناس دون بعض.\nوالعلم يحيط أن من لم يجمع لهم الناس كلهم، ولم يخبرهم الناس كلهم، ولم يكونوا هم الناس (2) كلهم.\nولكنه لما كان اسم الناس يقع على ثلاثة نفر،","bab":"باب: بيان ما نزل من الكتاب عام الظاهر، يراد به كله الخاص."},{"id":"risala-shafii:143","bookId":"risala-shafii","type":"section","seq":143,"chapter":"الجزء الأول","title":"ص: 60","page":"ج1 ص58","text":"وعلى جميع الناس، وعلى من بين جمعهم وثلاثة منهم، كان صحيحا في لسان العرب أن يقال: \" الذين قال لهم الناس (173) \" [آل عمران] ، وإنما الذين قال لهم ذلك أربعة نفر \" إن الناس قد جمعوا لكم (173) \" [آل عمران] ، يعنون المنصرفين عن أحد.\nوإنما هم جماعة غير كثير من الناس، الجامعون منهم، غير المجموع لهم، والمخبرون للمجموع لهم غير الطائفتين، والأكثر من الناس في بلدانهم غير الجامعين، ولا المجموع لهم ولا المخبرين.\nوقال: \" ياأيها الناس ضرب مثل فاستمعوا له. إن الذين تدعون من دون الله لن يخلقوا ذبابا ولو اجتمعوا له، وإن يسلبهم الذباب شيئا لا يستنقذوه منه. ضعف الطالب والمطلوب (73) \" [الحج] .\nقال: فمخرج اللفظ عام على الناس كلهم. وبين عند أهل العلم بلسان العرب منهم: أنه إنما يراد بهذا اللفظ العام المخرج بعض الناس، دون بعض؛ لأنه لا يخاطب بهذا إلا من يدعو من دون الله إلها، تعالى عما يقولون علوا كبيرا؛ لأن فيهم من المؤمنين","bab":"باب: بيان ما نزل من الكتاب عام الظاهر، يراد به كله الخاص."},{"id":"risala-shafii:144","bookId":"risala-shafii","type":"section","seq":144,"chapter":"الجزء الأول","title":"ص: 61","page":"ج1 ص58","text":"المغلوبين على عقولهم، وغير البالغين ممن لا يدعو معه إلها.\nقال: وهذا في معنى الآية قبلها عند أهل العلم باللسان، والآية قبلها أوضح عند غير أهل العلم، لكثرة الدلالات فيها.\nقال \"الشافعي \": قال الله تبارك وتعالى: \" ثم أفيضوا من حيث أفاض الناس (199) \" [البقرة] ، فالعلم يحيط - إن شاء الله - أن الناس كلهم لم يحضروا عرفة في زمان رسول الله، ورسول الله المخاطب بهذا ومن معه، ولكن صحيحا من كلام العرب أن يقال: \" ثم أفيضوا من حيث أفاض الناس \"، يعني بعض الناس.\nوهذه الآية في مثل معنى الآيتين قبلها، وهي عند العرب سواء. والآية الأولى أوضح عند من يجهل لسان العرب من الثانية، والثانية أوضح عندهم من الثالثة، وليس يختلف عند العرب وضوح هذه الآيات معا؛ لأن أقل البيان عندها كاف من أكثره، إنما يريد السامع فهم قول القائل، فأقل ما يفهمه به كاف عنده.","bab":"باب: بيان ما نزل من الكتاب عام الظاهر، يراد به كله الخاص."},{"id":"risala-shafii:145","bookId":"risala-shafii","type":"section","seq":145,"chapter":"الجزء الأول","title":"ص: 62","page":"ج1 ص60","text":"@ وقال الله جل ثناؤه: \" وقودها الناس والحجارة (24) \" [البقرة] ، فدل كتاب الله على أنه إنما وقودها بعض الناس، لقول الله: \" إن الذين سبقت لهم منا الحسنى. أولئك عنها مبعدون (101) \" [الأنبياء] .","bab":"باب: بيان ما نزل من الكتاب عام الظاهر، يراد به كله الخاص."},{"id":"risala-shafii:146","bookId":"risala-shafii","type":"section","seq":146,"chapter":"الجزء الأول","title":"باب: الصنف الذي يبين سياقه معناه.","page":"ج1 ص61","text":"قال الله تبارك وتعالى: \" واسألهم عن القرية التي كانت حاضرة البحر إذ يعدون في السبت إذ تأتيهم حيتانهم يوم سبتهم شرعا، ويوم لا يسبتون لا تأتيهم. كذلك نبلوهم بما كانوا يفسقون (163) \" [الأعراف] .\nفابتدأ - جل ثناؤه - ذكر الأمر بمسألتهم عن القرية الحاضرة البحر، فلما قال: \" إذ يعدون في السبت \"الآية، دل على أنه إنما أراد أهل القرية؛ لأن القرية لا تكون عادية، ولا فاسقة بالعدوان في السبت ولا غيره، وأنه إنما أراد بالعدوان أهل القرية الذين بلاهم بما كانوا يفسقون.\nوقال: \" وكم قصمنا من قرية كانت ظالمة، وأنشأنا بعدها قوما آخرين (11) فلما أحسوا بأسنا إذا هم منها يركضون (12) \" [الأنبياء] .\nوهذه الآية في مثل معنى الآية قبلها، فذكر قصم القرية، فلما ذكر أنها ظالمة بان للسامع أن الظالم إنما هم أهلها، دون منازلها التي لا تظلم، ولما ذكر القوم المنشئين بعدها، وذكر إحساسهم البأس عند القصم، أحاط العلم أنه إنما أحس البأس من يعرف البأس من الآدميين.","bab":"باب: الصنف الذي يبين سياقه معناه."},{"id":"risala-shafii:147","bookId":"risala-shafii","type":"section","seq":147,"chapter":"الجزء الأول","title":"الصنف الذي يدل لفظه على باطنه، دون ظاهره.","page":"ج1 ص62","text":"قال الله تبارك وتعالى، وهو يحكي قول إخوة يوسف لأبيهم: \" ما شهدنا إلا بما علمنا، وما كنا للغيب حافظين (81) ، واسأل القرية التي كنا فيها، والعير التي أقبلنا فيها، وإنا لصادقون (82) \" [يوسف] .\nفهذه الآية في مثل معنى الآيات قبلها، لا تختلف عند أهل العلم باللسان، أنهم إنما يخاطبون أباهم بمسألة أهل القرية وأهل العير، لأن القرية والعير لا ينبئان عن صدقهم.","bab":"باب: الصنف الذي يبين سياقه معناه."},{"id":"risala-shafii:148","bookId":"risala-shafii","type":"section","seq":148,"chapter":"الجزء الأول","title":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص.","page":"ج1 ص64","text":"قال الله - جل ثناؤه -: \" ولأبويه لكل واحد منهما السدس مما ترك إن كان له ولد، فإن لم يكن له ولد وورثه أبواه فلأمه الثلث، فإن كان له إخوة فلأمه السدس (11) \" [النساء] .","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:149","bookId":"risala-shafii","type":"section","seq":149,"chapter":"الجزء الأول","title":"ص: 65","page":"ج1 ص64","text":"وقال: \" ولكم نصف ما ترك أزواجكم إن لم يكن لهن ولد، فإن كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها أو دين، ولهن الربع مما تركتم إن لم يكن لكم ولد، فإن كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها أو دين، وإن كان رجل يورث كلالة أو امرأة، وله أخ أو أخت، فلكل واحد منهما السدس، فإن كانوا أكثر من ذلك فهم شركاء في الثلث من بعد وصية يوصى بها أو دين غير مضار، وصية من الله، والله عليم حليم (12) \" [النساء] .\nفأبان أن للوالدين والأزواج مما سمى في الحالات، وكان عام المخرج، فدلت سنة رسول الله على أنه إنما أريد به بعض الوالدين والأزواج، دون بعض، وذلك أن يكون دين الوالدين والمولود والزوجين واحدا، ولا يكون الوارث منهما قاتلا ولا مملوكا.\nوقال: \" من بعد وصية يوصى بها أو دين \".\nفأبان النبي أن الوصايا مقتصر بها على الثلث، لا يتعدى، ولأهل الميراث الثلثان؛ وأبان أن الدين قبل الوصايا","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:150","bookId":"risala-shafii","type":"section","seq":150,"chapter":"الجزء الأول","title":"ص: 66","page":"ج1 ص64","text":"والميراث، وأن لا وصية ولا ميراث حتى يستوفي أهل الدين دينهم.\nولولا دلالة السنة، ثم إجماع الناس، لم يكن ميراث إلا بعد وصية أو دين، ولم تعد الوصية أن تكون مبداة على الدين أو تكون والدين سواء.\nوقال الله: \" إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برءوسكم وأرجلكم إلى الكعبين (6) \" [المائدة] .\nفقصد - جل ثناؤه - قصد القدمين بالغسل، كما قصد الوجه واليدين، فكان ظاهر هذه الآية أنه لا يجزئ في القدمين إلا ما يجزئ في الوجه من الغسل، أو الرأس من المسح؛ وكان يحتمل أن يكون أريد بغسل القدمين أو مسحهما، بعض المتوضئين دون بعض.\nفلما مسح رسول الله على الخفين، وأمر به من أدخل رجليه في الخفين، وهو كامل الطهارة، دلت سنة رسول الله على أنه إنما أريد بغسل القدمين أو مسحهما بعض المتوضئين دون بعض.\nوقال الله تبارك وتعالى: \" والسارق والسارقة فاقطعوا أيديهما جزاء بما كسبا نكالا من الله (38) \" [المائدة] .","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:151","bookId":"risala-shafii","type":"section","seq":151,"chapter":"الجزء الأول","title":"ص: 67","page":"ج1 ص66","text":"وسن رسول الله أن: \" لا قطع في ثمر ولا كثر \" (1) ، وأن لا يقطع إلا من بلغت سرقته ربع دينار، فصاعدا.\nوقال الله: \" الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة (2) \" [النور] .\nوقال في الإماء: \" فإذا أحصن فإن أتين بفاحشة فعليهن نصف ما على المحصنات من العذاب (25) \" [النساء] .\nفدل القرآن على أنه إنما أريد بجلد المائة: الأحرار، دون الإماء. فلما رجم رسول الله الثيب من الزناة، ولم يجلده: دلت سنة رسول الله على أن المراد بجلد المائة من الزناة: الحران البكران، وعلى أن المراد بالقطع في السرقة: من سرق من حرز، وبلغت سرقته ربع دينار، دون غيرهما ممن لزمه اسم سرقة وزنا.\nوقال الله: \" واعلموا أنما غنمتم من شيء","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:152","bookId":"risala-shafii","type":"section","seq":152,"chapter":"الجزء الأول","title":"ص: 68","page":"ج1 ص67","text":"فأن لله خمسه، وللرسول ولذي القربى واليتامى والمساكين وابن السبيل (41) \" [الأنفال] .\nفلما أعطى رسول الله بني هاشم وبني المطلب سهم ذي القربى: دلت سنة رسول الله أن ذا القربى الذين جعل الله لهم سهما من الخمس: بنو هاشم وبنو المطلب، دون غيرهم.\nوكل قريش ذو قرابة، وبنو عبد شمس مساوية بني المطلب في القرابة، هم معا بنو أب وأم، وإن انفرد بعض بني المطلب بولادة من بني هاشم دونهم.\nفلما لم يكن السهم لمن انفرد بالولادة من بني المطلب دون من لم تصبه ولادة من بني هاشم منهم: دل ذلك على أنهم إنما أعطوا خاصة دون غيرهم بقرابة جذم النسب، مع كينونتهم معا مجتمعين في نصر النبي بالشعب وقبله وبعده، وما أراد الله - جل ثناؤه - بهم خاصا.","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:153","bookId":"risala-shafii","type":"section","seq":153,"chapter":"الجزء الأول","title":"ص: 69","page":"ج1 ص67","text":"ولقد ولدت بنو هاشم في قريش فما أعطي منهم أحد بولادتهم من الخمس شيئا، وبنو نوفل مساويتهم في جذم النسب، وإن انفردوا بأنهم بنوا أم دونهم.","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:154","bookId":"risala-shafii","type":"section","seq":154,"chapter":"الجزء الأول","title":"ص: 70","page":"ج1 ص67","text":"قال الله: \" واعلموا أنما غنمتم من شيء فأن لله خمسه وللرسول (41) \" [الأنفال] .\nفلما أعطى رسول الله السلب القاتل في","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:155","bookId":"risala-shafii","type":"section","seq":155,"chapter":"الجزء الأول","title":"ص: 71","page":"ج1 ص67","text":"الإقبال: دلت سنة النبي على أن الغنيمة المخموسة في كتاب الله، غير السلب، إذ كان السلب مغنوما في الإقبال، دون الأسلاب المأخوذة في غير الإقبال، وأن الأسلاب المأخوذة في غير الإقبال غنيمة تخمس مع ما سواها من الغنيمة بالسنة.","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:156","bookId":"risala-shafii","type":"section","seq":156,"chapter":"الجزء الأول","title":"ص: 72","page":"ج1 ص67","text":"ولولا الاستدلال بالسنة، وحكمنا بالظاهر","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:157","bookId":"risala-shafii","type":"section","seq":157,"chapter":"الجزء الأول","title":"ص: 73","page":"ج1 ص67","text":": قطعنا من لزمه اسم سرقة، وضربنا مائة كل من زنى، حرا ثيبا، وأعطينا سهم ذي القربى كل من بينه وبين النبي قرابة، ثم خلص ذلك إلى طوائف من العرب، لأن له فيهم وشايج أرحام، وخمسنا السلب، لأنه من المغنم مع ما سواه من الغنيمة.","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:158","bookId":"risala-shafii","type":"section","seq":158,"chapter":"الجزء الأول","title":"بيان فرض الله في كتابه اتباع سنة نبيه.","page":"ج1 ص67","text":"قال: \"الشافعي\": وضع الله رسوله من دينه وفرضه وكتابه، الموضع الذي أبان - جل ثناؤه - أنه جعله علما لدينه، بما افترض من طاعته، وحرم من معصيته، وأبان من فضيلته، بما قرن من الإيمان برسوله مع الإيمان به.\nفقال تبارك وتعالى: \" فآمنوا بالله ورسله ولا تقولوا: ثلاثة انتهوا خيرا لكم. إنما الله إله واحد سبحانه أن يكون له ولد (171) \" [النساء] .","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:159","bookId":"risala-shafii","type":"section","seq":159,"chapter":"الجزء الأول","title":"ص: 75","page":"ج1 ص73","text":"وقال: \" إنما المؤمنون الذين آمنوا بالله ورسوله وإذا كانوا معه على أمر جامع لم يذهبوا حتى يستأذنوه (62) \" [النور] .\nفجعل كمال ابتداء الإيمان، الذي ما سواه تبع له: الإيمان بالله ورسوله.\nفلو آمن عبد به، ولم يؤمن برسوله: لم يقع عليه اسم كمال الإيمان أبدا، حتى يؤمن برسوله معه.\nوهكذا سن رسول الله في كل من امتحنه للإيمان.\nأخبرنا \"مالك\" عن \"هلال بن أسامة\" عن \"عطاء بن يسار\" عن \"عمر بن الحكم\" قال: \" أتيت رسول الله بجارية، فقلت: يا رسول الله، علي رقبة، أفأعتقها؟ فقال لها رسول الله: أين الله؟ فقالت: في السماء. فقال: ومن أنا؟ قالت: أنت رسول الله. قال: فأعتقها \" (1) .","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:160","bookId":"risala-shafii","type":"section","seq":160,"chapter":"الجزء الأول","title":"ص: 76","page":"ج1 ص73","text":"قال \"الشافعي\": وهو\"معاوية بن الحكم\"، وكذلك رواه غير مالك، وأظن مالك (1) لم يحفظ اسمه.\nقال \"الشافعي: \" ففرض الله على الناس اتباع وحيه وسنن رسوله.\nفقال في كتابه: \" ربنا وابعث فيهم رسولا منهم يتلو عليهم آياتك، ويعلمهم الكتاب والحكمة، ويزكيهم. إنك أنت العزيز الحكيم (129) \" [البقرة] .\nوقال جل ثناؤه: \" كما أرسلنا فيكم رسولا منكم يتلو عليكم آياتنا، ويزكيكم، ويعلمكم الكتاب والحكمة، ويعلمكم ما لم تكونوا تعلمون (151) \" [البقرة] .","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:161","bookId":"risala-shafii","type":"section","seq":161,"chapter":"الجزء الأول","title":"ص: 77","page":"ج1 ص73","text":"وقال: \" لقد من الله على المؤمنين إذ بعث فيهم رسولا من أنفسهم يتلوا عليهم آياته، ويزكيهم، ويعلمهم الكتاب والحكمة، وإن كانوا من قبل لفي ضلال مبين (164) \" [آل عمران] .\nوقال جل ثناؤه: \" هو الذي بعث في الأميين رسولا منهم يتلو عليهم آياته، ويزكيهم، ويعلمهم الكتاب والحكمة، وإن كانوا من قبل لفي ضلال مبين (2) \" [الجمعة] .\nوقال: \" واذكروا نعمة الله عليكم، وما أنزل عليكم من الكتاب والحكمة يعظكم به (231) \" [البقرة] .\nوقال: \" وأنزل الله عليك الكتاب والحكمة، وعلمك ما لم تكن تعلم، وكان فضل الله عليك عظيما (113) \" [النساء] .\nوقال: \" واذكرن ما يتلى في بيوتكن من آيات","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:162","bookId":"risala-shafii","type":"section","seq":162,"chapter":"الجزء الأول","title":"ص: 78","page":"ج1 ص73","text":"الله والحكمة. إن الله كان لطيفا خبيرا (34) \" [الأحزاب] .\nفذكر الله الكتاب، وهو القرآن، وذكر الحكمة، فسمعت من أرضى من أهل العلم بالقرآن يقول: الحكمة سنة رسول الله.\nوهذا يشبه ما قال، والله أعلم.\nلأن القرآن ذكر وأتبعته الحكمة، وذكر الله منه على خلقه بتعليمهم الكتاب والحكمة، فلم يجز - والله أعلم - أن يقال الحكمة هاهنا إلا سنة رسول الله.\nوذلك أنها مقرونة مع كتاب الله، وأن الله افترض طاعة رسوله، وحتم على الناس اتباع أمره، فلا يجوز أن يقال لقول: فرض، إلا لكتاب الله، ثم سنة رسوله.\nلما وصفنا، من أن الله جعل الإيمان برسوله مقرونا بالإيمان به.","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:163","bookId":"risala-shafii","type":"section","seq":163,"chapter":"الجزء الأول","title":"ص: 79","page":"ج1 ص73","text":"وسنة رسول الله مبينة عن الله معنى ما أراد، دليلا على خاصه وعامه، ثم قرن الحكمة بها بكتابه، فاتبعها إياه، ولم يجعل هذا لأحد من خلقه غير رسوله.","bab":"باب: ما نزل عاما، دلت السنة خاصة على أنه يراد به الخاص."},{"id":"risala-shafii:164","bookId":"risala-shafii","type":"section","seq":164,"chapter":"الجزء الأول","title":"باب: فرض الله طاعة رسول الله مقرونة بطاعة الله، ومذكورة وحدها.","page":"ج1 ص73","text":"قال الله: \" وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمرا أن يكون لهم الخيرة من أمرهم، ومن يعص الله ورسوله، فقد ضل ضلالا مبينا (36) \" [الأحزاب] .\nوقال: \" ياأيها الذين آمنوا أطيعوا الله، وأطيعوا الرسول وأولي الأمر منكم، فإن تنازعتم في شيء فردوه إلى الله والرسول إن كنتم تؤمنون بالله واليوم الآخر ذلك خير وأحسن تأويلا (59) \" [النساء] .\nفقال بعض أهل العلم: أولوا الأمر: أمراء سرايا رسول الله - والله أعلم - وهكذا أخبرنا.","bab":"باب: فرض الله طاعة رسول الله مقرونة بطاعة الله، ومذكورة وحدها."},{"id":"risala-shafii:165","bookId":"risala-shafii","type":"section","seq":165,"chapter":"الجزء الأول","title":"ص: 80","page":"ج1 ص79","text":"وهو يشبه ما قال - والله أعلم -، لأن كل من كان حول مكة من العرب لم يكن يعرف إمارة، وكانت تأنف أن يعطي بعضها بعضا طاعة الإمارة.\nفلما دانت لرسول الله بالطاعة، لم تكن ترى ذلك يصلح لغير رسول الله.\nفأمروا أن يطيعوا أولي الأمر الذين أمرهم رسول الله، لا طاعة مطلقة، بل طاعة مستثناة، فيما لهم وعليهم، فقال: \" فإن تنازعتم في شيء فردوه إلى الله (59) \" [النساء] ، يعني: إن اختلفتم في شيء.\nوهذا - إن شاء الله - كما قال في أولي الأمر، إلا أنه يقول: \" فإن تنازعتم \"، يعني - والله أعلم - هم وأمراؤهم الذين أمروا بطاعتهم، \" فردوه إلى الله والرسول \"، يعني - والله اعلم - إلى ما قال الله","bab":"باب: فرض الله طاعة رسول الله مقرونة بطاعة الله، ومذكورة وحدها."},{"id":"risala-shafii:166","bookId":"risala-shafii","type":"section","seq":166,"chapter":"الجزء الأول","title":"ص: 81","page":"ج1 ص79","text":"والرسول إن عرفتموه، فإن لم تعرفوه سألتم الرسول عنه إذا وصلتم، أو من وصل منكم إليه.\nلأن ذلك الفرض الذي لا منازعة لكم فيه، لقول الله: \" وما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمرا أن يكون لهم الخيرة من أمرهم (36) [الأحزاب] .\nومن تنازع (1) ممن بعد رسول الله رد الأمر إلى قضاء الله، ثم قضاء رسوله، فإن لم يكن فيما تنازعوا فيه قضاء، نصا فيهما ولا في واحد منهما، ردوه قياسا على أحدهما، كما وصفت من ذكر القبلة والعدل والمثل، مع ما قال الله في غير آية مثل هذا المعنى.\nوقال: \" ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحين وحسن أولئك رفيقا (69) [النساء] .","bab":"باب: فرض الله طاعة رسول الله مقرونة بطاعة الله، ومذكورة وحدها."},{"id":"risala-shafii:167","bookId":"risala-shafii","type":"section","seq":167,"chapter":"الجزء الأول","title":"ص: 82","page":"ج1 ص79","text":"وقال: \" ياأيها الذين آمنوا أطيعوا الله ورسوله (20) \" [الأنفال] .","bab":"باب: فرض الله طاعة رسول الله مقرونة بطاعة الله، ومذكورة وحدها."},{"id":"risala-shafii:168","bookId":"risala-shafii","type":"section","seq":168,"chapter":"الجزء الأول","title":"باب: ما أمر الله من طاعة رسوله.","page":"ج1 ص79","text":"قال الله - جل ثناؤه -: \" إن الذين يبايعونك إنما يبايعون الله. يد الله فوق أيديهم فمن نكث فإنما ينكث على نفسه، ومن أوفى بما عاهد عليه الله فسيؤتيه أجرا عظيما (10) \" [الفتح] .\nوقال: \" من يطع الرسول فقد أطاع الله (80) \" [النساء] .\nفأعلمهم أن بيعتهم رسوله بيعته، وكذلك أعلمهم أن طاعتهم طاعته.\nوقال: \" فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم، ثم لا يجدوا في أنفسهم حرجا مما قضيت، ويسلموا تسليما (65) \" [النساء] .","bab":"باب: ما أمر الله من طاعة رسوله."},{"id":"risala-shafii:169","bookId":"risala-shafii","type":"section","seq":169,"chapter":"الجزء الأول","title":"ص: 83","page":"ج1 ص82","text":"نزلت هذه الآية فيما بلغنا - والله أعلم - في رجل خاصم \"الزبير\" في أرض، فقضى النبي بها \"للزبير\".\nوهذا القضاء سنة من رسول الله، لا حكم منصوص في القرآن.\nوالقرآن يدل - والله أعلم - على ما وصفت، لأنه لو كان قضاء بالقرآن كان حكما منصوصا بكتاب الله، وأشبه أن يكونوا إذا لم يسلموا لحكم كتاب الله نصا غير مشكل الأمر، أنهم ليسوا بمؤمنين، إذا ردوا حكم التنزيل، إذا لم يسلموا له.\nوقال تبارك وتعالى: \" لا تجعلوا دعاء الرسول بينكم كدعاء بعضكم بعضا. قد يعلم الله الذين يتسللون منكم لواذا","bab":"باب: ما أمر الله من طاعة رسوله."},{"id":"risala-shafii:170","bookId":"risala-shafii","type":"section","seq":170,"chapter":"الجزء الأول","title":"ص: 84","page":"ج1 ص82","text":"، فليحذر الذين يخالفون عن أمره أن تصيبهم فتنة أو يصيبهم عذاب أليم (63) \" [النور] .\nوقال: \" وإذا دعوا إلى الله ورسوله ليحكم بينهم إذا فريق منهم معرضون (48) . وإن يكن لهم الحق يأتوا إليه مذعنين (49) . أفي قلوبهم مرض أم ارتابوا أم يخافون أن يحيف الله عليهم ورسوله؟ بل أولئك هم الظالمون (50) إنما كان قول المؤمنين إذا دعوا إلى الله ورسوله ليحكم بينهم أن يقولوا: سمعنا وأطعنا، وأولئك هم المفلحون (51) . ومن يطع الله ورسوله، ويخش الله ويتقيه، فأولئك هم الفائزون (52) \" [النور] .\nفأعلم الله الناس في هذه الآية، أن دعاءهم إلى رسول الله ليحكم بينهم: دعاء إلى حكم الله، لأن الحاكم بينهم رسول الله، وإذا سلموا لحكم رسول الله، فإنما سلموا لحكمه بفرض الله.\nوأنه أعلمهم أن حكمه: حكمه، على معنى افتراضه حكمه، وما سبق في علمه - جل ثناؤه - من إسعاده بعصمته وتوفيقه، وما شهد له به من هدايته واتباعه أمره.","bab":"باب: ما أمر الله من طاعة رسوله."},{"id":"risala-shafii:171","bookId":"risala-shafii","type":"section","seq":171,"chapter":"الجزء الأول","title":"ص: 85","page":"ج1 ص82","text":"فأحكم فرضه بإلزام خلقه طاعة رسوله، وإعلامهم أنها طاعته.\nفجمع لهم أن أعلمهم أن الفرض عليهم اتباع أمره، وأمر رسوله، وأن طاعة رسوله: طاعته، ثم أعلمهم أنه فرض على رسوله اتباع أمره - جل ثناؤه -.","bab":"باب: ما أمر الله من طاعة رسوله."},{"id":"risala-shafii:172","bookId":"risala-shafii","type":"section","seq":172,"chapter":"الجزء الأول","title":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه.","page":"ج1 ص84","text":"قال \"الشافعي\": قال - الله جل ثناؤه - لنبيه: \" ياأيها النبي اتق الله ولا تطع الكافرين والمنافقين. إن الله كان عليما حكيما (1) واتبع ما يوحى إليك من ربك. إن الله كان بما تعملون خبيرا (2) \" [الأحزاب] .\nوقال: \" اتبع ما أوحي إليك من ربك، لا إله إلا هو، وأعرض عن المشركين (106) \" [الأنعام] .","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:173","bookId":"risala-shafii","type":"section","seq":173,"chapter":"الجزء الأول","title":"ص: 86","page":"ج1 ص85","text":"وقال: \" ثم جعلناك على شريعة من الأمر فاتبعها، ولا تتبع أهواء الذين لا يعلمون (18) \" [الجاثية] .\nفأعلم الله رسوله منه عليه بما سبق في علمه، من عصمته إياه من خلقه، فقال: \" ياأيها الرسول بلغ ما أنزل إليك من ربك، وإن لم تفعل، فما بلغت رسالته، والله يعصمك من الناس (67) \" [المائدة] .\nوشهد له - جل ثناؤه - باستمساكه بما أمره به، والهدى في نفسه، وهداية من اتبعه، فقال: \" وكذلك أوحينا إليك روحا من أمرنا ما كنت تدري: ما الكتاب ولا الإيمان، ولكن جعلناه نورا نهدي به من نشاء من عبادنا، وإنك لتهدي إلى صراط مستقيم (52) \" [الشورى] .\nوقال: \" ولولا فضل الله عليك، ورحمته لهمت طائفة منهم أن يضلوك، وما يضلون إلا أنفسهم، وما يضرونك من شيء","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:174","bookId":"risala-shafii","type":"section","seq":174,"chapter":"الجزء الأول","title":"ص: 87","page":"ج1 ص85","text":"، وأنزل الله عليك الكتاب والحكمة، وعلمك ما لم تكن تعلم، وكان فضل الله عليك عظيما (113) \" [النساء] .\nفأبان الله أن قد فرض على نبيه اتباع أمره، وشهد له بالبلاغ عنه، وشهد به لنفسه، ونحن نشهد له به، تقربا إلى الله بالإيمان به، وتوسلا إليه بتصديق كلماته.\nأخبرنا \"عبد العزيز\" عن \"عمرو بن أبي عمرو\" مولى \"المطلب\" عن \"المطلب بن حنطب\" أن رسول الله قال: \" ما تركت شيئا مما أمركم الله به إلا وقد أمرتكم به، ولا تركت شيئا مما نهاكم الله عنه إلا وقد نهيتكم عنه \" (1) .\nقال \"الشافعي\": وما أعلمنا الله مما سبق في علمه، وحتم قضائه الذي لا يرد، من فضله عليه ونعمته: أنه منعه من أن يهموا به أن يضلوه، وأعلمه أنهم لا يضرونه من شيء.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:175","bookId":"risala-shafii","type":"section","seq":175,"chapter":"الجزء الأول","title":"ص: 88","page":"ج1 ص85","text":"وفي شهادته له بأنه يهدي إلى صراط مستقيم، صراط الله، والشهادة بتأدية رسالته، واتباع أمره، وفيما وصفت من فرضه طاعته، وتأكيده إياها في الآي ذكرت: ما أقام الله به الحجة على خلقه، بالتسليم لحكم رسول الله واتباع أمره.\nقال \"الشافعي\": وما سن رسول الله فيما ليس لله فيه حكم، فبحكم الله سنه. وكذلك أخبرنا الله في قوله: \" وإنك لتهدي إلى صراط مستقيم (52) صراط الله ... (53) \" [الشورى] .\nوقد سن رسول الله مع كتاب الله، وسن فيما ليس فيه بعينه نص كتاب.\nوكل ما سن فقد ألزمنا الله اتباعه، وجعل في اتباعه طاعته، وفي العنود عن اتباعها معصيته التي لم يعذر بها خلقا،","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:176","bookId":"risala-shafii","type":"section","seq":176,"chapter":"الجزء الأول","title":"ص: 89","page":"ج1 ص87","text":"ولم يجعل له من اتباع سنن رسول الله مخرجا، لما وصفت، وما قال رسول الله.\nأخبرنا \"سفيان\" عن \"سالم أبو النضر\" مولى \"عمر بن عبيد الله\" سمع \"عبيد الله بن أبي رافع\" يحدث عن أبيه، أن رسول الله قال: \" لا ألفين أحدكم متكئا على أريكته، يأتيه الأمر من أمري، مما أمرت به، أو نهيت عنه، فيقول: لا أدري، ما وجدنا في كتاب الله اتبعناه \" (1) .","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:177","bookId":"risala-shafii","type":"section","seq":177,"chapter":"الجزء الأول","title":"ص: 90","page":"ج1 ص87","text":"قال \"سفيان\": وحدثنيه \"محمد بن المنكدر\" عن النبي مرسلا.\nقال \"الشافعي\": الأريكة: السرير.\nوسنن رسول الله مع كتاب الله وجهان: أحدهما: نص كتاب، فاتبعه رسول الله كما أنزل الله، والآخر: جملة، بين رسول الله فيه عن الله معنى ما أراد بالجملة، وأوضح كيف فرضها عاما أو خاصا، وكيف أراد أن يأتي به العباد، وكلاهما اتبع فيه كتاب الله.\nقال: فلم أعلم من أهل العلم مخالفا في أن سنن النبي من ثلاثة وجوه، فاجتمعوا منها على وجهين.\nوالوجهان يجتمعان ويتفرعان: أحدهما: ما أنزل الله فيه نص كتاب، فبين رسول الله مثل ما نص الكتاب، والآخر: مما أنزل الله فيه جملة كتاب، فبين عن الله معنى ما أراد؛ وهذان الوجهان اللذان لم يختلفوا فيهما.\nوالوجه الثالث: ما سن رسول الله فيما ليس فيه نص كتاب.\nفمنهم من قال: جعل الله له، بما افترض من طاعته، وسبق في علمه من توفيقه لرضاه، أن يسن فيما ليس فيه نص كتاب.\nومنهم من قال: لم يسن سنة قط إلا ولها أصل في الكتاب، كما كانت سنته لتبيين عدد الصلاة وعملها، على أصل جملة فرض الصلاة، وكذلك ما سن من البيوع وغيرها من الشرائع، لأن الله قال: \" لا تأكلوا أموالكم بينكم بالباطل (29) \" [النساء] ، وقال: \" وأحل الله البيع وحرم الربا (275) [البقرة] ، فما أحل وحرم فإنما بين فيه عن الله، كما بين الصلاة.\nومنهم من قال: بل جاءته به رسالة الله، فأثبتت سنته.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:178","bookId":"risala-shafii","type":"section","seq":178,"chapter":"الجزء الأول","title":"ص: 93","page":"ج1 ص90","text":"ومنهم من قال: ألقي في روعه كل ما سن، وسنته الحكمة: الذي ألقي في روعه عن الله، فكان ما ألقي في روعه سنته.\nأخبرنا \"عبد العزيز\" عن \"عمرو بن أبي عمرو\" عن \"المطلب\" قال: قال رسول الله: \" إن الروح الأمين قد ألقى في روعي أنه لن تموت نفس حتى تستوفي رزقها، فأجملوا في الطلب \" (1) .","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:179","bookId":"risala-shafii","type":"section","seq":179,"chapter":"الجزء الأول","title":"ص: 103","page":"ج1 ص90","text":"فكان مما ألقى في روعه سنته (2) ، وهي الحكمة التي ذكر الله، وما نزل به عليه كتاب، فهو كتاب الله، وكل جاءه من نعم الله، كما أراد الله، وكما جاءته النعم، تجمعها النعمة، وتتفرق بأنها في أمور بعضها غير بعض، ونسأل الله العصمة والتوفيق.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:180","bookId":"risala-shafii","type":"section","seq":180,"chapter":"الجزء الأول","title":"ص: 104","page":"ج1 ص90","text":"وأي هذا كان، فقد بين الله أنه فرض فيه طاعة رسوله، ولم يجعل لأحد من خلقه عذرا بخلاف أمر عرفه من أمر رسول الله، وأن قد جعل الله بالناس الحاجة إليه في دينهم، وأقام عليهم حجته بما دلهم عليه من سنن رسول الله معاني ما أراد الله بفرائضه في كتابه، ليعلم من عرف منها ما وصفنا أن سنته - صلى الله عليه - إذا كانت سنة مبينة عن الله معنى ما أراد من مفروضه فيما فيه كتاب يتلونه، وفيما ليس فيه نص كتاب أخرى (3) ، فهي كذلك أين كانت، لا يختلف حكم الله ثم حكم","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:181","bookId":"risala-shafii","type":"section","seq":181,"chapter":"الجزء الأول","title":"ص: 105","page":"ج1 ص90","text":"رسوله، بل هو لازم بكل حال.\nوكذلك قال رسول الله في حديث \"أبي رافع\" الذي كتبنا قبل هذا.\nوسأذكر مما وصفنا من السنة مع كتاب الله، والسنة فيما ليس فيه نص كتاب، بعض ما يدل على جملة ما وصفنا منه، إن شاء الله.\nفأول ما نبدأ به من ذكر سنة رسول الله مع كتاب الله: ذكر الاستدلال بسنته على الناسخ والمنسوخ من كتاب الله، ثم ذكر الفرائض المنصوصة التي سن رسول الله معها، ثم ذكر الفرائض الجمل التي أبان رسول الله عن الله كيف هي ومواقيتها، ثم ذكر العام من أمر الله الذي أراد به العام، والعام الذي أراد به الخاص، ثم ذكر سنته فيما ليس فيه نص كتاب.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:182","bookId":"risala-shafii","type":"section","seq":182,"chapter":"الجزء الأول","title":"ابتداء الناسخ والمنسوخ.","page":"ج1 ص105","text":"قال \"الشافعي: \": إن الله خلق الخلق لما سبق في علمه مما أراد بخلقهم وبهم، لا معقب لحكمه، وهو سريع الحساب.\nوأنزل عليهم الكتاب تبيانا لكل شيء، وهدى ورحمة، وفرض فيه فرائض أثبتها، وأخرى نسخها، رحمة لخلقه، بالتخفيف عنهم، وبالتوسعة عليهم، زيادة فيما ابتدأهم به من نعمه. وأثابهم على الانتهاء إلى ما أثبت عليهم: جنته، والنجاة من عذابه؛ فعمتهم رحمته فيما أثبت ونسخ، فله الحمد على نعمه.\nوأبان الله لهم أنه إنما نسخ ما نسخ من الكتاب بالكتاب، وأن السنة لا ناسخة للكتاب، وإنما هي تبع للكتاب، يمثل ما نزل نصا، ومفسرة معنى ما أنزل الله منه جملا.\nقال الله: \" وإذا تتلى عليهم آياتنا بينات قال الذين لا يرجون لقاءنا ائت بقرآن غير هذا أو بدله. قل ما يكون لي أن","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:183","bookId":"risala-shafii","type":"section","seq":183,"chapter":"الجزء الأول","title":"ص: 107","page":"ج1 ص105","text":"أبدله من تلقاء نفسي؛ إن أتبع إلا ما يوحى إلي. إني أخاف إن عصيت ربي عذاب يوم عظيم (15) \" [يونس] .\nفأخبر الله أنه فرض على نبيه اتباع ما يوحى إليه، ولم يجعل له تبديله من تلقاء نفسه.\nوفي قوله: \" ما يكون لي أن أبدله من تلقاء نفسي (15) \" [يونس] ، بيان ما وصفت، من أنه لا ينسخ كتاب الله إلا كتابه، كما كان المبتدىء لفرضه، فهو المزيل المثبت لما شاء منه، جل ثناؤه، ولا يكون ذلك لأحد من خلقه.\nوكذلك قال: \" يمحو الله ما يشاء ويثبت، وعنده أم الكتاب (39) \" [الرعد] .\nوقد قال بعض أهل العلم: في هذه الآية - والله أعلم - دلالة على أن الله جعل لرسوله أن يقول من تلقاء نفسه بتوفيقه فيما لم ينزل فيه كتابا، والله أعلم.\nوقيل في قوله: \" يمحو الله ما يشاء ... (39) \" [الرعد] : يمحو فرض ما يشاء، ويثبت فرض ما يشاء، وهذا يشبه ما قيل، والله أعلم.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:184","bookId":"risala-shafii","type":"section","seq":184,"chapter":"الجزء الأول","title":"ص: 108","page":"ج1 ص105","text":"وفي كتاب الله دلالة عليه، قال الله: \" ما ننسخ من آية أو ننسها نأت بخير منها أو مثلها. ألم تعلم أن الله على كل شيء قدير (106) \" [البقرة] .\nفأخبر الله أن نسخ القرآن، وتأخير إنزاله لا يكون إلا بقرآن مثله.\nوقال: \" وإذا بدلنا آية مكان آية، والله أعلم بما ينزل: قالوا: إنما أنت مفتر (101) \" [النحل] .\nوهكذا سنة رسول الله، لا ينسخها إلا سنة لرسول الله؛ ولو أحدث الله لرسوله في أمر سن فيه، غير ما سن رسول الله: لسن فيما أحدث الله إليه، حتى يبين للناس أن له سنة ناسخة للتي قبلها مما يخالفها. وهذا مذكور في سنته - صلى الله عليه وسلم -.\nفإن قال قائل: فقد وجدنا الدلالة على أن القرآن ينسخ القرآن، لأنه لا مثل للقرآن، فأوجدنا ذلك في السنة؟\nقال \"الشافعي\": فيما وصفت من فرض الله على الناس","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:185","bookId":"risala-shafii","type":"section","seq":185,"chapter":"الجزء الأول","title":"ص: 109","page":"ج1 ص106","text":"اتباع أمر رسول الله: دليل على أن سنة رسول الله إنما قبلت عن الله، فمن اتبعها فبكتاب الله تبعها، ولا نجد خبرا ألزمه الله خلقه نصا بينا إلا كتابه ثم سنة نبيه. فإذا كانت السنة كما وصفت، لا شبه لها من قول خلق من خلق الله: لم يجز أن ينسخها إلا مثلها، ولا مثل لها غير سنة رسول الله، لأن الله لم يجعل لآدمي بعده ما جعل له، بل فرض على خلقه اتباعه، فألزمهم أمره، فالخلق كلهم له تبع، ولا يكون للتابع أن يخالف ما فرض عليه اتباعه، ومن وجب عليه اتباع سنة رسول الله لم يكن له خلافها، ولم يقم مقام أن ينسخ شيئا منها.\nفإن قال: أفيحتمل أن تكون له سنة مأثورة قد نسخت، ولا تؤثر السنة التي نسختها؟\nفلا يحتمل هذا، وكيف يحتمل أن يؤثر ما وضع فرضه، ويترك ما يلزم فرضه؟! ولو جاز هذا خرجت عامة السنن من أيدي الناس، بأن يقولوا: لعلها منسوخة، وليس ينسخ فرض أبدا إلا أثبت مكانه فرض. كما نسخت قبلة بيت المقدس، فأثبت","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:186","bookId":"risala-shafii","type":"section","seq":186,"chapter":"الجزء الأول","title":"ص: 110","page":"ج1 ص106","text":"مكانها الكعبة، وكل منسوخ في كتاب وسنة هكذا.\nفإن قال قائل: هل تنسخ السنة بالقرآن؟\nقيل: لو نسخت السنة بالقرآن، كانت للنبي فيه سنة تبين أن سنته الأولى منسوخة بسنته الآخرة حتى تقوم الحجة على الناس، بأن الشيء ينسخ بمثله.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:187","bookId":"risala-shafii","type":"section","seq":187,"chapter":"الجزء الأول","title":"ص: 111","page":"ج1 ص108","text":"فإن قال: ما الدليل على ما تقول؟\nفما وصفت من موضعه من الإبانة عن الله معنى ما أراد بفرائضه، خاصا وعاما، مما وصفت في كتابي هذا، وأنه لا يقول أبدا لشيء إلا بحكم الله. ولو نسخ الله مما قال حكما، لسن رسول الله فيما نسخه سنة.\nولو جاز أن يقال: قد سن رسول الله ثم نسخ سنته بالقرآن، ولا يؤثر عن رسول الله السنة الناسخة: جاز أن يقال فيما حرم رسول الله من البيوع كلها: قد يحتمل أن يكون حرمها قبل أن ينزل عليه: \" وأحل الله البيع وحرم الربا (275) \" [البقرة] ؛ وفيمن رجم من الزناة: قد يحتمل أن يكون الرجم منسوخا لقول الله: \" الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة (2) \" [النور] ؛ وفي المسح","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:188","bookId":"risala-shafii","type":"section","seq":188,"chapter":"الجزء الأول","title":"ص: 112","page":"ج1 ص108","text":"على الخفين: نسخت آية الوضوء المسح؛ وجاز أن يقال: لا يدرأ عن سارق سرق من غير حرز، وسرقته أقل من ربع دينار، لقول الله: \" السارق والسارقة فاقطعوا أيديهما (38) \" [المائدة] ، لأن اسم {السرقة} يلزم من سرق قليلا وكثيرا، ومن حرز، ومن غير حرز؛ ولجاز رد كل حديث عن رسول الله، بأن يقال: لم يقله، إذا لم يجده مثل التنزيل؛ وجاز رد السنن بهذين الوجهين، فتركت كل سنة معها كتاب جملة تحتمل سنته أن توافقه، وهي لا تكون أبدا","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:189","bookId":"risala-shafii","type":"section","seq":189,"chapter":"الجزء الأول","title":"ص: 113","page":"ج1 ص108","text":"إلا موافقة له، إذا احتمل اللفظ فيما روي عنه خلاف اللفظ في التنزيل بوجه، أو احتمل أن يكون في اللفظ عنه أكثر مما في اللفظ في التنزيل، وإن كان محتملا أن يخالفه من وجه.\nوكتاب الله وسنة رسوله تدل على خلاف هذا القول، وموافقة ما قلنا.\nوكتاب الله البيان الذي يشفى (1) به من العمى، وفيه الدلالة على موضع رسول الله من كتاب الله ودينه، واتباعه له وقيامه بتبيينه عن الله.","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:190","bookId":"risala-shafii","type":"section","seq":190,"chapter":"الجزء الأول","title":"الناسخ والمنسوخ الذي يدل الكتاب على بعضه، والسنة على بعضه.","page":"ج1 ص110","text":"قال \"الشافعي\": مما نقل بعض من سمعت منه من أهل العلم، أن الله أنزل فرضا في الصلاة قبل فرض الصلوات الخمس،","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:191","bookId":"risala-shafii","type":"section","seq":191,"chapter":"الجزء الأول","title":"ص: 114","page":"ج1 ص113","text":"فقال: \" ياأيها المزمل (1) قم الليل إلا قليلا (2) نصفه أو انقص منه قليلا (3) أو زد عليه ورتل القرآن ترتيلا (4) \" [المزمل] ، ثم نسخ هذا في السورة معه، فقال: \" إن ربك يعلم أنك تقوم أدنى من ثلثي الليل ونصفه وثلثه، وطائفة من الذين معك، والله يقدر الليل والنهار. علم أن لن تحصوه فتاب عليكم، فاقرءوا ما تيسر من القرآن، علم أن سيكون منكم مرضى وآخرون يضربون في الأرض يبتغون من فضل الله، وآخرون يقاتلون في سبيل الله فاقرءوا ما تيسر منه، وأقيموا الصلاة وآتوا الزكاة (20) \" [المزمل] .\nولما ذكر الله بعد أمره بقيام الليل نصفه إلا قليلا، أو لزيادة عليه، فقال: \" أدنى من ثلثي الليل ونصفه وثلثه، وطائفة من الذين معك (20) \" [المزمل] ، فخفف، فقال: \" علم أن سيكون منكم مرضى \" قرأ إلى: \" فاقرءوا ما تيسر منه (20) \" [المزمل] .\nقال \"الشافعي\": فكان بينا في كتاب الله نسخ","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:192","bookId":"risala-shafii","type":"section","seq":192,"chapter":"الجزء الأول","title":"ص: 115","page":"ج1 ص113","text":"قيام الليل ونصفه والنقصان من النصف، والزيادة عليه بقول الله: \" فاقرءوا ما تيسر منه (20) \" [المزمل] .\nفاحتمل قول الله: \" فاقرءوا ما تيسر منه (20) \" [المزمل] : معنيين:\n- أحدهما: أن يكون فرضا ثابتا، لأنه أزيل به فرض غيره.\n- والآخر: أن يكون فرضا منسوخا أزيل بغيره، كما أزيل به غيره، وذلك لقول الله: \" ومن الليل فتهجد به نافلة لك عسى أن يبعثك ربك مقاما محمودا (79) \" [الإسراء] ، فاحتمل قوله: \" ومن الليل فتهجد به نافلة لك \"، أن يتهجد بغير الذي فرض عليه، مما تيسر منه.\nقال: فكان الواجب طلب الاستدلال بالسنة على أحد المعنيين، فوجدنا سنة رسول الله تدل على ألا واجب من الصلاة إلا الخمس، فصرنا إلى أن الواجب الخمس، وأن ما سواها من واجب","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:193","bookId":"risala-shafii","type":"section","seq":193,"chapter":"الجزء الأول","title":"ص: 116","page":"ج1 ص113","text":"من صلاة قبلها، منسوخ بها، استدلالا بقول الله: \" فتهجد به نافلة لك (79) \" [الإسراء] ، وأنها ناسخة لقيام الليل ونصفه وثلثه وما تيسر.\nولسنا نحب لأحد ترك أن يتهجد بما يسره الله عليه من كتابه، مصليا به، وكيف ما أكثر فهو أحب إلينا.\nأخبرنا \"مالك\" عن عمه \"أبي سهيل بن مالك\" عن أبيه، أنه سمع \"طلحة بن عبيد الله\" يقول: \" جاء أعرابي من أهل نجد، ثائر الرأس، نسمع دوي صوته، ولا نفقه ما يقول، حتى دنا، فإذا هو يسأل عن الإسلام؟ فقال النبي: خمس صلوات في اليوم والليلة، قال: هل علي غيرها؟ فقال: لا، إلا أن تطوع. قال: وذكر له رسول الله صيام شهر رمضان، فقال: هل علي غيره؟ قال: لا، إلا أن تطوع، فأدبر الرجل، وهو يقول: لا أزيد على هذا، ولا أنقص منه، فقال رسول الله: أفلح إن صدق \" (1) .","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:194","bookId":"risala-shafii","type":"section","seq":194,"chapter":"الجزء الأول","title":"ص: 117","page":"ج1 ص113","text":"ورواه \"عبادة بن الصامت\" عن النبي، أنه قال: \" خمس صلوات كتبهن الله على خلقه، فمن جاء بهن لم يضيع منهن شيئا، استخفافا بحقهن: كان له عند الله عهدا (2) أن يدخله الجنة \" (3) .","bab":"باب: ما أبان الله لخلقه من فرضه على رسوله اتباع ما أوحى إليه، وما شهد له به من اتباع ما أمر به، ومن هداه، وأنه هاد لمن اتبعه."},{"id":"risala-shafii:195","bookId":"risala-shafii","type":"section","seq":195,"chapter":"الجزء الأول","title":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية.","page":"ج1 ص113","text":"قال الله تبارك وتعالى: \" ويسألونك عن المحيض؟ قل: هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن، فإذا تطهرن فأتوهن من حيث أمركم الله. إن الله يحب التوابين، ويحب المتطهرين (222) \" [البقرة] .\nقال \"الشافعي\": افترض الله الطهارة على المصلي، في الوضوء والغسل من الجنابة، فلم تكن لغير طاهر صلاة. ولما","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:196","bookId":"risala-shafii","type":"section","seq":196,"chapter":"الجزء الأول","title":"ص: 118","page":"ج1 ص117","text":"ذكر الله المحيض، فأمر باعتزال النساء حتى يطهرن، فإذا تطهرن أتين: استدللنا على أن تطهرهن بالماء: بعد زوال المحيض، لأن الماء موجود في الحالات كلها في الحضر، فلا يكون للحائض طهارة بالماء، لأن الله إنما ذكر التطهر بعد أن يطهرن، وتطهرهن: زوال المحيض، في كتاب الله ثم سنة رسوله.\nأخبرنا \"مالك\" عن \"عبد الرحمن بن القاسم\" عن أبيه، عن \"عائشة\"، وذكرت إحرامها مع النبي، وأنها حاضت، فأمرها أن تقضي ما يقضي الحاج: \" غير أن لا تطوفي بالبيت حتى تطهري \" (1) .","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:197","bookId":"risala-shafii","type":"section","seq":197,"chapter":"الجزء الأول","title":"ص: 119","page":"ج1 ص117","text":"فاستدللنا على أن الله إنما أراد بفرض الصلاة من إذا توضأ واغتسل طهر؛ فأما الحائض، فلا تطهر بواحد منهما، وكان الحيض شيئا خلق فيها، لم تجتلبه على نفسها فتكون عاصية به، فزال عنها فرض الصلاة أيام حيضها، فلم يكن عليها قضاء ما تركت منها في الوقت الذي يزول عنها فيه فرضها.\nوقلنا في المغمى عليه، والمغلوب على عقله بالعارض من أمر الله، الذي لا جنابة له فيه، قياسا على الحائض، إن الصلاة عنه مرفوعة، لأنه لا يعقلها، ما دام في الحال التي لا يعقل فيها.\nوكان عاما في أهل العلم أن النبي لم يأمر الحائض بقضاء الصلاة، وعاما أنها أمرت بقضاء الصوم، ففرقنا بين الفرضين، استدلالا بما وصفت من نقل أهل العلم وإجماعهم.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:198","bookId":"risala-shafii","type":"section","seq":198,"chapter":"الجزء الأول","title":"ص: 120","page":"ج1 ص119","text":"@وكان الصوم مفارق الصلاة في أن للمسافر تأخيره عن شهر رمضان، وليس له ترك يوم لا يصلي فيه صلاة السفر، وكان الصوم شهرا من اثني عشر شهرا، وكان في أحد عشر شهرا خليا من فرض الصوم، ولم يكن أحد من الرجال - مطيقا بالفعل للصلاة - خليا من الصلاة.\nقال الله: \" لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون، ولا جنبا إلا عابري سبيل حتى تغتسلوا (43) \" [النساء] .\nفقال بعض أهل العلم: نزلت هذه الآية قبل تحريم الخمر (1) .\nفدل القرآن - والله أعلم - على ألا صلاة لسكران حتى يعلم ما يقول، إذ بدأ بنهيه عن الصلاة، وذكر معه الجنب، فلم يختلف أهل العلم ألا صلاة لجنب حتى يتطهر.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:199","bookId":"risala-shafii","type":"section","seq":199,"chapter":"الجزء الأول","title":"ص: 120","page":"ج1 ص119","text":"وإن كان نهي السكران عن الصلاة قبل تحريم الخمر: فهو حين حرم الخمر أولى أن يكون منهيا، بأنه عاص من وجهين: أحدهما: أن يصلي في الحال التي هو فيها منهي، والآخر: أن يشرب الخمر.\nوالصلاة قول وعمل وإمساك، فإذا لم يعقل القول والعمل والإمساك، فلم يأت بالصلاة كما أمر، فلا تجزئ عنه، وعليه إذا أفاق القضاء.\nويفارق المغلوب على عقله بأمر الله الذي لا حيلة له فيه: السكران، لأنه أدخل نفسه في السكر، فيكون على السكران القضاء، دون المغلوب على عقله بالعارض الذي لم يجتلبه على نفسه فيكون عاصيا باجتلابه.\nووجه الله رسوله للقبلة في الصلاة إلى بيت المقدس، فكانت القبلة التي لا يحل - قبل نسخها - استقبال غيرها، ثم نسخ","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:200","bookId":"risala-shafii","type":"section","seq":200,"chapter":"الجزء الأول","title":"ص: 122","page":"ج1 ص120","text":"الله قبلة بيت المقدس، ووجهه إلى البيت، فلا يحل لأحد استقبال بيت المقدس أبدا لمكتوبة، ولا يحل أن يستقبل غير البيت الحرام.\nقال: وكل كان حقا في وقته، فكان التوجه إلى بيت المقدس - أيام وجه الله إليه نبيه - حقا، ثم نسخه، فصار الحق في التوجه إلى البيت الحرام أبدا، لا يحل استقبال غيره في مكتوبة، إلا في بعض الخوف، أو نافلة في سفر، استدلالا بالكتاب والسنة.\nوهكذا كل ما نسخ الله، ومعنى (نسخ) : ترك فرضه: كان حقا في وقته، وتركه حقا إذا نسخه الله، فيكون من","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:201","bookId":"risala-shafii","type":"section","seq":201,"chapter":"الجزء الأول","title":"ص: 123","page":"ج1 ص120","text":"أدرك فرضه مطيعا به وبتركه، ومن لم يدرك فرضه مطيعا باتباع الفرض الناسخ له.\nقال الله لنبيه: \" قد نرى تقلب وجهك في السماء، فلنولينك قبلة ترضاها، فول وجهك شطر المسجد الحرام، وحيث ما كنتم فولوا وجوهكم شطره (144) \" [البقرة] .\nفإن قال قائل: فأين الدلالة على أنهم حولوا إلى قبلة بعد قبلة؟\nففي قول الله: \" سيقول السفهاء من الناس: ما ولاهم عن قبلتهم التي كانوا عليها؟ قل: لله المشرق والمغرب. يهدي من يشاء إلى صراط مستقيم (142) \" [البقرة] .\n\"مالك\" عن \"عبد الله بن دينار\" عن \"ابن عمر\"","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:202","bookId":"risala-shafii","type":"section","seq":202,"chapter":"الجزء الأول","title":"ص: 124","page":"ج1 ص120","text":"قال: \" بينما الناس بقباء في صلاة الصبح، إذ جاءهم آت، فقال: إن النبي قد أنزل عليه الليلة قرآن، وقد أمر أن يستقبل القبلة، فاستقبلوها، وكانت وجوههم إلى الشام، فاستداروا إلى الكعبة \" (1) .\n\"مالك\" عن \"يحيى بن سعيد\" عن \"سعيد بن المسيب\"","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:203","bookId":"risala-shafii","type":"section","seq":203,"chapter":"الجزء الأول","title":"ص: 125","page":"ج1 ص120","text":"أنه كان يقول: \" صلى رسول الله ستة عشر شهرا نحو بيت المقدس، ثم حولت القبلة قبل بدر بشهرين \" (2) .\nقال: والاستدلال بالكتاب في صلاة الخوف قول الله: \" فإن خفتم فرجالا أو ركبانا (239) \" [البقرة] ، وليس لمصلي المكتوبة أن يصلي راكبا إلا في خوف، ولم يذكر الله أن يتوجه القبلة. (1)","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:204","bookId":"risala-shafii","type":"section","seq":204,"chapter":"الجزء الأول","title":"ص: 126","page":"ج1 ص120","text":"وروى \"ابن عمر\" عن رسول الله صلاة الخوف، فقال في روايته: \" فإن كان خوف أشد من ذلك صلوا رجالا وركبانا، مستقبلي القبلة وغير مستقبليها \" (2) .\nوصلى رسول الله النافلة في السفر على راحلته أين توجهت به؛ حفظ ذلك عنه \"جابر ابن عبد الله\"، و\"أنس بن مالك\" وغيرهما، وكان لا يصلي المكتوبة مسافرا إلا بالأرض متوجها للقبلة.\n\"ابن أبي فديك\" عن \"ابن أبي ذئب\" عن \"عثمان بن عبد الله بن سراقة\" عن \"جابر بن عبد الله\": \" أن النبي كان يصلي على راحلته موجهة به قبل المشرق في غزوة بني أنمار \" (3) .\nقال الله: \" يا أيها النبي حرض المؤمنين على القتال، إن يكن منكم عشرون صابرون يغلبوا مائتين، وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا بأنهم قوم لا يفقهون (65) \" [الأنفال] .\nثم أبان في كتابه: أنه وضع عنهم أن يقوم الواحد بقتال العشرة، وأثبت عليهم أن يقوم الواحد بقتال الاثنين، فقال: \" الآن خفف الله عنكم، وعلم أن فيكم ضعفا، فإن يكن منكم مائة صابرة يغلبوا مائتين، وإن يكن منكم ألف يغلبوا ألفين بإذن الله، والله مع الصابرين (66) \"بالأنفال] .\nأخبرنا \"سفيان\" عن \"عمرو بن دينار\" عن \"ابن عباس\" قال: \" لما نزلت هذه الآية: \" إن يكن منكم عشرون صابرون","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:205","bookId":"risala-shafii","type":"section","seq":205,"chapter":"الجزء الأول","title":"ص: 128","page":"ج1 ص125","text":"يغلبوا مائتين (65) \" [الأنفال] ، كتب عليهم ألا يفر العشرون من المائتين، فأنزل الله: \" الآن خفف الله عنكم، وعلم أن فيكم ضعفا \" إلى: \" يغلبوا مائتين \"، فكتب أن لا يفر المائة من المائتين \" (1) .\nقال: وهذا كما قال \"ابن عباس\" إن شاء الله، وقد بين الله هذا في الآية، وليست تحتاج إلى تفسير.\nقال: \" واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم، فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت، أو يجعل الله لهن سبيلا (15) واللذان","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:206","bookId":"risala-shafii","type":"section","seq":206,"chapter":"الجزء الأول","title":"ص: 129","page":"ج1 ص127","text":"يأتيانها منكم فآذوهما، فإن تابا وأصلحا فأعرضوا عنهما، إن الله كان توابا رحيما (16) \" [النساء] .\nثم نسخ الله الحبس والأذى في كتابه، فقال: \" الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة (2) \" [النور] .\nفدلت السنة على أن جلد المائة للزانيين البكرين.\nأخبرنا \"عبد الوهاب\" عن \"يونس بن عبيد\" عن \"الحسن\" عن \"عبادة ابن الصامت\"، أن رسول الله قال: \" خذوا عني، خذوا عني، قد جعل الله لهن سبيلا، البكر بالبكر جلد مائة وتغريب عام، والثيب بالثيب جلد مائة والرجم \" (1) .\nأخبرنا الثقة من أهل العلم، عن \"يونس بن عبيد\"","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:207","bookId":"risala-shafii","type":"section","seq":207,"chapter":"الجزء الأول","title":"ص: 130","page":"ج1 ص127","text":"عن \"الحسن\" عن \"حطان الرقاشي\" عن \"عبادة بن الصامت\"، عن النبي مثله.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:208","bookId":"risala-shafii","type":"section","seq":208,"chapter":"الجزء الأول","title":"ص: 131","page":"ج1 ص127","text":"قال: فدلت سنة رسول الله أن جلد المائة ثابت على البكرين الحرين، ومنسوخ عن الثيبين، وأن الرجم ثابت على الثيبين الحرين.\nلأن قول رسول الله: \" خذوا عني، قد جعل الله","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:209","bookId":"risala-shafii","type":"section","seq":209,"chapter":"الجزء الأول","title":"ص: 132","page":"ج1 ص127","text":"لهن سبيلا، البكر بالبكر، جلد مائة وتغريب عام، والثيب بالثيب، جلد مائة والرجم \"، أول ما نزل، فنسخ به الحبس والأذى عن الزانيين.\nفلما رجم النبي \"ماعزا\" ولم يجلده، وأمر \"أنيسا\" أن يغدو على امرأة \"الأسلمي\"، فإن اعترفت رجمها: دل على نسخ الجلد عن الزانيين الحرين الثيبين، وثبت الرجم عليهما، لأن كل شيء أبدا بعد أول فهو آخر.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:210","bookId":"risala-shafii","type":"section","seq":210,"chapter":"الجزء الأول","title":"ص: 133","page":"ج1 ص127","text":"فدل كتاب الله، ثم سنة نبيه، على أن الزانيين المملوكين خارجان من هذا المعنى.\nقال الله - تبارك وتعالى - في المملوكات: \" فإذا أحصن: فإن أتين بفاحشة فعليهن نصف ما على المحصنات من العذاب (25) \" [النساء] .\nوالنصف لا يكون إلا من الجلد، الذي يتبعض، فأما الرجم - الذي هو قتل - فلا نصف له، لأن المرجوم قد","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:211","bookId":"risala-shafii","type":"section","seq":211,"chapter":"الجزء الأول","title":"ص: 134","page":"ج1 ص128","text":"يموت في أول حجر يرمى به، فلا يزاد عليه، ويرمى بألف وأكثر فيزاد عليه حتى يموت، فلا يكون لهذا نصف محدود أبدا.\nوالحدود موقتة بإتلاف نفس، والإتلاف موقت بعدد ضرب أو تحديد قطع، وكل هذا معروف، ولا نصف للرجم معروف.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:212","bookId":"risala-shafii","type":"section","seq":212,"chapter":"الجزء الأول","title":"ص: 135","page":"ج1 ص128","text":"وقال رسول الله: \" إذا زنت أمة أحدكم، فتبين زناها، فليجلدها \" (1) ، ولم يقل: (يرجمها) ، ولم يختلف المسلمون في ألا رجم على مملوك في الزنا.\nوإحصان الأمة إسلامها.\nوإنما قلنا هذا استدلالا بالسنة وإجماع أكثر أهل العلم.\nولما قال رسول الله: \" إذا زنت أمة أحدكم فتبين زناها، فليجلدها \"، ولم يقل: (محصنة كانت أو غير محصنة) ، استدللنا","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:213","bookId":"risala-shafii","type":"section","seq":213,"chapter":"الجزء الأول","title":"ص: 136","page":"ج1 ص128","text":"على أن قول الله في الإماء: \" فإذا أحصن فإن أتين بفاحشة فعليهن نصف ما على المحصنات من العذاب (25) \" [النساء] ، إذا أسلمن، لا إذا نكحن فأصبن بالنكاح، ولا إذا أعتقن وإن لم يصبن.\nفإن قال قائل: أراك توقع الإحصان على معاني مختلف؟\nقيل: نعم، جماع الإحصان أن يكون دون التحصين مانع من تناول المحرم. فالإسلام مانع، وكذلك الحرية مانعة، وكذلك الزوج والإصابة مانع، وكذلك الحبس في البيوت مانع، وكل ما منع أحصن. قال الله: \" وعلمناه صنعة لبوس لكم لتحصنكم من بأسكم (80) \" [الأنبياء] ، وقال: \" لا يقاتلونكم جميعا إلا في قرى محصنة (14) \" [الحشر] ، يعني: ممنوعة.\nقال: وآخر الكلام وأوله يدلان على أن معنى الإحصان، المذكور عاما في موضع دون غيره: أن الإحصان","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:214","bookId":"risala-shafii","type":"section","seq":214,"chapter":"الجزء الأول","title":"ص: 137","page":"ج1 ص128","text":"هاهنا الإسلام، دون النكاح والحرية والتحصين بالحبس والعفاف. وهذه الأسماء التي يجمعها اسم الإحصان.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:215","bookId":"risala-shafii","type":"section","seq":215,"chapter":"الجزء الأول","title":"الناسخ والمنسوخ الذي تدل عليه السنة والإجماع.","page":"ج1 ص133","text":"قال الله - تبارك وتعالى -: \" كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا: الوصية للوالدين والأقربين بالمعروف حقا على المتقين (180) \" [البقرة] .\nقال الله: \" والذين يتوفون منكم ويذرون","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:216","bookId":"risala-shafii","type":"section","seq":216,"chapter":"الجزء الأول","title":"ص: 138","page":"ج1 ص137","text":"أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج، فإن خرجن فلا جناح عليكم في ما فعلن في أنفسهن من معروف، والله عزيز حكيم (240) \" [البقرة] .\nفأنزل الله ميراث الوالدين ومن ورث بعدهما ومعهما من الأقربين، وميراث الزوج من زوجته، والزوجة من زوجها.\nفكانت الآيتان محتملتين لأن تثبتا الوصية للوالدين والأقربين، والوصية للزوج، والميراث مع الوصايا، فيأخذون بالميراث والوصايا، ومحتملة بأن تكون المواريث ناسخة للوصايا.\nفلما احتملت الآيتان ما وصفنا كان على أهل العلم طلب الدلالة من كتاب الله، فما لم يجدوه نصا في كتاب الله، طلبوه","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:217","bookId":"risala-shafii","type":"section","seq":217,"chapter":"الجزء الأول","title":"ص: 139","page":"ج1 ص137","text":"في سنة رسول الله، فإن وجدوه فما قبلوا عن رسول الله، فعن الله قبلوه، بما افترض من طاعته.\nووجدنا أهل الفتيا، ومن حفظنا عنه من أهل العلم بالمغازي، من قريش وغيرهم: لا يختلفون في أن النبي قال عام الفتح: \" لا وصية لوارث، ولا يقتل مؤمن بكافر \"، ويأثرونه عن من حفظوا عنه ممن لقوا من أهل العلم بالمغازي.\nفكان هذا نقل عامة عن عامة، وكان أقوى في بعض الأمر من نقل واحد عن واحد، وكذلك وجدنا أهل العلم عليه مجتمعين.\nقال: وروى بعض الشاميين حديثا ليس مما يثبته أهل الحديث، فيه: أن بعض رجاله مجهولون، فرويناه عن النبي منقطعا.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:218","bookId":"risala-shafii","type":"section","seq":218,"chapter":"الجزء الأول","title":"ص: 140","page":"ج1 ص137","text":"وإنما قبلناه بما وصفت من نقل أهل المغازي وإجماع العامة عليه، وإن كنا قد ذكرنا الحديث فيه، واعتمدنا على حديث أهل المغازي عاما وإجماع الناس.\nأخبرنا \"سفيان\" عن \"سليمان الأحول\" عن \"مجاهد\"، أن رسول الله قال: \" لا وصية لوارث \" (1) .","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:219","bookId":"risala-shafii","type":"section","seq":219,"chapter":"الجزء الأول","title":"ص: 142","page":"ج1 ص137","text":"فاستدللنا بما وصفت، من نقل عامة أهل المغازي عن النبي أن: \" لا وصية لوارث \"، على أن المواريث ناسخة للوصية للوالدين والزوجة، مع الخبر المنقطع عن النبي، وإجماع العامة على القول به.\nوكذلك قال أكثر العامة: إن الوصية للأقربين","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:220","bookId":"risala-shafii","type":"section","seq":220,"chapter":"الجزء الأول","title":"ص: 143","page":"ج1 ص137","text":"منسوخة زائل فرضها، إذا كانوا وارثين فبالميراث، وإن كانوا غير وارثين فليس بفرض أن يوصي لهم.\nإلا أن \"طاوسا\" وقليلا معه قالوا: نسخت الوصية للوالدين، وثبتت للقرابة غير الوارثين، فمن أوصى لغير قرابة لم يجز.\nفلما احتملت الآية ما ذهب إليه \"طاوس\"، من أن الوصية للقرابة ثابتة، إذ لم يكن في خبر أهل العلم بالمغازي إلا أن النبي قال: \" لا وصية لوارث \"، وجب عندنا على أهل العلم طلب الدلالة على خلاف ما قال \"طاوس\" أو موافقته:\nفوجدنا رسول الله حكم في ستة مملوكين كانوا لرجل لا مال له غيرهم، فأعتقهم عند الموت، فجزأهم النبي ثلاثة أجزاء، فأعتق اثنين، وأرق أربعة.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:221","bookId":"risala-shafii","type":"section","seq":221,"chapter":"الجزء الأول","title":"ص: 144","page":"ج1 ص137","text":"أخبرنا بذلك \"عبد الوهاب\" عن \"أيوب\" عن \"أبي قلابة\" عن \"أبي المهلب\" عن \"عمران بن حصين\" عن النبي.\nقال: فكانت دلالة السنة في حديث \"عمران بن حصين\" بينة بأن رسول الله أنزل عتقهم في المرض وصية.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:222","bookId":"risala-shafii","type":"section","seq":222,"chapter":"الجزء الأول","title":"ص: 145","page":"ج1 ص137","text":"والذي أعتقهم رجل من العرب، والعربي إنما يملك من لا قرابة بينه وبينه من العجم، فأجاز النبي لهم الوصية.\nفدل ذلك على أن الوصية لو كانت تبطل لغير قرابة: بطلت للعبيد المعتقين، لأنهم ليسوا بقرابة للمعتق.\nودل ذلك على أن لا وصية لميت إلا في ثلث ماله، ودل ذلك على أن يرد ما جاوز الثلث في الوصية، وعلى إبطال الاستسعاء، وإثبات القسم والقرعة.\nوبطلت وصية الوالدين، لأنهما وارثان، وثبت ميراثهما.\nومن أوصى له الميت من قرابة وغيرهم، جازت الوصية، إذا لم يكن وارثا.\nوأحب إلي لو أوصى لقرابته.\nوفي القرآن ناسخ ومنسوخ غير هذا، مفرق في مواضعه، في كتاب (أحكام القرآن) .\nوإنما وصفت منه جملا يستدل بها على ما كان في","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:223","bookId":"risala-shafii","type":"section","seq":223,"chapter":"الجزء الأول","title":"ص: 146","page":"ج1 ص137","text":"معناها، ورأيت أنها كافية في الأصل مما سكت عنه، وأسأل الله العصمة والتوفيق.\nوأتبعت ما كتبت منها علم الفرائض التي أنزلها الله مفسرات وجملا، وسنن رسول الله معها وفيها ليعلم من علم هذا من علم (الكتاب) ، الموضع الذي وضع الله به نبيه من كتابه ودينه وأهل دينه.\nويعلمون أن اتباع أمره طاعة الله، وأن سنته تبع لكتاب الله فيما أنزل، وأنها لا تخالف كتاب الله أبدا.\nويعلم من فهم (هذا الكتاب) أن البيان يكون من وجوه، لا من وجه واحد، يجمعها أنها عند أهل العلم بينة ومشتبهة البيان، وعند من يقصر علمه مختلفة البيان.","bab":"باب: فرض الصلاة الذي دل الكتاب ثم السنة على من تزول عنه بعذر، وعلى من لا تكتب صلاته بالمعصية."},{"id":"risala-shafii:224","bookId":"risala-shafii","type":"section","seq":224,"chapter":"الجزء الأول","title":"باب: الفرائض التي أنزل الله نصا.","page":"ج1 ص145","text":"قال الله - جل ثناؤه -: \" والذين يرمون المحصنات، ثم لم يأتوا بأربعة شهداء، فاجلدوهم ثمانين جلدة، ولا تقبلوا لهم شهادة أبدا، وأولئك هم الفاسقون (4) \" [النور] .\nقال \"الشافعي\": فالمحصنات هاهنا البوالغ الحرائر. وهذا يدل على أن الإحصان اسم جامع لمعاني مختلفة.\nوقال: \" والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم: فشهادة أحدهم أربع شهادات بالله إنه لمن الصادقين (6) والخامسة أن لعنة الله عليه إن كان من الكاذبين (7) ويدرأ عنها العذاب أن تشهد أربع شهادات بالله إنه لمن الكاذبين (8) والخامسة أن غضب الله عليها إن كان من الصادقين (9) \" [النور] .","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:225","bookId":"risala-shafii","type":"section","seq":225,"chapter":"الجزء الأول","title":"ص: 148","page":"ج1 ص146","text":"فلما فرق الله بين حكم الزوج والقاذف سواه، فحد القاذف سواه، إلا أن يأتي بأربعة شهداء، على ما قال، وأخرج الزوج باللعان من الحد: دل ذلك على أن قذفة المحصنات، الذين أريدوا بالجلد: قذفة الحرائر البوالغ غير الأزواج.\nوفي هذا الدليل على ما وصفت، من أن القرآن عربي، يكون منه ظاهره عاما، وهو يراد به الخاص، لا أن واحدة من الآيتين نسخت الأخرى، ولكن كل واحدة منهما على ما حكم الله به، فيفرق بينهما حيث فرق الله، ويجمعان حيث جمع الله.\nفإذا التعن الزوج خرج من الحد، كما يخرج الأجنبيون بالشهود، وإذا لم يلتعن - وزوجته حرة بالغة - حد.\nقال: وفي \"العجلاني\" وزوجته أنزلت آية اللعان، ولاعن النبي بينهما، فحكى اللعان بينهما \"سهل بن سعد الساعدي\"،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:226","bookId":"risala-shafii","type":"section","seq":226,"chapter":"الجزء الأول","title":"ص: 149","page":"ج1 ص146","text":"وحكاه \"ابن عباس\"، وحكى \"ابن عمر\" حضور لعان عند النبي، فما حكى منهم واحد كيف لفظ النبي في أمرهما باللعان.\nوقد حكوا معا أحكاما لرسول الله ليست نصا في القرآن، منها: تفريقه بين المتلاعنين، ونفيه الولد، وقوله: \" إن جاءت به هكذا فهو للذي يتهمه \" فجاءت به على الصفة، وقال: إن أمره لبين لولا ما حكى الله \"، وحكى \"ابن عباس\" أن النبي قال عند الخامسة: \" قفوه فإنها موجبة \" (1) .\nفاستدللنا على أنهم لا يحكون بعض ما يحتاج إليه من الحديث، ويدعون بعض ما يحتاج إليه منه، وأولاه أن يحكى من ذلك، كيف لاعن النبي بينهما: إلا علما بأن أحدا قرأ كتاب","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:227","bookId":"risala-shafii","type":"section","seq":227,"chapter":"الجزء الأول","title":"ص: 150","page":"ج1 ص147","text":"الله، يعلم أن رسول الله إنما لاعن كما أنزل الله.\nفاكتفوا بإبانة الله اللعان بالعدد والشهادة لكل واحد منهما، دون حكاية لفظ رسول الله حين لاعن بينهما.\nقال \"الشافعي\": في كتاب الله غاية الكفاية عن اللعان وعدده.\nثم حكى بعضهم عن النبي في الفرقة بينهما كما وصفت.\nوقد وصفنا سنن رسول الله مع كتاب الله قبل هذا.\nقال الله: \" ياأيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون (183) أياما معدودات ... (184) \" [البقرة] ، \" فمن شهد منكم الشهر فليصمه ومن كان مريضا (185) \" [البقرة] .\nثم بين أي شهر هو، فقال: \" شهر رمضان الذي أنزل فيه القرآن هدى للناس وبينات من الهدى والفرقان، فمن شهد منكم الشهر فليصمه، ومن كان مريضا أو على سفر فعدة من أيام أخر. يريد الله بكم اليسر ولا يريد بكم العسر، ولتكملوا العدة، ولتكبروا الله على ما هداكم، ولعلكم تشكرون (185) \" [البقرة] .\nقال \"الشافعي\": فما علمت أحدا من أهل العلم بالحديث","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:228","bookId":"risala-shafii","type":"section","seq":228,"chapter":"الجزء الأول","title":"ص: 158","page":"ج1 ص149","text":"قبلنا تكلف أن يروي عن النبي أن الشهر المفروض صومه شهر رمضان الذي بين شعبان وشوال، لمعرفتهم بشهر رمضان من الشهور واكتفاء منهم بأن الله فرضه.\nوقد تكلفوا حفظ صومه في السفر وفطره، وتكلفوا كيف قضاؤه، وما أشبه هذا، مما ليس فيه نص كتاب.\nولا علمت أحدا من غير أهل العلم احتاج في المسألة عن شهر رمضان: أي شهر هو؟ ولا: هل هو واجب أم لا؟\nوهكذا ما أنزل الله من جمل فرائضه، في أن عليهم صلاة وزكاة وحجا على من أطاقه، وتحريم الزنا والقتل وما أشبه هذا.\nقال: وقد كانت لرسول الله في هذا سننا (1) ليست","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:229","bookId":"risala-shafii","type":"section","seq":229,"chapter":"الجزء الأول","title":"ص: 159","page":"ج1 ص157","text":"نصا في القرآن، أبان رسول الله عن الله معنى ما أراد بها، وتكلم المسلمون في أشياء من فروعها، لم يسن رسول الله فيها سنة منصوصة.\n- فمنها: قول الله: \" فإن طلقها فلا تحل له من بعد حتى تنكح زوجا غيره، فإن طلقها فلا جناح عليهما أن يتراجعا (230) \" [البقرة] .\nفاحتمل قول الله: (حتى تنكح زوجا غيره) : أن يتزوجها زوج غيره، وكان هذا المعنى الذي يسبق إلى من خوطب به: أنها إذا عقدت عليها عقدة النكاح فقد نكحت.\nواحتمل: حتى يصيبها زوج غيره لأن اسم (النكاح) يقع بالإصابة، ويقع بالعقد.\nفلما قال رسول الله لامرأة طلقها زوجها ثلاثا ونكحها بعده رجل: \" لا تحلين حتى تذوقي عسيلته","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:230","bookId":"risala-shafii","type":"section","seq":230,"chapter":"الجزء الأول","title":"ص: 160","page":"ج1 ص157","text":"ويذوق عسيلتك \"، يعني: يصيبك زوج غيره؛ والإصابة: النكاح.\nفإن قال قائل: فاذكر الخبر عن رسول الله بما ذكرت.\nقيل: أخبرنا \"سفيان\" عن \"ابن شهاب\" عن \"عروة\" عن \"عائشة\": \" أن امرأة رفاعة","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:231","bookId":"risala-shafii","type":"section","seq":231,"chapter":"الجزء الأول","title":"ص: 161","page":"ج1 ص157","text":"جاءت إلى النبي، فقالت: إن رفاعة طلقني فبت طلاقي، وإن عبد الرحمن بن الزبير تزوجني، وإنما معه مثل هدبة الثوب (2) ، فقال رسول الله: أتريدين أن ترجعي إلى رفاعة؟ لا، حتى تذوقي عسيلته ويذوق عسيلتك \" (3) .\nقال \"الشافعي\": فبين رسول الله، أن إحلال الله إياها للزوج المطلق ثلاثا بعد زوج بالنكاح: إذا كان مع النكاح إصابة من الزوج.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:232","bookId":"risala-shafii","type":"section","seq":232,"chapter":"الجزء الأول","title":"الفرائض المنصوصة التي سن رسول الله معها.","page":"ج1 ص158","text":"قال الله - تبارك وتعالى -: \" إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق، وامسحوا برءوسكم","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:233","bookId":"risala-shafii","type":"section","seq":233,"chapter":"الجزء الأول","title":"ص: 162","page":"ج1 ص161","text":"وأرجلكم إلى الكعبين، وإن كنتم جنبا فاطهروا (6) \" [المائدة] .\nوقال: \" ولا جنبا إلا عابري سبيل حتى تغتسلوا (43) \" [النساء] .\nفأبان أن طهارة الجنب الغسل دون الوضوء.\nوسن رسول الله الوضوء كما أنزل الله: فغسل وجهه ويديه إلى المرفقين، ومسح برأسه، وغسل رجليه إلى الكعبين.\nأخبرنا \"عبد العزيز بن محمد\" عن \"زيد بن أسلم\" عن \"عطاء بن يسار\" عن \"ابن عباس\" عن النبي: \" أنه توضأ مرة مرة \" (1) .\nأخبرنا \"مالك عن عمرو بن يحيى\" عن أبيه، أنه قال \"لعبد الله بن زيد\"، وهو جد \"عمرو بن يحيى\": \" هل تستطيع أن","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:234","bookId":"risala-shafii","type":"section","seq":234,"chapter":"الجزء الأول","title":"ص: 163","page":"ج1 ص161","text":"تريني كيف كان رسول الله يتوضأ؟ فقال \"عبد الله\": نعم، فدعا بوضوء، فأفرغ على يديه، فغسل يديه مرتين، ثم مضمض واستنشق ثلاثا، ثم غسل وجهه ثلاثا، ثم غسل يديه مرتين مرتين إلى المرفقين، ثم مسح برأسه بيديه، فأقبل بهما وأدبر، بدأ بمقدم رأسه، ثم ذهب بهما إلى قفاه، ثم ردهما إلى المكان الذي بدأ منه، ثم غسل رجليه \" (2) .","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:235","bookId":"risala-shafii","type":"section","seq":235,"chapter":"الجزء الأول","title":"ص: 164","page":"ج1 ص161","text":"فكان ظاهر قول الله: (فاغسلوا وجوهكم) ، أقل ما وقع عليه اسم الغسل، وذلك مرة، واحتمل أكثر.\nفسن رسول الله الوضوء مرة، فوافق ذلك ظاهر القرآن، وذلك أقل ما يقع عليه اسم الغسل، واحتمل أكثر، وسنه مرتين وثلاثا.\nفلما سنه مرة استدللنا على أنه لو كانت مرة لا تجزئ: لم يتوضأ مرة ويصلي، وأن ما جاوز مرة اختيار، لا فرض في الوضوء لا يجزئ أقل منه.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:236","bookId":"risala-shafii","type":"section","seq":236,"chapter":"الجزء الأول","title":"ص: 165","page":"ج1 ص161","text":"وهذا مثل ما ذكرت من الفرائض قبله: لو ترك الحديث فيه استغني فيه بالكتاب، وحين حكي الحديث فيه دل على اتباع الحديث كتاب الله.\nولعلهم إنما حكوا الحديث فيه لأن أكثر ما توضأ رسول الله ثلاثا، فأرادوا أن الوضوء ثلاثا اختيار، لا أنه واجب لا يجزئ أقل منه، ولما ذكر منه في أن \" من توضأ وضوءه هذا - وكان ثلاثا - ثم صلى ركعتين لا يحدث نفسه فيهما، غفر له \" (3) ؛ فأرادوا طلب الفضل في الزيادة في الوضوء، وكانت الزيادة فيه نافلة.\nوغسل رسول الله في الوضوء المرفقين والكعبين، وكانت الآية محتملة أن يكونا مغسولين وأن يكون مغسولا إليهما، ولا يكونان مغسولين، ولعلهم حكوا الحديث إبانة لهذا أيضا.\nوأشبه الأمرين بظاهر الآية أن يكونا مغسولين.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:237","bookId":"risala-shafii","type":"section","seq":237,"chapter":"الجزء الأول","title":"ص: 166","page":"ج1 ص161","text":"وهذا بيان السنة مع بيان القرآن.\nوسواء البيان في هذا وفيما قبله، ومستغنى بفرضه بالقرآن عند أهل العلم، ومختلفان عند غيرهم.\nوسن رسول الله في الغسل من الجنابة غسل الفرج والوضوء كوضوء الصلاة ثم الغسل، فكذلك أحببنا أن نفعل.\nولم أعلم مخالفا حفظت عنه من أهل العلم في أنه كيف ما جاء بغسل وأتى على الإسباغ: أجزأه، وإن اختاروا غيره، لأن الفرض الغسل فيه، ولم يحدد تحديد الوضوء.\nوسن رسول الله فيما يجب منه الوضوء، وما الجنابة التي يجب بها الغسل، إذ لم يكن بعض ذلك منصوصا في الكتاب.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:238","bookId":"risala-shafii","type":"section","seq":238,"chapter":"الجزء الأول","title":"الفرض المنصوص الذي دلت السنة على أنه إنما أراد الخاص.","page":"ج1 ص166","text":"قال الله - تبارك وتعالى -: \" يستفتونك. قل: الله يفتيكم في الكلالة، إن امرؤ هلك ليس له ولد وله أخت فلها نصف ما ترك، وهو يرثها إن لم يكن لها ولد (176) \" [النساء] ،\nوقال: \" للرجال نصيب مما ترك الوالدان والأقربون، وللنساء نصيب مما ترك الوالدان والأقربون مما قل منه أو كثر نصيبا مفروضا (7) \" [النساء] .\nوقال: \" ولأبويه لكل واحد منهما السدس مما ترك إن كان له ولد، فإن لم يكن له ولد وورثه أبواه فلأمه الثلث، فإن كان له إخوة فلأمه السدس من بعد وصية يوصي بها أو دين. آباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعا فريضة","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:239","bookId":"risala-shafii","type":"section","seq":239,"chapter":"الجزء الأول","title":"ص: 168","page":"ج1 ص166","text":"من الله. إن الله كان عليما حكيما (11) ولكم نصف ما ترك أزواجكم إن لم يكن لهن ولد، فإن كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها أو دين (12) \" [النساء] .\nوقال: \" ولهن الربع (12) \" [النساء] ، مع آي المواريث كلها.\nفدلت السنة على أن الله إنما أراد ممن سمى له المواريث، من الإخوة والأخوات، والولد والأقارب، والوالدين والأزواج، وجميع من سمى له فريضة في كتابه، خاصا ممن سمى.\nوذلك أن يجتمع دين الوارث والموروث، فلا يختلفان، ويكونان من أهل دار المسلمين، ومن له عقد من المسلمين يأمن به على ماله ودمه، أو يكونان من المشركين، فيتوارثان بالشرك.\nأخبرنا \"سفيان\" عن \"الزهري\" عن \"علي بن حسين\"","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:240","bookId":"risala-shafii","type":"section","seq":240,"chapter":"الجزء الأول","title":"ص: 169","page":"ج1 ص166","text":"عن \"عمرو بن عثمان بن أسامة بن زيد\"، أن رسول الله قال: \" لا يرث المسلم الكافر، ولا الكافر المسلم \" (1) .","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:241","bookId":"risala-shafii","type":"section","seq":241,"chapter":"الجزء الأول","title":"ص: 170","page":"ج1 ص166","text":"وأن يكون الوارث والموروث حرين مع الإسلام.\nأخبرنا \"ابن عيينة\" عن \"ابن شهاب\" عن \"سالم\" عن أبيه، أن رسول الله قال: \" من باع عبدا وله مال، فماله للبائع، إلا أن يشترطه المبتاع \" (1) .\nقال: فلما كان بينا في سنة رسول الله أن العبد لا يملك مالا، وأن ما ملك العبد فإنما يملكه لسيده، وأن اسم المال له إنما هو إضافة إليه، لأنه في يديه، لا أنه مالك له، ولا يكون مالكا له وهو لا يملك نفسه، وهو مملوك، يباع ويوهب ويورث،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:242","bookId":"risala-shafii","type":"section","seq":242,"chapter":"الجزء الأول","title":"ص: 171","page":"ج1 ص167","text":"وكان الله إنما نقل ملك الموتى إلى الأحياء، فملكوا منها ما كان الموتى مالكين، وإن كان العبد أبا أو غيره ممن سميت له فريضة، فكان لو أعطيها ملكها سيده عليه، لم يكن السيد بأبي الميت ولا وارثا سميت له فريضة، فكنا لو أعطينا العبد بأنه أب، إنما أعطينا السيد الذي لا فريضة له، فورثنا غير من ورثه الله، فلم نورث عبدا لما وصفت، ولا أحدا لم تجتمع فيه الحرية والإسلام والبراءة من القتل، حتى لا يكون قاتلا.\nوذلك أنه روى \"مالك\" عن \"يحيى بن سعيد عن عمرو بن شعيب\"، أن رسول الله قال: \" ليس لقاتل شيء \" (2) .","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:243","bookId":"risala-shafii","type":"section","seq":243,"chapter":"الجزء الأول","title":"ص: 172","page":"ج1 ص167","text":"فلم نورث قاتلا ممن قتل، وكان أخف حال القاتل عمدا أن يمنع الميراث عقوبة، مع تعرض سخط الله، أن يمنع ميراث من عصى الله بالقتل.\nوما وصفت، من ألا يرث المسلم إلا مسلم حر غير قاتل عمدا، ما لا اختلاف فيه بين أحد من أهل العلم حفظت عنه ببلدنا ولا غيره.\nوفي اجتماعهم على ما وصفنا من هذا حجة تلزمهم","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:244","bookId":"risala-shafii","type":"section","seq":244,"chapter":"الجزء الأول","title":"ص: 173","page":"ج1 ص170","text":"ألا يتفرقوا في شيء من سنن رسول الله، بأن سنن رسول الله إذا قامت هذا المقام فيما لله فيه فرض منصوص، فدلت على أنه على بعض من لزمه اسم ذلك الفرض دون بعض: كانت فيما كان مثله من القرآن: هكذا، وكانت فيما سن النبي فيما ليس فيه لله حكم منصوص: هكذا.\nوأولى أن لا يشك عالم في لزومها، وأن يعلم أن أحكام الله ثم أحكام رسوله لا تختلف، وأنها تجري على مثال واحد.\nقال الله - تبارك وتعالى -: \" لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم (29) \" [النساء] .\nوقال: \" ذلك بأنهم قالوا: إنما البيع مثل الربا، وأحل الله البيع، وحرم الربا (275) \" [البقرة] .\nونهى رسول الله عن بيوع تراضى بها المتبايعان،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:245","bookId":"risala-shafii","type":"section","seq":245,"chapter":"الجزء الأول","title":"ص: 174","page":"ج1 ص172","text":"فحرمت، مثل الذهب بالذهب إلا مثلا بمثل، ومثل الذهب بالورق وأحدهما نقد والآخر نسية (1) ، وما كان في معنى هذا، مما ليس في التبايع به مخاطرة، ولا أمر يجهله البائع ولا المشتري.\nفدلت السنة على أن الله - جل ثناؤه - أراد بإحلال البيع ما لم يحرم منه، دون ما حرم على لسان نبيه.\nثم كانت لرسول الله في بيوع سوى هذا سننا (2) منها:","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:246","bookId":"risala-shafii","type":"section","seq":246,"chapter":"الجزء الأول","title":"ص: 175","page":"ج1 ص172","text":"العبد يباع، وقد دلس البائع المشتري بعيب، فللمشتري رده، وله الخراج بضمانه. ومنها: أن من باع عبدا وله مال، فماله للبائع إلا أن يشترطه المبتاع. ومنها: من باع نخلا قد أبرت، فثمرها للبائع إلا أن يشترط المبتاع، لزم الناس الأخذ بها، بما ألزمهم الله من الانتهاء إلى أمره.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:247","bookId":"risala-shafii","type":"section","seq":247,"chapter":"الجزء الأول","title":"جمل الفرائض.","page":"ج1 ص173","text":"قال الله - تبارك وتعالى -: \" إن الصلاة كانت على المؤمنين كتابا موقوتا (103) \" [النساء] .\nوقال: \" وأقيموا الصلاة وآتوا الزكاة (43) \" [النساء] .\nوقال لنبيه: \" خذ من أموالهم صدقة تطهرهم وتزكيهم بها (103) \" [التوبة] .\nوقال: \" ولله على الناس حج البيت من استطاع إليه سبيلا (97) \" [آل عمران] .\nقال \"الشافعي\": أحكم الله فرضه في كتابه","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:248","bookId":"risala-shafii","type":"section","seq":248,"chapter":"الجزء الأول","title":"ص: 177","page":"ج1 ص175","text":"في الصلاة والزكاة والحج، وبين كيف فرضه على لسان نبيه.\nفأخبر رسول الله أن عدد الصلوات المفروضات: خمس، وأخبر أن عدد الظهر والعصر والعشاء في الحضر: أربع أربع، وعدد المغرب: ثلاث، وعدد الصبح: ركعتان.\nوسن فيها كلها قراءة، وسن أن الجهر منها بالقراءة: في المغرب والعشاء والصبح، وأن المخافتة بالقراءة: في الظهر والعصر.\nوسن أن الفرض في الدخول في كل صلاة بتكبير، والخروج منها بتسليم، وأنه يؤتى فيها بتكبير، ثم قراءة، ثم ركوع، ثم سجدتين بعد الركوع، وما سوى هذا من حدودها.\nوسن في صلاة السفر قصرا، كلما كان أربعا من الصلوات، إن شاء المسافر، وإثبات المغرب والصبح على حالها في الحضر.\nوأنها كلها إلى القبلة، مسافرا كان أو مقيما، إلا في حال من الخوف واحدة.\nوسن أن النوافل في مثل حالها، لا تحل إلا بطهور، ولا تجوز إلا بقراءة، وما تجوز به المكتوبات من السجود والركوع واستقبال القبلة في الحضر وفي الأرض وفي السفر، وأن للراكب أن يصلي في النافلة حيث توجهت به دابته.\nأخبرنا \"ابن أبي فديك\" عن \"ابن أبي ذئب\" عن \"عثمان بن عبد الله بن سراقة\" عن \"جابر بن عبد الله\": \" أن رسول الله في غزوة بني أنمار كان يصلي على راحلته متوجها قبل المشرق \" (1) .\nأخبرنا \"مسلم (2) \" عن \"ابن جريج\" عن \"أبي الزبير\" عن \"جابر\" عن النبي مثل معناه، لا أدري، أسمى بني أنمار أو لا؟ أو قال: \" صلى في سفر \".\nوسن رسول الله في صلاة الأعياد، والاستسقاء سنة الصلوات في عدد الركوع والسجود، وسن في صلاة الكسوف، فزاد فيها ركعة على ركوع الصلوات، فجعل في كل ركعة ركعتين.\nقال: أخبرنا \"مالك\" عن \"يحيى بن سعيد بن عمرة\" عن \"عائشة\" عن النبي.\nوأخبرنا \"مالك\" عن \"هشام\" عن أبيه، عن \"عائشة\" عن النبي.\nقال: \"مالك\" عن \"زيد بن أسلم\" عن \"عطاء بن يسار\" عن \"ابن عباس\" عن النبي مثله.\nقال: فحكي عن \"عائشة\"، و\"ابن عباس\" في هذه الأحاديث، صلاة النبي بلفظ مختلف، واجتمع في حديثهما معا على أنه صلى صلاة الكسوف ركعتين، في كل ركعة ركعتين.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:249","bookId":"risala-shafii","type":"section","seq":249,"chapter":"الجزء الأول","title":"ص: 180","page":"ج1 ص178","text":"وقال الله في الصلاة: \" إن الصلاة كانت على المؤمنين كتابا موقوتا (103) \" [النساء] .\nفبين رسول الله عن الله تلك المواقيت، وصلى الصلوات لوقتها، فحوصر يوم الأحزاب، فلم يقدر على الصلاة في وقتها، فأخرها للعذر، حتى صلى الظهر والعصر والمغرب والعشاء في مقام واحد.\nأخبرنا \"محمد بن إسماعيل بن أبي فديك\" عن \"ابن أبي ذئب\" عن \"المقبري\" عن \"عبد الرحمن بن أبي سعيد\" عن أبيه، قال: \" حبسنا يوم الخندق عن الصلاة، حتى كان بعد المغرب بهوي (1) من الليل، حتى كفينا، وذلك قول الله: \" وكفى الله المؤمنين القتال، وكان الله قويا عزيزا (25) \" [الأحزاب] ، فدعا رسول الله بلالا فأمره، فأقام الظهر فصلاها،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:250","bookId":"risala-shafii","type":"section","seq":250,"chapter":"الجزء الأول","title":"ص: 181","page":"ج1 ص178","text":"فأحسن صلاتها، كما كان يصليها في وقتها، ثم أقام العصر فصلاها هكذا، ثم أقام المغرب فصلاها كذلك، ثم أقام العشاء فصلاها كذلك أيضا، قال: وذلك قبل أن ينزل في صلاة الخوف: \" فرجالا أو ركبانا (239) \" [البقرة] (2) .\nقال: فبين \"أبو سعيد\" أن ذلك قبل أن ينزل الله على النبي الآية التي ذكرت فيها صلاة الخوف.\nوالآية التي ذكر فيها صلاة الخوف قول الله: \" وإذا ضربتم في الأرض، فليس عليكم جناح أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا. إن الكافرين كانوا","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:251","bookId":"risala-shafii","type":"section","seq":251,"chapter":"الجزء الأول","title":"ص: 182","page":"ج1 ص178","text":"لكم عدوا مبينا (101) \" [النساء] ، وقال: \" وإذا كنت فيهم فأقمت لهم الصلاة، فلتقم طائفة منهم معك وليأخذوا أسلحتهم، فإذا سجدوا فليكونوا من ورائكم، ولتأت طائفة أخرى لم يصلوا فليصلوا معك (102) \" [النساء] .\nأخبرنا \"مالك\" عن \"يزيد بن رومان\" عن \"صالح بن خوات\" عن من صلى مع رسول الله صلاة الخوف يوم ذات الرقاع: \" أن طائفة صفت معه، وطائفة وجاه العدو، فصلى بالذين معه ركعة، ثم ثبت قائما وأتموا لأنفسهم، ثم انصرفوا فصفوا وجاه العدو، وجاءت الطائفة الأخرى فصلى بهم الركعة التي بقيت من صلاته، ثم ثبت جالسا وأتموا لأنفسهم، ثم سلم بهم \" (3) .","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:252","bookId":"risala-shafii","type":"section","seq":252,"chapter":"الجزء الأول","title":"ص: 183","page":"ج1 ص178","text":"أخبرني من سمع \"عبد الله بن عمر بن حفص\" يذكر عن أخيه \"عبيد الله بن عمر\" عن \"القاسم بن محمد\" عن \"صالح بن خوات\" عن أبيه \"خوات بن جبير\" عن النبي مثل حديث \"يزيد بن رومان\".\nوفي هذا دلالة على ما وصفت قبل هذا في (هذا الكتاب) : من أن رسول الله إذا سن سنة فأحدث الله إليه","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:253","bookId":"risala-shafii","type":"section","seq":253,"chapter":"الجزء الأول","title":"ص: 184","page":"ج1 ص179","text":"في تلك السنة نسخها أو مخرجا إلى سعة منها: سن رسول الله سنة تقوم الحجة على الناس بها، حتى يكونوا إنما صاروا من سنته إلى سنته التي بعدها.\nفنسخ الله تأخير الصلاة عن وقتها في الخوف إلى أن يصلوها - كما أنزل الله وسن رسوله - في وقتها، ونسخ رسول الله سنته في تأخيرها بفرض الله في كتابه ثم بسنته، صلاها رسول الله في وقتها كما وصفت.\nأخبرنا \"مالك\" عن \"نافع\" عن \"ابن عمر\"، أراه عن النبي،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:254","bookId":"risala-shafii","type":"section","seq":254,"chapter":"الجزء الأول","title":"ص: 185","page":"ج1 ص179","text":"فذكر صلاة الخوف، فقال: \" إن كان خوف أشد من ذلك صلوا رجالا وركبانا، مستقبلي القبلة أو غير مستقبليها \" (1) .\nأخبرنا رجل عن \"ابن أبي ذئب\" عن \"الزهري\" عن \"سالم\"، عن أبيه، عن النبي مثل معناه، ولم يشك أنه عن أبيه، وأنه مرفوع إلى النبي.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:255","bookId":"risala-shafii","type":"section","seq":255,"chapter":"الجزء الأول","title":"ص: 186","page":"ج1 ص179","text":"قال: فدلت سنة رسول الله على ما وصفت، من أن القبلة في المكتوبة على فرضها أبدا، إلا في الموضع الذي لا يمكن فيه الصلاة إليها، وذلك عند المسابقة والهرب وما كان في المعنى الذي لا يمكن فيه الصلاة إليها.\nوثبتت السنة في هذا، ألا تترك الصلاة في وقتها، كيف ما أمكنت المصلي.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:256","bookId":"risala-shafii","type":"section","seq":256,"chapter":"الجزء الأول","title":"في الزكاة.","page":"ج1 ص183","text":"قال الله: \" وأقيموا الصلاة وآتوا الزكاة (43) \" [البقرة] ،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:257","bookId":"risala-shafii","type":"section","seq":257,"chapter":"الجزء الأول","title":"ص: 187","page":"ج1 ص186","text":"وقال: \" والمقيمين الصلاة والمؤتون الزكاة (162) \" [النساء] ، وقال: \" فويل للمصلين (4) الذين هم عن صلاتهم ساهون (5) الذين هم يراءون (6) ويمنعون الماعون (7) \" [الماعون] .\nفقال بعض أهل العلم: هي الزكاة المفروضة.\nقال الله: \" خذ من أموالهم صدقة تطهرهم وتزكيهم بها، وصل عليهم؛ إن صلاتك سكن لهم والله سميع عليم (103) \" [التوبة] .\nفكان مخرج الآية عاما على الأموال، وكان يحتمل أن تكون على بعض الأموال دون بعض، فدلت السنة على أن الزكاة في بعض الأموال دون بعض.\nفلما كان المال أصنافا، منه الماشية، فأخذ رسول الله","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:258","bookId":"risala-shafii","type":"section","seq":258,"chapter":"الجزء الأول","title":"ص: 188","page":"ج1 ص186","text":"من الإبل والغنم، وأمر - فيما بلغنا - بالأخذ من البقر خاصة، دون الماشية سواها، ثم أخذ منها بعدد مختلف، كما قضى الله على لسان نبيه، وكان للناس ماشية من خيل وحمر وبغال وغيرها، فلما لم يأخذ رسول الله منها شيئا، وسن أن ليس في الخيل صدقة: استدللنا على أن الصدقة فيما أخذ منه وأمر بالأخذ منه، دون غيره.\nوكان للناس زرع وغراس، فأخذ رسول الله من النخل والعنب الزكاة بخرص (1) غير مختلف ما أخذ منهما،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:259","bookId":"risala-shafii","type":"section","seq":259,"chapter":"الجزء الأول","title":"ص: 189","page":"ج1 ص186","text":"وأخذ منهما معا العشر إذا سقيا بسماء أو عين، ونصف العشر إذا سقيا بغرب (2) .\nوقد أخذ بعض أهل العلم من الزيتون، قياسا على النخل والعنب.\nولم يزل للناس غراس غير النخل والعنب والزيتون كثير، من الجوز واللوز والتين وغيره، فلما لم يأخذ رسول الله منه شيئا، ولم يأمر بالأخذ منه، استدللنا على أن فرض الله الصدقة فيما كان من غراس: في بعض الغراس دون بعض.\nوزرع الناس الحنطة والشعير والذرة، وأصنافا سواها، فحفظنا عن رسول الله الأخذ من الحنطة والشعير والذرة، وأخذ من قبلنا من الدخن والسلت","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:260","bookId":"risala-shafii","type":"section","seq":260,"chapter":"الجزء الأول","title":"ص: 190","page":"ج1 ص186","text":"والعلس والأرز (3) وكل ما نبته (4) الناس وجعلوه قوتا، خبزا وعصيدة وسويقا وأدما، مثل الحمص والقطاني (5) ،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:261","bookId":"risala-shafii","type":"section","seq":261,"chapter":"الجزء الأول","title":"ص: 191","page":"ج1 ص186","text":"فهي تصلح خبزا وسويقا وأدما، اتباعا لمن مضى، وقياسا على ما ثبت أن رسول الله أخذ منه الصدقة، وكان في معنى ما أخذ النبي، لأن الناس نبتوه ليقتاتوه.\nوكان للناس نبات غيره، فلم يأخذ منه رسول الله، ولا من بعد رسول الله علمناه، ولم يكن في معنى ما أخذ منه، وذلك مثل الثفاء","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:262","bookId":"risala-shafii","type":"section","seq":262,"chapter":"الجزء الأول","title":"ص: 191","page":"ج1 ص186","text":"والأسبيوش والكسبرة وحب العصفر (6) ، وما أشبهه، فلم تكن فيه زكاة: فدل ذلك على أن الزكاة في بعض الزرع دون بعض.\nوفرض رسول الله في الورق (1) صدقة، وأخذ المسلمون في الذهب بعده صدقة، إما بخبر عن النبي لم يبلغنا، جص 193&gt; وإما قياسا على أن الذهب والورق نقد الناس الذي اكتنزوه وأجازوه","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:263","bookId":"risala-shafii","type":"section","seq":263,"chapter":"الجزء الأول","title":"ص: 194","page":"ج1 ص186","text":"أثمانا على ما تبايعوا به في البلدان قبل الإسلام وبعده.\nوللناس تبر (2) غيره، من نحاس وحديد ورصاص، فلما لم يأخذ منه رسول الله ولا أحد بعده زكاة، تركناه، اتباعا بتركه، وأنه لا يجوز أن يقاس بالذهب والورق، الذين هما الثمن عاما في البلدان على غيرهما، لأنه في غير معناهما، لا زكاة فيه، ويصلح أن يشترى بالذهب والورق غيرهما من التبر إلى أجل معلوم وبوزن معلوم.\nوكان الياقوت والزبرجد أكثر ثمنا من الذهب والورق، فلما لم يأخذ منهما رسول الله، ولم يأمر بالأخذ ولا من بعده علمناه، وكانا مال الخاصة، وما لا يقوم به على أحد في شيء استهلكه الناس، لأنه غير نقد، لم يأخذ منهما.\nثم كان ما نقلت العامة عن رسول الله في زكاة الماشية والنقد، أنه أخذها في كل سنة مرة.\nوقال الله: \" وآتوا حقه يوم حصاده (141) \" [الأنعام] ، فسن رسول الله أن يؤخذ مما فيه زكاة من نبات الأرض، الغراس وغيره، على حكم الله - جل ثناؤه -، يوم يحصد، لا وقت له غيره.\nوسن في الركاز الخمس، فدل على أنه يوم يوجد، لا في وقت غيره.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:264","bookId":"risala-shafii","type":"section","seq":264,"chapter":"الجزء الأول","title":"ص: 196","page":"ج1 ص195","text":"أخبرنا \"سفيان\" عن \"الزهري\" عن \"ابن المسيب\" و\"أبي سلمة\" عن \"أبي هريرة\"، أن رسول الله قال: \" وفي الركاز الخمس \" (1) .\nولولا دلالة السنة كان ظاهر القرآن أن الأموال كلها سواء، وأن الزكاة في جميعها دون بعض.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:265","bookId":"risala-shafii","type":"section","seq":265,"chapter":"الجزء الأول","title":"في الحج] .","page":"ج1 ص195","text":"وفرض الله الحج على من يجد السبيل، فذكر عن النبي: أن السبيل الزاد والمركب، وأخبر رسول الله بمواقيت الحج وكيف التلبية فيه، وما سن، وما يتقي المحرم من لبس الثياب والطيب، وأعمال الحج سواها، من عرفة والمزدلفة والرمي والحلاق والطواف، وما سوى ذلك.\nفلو أن امرأ لم يعلم لرسول الله سنة مع كتاب الله إلا ما وصفنا، مما سن رسول الله فيه معنى ما أنزله الله جملة، وأنه إنما","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:266","bookId":"risala-shafii","type":"section","seq":266,"chapter":"الجزء الأول","title":"ص: 198","page":"ج1 ص197","text":"استدرك ما وصفت من فرض الله الأعمال، وما يحرم وما يحل، ويدخل به فيه ويخرج منه، ومواقيته، وما سكت عنه سوى ذلك من أعماله: قامت الحجة عليه بأن سنة رسول الله إذا قامت هذا المقام مع فرض الله في كتابه مرة أو أكثر، قامت كذلك أبدا.\nواستدل أنه لا تخالف له سنة أبدا كتاب الله، وأن سنته، وإن لم يكن فيها نص كتاب: لازمة، بما وصفت من هذا، مع ما ذكرت سواه، مما فرض الله من طاعة رسوله.\nووجب عليه أن يعلم أن الله لم يجعل هذا لخلق غير رسوله.\nوأن يجعل قول كل أحد وفعله أبدا تبعا لكتاب الله ثم سنة رسوله.\nوأن يعلم أن عالما إن روي عنه قول يخالف فيه شيئا","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:267","bookId":"risala-shafii","type":"section","seq":267,"chapter":"الجزء الأول","title":"ص: 199","page":"ج1 ص197","text":"سن فيه رسول الله سنة، لو علم سنة رسول الله لم يخالفها، وانتقل عن قوله إلى سنة النبي - إن شاء الله - وإن لم يفعل كان غير موسع له.\nفكيف والحجج في مثل هذا لله قائمة على خلقه، بما افترض من طاعة النبي، وأبان من موضعه الذي وضعه به من وحيه ودينه وأهل دينه.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:268","bookId":"risala-shafii","type":"section","seq":268,"chapter":"الجزء الأول","title":"في العدد] .","page":"ج1 ص197","text":"قال الله: \" والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا (234) \" [البقرة] ، وقال: \" والمطلقات يتربصن بأنفسهن ثلاثة قروء (228) \" [البقرة] .\nوقال: \" واللائي يئسن من المحيض من نسائكم","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:269","bookId":"risala-shafii","type":"section","seq":269,"chapter":"الجزء الأول","title":"ص: 200","page":"ج1 ص199","text":"إن ارتبتم فعدتهن ثلاثة أشهر واللائي لم يحضن، وأولات الأحمال أجلهن أن يضعن حملهن (4) \" [الطلاق] .\nفقال بعض أهل العلم: قد أوجب الله على المتوفى عنها زوجها أربعة أشهر وعشرا، وذكر أن أجل الحامل أن تضع، فإذا جمعت أن تكون حاملا متوفى عنها، أتت بالعدتين معا، كما أجدها في كل فرضين جعلا عليها أتت بهما معا.\nقال: فلما قال رسول الله \"لسبيعة بنت الحرث\"، ووضعت بعد وفاة زوجها بأيام: \" قد حللت فتزوجي \" (1) ، دل هذا على أن العدة في الوفاة والعدة في الطلاق بالأقراء والشهور، إنما أريد به من لا حمل به من النساء، وأن الحمل إذا كان فالعدة سواه ساقطة.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:270","bookId":"risala-shafii","type":"section","seq":270,"chapter":"الجزء الأول","title":"في محرمات النساء] .","page":"ج1 ص199","text":"قال الله: \" حرمت عليكم أمهاتكم وبناتكم وأخواتكم وعماتكم وخالاتكم وبنات الأخ وبنات الأخت وأمهاتكم اللاتي أرضعنكم وأخواتكم من الرضاعة وأمهات نسائكم وربائبكم اللاتي في حجوركم من نسائكم اللاتي دخلتم بهن، فإن لم تكونوا دخلتم بهن فلا جناح عليكم، وحلائل أبنائكم الذين من أصلابكم وأن تجمعوا بين الأختين إلا ما قد سلف، إن الله كان غفورا رحيما (23) والمحصنات من النساء إلا ما ملكت أيمانكم، كتاب الله عليكم، وأحل لكم ما وراء ذلكم أن تبتغوا بأموالكم محصنين غير مسافحين، فما استمتعتم به منهن فآتوهن أجورهن فريضة، ولا جناح عليكم فيما تراضيتم به من بعد الفريضة إن الله كان عليما حكيما (24) \" [النساء] .\nفاحتملت الآية معنيين: أحدهما: أن ما سمى الله من النساء محرما محرم، وما سكت عنه حلال بالصمت عنه، وبقول الله:","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:271","bookId":"risala-shafii","type":"section","seq":271,"chapter":"الجزء الأول","title":"ص: 202","page":"ج1 ص200","text":"\" وأحل لكم ما وراء ذلكم \"، وكان هذا المعنى هو الظاهر من الآية.\nوكان بينا في الآية تحريم الجمع بمعنى غير تحريم الأمهات، فكان ما سمى حلالا حلال، وما سمى حراما حرام، وما نهى عن الجمع بينه من الأختين كما نهى عنه.\nوكان في نهيه عن الجمع بينهما دليل على أنه إنما حرم الجمع، وأن كل واحدة منهما على الانفراد حلال في الأصل،","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:272","bookId":"risala-shafii","type":"section","seq":272,"chapter":"الجزء الأول","title":"ص: 203","page":"ج1 ص200","text":"وما سواهن من الأمهات والبنات والعمات والخالات: محرمات في الأصل.\nوكان معنى قوله: \" وأحل لكم ما وراء ذلكم \"، من سمى تحريمه في الأصل، ومن هو في مثل حاله بالرضاع: أن ينكحوهن بالوجه الذي حل به النكاح.","bab":"باب: الفرائض التي أنزل الله نصا."},{"id":"risala-shafii:273","bookId":"risala-shafii","type":"section","seq":273,"chapter":"الجزء الثاني.","title":"الجزء الثاني.","page":"ج1 ص201","text":"[ ... قال أنا الربيع بن سليمان قال أخبرنا الشافعي قال:]\nبسم الله الرحمن الرحيم.\nفإن قال قائل: ما دل على هذا؟\nفإن النساء المباحات لا يحل أن ينكح منهن أكثر من أربع، ولو نكح خامسة فسخ النكاح، فلا تحل منهن واحدة إلا بنكاح صحيح، وقد كانت الخامسة من الحلال بوجه، وكذلك الواحدة، بمعنى قول الله: \" وأحل لكم ما وراء ذلكم \"، بالوجه الذي أحل به النكاح، وعلى الشرط الذي أحله به، لا مطلقا.\nفيكون نكاح الرجل المرأة لا يحرم عليه نكاح عمتها ولا خالتها بكل حال، كما حرم الله أمهات النساء بكل حال، فتكون العمة والخالة داخلتين في معنى من أحل بالوجه الذي أحلها به."},{"id":"risala-shafii:274","bookId":"risala-shafii","type":"section","seq":274,"chapter":"الجزء الثاني.","title":"ص: 206","page":"ج1 ص203","text":"كما يحل له نكاح امرأة إذا فارق رابعة: كانت العمة إذا فورقت ابنت أخيها، حلت."},{"id":"risala-shafii:275","bookId":"risala-shafii","type":"section","seq":275,"chapter":"الجزء الثاني.","title":"في محرمات الطعام] .","page":"ج1 ص205","text":"وقال الله لنبيه: \" قل: لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير، فإنه رجس أو فسقا أهل لغير الله به (145) \" [الأنعام] .\nفاحتملت الآية معنيين: أحدهما: أن لا يحرم على طاعم أبدا إلا ما استثنى الله.\nوهذا المعنى الذي إذا وجه رجل مخاطبا به كان الذي"},{"id":"risala-shafii:276","bookId":"risala-shafii","type":"section","seq":276,"chapter":"الجزء الثاني.","title":"ص: 207","page":"ج1 ص206","text":"يسبق إليه أنه لا يحرم غير ما سمى الله محرما، وما كان هكذا فهو الذي يقول له: أظهر المعاني وأعمها وأغلبها، والذي لو احتملت الآية معنى سواه كان هو المعنى الذي يلزم أهل العلم القول به، إلا أن تأتي سنة النبي تدل على معنى غيره، مما تحتمله الآية، فيقول: هذا معنى ما أراد الله تبارك وتعالى.\nولا يقال بخاص في كتاب الله ولا سنة إلا بدلالة فيهما أو في واحد منهما. ولا يقال بخاص حتى تكون الآية تحتمل أن يكون أريد بها ذلك الخاص، فأما ما لم تكن محتملة له فلا يقال فيها بما لم تحتمل الآية.\nويحتمل قول الله: \" قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه (145) \" [الأنعام] ، من شيء سئل عنه رسول الله دون غيره."},{"id":"risala-shafii:277","bookId":"risala-shafii","type":"section","seq":277,"chapter":"الجزء الثاني.","title":"ص: 208","page":"ج1 ص206","text":"ويحتمل: مما كنتم تأكلون. وهذا أولى معانيه، استدلالا بالسنة عليه، دون غيره.\nأخبرنا \"سفيان\" عن \"ابن شهاب\" عن \"أبي إدريس الخولاني\" عن \"أبي ثعلبة\": \" أن النبي نهى عن كل ذي ناب من السباع \" (1) .\nأخبرنا \"مالك\" عن \"إسماعيل بن أبي حكيم\" عن عبيدة بن سفيان الحضرمي\" عن \"أبي هريرة\"، عن النبي قال: \" أكل كل ذي ناب من السباع حرام \" (2) ."},{"id":"risala-shafii:278","bookId":"risala-shafii","type":"section","seq":278,"chapter":"الجزء الثاني.","title":"فيما تمسك عنه المعتدة من الوفاة] .","page":"ج1 ص206","text":"قال الله: \" والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا فإذا بلغن أجلهن فلا جناح عليكم فيما فعلن في أنفسهن بالمعروف، والله بما تعملون خبير (234) \" [البقرة] .\nفذكر الله أن على المتوفى عنهن عدة، وأنهن إذا بلغنها فلهن أن يفعلن في أنفسهن بالمعروف، ولم يذكر شيئا تجتنبه في العدة.\nقال: فكان ظاهر الآية أن تمسك المعتدة في العدة عن الأزواج فقط، مع إقامتها في بيتها -: بالكتاب.\nوكانت تحتمل أن تمسك عن الأزواج، وأن يكون عليها في الإمساك عن الأزواج إمساك عن غيره، مما كان مباحا لها قبل العدة من طيب وزينة."},{"id":"risala-shafii:279","bookId":"risala-shafii","type":"section","seq":279,"chapter":"الجزء الثاني.","title":"ص: 210","page":"ج1 ص209","text":"فلما سن رسول الله على المعتدة من الوفاة الإمساك عن الطيب وغيره، كان عليها الإمساك عن الطيب وغيره بفرض السنة، والإمساك عن الأزواج والسكنى في بيت زوجها بالكتاب ثم السنة.\nواحتملت السنة في هذا الموضع ما احتملت في غيره: من أن تكون السنة بينت عن الله كيف إمساكها، كما بينت الصلاة والزكاة والحج، واحتملت أن يكون رسول الله سن فيما ليس فيه نص حكم لله."},{"id":"risala-shafii:280","bookId":"risala-shafii","type":"section","seq":280,"chapter":"الجزء الثاني.","title":"باب العلل في الحديث.","page":"ج1 ص209","text":"قال \"الشافعي\": قال لي قائل: فإنا نجد من الأحاديث عن رسول الله أحاديث في القرآن مثلها نصا، وأخرى في القرآن مثلها","bab":"باب العلل في الحديث."},{"id":"risala-shafii:281","bookId":"risala-shafii","type":"section","seq":281,"chapter":"الجزء الثاني.","title":"ص: 211","page":"ج1 ص210","text":"جملة، وفي الأحاديث منها أكثر مما في القرآن، وأخرى ليس منها شيء في القرآن، وأخرى موتفقة، وأخرى مختلفة: ناسخة ومنسوخة، وأخرى مختلفة: ليس فيها دلالة على ناسخ ولا منسوخ، وأخرى فيها نهي لرسول الله، فتقولون: ما نهى عنه حرام، وأخرى لرسول الله فيها نهي، فتقولون: نهيه وأمره على الاختيار لا على التحريم، ثم نجدكم تذهبون إلى بعض المختلفة من","bab":"باب العلل في الحديث."},{"id":"risala-shafii:282","bookId":"risala-shafii","type":"section","seq":282,"chapter":"الجزء الثاني.","title":"ص: 212","page":"ج1 ص210","text":"الأحاديث دون بعض، ونجدكم تقيسون على بعض حديثه، ثم يختلف قياسكم عليها، وتتركون بعضا فلا تقيسون عليه، فما حجتكم في القياس وتركه؟ ثم تفترقون بعد: فمنكم من يترك من حديثه الشيء ويأخذ بمثل الذي ترك وأضعف إسنادا منه.\nقال \"الشافعي\": فقلت له: كل ما سن رسول الله مع كتاب الله من سنة فهي موافقة كتاب الله في النص بمثله، وفي الجملة بالتبيين عن الله، والتبيين يكون أكثر تفسيرا من الجملة.\nوما سن مما ليس فيه نص كتاب الله فبفرض الله طاعته عامة في أمره تبعناه.\nوأما الناسخة والمنسوخة من حديثه فهي كما نسخ الله الحكم في كتابه بالحكم غيره من كتابه عامة في أمره، وكذلك سنة رسول الله تنسخ بسنته.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:283","bookId":"risala-shafii","type":"section","seq":283,"chapter":"الجزء الثاني.","title":"ص: 213","page":"ج1 ص210","text":"وذكرت له بعض ما كتبت في كتابي قبل هذا من إيضاح ما وصفت.\nفأما المختلفة التي لا دلالة على أيها ناسخ ولا أيها منسوخ، فكل أمره موتفق صحيح، لا اختلاف فيه.\nورسول الله عربي اللسان والدار، فقد يقول القول عاما يريد به العام، وعاما يريد به الخاص، كما وصفت لك في كتاب الله وسنن رسول الله قبل هذا.\nويسئل عن الشيء فيجيب على قدر المسألة، ويؤدي عنه المخبر عنه الخبر متقصى، والخبر مختصرا، والخبر فيأتي ببعض معناه دون بعض.\nويحدث عنه الرجل الحديث قد أدرك جوابه ولم يدرك المسألة فيدله على حقيقة الجواب، بمعرفته السبب الذي يخرج عليه الجواب.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:284","bookId":"risala-shafii","type":"section","seq":284,"chapter":"الجزء الثاني.","title":"ص: 214","page":"ج1 ص210","text":"ويسن في الشيء سنة وفيما يخالفه أخرى، فلا يخلص بعض السامعين بين اختلاف الحالين اللتين سن فيهما.\nويسن سنة في نص معناه، فيحفظها حافظ، ويسن في معنى يخالفه في معنى ويجامعه في معنى، سنة غيرها، لاختلاف الحالين، فيحفظ غيره تلك السنة، فإذا أدى كل ما حفظ رآه بعض السامعين اختلافا، وليس منه شيء مختلف.\nويسن بلفظ مخرجه عام جملة بتحريم شيء أو بتحليله، ويسن في غيره خلاف الجملة، فيستدل على أنه لم يرد بما حرم ما أحل، ولا بما أحل ما حرم.\nولكل هذا نظير فيما كتبنا من جمل أحكام الله.\nويسن السنة ثم ينسخها بسنته، ولم يدع أن يبين","bab":"باب العلل في الحديث."},{"id":"risala-shafii:285","bookId":"risala-shafii","type":"section","seq":285,"chapter":"الجزء الثاني.","title":"ص: 215","page":"ج1 ص210","text":"كلما نسخ من سنته بسنته، ولكن ربما ذهب على الذي سمع من رسول الله بعض علم الناسخ أو علم المنسوخ، فحفظ أحدهما دون الذي سمع من رسول الله الآخر، وليس يذهب ذلك على عامتهم، حتى لا يكون فيهم موجودا إذا طلب.\nوكل ما كان كما وصفت أمضي على ما سنه، وفرق بين ما فرق بينه منه.\nوكانت طاعته في تشعيبه على ما سنه واجبة، ولم يقل: ما فرق بين كذا كذا؟\nلأن قول: ما فرق بين كذا كذا؟ فيما فرق بينه رسول الله، لا يعدو أن يكون جهلا ممن قاله، أو ارتيابا شرا من الجهل، وليس فيه طاعة الله باتباعه.\nوما لم يوجد فيه إلا الاختلاف: فلا يعدو أن يكون لم يحفظ متقصى، كما وصفت قبل هذا، فيعد مختلفا، ويغيب عنا من سبب تبيينه ما علمنا في غيره، أو وهما من محدث.\nولم نجد عنه شيئا مختلفا فكشفناه: إلا وجدنا له وجها يحتمل به ألا يكون مختلفا، وأن يكون داخلا في الوجوه التي وصفت لك.\nأو نجد الدلالة على الثابت منه دون غيره، بثبوت الحديث، فلا يكون الحديثان اللذان نسبا إلى الاختلاف متكافيين، فنصير إلى الأثبت من الحديثين.\nأو يكون على الأثبت منهما دلالة من كتاب الله أو سنة نبيه أو الشواهد التي وصفنا قبل هذا، فنصير إلى الذي هو أقوى وأولى أن يثبت بالدلايل.\nولم نجد عنه حديثين مختلفين إلا ولهما مخرج أو على أحدهما دلالة بأحد ما وصفت: إما بموافقة كتاب","bab":"باب العلل في الحديث."},{"id":"risala-shafii:286","bookId":"risala-shafii","type":"section","seq":286,"chapter":"الجزء الثاني.","title":"ص: 217","page":"ج1 ص213","text":"أو غيره من سنته أو بعض الدلايل.\nوما نهى عنه رسول الله فهو على التحريم، حتى تأتي دلالة عنه على أنه أراد به غير التحريم.\nقال: وأما القياس على سنن رسول الله فأصله وجهان، ثم يتفرع في أحدهما وجوه.\nقال: وما هما؟\nقلت: إن الله تعبد خلقه في كتابه وعلى لسان نبيه بما سبق في قضائه أن يتعبدهم به، ولما شاء، لا معقب لحكمه فيما تعبدهم به، مما دلهم رسول الله على المعنى الذي له تعبدهم به، أو وجدوه في الخبر عنه لم ينزل في شيء في مثل المعنى الذي له تعبد خلقه،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:287","bookId":"risala-shafii","type":"section","seq":287,"chapter":"الجزء الثاني.","title":"ص: 218","page":"ج1 ص216","text":"ووجب على أهل العلم أن يسلكوه سبيل السنة، إذا كان في معناها، وهذا الذي يتفرع تفرعا كثيرا.\nوالوجه الثاني: أن يكون أحل لهم شيئا جملة، وحرم منه شيئا بعينه، فيحلون الحلال بالجملة، ويحرمون الشيء بعينه، ولا يقيسون عليه: على الأقل الحرام، لأن الأكثر منه حلال، والقياس على الأكثر أولى أن يقاس عليه من الأقل.\nوكذلك إن حرم جملة وأحل بعضها، وكذلك إن فرض شيئا وخص رسول الله التخفيف في بعضه.\nوأما القياس فإنما أخذناه استدلالا بالكتاب والسنة والآثار.\nوأما أن نخالف حديثا عن رسول الله ثابتا عنه: فأرجو أن لا يؤخذ ذلك علينا إن شاء الله.\nوليس ذلك لأحد، ولكن قد يجهل الرجل السنة فيكون له قول يخالفها، لا أنه عمد خلافها، وقد يغفل المرء ويخطئ في التأويل.\nقال: فقال لي قائل: فمثل لي كل صنف مما وصفت مثالا، تجمع لي فيه الإتيان على ما سألت عنه، بأمر لا تكثر علي فأنساه، وابدأ بالناسخ والمنسوخ من سنن النبي، واذكر منها","bab":"باب العلل في الحديث."},{"id":"risala-shafii:288","bookId":"risala-shafii","type":"section","seq":288,"chapter":"الجزء الثاني.","title":"ص: 220","page":"ج1 ص219","text":"شيئا مما معه القرآن، وإن كررت بعض ما ذكرت.\nفقلت له: كان أول ما فرض الله على رسوله في القبلة أن يستقبل بيت المقدس للصلاة، فكان بيت المقدس القبلة التي لا يحل لأحد أن يصلي إلا إليها. في الوقت الذي استقبلها فيه رسول الله، فلما نسخ الله قبلة بيت المقدس ووجه رسوله والناس إلى الكعبة: كانت الكعبة القبلة التي لا يحل لمسلم أن يستقبل المكتوبة في غير حال من الخوف، غيرها، ولا يحل أن يستقبل بيت المقدس أبدا.\nوكل كان حقا في وقته، بيت المقدس من حين استقبله النبي إلى أن حول عنه: الحق في القبلة، ثم البيت الحرام - الحق في القبلة إلى يوم القيامة.\nوهكذا كل منسوخ في كتاب الله وسنة نبيه.\nقال: وهذا - مع إبانته لك الناسخ والمنسوخ من الكتاب والسنة -: دليل لك على أن النبي إذا سن سنة حوله الله","bab":"باب العلل في الحديث."},{"id":"risala-shafii:289","bookId":"risala-shafii","type":"section","seq":289,"chapter":"الجزء الثاني.","title":"ص: 221","page":"ج1 ص219","text":"عنها إلى غيرها، سن أخرى يصير إليها الناس بعد التي حول عنها، لئلا يذهب على عامتهم الناسخ فيثبتون على المنسوخ.\nولئلا يشبه على أحد بأن رسول الله يسن فيكون في الكتاب شيء يرى من جهل اللسان أو العلم بموقع السنة مع الكتاب أو إبانتها معانيه: أن الكتاب ينسخ السنة.\nفقال: أفيمكن أن تخالف السنة في هذا الكتاب؟\nقلت: لا، وذلك: لأن الله - جل ثناؤه - أقام على خلقه الحجة من وجهين، أصلهما في الكتاب: كتابه، ثم سنة نبيه، بفرضه في كتابه اتباعها.\nفلا يجوز أن يسن رسول الله سنة لازمة فتنسخ فلا يسن ما نسخها، وإنما يعرف الناسخ بالآخر من الأمرين،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:290","bookId":"risala-shafii","type":"section","seq":290,"chapter":"الجزء الثاني.","title":"ص: 222","page":"ج1 ص219","text":"وأكثر الناسخ في كتاب الله إنما عرف بدلالة سنن رسول الله.\nفإذا كانت السنة تدل على ناسخ القرآن، وتفرق بينه وبين منسوخه: لم يكن أن تنسخ السنة بقرآن إلا أحدث رسول الله مع القرآن سنة تنسخ سنته الأولى، لتذهب الشبهة عن من أقام الله عليه الحجة من خلقه.\nقال: أفرأيت لو قال قائل: حيث وجدت القرآن ظاهرا عاما، ووجدت سنة تحتمل أن تبين عن القرآن، وتحتمل أن تكون بخلاف ظاهره، علمت أن السنة منسوخة بالقرآن؟\nفقلت له: لا يقول هذا عالم.\nقال: ولم؟\nقلت: إذا كان الله فرض على نبيه اتباع ما أنزل إليه، وشهد له بالهدى، وفرض على الناس طاعته، وكان اللسان - كما وصفت قبل هذا - محتملا للمعاني، وأن يكون كتاب الله ينزل عاما يراد به الخاص، وخاصا يراد به العام، وفرضا جملة بينه رسول الله،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:291","bookId":"risala-shafii","type":"section","seq":291,"chapter":"الجزء الثاني.","title":"ص: 223","page":"ج1 ص221","text":"فقامت السنة مع كتاب الله هذا المقام: لم تكن السنة لتخالف كتاب الله، ولا تكون السنة إلا تبعا لكتاب الله، بمثل تنزيله، أو مبينة معنى ما أراد الله، فهي بكل حال متبعة كتاب الله.\nقال: أفتوجدني الحجة بما قلت في القرآن؟\nفذكرت له بعض ما وصفت في كتاب: (السنة مع القرآن) (1) ، من أن الله فرض الصلاة والزكاة والحج، فبين رسول الله كيف الصلاة، وعددها، ومواقيتها، وسننها، وفي كم الزكاة من المال وما يسقط عنه من المال ويثبت عليه، ووقتها، وكيف عمل الحج، وما يجتنب فيه ويباح.\nقال: وذكرت له قول الله: \" والسارق والسارقة فاقطعوا أيديهما (38) \" [المائدة] ، و\" الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة (2) \" [النور] ، وأن رسول الله لما سن القطع على من بلغت سرقته","bab":"باب العلل في الحديث."},{"id":"risala-shafii:292","bookId":"risala-shafii","type":"section","seq":292,"chapter":"الجزء الثاني.","title":"ص: 224","page":"ج1 ص221","text":"ربع دينار فصاعدا، والجلد على الحرين البكرين دون الثيبين الحرين والمملوكين: دلت سنة رسول الله على أن الله أراد بها الخاص من الزناة والسراق، وإن كان مخرج الكلام عاما في الظاهر على السراق والزناة.\nقال: فهذا عندي كما وصفت، أفتجد حجة على من روى أن النبي قال: \" ما جاءكم عني فاعرضوه على كتاب الله، فما وافقه فأنا قلته، وما خالفه فلم أقله \" (2) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:293","bookId":"risala-shafii","type":"section","seq":293,"chapter":"الجزء الثاني.","title":"ص: 225","page":"ج1 ص221","text":"فقلت له: ما روى هذا أحد يثبت حديثه في شيء صغر ولا كبر، فيقال لنا: قد ثبتم حديث من روى هذا في شيء.\nوهذه أيضا رواية منقطعة عن رجل مجهول، ونحن لا نقبل مثل هذه الرواية في شيء.\nقال: فهل عن النبي رواية بما قلتم؟\nفقلت له: نعم.\nأخبرنا \"سفيان\" قال: أخبرني \"سالم أبو النضر\" أنه سمع","bab":"باب العلل في الحديث."},{"id":"risala-shafii:294","bookId":"risala-shafii","type":"section","seq":294,"chapter":"الجزء الثاني.","title":"ص: 226","page":"ج1 ص222","text":"\"عبيد الله بن أبي رافع\" يحدث عن أبيه: أن النبي قال: \" لاألفين أحدكم متكئا على أريكته يأتيه الأمر من أمري مما أمرت به أو نهيت عنه، فيقول: لا أدري، ما وجدنا في كتاب الله اتبعناه \" (1) .\nقال \"الشافعي\": فقد ضيق رسول الله على الناس أن يردوا أمره، بفرض الله عليهم اتباع أمره.\nقال: فأبن لي جملا أجمع لك أهل العلم، أو أكثرهم عليه من سنة مع كتاب الله، يحتمل أن تكون السنة مع الكتاب دليلا على أن الكتاب خاص وإن كان ظاهره عاما.\nفقلت له: نعم، ما سمعتني حكيت في كتابي.\nقال: فأعد منه شيئا.\nقلت: قال الله: \" حرمت عليكم أمهاتكم","bab":"باب العلل في الحديث."},{"id":"risala-shafii:295","bookId":"risala-shafii","type":"section","seq":295,"chapter":"الجزء الثاني.","title":"ص: 227","page":"ج1 ص225","text":"وبناتكم وأخواتكم وعماتكم وخالاتكم وبنات الأخ وبنات الأخت وأمهاتكم اللاتي أرضعنكم وأخواتكم من الرضاعة وأمهات نسائكم وربائبكم اللاتي في حجوركم من نسائكم اللاتي دخلتم بهن، فإن لم تكونوا دخلتم بهن فلا جناح عليكم، وحلائل أبنائكم الذين من أصلابكم وأن تجمعوا بين الأختين إلا ما قد سلف إن الله كان غفورا رحيما (23) والمحصنات من النساء إلا ما ملكت أيمانكم، كتاب الله عليكم، وأحل لكم ما وراء ذلكم (24) \" [النساء] .\nقال: وذكر الله من حرم، ثم قال: \" وأحل لكم ما وراء ذلكم \"، فقال رسول الله: \" لا يجمع بين المرأة وعمتها، ولا بين المرأة وخالتها \" (1) ، فلم أعلم مخالفا في اتباعه.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:296","bookId":"risala-shafii","type":"section","seq":296,"chapter":"الجزء الثاني.","title":"ص: 228","page":"ج1 ص225","text":"فكانت فيه دلالتان: دلالة على أن سنة رسول الله لا تكون مخالفة لكتاب الله بحال، ولكنها مبينة عامه وخاصه.\nودلالة على أنهم قبلوا فيه خبر الواحد، فلا نعلم أحدا رواه من وجه يصح عن النبي إلا \"أبا هريرة\".\nقال: أفيحتمل أن يكون هذا الحديث عندك خلافا لشيء من ظاهر الكتاب؟\nفقلت: لا، ولا غيره.\nقال: فما معنى قول الله: \" حرمت عليكم أمهاتكم \"، فقد ذكر التحريم وقال: \" وأحل لكم ما وراء ذلكم \"؟","bab":"باب العلل في الحديث."},{"id":"risala-shafii:297","bookId":"risala-shafii","type":"section","seq":297,"chapter":"الجزء الثاني.","title":"ص: 229","page":"ج1 ص226","text":"قلت: ذكر تحريم من هو حرام بكل حال، مثل: الأم والبنت والأخت والعمة وبنات الأخ وبنات الأخت، وذكر من حرم بكل حال من النسب والرضاع، وذكر من حرم من الجمع بينه وكان أصل كل واحد منهما مباحا على الانفراد، قال: \" وأحل لكم ما وراء ذلكم \"، يعني: بالحال التي أحلها به.\nألا ترى أن قوله: \" وأحل لكم ما وراء ذلكم \" بمعنى: ما أحل به، لا أن واحدة من النساء حلال بغير نكاح يصح، ولا أنه يجوز نكاح خامسة على أربع، ولا جمع بين أختين، ولا غير ذلك مما نهى عنه.\nفذكرت له فرض الله في الوضوء، ومسح النبي على الخفين، وما صار إليه أكثر أهل العلم من قبول المسح.\nفقال: أفيخالف المسح شيئا من القرآن؟\nقلت: لا تخالفه سنة بحال.\nقال: فما وجهه؟\nقلت: لما قال: \" إذا قمتم إلى الصلاة فاغسلوا وجوهكم وأيديكم إلى المرافق وامسحوا برءوسكم وأرجلكم إلى الكعبين (6) \" [المائدة] ، دلت السنة على أن من كان على طهارة ما لم يحدث فقام إلى الصلاة لم يكن عليه هذا الفرض، فكذلك دلت على أن فرض غسل القدمين إنما هو على المتوضئ لا خفي عليه لبسهما كامل الطهارة.\nوذكرت له تحريم النبي كل ذي ناب من السباع، وقد قال الله: \" قل لا أجد في ما أوحي إلي محرما على طاعم يطعمه إلا أن يكون ميتة أو دما مسفوحا أو لحم خنزير فإنه رجس، أو فسقا أهل لغير الله به، فمن اضطر غير باغ ولا عاد فإن ربك غفور رحيم (145) \" [الأنعام] ، ثم سمى ما حرم.\nفقال: فما معنى هذا؟\nقلنا: معناه: قل لا أجد فيما يوحى إلي محرما مما كنتم تأكلون إلا أن يكون ميتة وما ذكر بعدها، فأما ما تركتم أنكم لم تعدوه من الطيبات فلم يحرم عليكم مما كنتم تستحلون إلا ما سمى الله، ودلت السنة على أنه حرم عليكم منه ما كنتم تحرمون، لقول الله: \" ويحل لهم الطيبات ويحرم عليهم الخبائث (157) \" [الأعراف] .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:298","bookId":"risala-shafii","type":"section","seq":298,"chapter":"الجزء الثاني.","title":"ص: 232","page":"ج1 ص230","text":"قال: وذكرت له قول الله: \" وأحل الله البيع وحرم الربا (275) \" [البقرة] ، وقوله: \" لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم (29) \" [النساء] ، ثم حرم رسول الله بيوعا، منها الدنانير بالدراهم إلى أجل، وغيرها: فحرمها المسلمون بتحريم رسول الله، فليس هذا ولا غيره خلافا لكتاب الله.\nقال: فحد لي معنى هذا بأجمع منه وأخصر.\nفقلت له: لما كان في كتاب الله دلالة على أن الله قد وضع رسوله موضع الإبانة عنه، وفرض على خلقه اتباع أمره، فقال: \" وأحل الله البيع وحرم الربا (275) \" [البقرة] ، فإنما يعني: أحل الله البيع إذا كان على غير ما نهى الله عنه في كتابه أو على لسان نبيه، وكذلك قوله: \" وأحل لكم ما وراء ذلكم (24) [النساء] ، بما أحله الله به","bab":"باب العلل في الحديث."},{"id":"risala-shafii:299","bookId":"risala-shafii","type":"section","seq":299,"chapter":"الجزء الثاني.","title":"ص: 233","page":"ج1 ص230","text":"من النكاح وملك اليمين في كتابه، لا أنه أباحه بكل وجه، وهذا كلام عربي.\nوقلت له: لو جاز أن تترك سنة مما ذهب إليه من جهل مكان السنن من الكتاب، ترك ما وصفنا من المسح على الخفين، وإباحة كل ما لزمه اسم بيع، وإحلال أن يجمع بين المرأة وعمتها وخالتها، وإباحة كل ذي ناب من السباع، وغير ذلك.\nولجاز أن يقال: سن النبي ألا يقطع من لم تبلغ سرقته ربع دينار قبل التنزيل، ثم نزل عليه: \" والسارق والسارقة فاقطعوا أيديهما (38) \" [المائدة] ، فمن لزمه اسم سرقة قطع.\nولجاز أن يقال: إنما سن النبي الرجم على الثيب حتى نزلت عليه: \" الزانية والزاني فاجلدوا كل واحد منهما مائة","bab":"باب العلل في الحديث."},{"id":"risala-shafii:300","bookId":"risala-shafii","type":"section","seq":300,"chapter":"الجزء الثاني.","title":"ص: 234","page":"ج1 ص230","text":"جلدة (2) \" [النور] ، فيجلد البكر والثيب، ولا نرجمه.\nوأن يقال في البيوع التي حرم رسول الله: إنما حرمها قبل التنزيل، فلما أنزلت: \" وأحل الله البيع وحرم الربا (275) [البقرة] ، كانت حلالا.\nوالربا: أن يكون للرجل على الرجل الدين فيحل فيقول: أتقضي أم تربي؟ فيؤخر عنه ويزيده في ماله. وأشباه لهذا كثيرة.\nفمن قال هذا كان معطلا لعامة سنن رسول الله، وهذا القول جهل ممن قاله.\nقال: أجل.\nوسنة رسول الله كما وصفت، ومن خالف ما قلت فيها فقد جمع الجهل بالسنة والخطأ في الكلام فيما يجهل.\nقال: فاذكر سنة نسخت بسنة سوى هذا.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:301","bookId":"risala-shafii","type":"section","seq":301,"chapter":"الجزء الثاني.","title":"ص: 235","page":"ج1 ص231","text":"فقلت له: السنن الناسخة والمنسوخة مفرقة في مواضعها، وإن رددت طالت.\nقال: فيكفي منها بعضها، فاذكره مختصرا بينا.\nفقلت: أخبرنا \"مالك\" عن \" عبد الله بن أبي بكر بن محمد بن عمرو بن حزم\" عن \"عبد الله بن واقد\" عن \"عبد الله بن عمر\"، قال: \" نهى رسول الله عن أكل لحوم الضحايا بعد ثلاث \"، قال \"عبد الله بن أبي بكر\": فذكرت ذلك \"لعمرة\"، فقالت: صدق، سمعت \"عائشة\" تقول: \" دف (1) ناس من أهل البادية حضرة الأضحى في زمان النبي، فقال النبي: ادخروا لثلاث وتصدقوا بما بقي. قالت: فلما كان بعد ذلك قيل: يا رسول الله، لقد كان الناس ينتفعون بضحاياهم، يجملون","bab":"باب العلل في الحديث."},{"id":"risala-shafii:302","bookId":"risala-shafii","type":"section","seq":302,"chapter":"الجزء الثاني.","title":"ص: 236","page":"ج1 ص231","text":"منها الودك (2) ويتخذون الأسقية، فقال رسول الله: وما ذاك، - أو كما قال -، قالوا: يا رسول الله، نهيت عن إمساك لحوم الضحايا بعد ثلاث، فقال رسول الله: إنما نهيتكم من أجل الدافة التي دفت حضرة الأضحى، فكلوا وتصدقوا وادخروا \" (3) .\nوأخبرنا \"ابن عيينة\" عن \"الزهري\" عن \"أبي عبيد\" مولى \"ابن أزهر\"، قال: شهدت العيد مع \"علي بن أبي طالب\" فسمعته يقول: لا يأكلن أحدكم من لحم نسكه بعد ثلاث.\nأخبرنا الثقة عن \"معمر\" عن \"الزهري\" عن \"أبي عبيد\"","bab":"باب العلل في الحديث."},{"id":"risala-shafii:303","bookId":"risala-shafii","type":"section","seq":303,"chapter":"الجزء الثاني.","title":"ص: 237","page":"ج1 ص231","text":"عن \"علي\" أنه قال: قال رسول الله: \" لا يأكلن أحدكم من لحم نسكه بعد ثلاث \" (4) .\nأخبرنا \"ابن عيينة\" عن \"إبراهيم بن ميسرة\" قال: سمعت \"أنس بن مالك\" يقول: إنا لنذبح ما شاء الله من ضحايانا، ثم نتزود بقيتها إلى البصرة.\nقال \"الشافعي\": فهذه الأحاديث تجمع معاني، منها:","bab":"باب العلل في الحديث."},{"id":"risala-shafii:304","bookId":"risala-shafii","type":"section","seq":304,"chapter":"الجزء الثاني.","title":"ص: 238","page":"ج1 ص231","text":"أن حديث \"علي\" عن النبي في النهي عن إمساك لحوم الضحايا بعد ثلاث، وحديث \"عبد الله بن واقد\"، موتفقان عن النبي.\nوفيها دلالة على أن \"عليا\" سمع النهي من النبي، وأن النهي بلغ \"عبد الله بن واقد\".\nودلالة على أن الرخصة من النبي لم تبلغ \"عليا\" ولا \"عبد الله بن واقد\"، ولو بلغتهما الرخصة، ما حدثا بالنهي، والنهي منسوخ، وتركا الرخصة، والرخصة ناسخة، والنهي منسوخ لا يستغني سامعه عن علم ما نسخه.\nوقول \"أنس بن مالك\": كنا نهبط بلحوم الضحايا البصرة، يحتمل أن يكون \"أنس\" سمع الرخصة ولم يسمع النهي قبلها، فتزود بالرخصة ولم يسمع نهيا أو سمع الرخصة والنهي، فكان النهي منسوخا، فلم يذكره.\nفقال كل واحد من المختلفين بما علم.\nوهكذا يجب على من سمع شيئا من رسول الله، أو ثبت له عنه: أن يقول بما سمع، حتى يعلم غيره.\nقال \"الشافعي\": فلما حدثت عائشة عن النبي بالنهي عن إمساك لحوم الضحايا بعد ثلاث، ثم بالرخصة فيها بعد النهي، وأن رسول الله أخبر أنه نهى عن إمساك لحوم الضحايا بعد ثلاث للدافة: كان الحديث التام المحفوظ أوله وآخره وسبب التحريم والإحلال فيه: حديث عائشة عن النبي، وكان على من علمه أن يصير إليه.\nوحديث عائشة من أبين ما يوجد في الناسخ والمنسوخ من السنن.\nوهذا يدل على أن بعض الحديث يخص، فيحفظ بعضه دون بعض، فيحفظ منه شيء كان أولا ولا يحفظ آخرا، ويحفظ أخرا ولا يحفظ أولا، فيؤدي كل ما حفظ.\nفالرخصة بعدها في الإمساك والأكل والصدقة من لحوم الضحايا إنما هي لواحد من معنيين، لاختلاف الحالين:\nفإذا دفت الدافة ثبت النهي عن إمساك لحوم الضحايا بعد ثلاث، وإذا لم تدف دافة فالرخصة ثابتة بالأكل والتزود والادخار والصدقة.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:305","bookId":"risala-shafii","type":"section","seq":305,"chapter":"الجزء الثاني.","title":"ص: 240","page":"ج1 ص234","text":"ويحتمل أن يكون النهي عن إمساك لحوم الضحايا بعد ثلاث منسوخا في كل حال، فيمسك الإنسان من ضحيته ما شاء، ويتصدق بما شاء.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:306","bookId":"risala-shafii","type":"section","seq":306,"chapter":"الجزء الثاني.","title":"وجه آخر","page":"ج1 ص239","text":"من الناسخ والمنسوخ.\nأخبرنا \"محمد بن إسماعيل بن أبي فديك\" عن \"ابن أبي ذئب\" عن \"المقبري\" عن \"عبد الرحمن بن أبي سعيد\" عن \"أبي سعيد","bab":"باب العلل في الحديث."},{"id":"risala-shafii:307","bookId":"risala-shafii","type":"section","seq":307,"chapter":"الجزء الثاني.","title":"ص: 243","page":"ج1 ص242","text":"الخدري\"، قال: \" حبسنا يوم الخندق عن الصلاة، حتى كان بعد المغرب بهوى من الليل، حتى كفينا، وذلك قول الله: \" وكفى الله المؤمنين القتال وكان الله قويا عزيزا (25) \" [الأحزاب] ، قال: فدعا رسول الله بلالا، فأمره فأقام الظهر، فصلاها فأحسن صلاتها كما كان يصليها في وقتها، ثم أقام العصر فصلاها كذلك، ثم أقام المغرب فصلاها كذلك، ثم أقام العشاء، فصلاها كذلك أيضا، قال: وذلك قبل أن أنزل الله في صلاة الخوف: \" فرجالا أو ركبانا (239) \" [البقرة] \" (1) .\n\"الشافعي\": فلما حكى \"أبو سعيد\" أن صلاة النبي عام الخندق كانت قبل أن ينزل في صلاة الخوف: \" فرجالا أو ركبانا (239) \" [البقرة] ، استدللنا على أنه لم يصل صلاة الخوف إلا بعدها، إذ حضرها \"أبو سعيد\"، وحكى تأخير الصلوات حتى خرج من وقت عامتها، وحكى أن ذلك قبل نزول صلاة الخوف.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:308","bookId":"risala-shafii","type":"section","seq":308,"chapter":"الجزء الثاني.","title":"ص: 244","page":"ج1 ص242","text":"قال: فلا تؤخر صلاة الخوف بحال أبدا عن الوقت إن كانت في حضر، أو عن وقت الجمع في السفر، بخوف ولا غيره، ولكن تصلى كما صلى رسول الله.\nوالذي أخذنا به في صلاة الخوف أن \"مالكا\" أخبرنا عن \"يزيد بن رومان\" عن \"صالح بن خوات\" عن من صلى مع رسول الله صلاة الخوف يوم ذات الرقاع: \" أن طائفة صفت معه، وطائفة وجاه العدو، فصلى بالذين معه ركعة، ثم ثبت قائما وأتموا لأنفسهم، ثم انصرفوا، فصفوا وجاه العدو، وجاءت الطائفة الأخرى فصلى بهم الركعة التي بقيت من صلاته، ثم ثبت جالسا وأتموا لأنفسهم، ثم سلم بهم \" (2) .\nقال: أخبرنا من سمع عبد الله بن عمر بن حفص\" يخبر عن أخيه \"عبيد الله بن عمر\" عن \"القاسم بن محمد\" عن \"صالح بن خوات بن جبير\" عن أبيه عن النبي مثله.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:309","bookId":"risala-shafii","type":"section","seq":309,"chapter":"الجزء الثاني.","title":"ص: 245","page":"ج1 ص242","text":"قال: وقد روى أن النبي صلى صلاة الخوف على غير ما حكى \"مالك\".\nوإنما أخذنا بهذا دونه لأنه كان أشبه بالقرآن، وأقوى في مكايدة العدو.\nوقد كتبنا هذا بالاختلاف فيه، وتبين الحجة في {كتاب الصلاة} ، وتركنا ذكر من خالفنا فيه وفي غيره من الأحاديث، لأن ما خولفنا فيه منها مفترق في كتبه.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:310","bookId":"risala-shafii","type":"section","seq":310,"chapter":"الجزء الثاني.","title":"وجه آخر.","page":"ج1 ص242","text":"قال الله - تبارك وتعالى: \" واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل الله لهن سبيلا (15) واللذان يأتيانها منكم فآذوهما فإن تابا وأصلحا فأعرضوا عنهما (16) \" [النساء] .\nفكان حد الزانيين بهذه الآية الحبس والأذى، حتى أنزل الله على رسوله حد الزنا، فقال: \" الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة (2) \" [النور] ، وقال في الإماء: \" فإذا أحصن فإن أتين بفاحشة فعليهن نصف ما على المحصنات من العذاب (25) \" [النساء] ، فنسخ الحبس عن الزناة، وثبت عليهم الحدود.\nودل قول الله في الإماء: \" فعليهن نصف ما على المحصنات من العذاب (25) \" [النساء] : على فرق الله بين حد المماليك والأحرار في الزنا، وعلى أن النصف لا يكون إلا من جلد، لأن الجلد بعدد، ولا يكون من رجم، لأن الرجم إتيان على النفس بلا عدد، لأنه قد يؤتى عليها برجمة واحدة، وبألف وأكثر، فلا نصف","bab":"باب العلل في الحديث."},{"id":"risala-shafii:311","bookId":"risala-shafii","type":"section","seq":311,"chapter":"الجزء الثاني.","title":"ص: 247","page":"ج1 ص245","text":"لما لا يعلم بعدد، ولا نصف للنفس فيؤتى بالرجم على نصف النفس.\nواحتمل قول الله في سورة النور: \" الزانية والزاني فاجلدوا كل واحد منهما مائة جلدة (2) \"، أن يكون على جميع الزناة الأحرار، وعلى بعضهم دون بعض، فاستدللنا بسنة رسول الله - بأبي هو وأمي - على من أريد بالمائة جلدة.\nأخبرنا \"عبد الوهاب\" عن \"يونس بن عبيد\" عن \" الحسن\" عن \"عبادة بن الصامت\" أن رسول الله قال: \" خذوا عني، خذوا عني، قد جعل الله لهن سبيلا: البكر بالبكر جلد مائة وتغريب عام، والثيب بالثب جلد مائة والرجم \" (1) .\nقال: فدل قول رسول الله: \" قد جعل الله لهن سبيلا \"، على أن هذا أول ما حد به الزناة، لأن الله يقول: \" حتى يتوفاهن الموت أو يجعل الله لهن سبيلا (15) \" [النساء] .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:312","bookId":"risala-shafii","type":"section","seq":312,"chapter":"الجزء الثاني.","title":"ص: 248","page":"ج1 ص245","text":"ثم رجم رسول الله \"ماعزا\" ولم يجلده، وامرأة \"الأسلمي\" ولم يجلدها، فدلت سنة سول الله على أن الجلد منسوخ عن الزانيين الثيبين.\nقال: ولم يكن بين الأحرار في الزنا فرق إلا بالإحصان بالنكاح وخلاف الإحصان به.\nوإذ كان قول النبي: \" قد جعل الله لهن سبيلا، البكر بالبكر جلد مائة وتغريب عام \"، ففي هذا دلالة على أنه أول ما نسخ الحبس عن الزانيين، وحدا بعد الحبس، وأن كل حد حده الزانيين فلا يكون إلا بعد هذا، إذ كان هذا أول حد الزانيين.\nأخبرنا \"مالك\" عن \"ابن شهاب\" عن \"عبيد الله","bab":"باب العلل في الحديث."},{"id":"risala-shafii:313","bookId":"risala-shafii","type":"section","seq":313,"chapter":"الجزء الثاني.","title":"ص: 249","page":"ج1 ص245","text":"بن عبد الله\" عن \"أبي هريرة\" و\"زيد بن خالد\" أنهما أخبراه: \" أن رجلين اختصما إلى رسول الله، فقال أحدهما: يا رسول الله! اقض بيننا بكتاب الله؟ وقال الآخر - وهو أفقههما -: أجل يا رسول الله، فاقض بيننا بكتاب الله، وائذن لي في أن أتكلم، قال: تكلم، قال: إن ابني كان عسيفا (2) على هذا، فزنى بامرأته، فأخبرت أن على ابني الرجم، (3) فافتديت منه بمائة شاة وجارية لي، ثم إني سألت أهل العلم، فأخبروني أن على ابني جلد مائة وتغريب عام، وإنما الرجم على امرأته؟ فقال رسول الله: والذي نفسي بيده، لأقضين","bab":"باب العلل في الحديث."},{"id":"risala-shafii:314","bookId":"risala-shafii","type":"section","seq":314,"chapter":"الجزء الثاني.","title":"ص: 250","page":"ج1 ص245","text":"بينكما بكتاب الله، أما غنمك وجاريتك فرد إليك. وجلد ابنه مائة وغربه عاما، وأمر \"أنيس (4) الأسلمي\" أن يأتي امرأة الآخر، فإن اعترفت رجمها، فاعترفت فرجمها \" (5) .\nأخبرنا \"مالك\" عن \"نافع\" عن \"ابن عمر\": \" أن النبي رجم يهوديين زنيا \" (6) .\nقال: فثبت جلد مائة والنفي على البكرين الزانيين، والرجم على الثيبين الزانيين.\nوإن كانا ممن أريدا بالجلد فقد نسخ عنهما الجلد مع الرجم، وإن لم يكونا أريدا بالجلد وأريد به البكران: فهما مخالفان للثيبين.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:315","bookId":"risala-shafii","type":"section","seq":315,"chapter":"الجزء الثاني.","title":"ص: 251","page":"ج1 ص245","text":"ورجم الثيبين بعد آية الجلد، بما روى رسول الله عن الله، وهذا أشبه معانيه وأولاها به عندنا، والله أعلم.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:316","bookId":"risala-shafii","type":"section","seq":316,"chapter":"الجزء الثاني.","title":"وجه آخر.","page":"ج1 ص245","text":"أخبرنا \"مالك\" عن \"ابن شهاب\" عن \"أنس بن مالك\": \" أن النبي ركب فرسا، فصرع عنه، فجحش شقه الأيمن (1) ، فصلى صلاة من الصلوات وهو قاعد، وصلينا وراءه قعودا، فلما انصرف قال: إنما جعل الإمام ليؤتم به، فإذا صلى قائما فصلوا قياما، وإذا ركع فاركعوا، وإذا رفع فارفعوا، وإذا قال: سمع الله لمن حمده،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:317","bookId":"risala-shafii","type":"section","seq":317,"chapter":"الجزء الثاني.","title":"ص: 252","page":"ج1 ص251","text":"فقولوا: ربنا ولك الحمد، وإذا صلى جالسا فصلوا جلوسا أجمعون \" (2) .\nأخبرنا \"مالك\" عن \"هشام بن عروة\" عن أبيه، عن \"عائشة\"، أنها قالت: \" صلى رسول الله في بيته، وهو شاك، فصلى جالسا، وصلى وراءه قوم قياما، فأشار إليهم: أن اجلسوا، فلما انصرف قال: إنما جعل الإمام ليؤتم به، فإذا ركع فاركعوا، وإذا رفع فارفعوا، وإذا صلى جالسا فصلوا جلوسا \" (3) .\nقال: وهذا مثل حديث \"أنس\"، وإن كان حديث \"أنس\" مفسرا وأوضح من تفسير هذا.\nأخبرنا \"مالك\" عن \"هشام بن عروة\" عن أبيه: \" أن رسول الله خرج في مرضه، فأتى \"أبا بكر\" وهو قائم يصلي بالناس، فاستأخر \"أبو بكر\"، فأشار إليه رسول الله أن كما أنت،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:318","bookId":"risala-shafii","type":"section","seq":318,"chapter":"الجزء الثاني.","title":"ص: 253","page":"ج1 ص251","text":"فجلس رسول الله إلى جنب \"أبي بكر\"، فكان \"أبو بكر\" يصلي بصلاة رسول الله، وكان الناس يصلون بصلاة \"أبي بكر\" \" (4) .\nوبه يأخذ \"الشافعي\".\nقال: وذكر \"إبراهيم النخعي\" عن \"الأسود بن يزيد\" عن \"عائشة\" عن رسول الله \"وأبي بكر\" مثل معنى حديث عروة: \" أن النبي صلى قاعدا، و\"أبو بكر\" قائما،، يصلي بصلاة النبي، وهم وراءه قياما \" (5) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:319","bookId":"risala-shafii","type":"section","seq":319,"chapter":"الجزء الثاني.","title":"ص: 254","page":"ج1 ص251","text":"قال: فلما كانت صلاة النبي في مرضه الذي مات فيه، قاعدا والناس خلفه قياما، استدللنا على أن أمره الناس بالجلوس في سقطته عن الفرس: قبل مرضه الذي مات فيه، فكانت صلاته في مرضه الذي مات فيه، قاعدا والناس خلفه قياما: ناسخة، لأن يجلس الناس بجلوس الإمام.\nوكان في ذلك دليل بما جاءت به السنة وأجمع عليه","bab":"باب العلل في الحديث."},{"id":"risala-shafii:320","bookId":"risala-shafii","type":"section","seq":320,"chapter":"الجزء الثاني.","title":"ص: 255","page":"ج1 ص251","text":"الناس، من أن الصلاة قائما إذا أطاقها المصلي، وقاعدا إذا لم يطق، وأن ليس للمطيق القيام منفردا أن يصلي قاعدا.\nفكانت سنة النبي أن صلى في مرضه قاعدا ومن خلفه قياما، مع أنها ناسخة لسنته الأولى قبلها: موافقة سنته في الصحيح والمريض، وإجماع الناس أن يصلي كل واحد منهما فرضه، كما يصلي المريض خلف الإمام الصحيح قاعدا والإمام قائما.\nوهكذا نقول: يصلي الإمام جالسا ومن خلفه من الأصحاء قياما، فيصلي كل واحد فرضه، ولو وكل غيره كان حسنا.\nوقد أوهم بعض الناس، فقال: لا يؤمن أحد بعد النبي جالسا، واحتج بحديث رواه منقطع عن رجل مرغوب","bab":"باب العلل في الحديث."},{"id":"risala-shafii:321","bookId":"risala-shafii","type":"section","seq":321,"chapter":"الجزء الثاني.","title":"ص: 256","page":"ج1 ص251","text":"الرواية عنه، لا يثبت بمثله حجة على أحد، فيه: \" لا يؤمن أحد بعدي جالسا \" (1) .\nقال: ولهذا أشباه في السنة من الناسخ والمنسوخ.\nوفي هذا دلالة على ما كان في مثل معناها، إن شاء الله.\nوكذلك له أشباه في كتاب الله، قد وصفنا بعضها","bab":"باب العلل في الحديث."},{"id":"risala-shafii:322","bookId":"risala-shafii","type":"section","seq":322,"chapter":"الجزء الثاني.","title":"ص: 259","page":"ج1 ص255","text":"في كتابنا هذا، وما بقي مفرق في أحكام القرآن والسنة في مواضعه.\nقال: فقال: فاذكر من الأحاديث المختلفة التي لا دلالة فيها على ناسخ ولا منسوخ، والحجة فيما ذهبت إليه منها دون ما تركت.\nفقلت له: قد ذكرت قبل هذا (1) : أن رسول الله صلى صلاة الخوف يوم ذات الرقاع، فصف بطائفة، وطائفة في غير صلاة بإزاء العدو، فصلى بالذين معه ركعة، وأتموا لأنفسهم، ثم انصرفوا فوقفوا بإزاء العدو، وجاءت الطائفة الأخرى فصلى بهم الركعة التي بقيت، ثم ثبت جالسا وأتموا لأنفسهم، ثم سلم بهم.\nقال: وروى \"ابن عمر\" عن النبي: أنه صلى","bab":"باب العلل في الحديث."},{"id":"risala-shafii:323","bookId":"risala-shafii","type":"section","seq":323,"chapter":"الجزء الثاني.","title":"ص: 260","page":"ج1 ص258","text":"صلاة الخوف خلاف هذه الصلاة في بعض أمرها، فقال: صلى ركعة بطائفة، وطائفة بينه وبين العدو، ثم انصرفت الطائفة التي وراءه، فكانت بينه وبين العدو، وجاءت الطائفة التي لم تصل معه، فصلى بهم الركعة التي بقيت عليه من صلاته، وسلم، ثم انصرفوا فقضوا معا.\nقال: وروى \"أبو عياش الزرقي\": \" أن النبي صلى يوم عسفان و\"خالد بن الوليد\" بينه وبين القبلة، فصف بالناس معه معا، ثم ركع وركعوا معا، ثم سجد فسجدت معه طائفة،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:324","bookId":"risala-shafii","type":"section","seq":324,"chapter":"الجزء الثاني.","title":"ص: 261","page":"ج1 ص258","text":"وحرسته طائفة، فلما قام من السجود سجد الذين حرسوه، ثم قاموا في صلاته \" (2) .\nوقال \"جابر\" قريبا من هذا المعنى.\nقال: وقد روي ما لا يثبت مثله بخلافها كلها.\nفقال لي قائل: وكف صرت إلى الأخذ بصلاة النبي ذات الرقاع دون غيرها؟\nفقلت: أما حديث \"أبي عياش\" و\"جابر\" في صلاة الخوف فكذلك أقول، وإذا كان مثل السبب الذي صلى له تلك الصلاة.\nقال: وما هي؟\nقلت: كان رسول الله في ألف وأربعمائة، وكان \"خالد بن الوليد\" في مائتين، وكان منه بعيدا في صحراء واسعة، لا يطمع فيه، لقلة من معه، وكثرة من مع رسول الله، وكان الأغلب منه أنه مأمون على أن يحمل عليه، ولو حمل من بين يديه رآه، وقد حرس منه في السجود، إذ كان لا يغيب عن طرفه.\nفإذا كانت الحال بقلة العدو وبعده، وأن لا حائل دونه يستره، كما وصفت: أمرت بصلاة الخوف هكذا.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:325","bookId":"risala-shafii","type":"section","seq":325,"chapter":"الجزء الثاني.","title":"ص: 263","page":"ج1 ص259","text":"قال: فقال: قد عرفت أن الرواية في صلاة ذات الرقاع لا تخالف هذا، لاختلاف الحالين، قال: فكيف خالفت حديث \"ابن عمر\"؟\nفقلت له: رواه عن النبي \"خوات بن جبير\"، وقال \"سهل بن أبي حثمة\" بقريب من معناه، وحفظ عن \"علي بن أبي طالب\" أنه صلى صلاة الخوف ليلة الهرير كما روى \"خوات بن جبير عن النبي، وكان \"خوات\" متقدم الصحبة والسن.\nفقال: فهل من حجة أكثر من تقدم صحبته؟","bab":"باب العلل في الحديث."},{"id":"risala-shafii:326","bookId":"risala-shafii","type":"section","seq":326,"chapter":"الجزء الثاني.","title":"ص: 264","page":"ج1 ص259","text":"فقلت: نعم، ما وصفت: فيه من الشبه بمعنى كتاب الله.\nقال: فأين يوافق كتاب الله؟\nقلت: قال الله: \" وإذا كنت فيهم فأقمت لهم الصلاة فلتقم طائفة منهم معك، وليأخذوا أسلحتهم فإذا سجدوا فليكونوا من ورائكم، ولتأت طائفة أخرى لم يصلوا فليصلوا معك، وليأخذوا حذرهم وأسلحتهم. ود الذين كفروا لو تغفلون عن أسلحتكم وأمتعتكم فيميلون عليكم ميلة واحدة، ولا جناح عليكم إن كان بكم أذى من مطر أو كنتم مرضى أن تضعوا أسلحتكم، وخذوا حذركم (102) \" [النساء] .\nوقال: \" فإذا اطمأننتم فأقيموا الصلاة، إن الصلاة كانت على المؤمنين كتابا موقوتا (103) \" [النساء] ، يعني - والله أعلم -: فأقيموا الصلاة كما كنتم تصلون في غير الخوف.\nفلما فرق الله بين الصلاة في الخوف وفي الأمن، حياطة لأهل دينه أن ينال منهم عدوهم غرة: فتعقبنا حديث \"خوات بن جبير\" والحديث الذي يخالفه، فوجدنا حديث \"خوات بن جبير\"","bab":"باب العلل في الحديث."},{"id":"risala-shafii:327","bookId":"risala-shafii","type":"section","seq":327,"chapter":"الجزء الثاني.","title":"ص: 265","page":"ج1 ص259","text":"أولى بالحزم في الحذر منه، وأحرى أن تتكافأ الطائفتان فيها.\nوذلك أن الطائفة التي تصلي مع الإمام أولا محروسة بطائفة في غير صلاة، والحارس إذا كان في غير صلاة كان متفرغا من فرض الصلاة، قائما وقاعدا، ومنحرفا يمينا وشمالا، وحاملا إن حمل عليه، ومتكلما إن خاف عجلة من عدوه، ومقاتلا إن أمكنته فرصة، غير محول بينه وبين هذا في الصلاة، ويخفف الإمام بمن معه الصلاة إذا خاف حملة العدو، بكلام الحارس.\nقال: وكان الحق للطائفتين معا سواء، فكانت الطائفتان في حديث \"خوات\" سواء، تحرس كل واحدة من الطائفتين الأخرى، والحارسة خارجة من الصلاة، فتكون الطائفة الأولى قد أعطت الطائفة التي حرستها مثل الذي أخذت منها، فحرستها خلية من الصلاة، فكان هذا عدلا بين الطائفتين.\nقال: وكان الحديث الذي يخالف حديث \"خوات بن جبير\"، على خلاف الحذر، تحرس الطائفة الأولى في ركعة، ثم تنصرف المحروسة قبل تكمل (1) الصلاة، فتحرس، ثم تصلي","bab":"باب العلل في الحديث."},{"id":"risala-shafii:328","bookId":"risala-shafii","type":"section","seq":328,"chapter":"الجزء الثاني.","title":"ص: 266","page":"ج1 ص259","text":"الطائفة الثانية محروسة بطائفة في صلاة، ثم يقضيان جميعا، لا حارس لهما، لأنه لم يخرج من الصلاة إلا الإمام، وهو وحده ولا يعني شيئا، فكان هذا خلاف الحذر والقوة في المكيدة.\nوقد أخبرنا الله أنه فرق بين صلاة الخوف وغيرها، نظرا لأهل دينه أن لا ينال منهم عدوهم غرة، ولم تأخذ الطائفة الأولى من الآخرة مثل ما أخذت منها.\nووجدت الله ذكر صلاة الإمام والطائفتين معا، ولم يذكر على الإمام ولا على واحدة من الطائفتين قضاء، فدل ذلك على أن حال الإمام ومن خلفه، في أنهم يخرجون من الصلاة لا قضاء عليهم، سواء.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:329","bookId":"risala-shafii","type":"section","seq":329,"chapter":"الجزء الثاني.","title":"ص: 267","page":"ج1 ص259","text":"وهكذا حديث \"خوات\" وخلاف الحديث الذي يخالفه.\nقال \"الشافعي\": فقال: فهل للحديث الذي تركت وجه غير ما وصفت؟\nقلت: نعم، يحتمل أن يكون لما جاز أن تصلى صلاة الخوف على خلاف الصلاة في غير الخوف: جاز لهم أن يصلوها كيف ما تيسر لهم، وبقدر حالاتهم وحالات العدو، إذا أكملوا العدد، فاختلف صلاتهم، وكلها مجزية عنهم.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:330","bookId":"risala-shafii","type":"section","seq":330,"chapter":"الجزء الثاني.","title":"وجه آخر من الاختلاف","page":"ج1 ص267","text":"قال \"الشافعي\": قال لي قائل: قد اختلف في التشهد، فروى \"ابن مسعود\" عن النبي: \" أنه كان يعلمهم التشهد كما يعلمهم","bab":"باب العلل في الحديث."},{"id":"risala-shafii:331","bookId":"risala-shafii","type":"section","seq":331,"chapter":"الجزء الثاني.","title":"ص: 268","page":"ج1 ص267","text":"السورة من القرآن \"، فقال في مبتداه ثلاث كلمات: \" التحيات لله \"، فبأي التشهد أخذت؟\nفقلت: أخبرنا \"مالك\" عن \"ابن شهاب\" عن \"عروة\" عن \"عبد الرحمن بن عبد القاري\" أنه سمع \"عمر بن الخطاب\" يقول على المنبر، وهو يعلم الناس التشهد، يقول: قولوا: \" التحيات لله، الزاكيات لله، الطيبات الصلوات لله، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله، وأشهد أن محمدا عبده ورسوله \" (1) .\nقال \"الشافعي\": فكان هذا الذي علمنا من سبقنا بالعلم من فقهائنا صغارا، ثم سمعناه بإسناد وسمعنا ما خالفه، فلم نسمع إسنادا في التشهد، يخالفه ولا يوافقه: أثبت عندنا منه، وإن كان غيره ثابتا.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:332","bookId":"risala-shafii","type":"section","seq":332,"chapter":"الجزء الثاني.","title":"ص: 269","page":"ج1 ص267","text":"فكان الذي نذهب إليه: أن \"عمر\" لا يعلم الناس على المنبر بين ظهراني أصحاب رسول الله، إلا على ما علمهم النبي.\nفلما انتهى إلينا من حديث أصحابنا حديث يثبته عن النبي صرنا إليه، وكان أولى بنا.\nقال: وما هو؟\nقلت: أخبرنا الثقة، وهو \"يحي بن حسان\" عن \"الليث بن سعد\" عن \"أبي الزبير المكي\" عن \"سعيد بن جبير\" و\"طاوس\" عن \"ابن عباس\" أنه قال: \" كان رسول الله يعلمنا التشهد كما يعلمنا القرآن، فكان يقول: التحيات المباركات الصلوات الطيبات لله،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:333","bookId":"risala-shafii","type":"section","seq":333,"chapter":"الجزء الثاني.","title":"ص: 270","page":"ج1 ص267","text":"سلام عليك أيها النبي ورحمة الله وبركاته، سلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله، وأن محمدا رسول الله \" (2) .\nقال \"الشافعي\": فقال: فأنى ترى الرواية اختلفت فيه عن النبي؟ فروى \"ابن مسعود\" خلاف هذا، وروى \"أبو موسى\" خلاف هذا، و\"جابر\" خلاف هذا، وكلها قد يخالف بعضها بعضا في شيء من لفظه، ثم علم \"عمر\" خلاف هذا كله في بعض لفظه،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:334","bookId":"risala-shafii","type":"section","seq":334,"chapter":"الجزء الثاني.","title":"ص: 271","page":"ج1 ص267","text":"وكذلك تشهد عائشة، وكذلك تشهد \"ابن عمر\"، ليس فيها شيء إلا في لفظه شيء غير ما في لفظ صاحبه، وقد يزيد بعضها الشيء على بعض.\nفقلت له: الأمر في هذا بين.\nقال: فأبنه لي.\nقلت: كل كلام أريد به تعظيم الله، فعلمهم رسول الله، فلعله جعل يعلمه الرجل فيحفظه، والآخر فيحفظه،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:335","bookId":"risala-shafii","type":"section","seq":335,"chapter":"الجزء الثاني.","title":"ص: 272","page":"ج1 ص267","text":"وما أخذ حفظا فأكثر ما يحترس فيه منه إحالة المعنى، فلم تكن فيه زيادة ولا نقص ولا اختلاف شيء من كلامه يحيل المعنى فلا تسع إحالته.\nفلعل النبي أجاز لكل امرئ منهم كما حفظ، إذ كان لا معنى فيه يحيل شيئا عن حكمه، ولعل من اختلفت روايته واختلف تشهده إنما توسعوا فيه فقالوا على ما حفظوا، وعلى ما حضرهم وأجيز لهم.\nقال: أفتجد شيئا يدل على إجازة ما وصفت؟\nفقلت: نعم.\nقال: وما هو؟","bab":"باب العلل في الحديث."},{"id":"risala-shafii:336","bookId":"risala-shafii","type":"section","seq":336,"chapter":"الجزء الثاني.","title":"ص: 273","page":"ج1 ص267","text":"قلت: أخبرنا \"مالك\" عن \"ابن شهاب\" عن \"عروة\" عن \"عبد الرحمن بن عبد القاري\" قال: سمعت \"عمر بن الخطاب\" يقول: \" سمعت \"هشام بن حكيم بن حزام\" يقرأ سورة الفرقان على غير ما أقرأها، وكان النبي أقرأنيها، فكدت أعجل عليه، ثم أمهلته حتى انصرف، ثم لببته بردائه (1) فجئت به إلى النبي، فقلت: يا رسول الله، إني سمعت هذا يقرأ سورة الفرقان على غير ما أقرأتنيها؟ فقال له رسول الله: اقرأ، فقرأ القراءة التي سمعته يقرأ، فقال رسول الله: هكذا أنزلت، ثم قال لي: اقرأ، فقرأت، فقال: هكذا أنزلت، إن هذا القرآن أنزل على سبعة أحرف، فاقرءوا ما تيسر \" (2) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:337","bookId":"risala-shafii","type":"section","seq":337,"chapter":"الجزء الثاني.","title":"ص: 274","page":"ج1 ص267","text":"قال: فإذ كان الله لرأفته بخلقه أنزل كتابه على سبعة أحرف، معرفة منه بأن الحفظ قد يزل، ليحل لهم قراءته وإن اختلف اللفظ فيه، ما لم يكن في اختلافهم إحالة معنى: كان ما سوى كتاب الله أولى أن يجوز فيه اختلاف اللفظ ما لم يحل معناه.\nوكل ما لم يكن فيه حكم، فاختلاف اللفظ فيه لا يحيل معناه.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:338","bookId":"risala-shafii","type":"section","seq":338,"chapter":"الجزء الثاني.","title":"ص: 275","page":"ج1 ص267","text":"وقد قال بعض التابعين: لقيت أناسا من أصحاب رسول الله، فاجتمعوا في المعنى واختلفوا علي في اللفظ، فقلت لبعضهم ذلك، فقال: لا بأس ما لم يحيل (3) المعنى.\nقال \"الشافعي\": فقال: ما في التشهد إلا تعظيم الله، وإني لأرجو أن يكون كل هذا فيه واسعا، وأن لا يكون الاختلاف فيه إلا من حيث ذكرت، ومثل هذا _ كما قلت _ يمكن في صلاة","bab":"باب العلل في الحديث."},{"id":"risala-shafii:339","bookId":"risala-shafii","type":"section","seq":339,"chapter":"الجزء الثاني.","title":"ص: 276","page":"ج1 ص270","text":"الخوف، فيكون إذا جاء بكمال الصلاة على أي الوجوه روي عن النبي أجزأه، إذ خالف الله بينها وبين ما سواها من الصلوات، ولكن كيف صرت إلى اختيار حديث \"ابن عباس\" عن النبي في التشهد دون غيره؟\nقلت: لما رأيته واسعا، وسمعته عن \"ابن عباس\" صحيحا، كان عندي أجمع وأكثر لفظا من غيره، فأخذت به، غير معنف لمن أخذ بغيره مما ثبت عن رسول الله.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:340","bookId":"risala-shafii","type":"section","seq":340,"chapter":"الجزء الثاني.","title":"اختلاف الرواية على وجه غير الذي قبله.","page":"ج1 ص275","text":"أخبرنا \"مالك\" عن \"نافع\" عن \"أبي سعيد الخدري\" أن رسول الله قال: \" لا تبيعوا الذهب بالذهب إلا مثلا بمثل، ولا تشفوا (1) بعضها على بعض، ولا تبيعوا الورق (2) بالورق إلا مثلا","bab":"باب العلل في الحديث."},{"id":"risala-shafii:341","bookId":"risala-shafii","type":"section","seq":341,"chapter":"الجزء الثاني.","title":"ص: 277","page":"ج1 ص276","text":"بمثل، ولا تشفوا بعضها على بعض، ولا تبيعوا شيئا منها غائبا بناجز (3) \" (4) .\nأخبرنا \"مالك\" عن \"موسى بن أبي تميم\" عن \"سعيد بن يسار\" عن \"أبي هريرة\" أن رسول الله قال: \" الدينار بالدينار، والدرهم بالدرهم، لا فضل بينهما \" (5) .\nأخبرنا \"مالك\" عن \"حميد بن قيس\" عن \"مجاهد\" عن \"ابن عمر\" أنه قال: \" الدينار بالدينار، والدرهم بالدرهم، لا فضل بينهما، هذا عهد نبينا إلينا، وعهدنا إليكم \" (6) .\nقال \"الشافعي\": وروى \"عثمان بن عفان\" و\"عبادة","bab":"باب العلل في الحديث."},{"id":"risala-shafii:342","bookId":"risala-shafii","type":"section","seq":342,"chapter":"الجزء الثاني.","title":"ص: 278","page":"ج1 ص276","text":"بن الصامت\" عن رسول الله النهي عن الزيادة في الذهب بالذهب، يدا بيد (7) .\nقال \"الشافعي\": وبهذه الأحاديث نأخذ، وقال بمثل معناها الأكابر من أصحاب رسول الله، وأكثر المفتيين بالبلدان.\nأخبرنا \"سفيان\" أنه سمع \"عبيد الله بن أبي يزيد\" يقول: سمعت \"ابن عباس\" يقول: أخبرني \"أسامة بن زيد\" أن النبي قال: \" إنما الربا في النسية (1) \" (2) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:343","bookId":"risala-shafii","type":"section","seq":343,"chapter":"الجزء الثاني.","title":"ص: 279","page":"ج1 ص276","text":"قال: فأخذ بهذا \"ابن عباس\" ونفر من أصحابه المكيين وغيرهم.\nقال: فقال لي: قائل هذا الحديث مخالف للأحادث قبله؟\nقلت: قد يحتمل خلافها وموافقتها.\nقال: وبأي شيء يحتمل موافقتها؟\nقلت: قد يكون \"أسامة\" سمع رسول الله يسأل عن","bab":"باب العلل في الحديث."},{"id":"risala-shafii:344","bookId":"risala-shafii","type":"section","seq":344,"chapter":"الجزء الثاني.","title":"ص: 280","page":"ج1 ص276","text":"الصنفين المختلفين، مثل الذهب بالورق، والتمر بالحنطة أو ما اختلف جنسه متفاضلا يدا بيد، فقال: \" إنما الربا في النسية \"، أو تكون المسألة سبقته بهذا وأدرك الجواب، فروى الجواب ولم يحفظ المسألة، أو شك فيها، لأنه ليس في حديثه ما ينفي هذا عن حديث \"أسامة\"، فاحتمل موافقتها لهذا.\nفقال: فلم قلت: يحتمل خلافها؟\nقلت: لأن \"ابن عباس\" الذي رواه، وكان يذهب فيه غير هذا المذهب، فيقول: لا ربا في بيع يدا بيد، إنما الربا في النسية.\nفقال: فما الحجة إن كانت الأحاديث قبله مخالفة: في تركه إلى غيره؟\nفقلت له: كل واحد ممن روى خلاف \"أسامة\"، وإن لم يكن أشهر بالحفظ للحديث من \"أسامة\"، فليس به تقصير عن حفظه، و\"عثمان بن عفان\" و\"عبادة بن الصامت\" أشد تقدما بالسن","bab":"باب العلل في الحديث."},{"id":"risala-shafii:345","bookId":"risala-shafii","type":"section","seq":345,"chapter":"الجزء الثاني.","title":"ص: 281","page":"ج1 ص276","text":"والصحبة من \"أسامة\"، و\"أبو هريرة\" أسن وأحفظ من روى الحديث في دهره.\nولما كان حديث اثنين أولى في الظاهر بالحفظ، وبأن ينفى عنه الغلط من حديث واحد: كان حديث الأكثر الذي هو أشبه أن يكون أولى بالحفظ من حديث من هو أحدث منه، وكان حديث خمسة أولى أن يصار إليه من حديث واحد.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:346","bookId":"risala-shafii","type":"section","seq":346,"chapter":"الجزء الثاني.","title":"وجه آخر مما يعد مختلفا","page":"ج1 ص278","text":"وليس عندنا بمختلف.\nأخبرنا \"ابن عيينة\" عن \"محمد بن العجلان\" عن \"عاصم بن عمر بن قتادة\" عن \"محمود بن لبيد\" عن \"رافع بن خديج\" أن رسول الله قال: \" أسفروا بالفجر، فإن ذلك أعظم للأجر، أو: أعظم لأجوركم \" (1) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:347","bookId":"risala-shafii","type":"section","seq":347,"chapter":"الجزء الثاني.","title":"ص: 283","page":"ج1 ص282","text":"أخبرنا \"سفيان\" عن \"الزهري\" عن \"عروة\" عن \"عائشة\" قالت: \" كن النساء من المؤمنات يصلين مع النبي الصبح، ثم ينصرفن وهن متلفعات بمروطهن (2) ، ما يعرفهن أحد من الغلس (3) \" (4) .\nقال: وذكر تغليس النبي بالفجر \"سهل بن سعد\" وزيد بن ثابت\" وغيرهما من أصحاب رسول الله، شبيه بمعنى \"عائشة\".\nقال \"الشافعي\": قال لي قائل: نحن نرى أن نسفر","bab":"باب العلل في الحديث."},{"id":"risala-shafii:348","bookId":"risala-shafii","type":"section","seq":348,"chapter":"الجزء الثاني.","title":"ص: 284","page":"ج1 ص282","text":"بالفجر اعتمادا على حديث \"رافع بن خديج\" ونزعم أن الفضل في ذلك، وأنت ترى أن جائزا لنا إذا اختلف الحديثان أن نأخذ بأحدهما، ونحن نعد هذا مخالفا لحديث \"عائشة\".\nقال: فقلت له: إن كان مخالفا لحديث \"عائشة\"، فكان الذي يلزمنا وإياك أن نصير إلى حديث \"عائشة\" دونه، لأن أصل ما نبني نحن وأنتم عليه: أن الأحاديث إذا اختلفت لم نذهب إلى واحد منها دون غيره إلا بسبب يدل على أن الذي ذهبنا إليه أقوى من الذي تركنا.\nقال: وما ذلك السبب؟\nقلت: أن يكون أحد الحديثين أشبه بكتاب الله، فإذا أشبه كتاب الله كانت فيه الحجة.\nقال: هكذا نقول.\nقلنا: فإن لم يكن فيه نص كتاب كان","bab":"باب العلل في الحديث."},{"id":"risala-shafii:349","bookId":"risala-shafii","type":"section","seq":349,"chapter":"الجزء الثاني.","title":"ص: 285","page":"ج1 ص282","text":"أولاهما بنا الأثبت منهما، وذلك أن يكون من رواه أعرف إسنادا وأشهر بالعلم وأحفظ له، أو يكون روي الحديث الذي ذهبنا إليه من وجهين أو أكثر، والذي تركنا من وجه، فيكون الأكثر أولى بالحفظ من الأقل، أو يكون الذي ذهبنا إليه أشبه بمعنى كتاب الله، أو أشبه بما سواهما من سنن رسول الله، أو أولى بما يعرف أهل العلم، أو أصح في القياس، والذي عليه الأكثر من أصحاب رسول الله.\nقال: وهكذا نقول ويقول أهل العلم.\nقلت: فحديث \"عائشة\" أشبه بكتاب الله، لأن الله يقول: \" حافظوا على الصلوات والصلاة الوسطى (238) \" [البقرة] ، فإذا حل الوقت فأولى المصلين بالمحافظة المقدم الصلاة.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:350","bookId":"risala-shafii","type":"section","seq":350,"chapter":"الجزء الثاني.","title":"ص: 286","page":"ج1 ص282","text":"وهو أيضا أشهر رجالا بالثقة وأحفظ، ومع حديث \"عائشة\": ثلاثة كلهم يروون عن النبي مثل معنى حديث \"عائشة\": \"زيد بن ثابت\" و\"سهل بن سعد\".\nوهذا أشبه بسنن النبي من حديث \"رافع بن خديج\".\nقال: وأي سنن؟\nقلت: قال رسول الله: \" أول الوقت رضوان الله، وآخره عفو الله \" (1) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:351","bookId":"risala-shafii","type":"section","seq":351,"chapter":"الجزء الثاني.","title":"ص: 287","page":"ج1 ص283","text":"وهو لا يؤثر على رضوان الله شيئا، والعفو لا يحتمل إلا معنيين: عفو عن تقصير، أو توسعة، والتوسعة تشبه أن يكون الفضل في غيرها، إذ لم يؤمر بترك ذلك الغير الذي وسع في خلافها.\nقال: وما تريد بهذا؟","bab":"باب العلل في الحديث."},{"id":"risala-shafii:352","bookId":"risala-shafii","type":"section","seq":352,"chapter":"الجزء الثاني.","title":"ص: 288","page":"ج1 ص283","text":"قلت: إذ لم نؤمر بترك الوقت الأول، وكان جائزا أن نصلي فيه وفي غيره قبله، فالفضل في التقديم، والتأخير تقصير موسع.\nوقد أبان رسول الله مثل ما قلنا، وسئل: أي الأعمال أفضل؟ فقال: \" الصلاة في أول وقتها \" (2) .\nوهو لا يدع موضع الفضل، ولا يأمر الناس إلا به.\nوهو الذي لا يجهله عالم: أن تقديم الصلاة في أول وقتها أولى بالفضل، لما يعرض للآدميين من الأشغال والنسيان والعلل.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:353","bookId":"risala-shafii","type":"section","seq":353,"chapter":"الجزء الثاني.","title":"ص: 289","page":"ج1 ص283","text":"وهذا أشبه بمعنى كتاب الله.\nقال: وأين هو من الكتاب؟\nقلت: قال الله: \" حافظوا على الصلوات والصلاة الوسطى (238) \" [البقرة] ، ومن قدم الصلاة في أول وقتها كان أولى بالمحافظة عليها ممن أخرها عن أول الوقت.\nوقد رأينا الناس فيما وجب عليهم وفيما تطوعوا به يؤمرون بتعجيله إذا أمكن، لما يعرض للآدميين من الأشغال والنسيان والعلل، الذي لا تجهله العقول.\nوإن تقديم صلاة الفجر في أول وقتها عن \"أبي بكر\" و\"عمر\" و\"عثمان\" و\"علي بن أبي طالب\" و\"ابن مسعود\" \"وأبي موسى الأشعري\" و\"أنس بن مالك\" وغيرهم: مثبت.\nفقال: فإن \"أبا بكر\" و\"عمر\" و\"عثمان\" دخلوا في الصلاة مغلسين وخرجوا منها مسفرين، بإطالة القراءة؟","bab":"باب العلل في الحديث."},{"id":"risala-shafii:354","bookId":"risala-shafii","type":"section","seq":354,"chapter":"الجزء الثاني.","title":"ص: 290","page":"ج1 ص286","text":"فقلت له: قد أطالوا القراءة وأوجزوها، والوقت في الدخول لا في الخروج من الصلاة وكلهم دخل مغلسا، وخرج رسول الله منها مغلسا.\nفخالفت الذي هو أولى بك أن تصير إليه، مما ثبت عن رسول الله، وخالفتهم، فقلت: يدخل الداخل فيها مسفرا ويخرج مسفرا ويوجز القراءة، فخالفتهم في الدخول وما احتججت به من طول القراءة، وفي الأحاديث عن بعضهم أنه خرج منها مغلسا.\nقال: فقال: أفتعد خبر \"رافع\" يخالف خبر \"عائشة\"؟\nفقلت له: لا.\nفقال: فبأي وجه يوافقه؟\nفقلت: إن رسول الله لما حض الناس على تقديم الصلاة، وأخبر بالفضل فيها: احتمل أن يكون من الراغبين من يقدمها قبل الفجر الآخر، فقال: \" أسفروا بالفجر \"، يعني: حتى يتبين الفجر الآخر معترضا.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:355","bookId":"risala-shafii","type":"section","seq":355,"chapter":"الجزء الثاني.","title":"ص: 291","page":"ج1 ص286","text":"قال: أفيحتمل معنى غير ذلك؟\nقلت: نعم، يحتمل ما قلت، وما بين ما قلنا وقلت، وكل معنى يقع عليه اسم {الإسفار} .\nقال: فما جعل معناكم أولى من معنانا؟\nفقلت: بما وصفت من التأويل، وبأن النبي قال: \" هما فجران، فأما الذي كأنه ذنب السرحان (1) ، فلا يحل شيئا ولا يحرمه، وأما الفجر المعترض فيحل الصلاة ويحرم الطعام \" (2) ، يعني: على من أراد الصيام.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:356","bookId":"risala-shafii","type":"section","seq":356,"chapter":"الجزء الثاني.","title":"وجه آخر مما يعد مختلفا.","page":"ج1 ص289","text":"أخبرنا \"سفيان\" عن \"الزهري\" عن \"عطاء بن يزيد الليثي\" عن \"أبي أيوب الأنصاري\" أن النبي قال: \" لا تستقبلوا القبلة ولا تستدبروها لغايط أو بول، ولكن شرقوا أو غربوا. قال أبو أيوب: فقدمنا الشام، فوجدنا مراحيض قد صنعت، فننحرف ونستغفر الله \" (1) .\nأخبرنا \"مالك\" عن \"يحيى بن سعيد\" عن \"محمد بن يحيى بن حبان\" عن عمه \"واسع بن حبانط عن \"عبد الله بن عمر\" أنه كان يقول: \" إن ناسا يقولون: إذا قعدت على حاجتك فلا تستقبل القبلة ولا بيت المقدس، فقال \"عبد الله\": لقد ارتقيت على","bab":"باب العلل في الحديث."},{"id":"risala-shafii:357","bookId":"risala-shafii","type":"section","seq":357,"chapter":"الجزء الثاني.","title":"ص: 293","page":"ج1 ص292","text":"ظهر بيت لنا، فرأيت رسول الله على لبنتين مستقبلا بيت المقدس لحاجته \" (2) .\nقال \"الشافعي\": أدب رسول الله من كان بين ظهرانيه، وهم عرب، لا مغتسلات لهم أو لأكثرهم في منازلهم، فاحتمل أدبه لهم معنيين:\n- أحدهما: أنهم إنما كانوا يذهبون لحوايجهم في الصحراء، فأمرهم ألا يستقبلوا القبلة ولا يستدبروها، لسعة الصحراء، ولخفة المؤونة عليهم، لسعة مذاهبهم عن أن تستقبل القبلة أو تستدبر لحاجة الإنسان من غايط أو بول، ولم يكن لهم مرفق (3) في استقبال القبلة ولا استدبارها أوسع عليهم من توقى ذلك.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:358","bookId":"risala-shafii","type":"section","seq":358,"chapter":"الجزء الثاني.","title":"ص: 294","page":"ج1 ص292","text":"وكثيرا ما يكون الذاهبون في تلك الحال في غير ستر عن مصلي (4) ، يرى عوراتهم مقبلين ومدبرين، إذا استقبل القبلة، فأمروا أن يكرموا قبلة الله ويستروا العورات من مصلي، إن صلى حيث يراهم، وهذا المعنى أشبه معانيه، والله أعلم.\nوقد يحتمل أن يكون نهاهم أن يستقبلوا ما جعل قبلة في صحراء لغائط أو بول، لئلا يتغوط أو يبال في القبلة، فتكون قذرة بذلك، أو من ورائها، فيكون من ورائها أذى للمصلين إليها.\nقال: فسمع \"أبو أيوب\" ما حكى عن النبي جملة، فقال","bab":"باب العلل في الحديث."},{"id":"risala-shafii:359","bookId":"risala-shafii","type":"section","seq":359,"chapter":"الجزء الثاني.","title":"ص: 295","page":"ج1 ص292","text":"به على المذهب في الصحراء والمنازل، ولم يفرق في المذهب بين المنازل التي للناس مرافق في أن يضعوها في بعض الحالات مستقبلة القبلة أو مستدبرتها، والتي يكون فيها الذاهب لحاجته مستترا، فقال بالحديث جملة، كما سمعه جملة.\nوكذلك ينبغي لمن سمع الحديث أن يقول به على عمومه وجملته، حتى يجد دلالة يفرق بها فيه بينه.\nقال \"الشافعي\": لما حكى \"ابن عمر\" أنه رأى النبي مستقبلا بيت المقدس لحاجته، وهو إحدى القبلتين، وإذا استقبله استدبر الكعبة: أنكر على من يقول لا يستقبل القبلة ولا","bab":"باب العلل في الحديث."},{"id":"risala-shafii:360","bookId":"risala-shafii","type":"section","seq":360,"chapter":"الجزء الثاني.","title":"ص: 296","page":"ج1 ص292","text":"تستدبرها لحاجة، ورأى أن لا ينبغي لأحد أن ينتهي عن أمر فعله رسول الله.\nولم يسمع - فيما يرى - ما أمر به رسول الله في الصحراء، فيفرق بين الصحراء والمنازل، فيقول بالنهي في الصحراء وبالرخصة في المنازل، فيكون قد قال بما سمع ورأى، وفرق بالدلالة عن رسول الله على ما فرق بينه، لافتراق حال الصحراء والمنازل.\nوفي هذا بيان أن كل من سمع من رسول الله شيئا قبله عنه وقال به، وإن لم يعرف حيث يتفرق لم يتفرق بين ما لم يعرف إلا بدلالة عن رسول الله على الفرق بينه.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:361","bookId":"risala-shafii","type":"section","seq":361,"chapter":"الجزء الثاني.","title":"ص: 297","page":"ج1 ص292","text":"ولهذا أشباه في الحديث، اكتفينا بما ذكرنا منها مما لم نذكر.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:362","bookId":"risala-shafii","type":"section","seq":362,"chapter":"الجزء الثاني.","title":"وجه آخر من الاختلاف.","page":"ج1 ص295","text":"أخبرنا \"ابن عيينة\" عن \"الزهري\" عن \"عبيد الله بن عبد الله بن عتبة\" عن \"ابن عباس\" قال: أخبرني \"الصعب بن جثامة\" \" أنه سمع النبي يسأل عن أهل الدار من المشركين يبيتون فيصاب من نسائهم وذراريهم، فقال رسول الله: هم منهم \". وزاد \"عمرو بن دينار\" عن \"الزهري\" \" هم من آبائهم \" (1) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:363","bookId":"risala-shafii","type":"section","seq":363,"chapter":"الجزء الثاني.","title":"ص: 298","page":"ج1 ص297","text":"أخبرنا \"ابن عيينة\" عن \"الزهري\" عن \"ابن كعب بن مالك\" عن عمه: \" أن النبي لما بعث إلى \"ابن أبي الحقيق\"، نهى عن قتل النساء والولدان \" (2) .\nقال: فكان \"سفيان\" يذهب إلى أن قول النبي: \" هم منهم \" إباحة لقتلهم، وأن حديث \"ابن أبي الحقيق\" ناسخ له، وقال: كان \"الزهري\" إذا حدث حديث \"الصعب بن جثامة\"، أتبعه حديث \"ابن كعب\".","bab":"باب العلل في الحديث."},{"id":"risala-shafii:364","bookId":"risala-shafii","type":"section","seq":364,"chapter":"الجزء الثاني.","title":"ص: 299","page":"ج1 ص297","text":"قال \"الشافعي\": وحديث \"الصعب بن جثامة\" في عمرة النبي، فإن كان في عمرته الأولى فقد قيل: أمر \"ابن أبي الحقيق\" قبلها، وقيل: في سنتها، وإن كان في عمرته الآخرة، فهو بعد أمر \"ابن أبي الحقيق\" غير شك، والله اعلم.\nولم نعلمه - صلى الله عليه - رخص في قتل النساء والولدان ثم نهى عنه.\nومعنى نهيه عندنا - والله أعلم - عن قتل النساء والولدان: أن يقصد قصدهم بقتل، وهم يعرفون متميزين ممن أمر بقتله منهم.\nومعنى قوله: هم منهم: أنهم يجمعون خصلتين: أن","bab":"باب العلل في الحديث."},{"id":"risala-shafii:365","bookId":"risala-shafii","type":"section","seq":365,"chapter":"الجزء الثاني.","title":"ص: 300","page":"ج1 ص297","text":"ليس لهم حكم الإيمان الذي يمنع به الدم، ولا حكم دار الإيمان الذي يمنع به الإغارة على الدار.\nوإذ أباح رسول الله البيات والإغارة على الدار، فأغار على بني المصطلق غارين: فالعلم يحيط أن البيات والإغارة إذا حل بإحلال رسول الله لم يمتنع أحد بيت أو أغار من أن يصيب النساء والولدان، فيسقط المأثم فيهم والكفارة والعقل والقود عن من أصابهم، إذ أبيح له أن يبيت ويغير، وليست لهم حرمة الإسلام.\nولا يكون له قتلهم عامدا لهم متميزين عارفا بهم.\nفإنما نهى عن قتل الولدان: لأنهم لم يبلغوا كفرا فيعملوا به، وعن قتل النساء: لأنه لا معنى فيهن لقتال وأنهن والولدان يتخولون (3) فيكونون قوة لأهل دين الله.\nفإن قال قائل: أبن هذا بغيره.\nقيل: فيه ما اكتفى العالم به من غيره.\nفإن قال: أفتجد ما تشده به غيره، وتشبهه من كتاب الله؟\nقلت: نعم، قال الله: \" وما كان لمؤمن أن يقتل مؤمنا إلا خطأ، ومن قتل مؤمنا خطأ فتحرير رقبة مؤمنة ودية مسلمة إلى أهله إلا أن يصدقوا، فإن كان من قوم عدو لكم وهو مؤمن فتحرير رقبة مؤمنة، وإن كان من قوم بينكم وبينهم ميثاق فدية مسلمة إلى أهله، وتحرير رقبة مؤمنة، فمن لم يجد فصيام شهرين متتابعين توبة من الله، وكان الله عليما حكيما (92) \" [النساء] .\nقال: فأوجب الله بقتل المؤمن خطأ الدية وتحرير رقبة، وفي قتل ذي الميثاق الدية وتحرير رقبة، إذا كانا معا ممنوعي الدم، بالإيمان والعهد والدار معا، فكان المؤمن في الدار غير","bab":"باب العلل في الحديث."},{"id":"risala-shafii:366","bookId":"risala-shafii","type":"section","seq":366,"chapter":"الجزء الثاني.","title":"ص: 302","page":"ج1 ص297","text":"الممنوعة وهو ممنوع بالإيمان، فجعلت فيه الكفارة بإتلافه، ولم يجعل فيه الدية، وهو ممنوع الدم بالإيمان، فلما كان الولدان والنساء من المشركين لا ممنوعين بإيمان ولا دار: لم يكن فيهم عقل ولا قود ولا دية ولا مأثم - إن شاء الله - ولا كفارة.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:367","bookId":"risala-shafii","type":"section","seq":367,"chapter":"الجزء الثاني.","title":"في غسل الجمعة","page":"ج1 ص301","text":"فقال: فاذكر وجوها من الأحاديث المختلفة عند بعض الناس أيضا.\nفقلت: أخبرنا \"مالك\" عن \"صفوان بن سليم\" عن \"عطاء بن يسار\" عن \"أبي سعيد الخدري\"، أن رسول الله قال: \" غسل يوم الجمعة واجب على كل محتلم \" (1) .\nأخبرنا \"ابن عيينة\" عن \"الزهري\" عن \"سالم\" عن أبيه،","bab":"باب العلل في الحديث."},{"id":"risala-shafii:368","bookId":"risala-shafii","type":"section","seq":368,"chapter":"الجزء الثاني.","title":"ص: 303","page":"ج1 ص302","text":"أن النبي قال: من جاء منكم الجمعة فليغتسل \" (2) .\nقال \"الشافعي\": فكان قول رسول الله في: ((غسل يوم الجمعة واجب)) ، وأمره بالغسل، يحتمل معنيين: الظاهر منهما أنه واجب، فلا تجزئ الطهارة لصلاة الجمعة إلا بالغسل، كما لا يجزئ في طهارة الجنب غير الغسل، ويحتمل واجب في الاختيار والأخلاق والنظافة.\nأخبرنا \"مالك\" عن \"الزهري\" عن \"سالم\" قال: \" دخل رجل من أصحاب النبي يوم الجمعة، و\"عمر بن الخطاب\" يخطب، فقال \"عمر\": أيت ساعة هذه، فقال: يا أمير المؤمنين، انقلبت من السوق، فسمعت النداء، فما زدت على أن توضأت، فقال \"عمر\":","bab":"باب العلل في الحديث."},{"id":"risala-shafii:369","bookId":"risala-shafii","type":"section","seq":369,"chapter":"الجزء الثاني.","title":"ص: 304","page":"ج1 ص302","text":"الوضوء أيضا! وقد علمت أن رسول الله كان يأمر بالغسل؟! \" (3) .\nأخبرنا الثقة عن \"معمر\" عن \"الزهري\" عن \"سالم\" عن أبيه مثل معنى حديث \"مالك\"، وسمى الداخل يوم الجمعة بغير غسل: \"عثمان بن عفان\".\nقال: فلما حفظ \"عمر\" عن رسول الله أنه كان يأمر بالغسل، وعلم أن \"عثمان\" قد علم من أمر رسول الله بالغسل، ثم ذكر \"عمر\" \"لعثمان\" أمر النبي بالغسل، وعلم \"عثمان\" ذلك: فلو ذهب","bab":"باب العلل في الحديث."},{"id":"risala-shafii:370","bookId":"risala-shafii","type":"section","seq":370,"chapter":"الجزء الثاني.","title":"ص: 305","page":"ج1 ص302","text":"على متوهم أن \"عثمان\" نسي، فقد ذكره \"عمر\" قبل الصلاة بنسيانه، فلما لم يترك \"عثمان\" الصلاة للغسل، ولما لم يأمره \"عمر\" بالخروج للغسل: دل ذلك على أنهما قد علما أن أمر رسول الله بالغسل على الاختيار (4) ، لا على أن لا يجزئ غيره، لأن \"عمر\" لم يكن ليدع أمره بالغسل، ولا \"عثمان\" إذ علمنا أنه ذاكر لترك الغسل، وأمر النبي بالغسل: إلا والغسل - كما وصفنا - على الاختيار.\nقال: وروى \"البصريون\" أن النبي قال: \" من توضأ يوم الجمعة فبها ونعمة، ومن اغتسل فالغسل أفضل \" (5) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:371","bookId":"risala-shafii","type":"section","seq":371,"chapter":"الجزء الثاني.","title":"ص: 306","page":"ج1 ص302","text":"أخبرنا \"سفيان\" عن \"يحيى\" عن \"عمرة \" عن \"عائشة\" قالت: \" كان الناس عمال أنفسهم، وكانوا يروحون بهيآتهم، فقيل لهم: لو اغتسلتم \" (6) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:372","bookId":"risala-shafii","type":"section","seq":372,"chapter":"الجزء الثاني.","title":"النهي عن معنى دل عليه معنى في حديث غيره.","page":"ج1 ص302","text":"أخبرنا \"مالك\" عن \"أبي الزناد\" و\"محمد بن يحيى بن حبان\" عن \"الأعرج\" عن \"أبي هريرة\" أن رسول الله قال: \" لا يخطب أحدكم على خطبة أخيه \" (1) .\nأخبرنا مالك\" عن \"نافع\" عن \"ابن عمر\" عن النبي، أنه قال: \" لا يخطب أحدكم على خطبة أخيه \" (2) .\nقال \"الشافعي\": فلو لم تأت عن رسول الله دلالة على أن نهيه عن أن يخطب على خطبة أخيه على معنى دون معنى:","bab":"باب العلل في الحديث."},{"id":"risala-shafii:373","bookId":"risala-shafii","type":"section","seq":373,"chapter":"الجزء الثاني.","title":"ص: 308","page":"ج1 ص306","text":"كان الظاهر أن حراما أن يخطب المرء على خطبة غيره من حين يبتدئ إلى أن يدعها.\nقال: وكان قول النبي: \" لا يخطب أحدكم على خطبة أخيه \" يحتمل أن يكون جوابا أراد به في معنى الحديث، ولم يسمع من حدثه: السبب الذي له قال رسول الله هذا، فأديا بعضه دون بعض، أو شكا في بعضه وسكتا عما شكا فيه.\nفيكون النبي سئل عن رجل خطب امرأة فرضيته وأذنت في نكاحه، فخطبها أرجح عندها منه، فرجعت عن الأول الذي أذنت في إنكاحه، فنهى عن خطبة المرأة إذا كانت بهذه","bab":"باب العلل في الحديث."},{"id":"risala-shafii:374","bookId":"risala-shafii","type":"section","seq":374,"chapter":"الجزء الثاني.","title":"ص: 309","page":"ج1 ص306","text":"الحال، وقد يكون أن ترجع عن من أذنت في إنكاحه، فلا ينكحها من رجعت له، فيكون فسادا عليها وعلى خاطبها الذي أذنت في إنكاحه.\nفإن قال قائل: لم صرت إلى أن تقول إن نهي النبي أن يخطب الرجل على خطبة أخيه: على معنى دون معنى؟\nفبالدلالة عنه.\nفإن قال: فأين هي؟\nقيل له - إن شاء الله -: أخبرنا \"مالك\" عن \"عبد الله بن يزيد\" مولى \"الأسود بن سفيان\" عن \"أبي سلمة بن عبد الرحمن\" عن \"فاطمة بنت قيس\": \" أن زوجها طلقها، فأمرها رسول الله أن تعتد في","bab":"باب العلل في الحديث."},{"id":"risala-shafii:375","bookId":"risala-shafii","type":"section","seq":375,"chapter":"الجزء الثاني.","title":"ص: 310","page":"ج1 ص307","text":"بيت \"ابن أم مكتوم\"، وقال: إذا حللت فآذنيني، قالت: فلما حللت ذكرت له أن \"معاوية بن أبي سفيان\" و\"أبا جهم\" خطباني، فقال رسول الله: فأما \"أبو جهم\" فلا يضع عصاه عن عاتقه، وأما \"معاوية\" فصعلوك لا مال له، انكحي \"أسامة بن زيد\"، قالت: فكرهته، فقال: انكحي\" أسامة\"، فنكحته، فجعل الله فيه خيرا، واغتبطت به \" (1) .\nقال \"الشافعي\": فبهذا قلنا.\nودلت سنة رسول الله في خطبته \"فاطمة\" على \"أسامة\" بعد إعلامها رسول الله أن \"معاوية\" و\"أبا جهم\" خطباها، على أمرين:\n- أحدهما: أن النبي يعلم أنهما لا يخطبانها إلا وخطبة أحدهما بعد خطبة الآخر، فلما لم ينهها ولم يقل لها ما كان لواحد","bab":"باب العلل في الحديث."},{"id":"risala-shafii:376","bookId":"risala-shafii","type":"section","seq":376,"chapter":"الجزء الثاني.","title":"ص: 311","page":"ج1 ص307","text":"أن يخطبك حتى يترك الآخر خطبتك، وخطبها على \"أسامة بن زيد\" بعد خطبتهما: فاستدللنا على أنها لم ترضى، (2) ولو رضيت واحدا منهما أمرها أن تتزوج من رضيت، وأن إخبارها إياه بمن خطبها، إنما كان إخبارا عما لم تأذن فيه، ولعلها استشارة له، ولا يكون أن تستشيره وقد أذنت بأحدهما.\nفلما خطبها على \"أسامة\" استدللنا على أن الحال التي خطبها فيه غير الحال التي نهى عن خطبتها فيها، ولم تكن حال تفرق بين خطبتها حتى يحل بعضها ويحرم بعضها، إلا إذا أذنت للولي أن يزوجها، فكان لزوجها - إن زوجها الولي - أن يلزمها التزويج، وكان عليه أن يلزمه، وحلت له، فأما قبل ذلك فحالها واحدة: ليس لوليها أن يزوجها حتى تأذن، فركونها وغير ركونها سواء.\nفإن قال قائل: فإنها راكنة مخالفة لحالها غير راكنة.\nفكذلك هي لو خطبت فشتمت الخاطب وترغبت عنه ثم عاد عليها بالخطبة فلم تشتمه ولم تظهر ترغبا ولم تركن: كانت حالها التي تركت فيها شتمه مخالفة لحالها التي شتمته فيها، وكانت في هذه الحال أقرب إلى الرضا، ثم تنتقل حالاتها، لأنها قبل الركون إلى متأول، بعضها أقرب إلى الركون من بعض.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:377","bookId":"risala-shafii","type":"section","seq":377,"chapter":"الجزء الثاني.","title":"ص: 313","page":"ج1 ص309","text":"ولا يصح فيه معنى بحال - والله أعلم - إلا ما وصفت من أنه نهى عن الخطبة بعد إذنها للولي بالتزويج، حتى يصير أمر الولي جائزا، فأما ما لم يجز أمر الولي فأول حالها وآخرها سواء، والله أعلم.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:378","bookId":"risala-shafii","type":"section","seq":378,"chapter":"الجزء الثاني.","title":"النهي عن معنى أوضح من معنى قبله.","page":"ج1 ص312","text":"أخبرنا \"مالك\" عن \"نافع\" عن \"ابن عمر\" أن رسول الله قال: \" المتبايعان كل واحد منهما بالخيار على صاحبه ما لم يتفرقا، إلا بيع الخيار \" (1) .","bab":"باب العلل في الحديث."},{"id":"risala-shafii:379","bookId":"risala-shafii","type":"section","seq":379,"chapter":"الجزء الثاني.","title":"ص: 314","page":"ج1 ص313","text":"أخبرنا \"سفيان\" عن \"الزهري\" عن \"سعيد بن المسيب\" عن \"أبي هريرة\" أن رسول الله قال: \" لا يبيع الرجل على بيع أخيه \" (2) .\nقال \"الشافعي\": وهذا معنى يبين أن رسول الله قال: \"المتبايعان بالخيار ما لم يتفرقا\"، وأن نهيه عن أن يبيع الرجل على بيع أخيه، إنما هو قبل أن يتفرقا عن مقامهما الذي تبايعا فيه.\nوذلك أنهما لا يكونان متبايعين حتى يعقدا البيع معا، فلو كان البيع إذا عقداه لزم كل واحد منهما، ما ضر البائع أن يبيعه رجل سلعة كسلعته أو غيرها، وقد تم بيعه لسلعته، ولكنه لما كان لهما الخيار كان الرجل لو اشترى من رجل ثوبا بعشرة دنانير فجاءه آخر فأعطاه مثله بتسعة دنانير: أشبه أن يفسخ البيع، إذا كان له الخيار قبل أن يفارقه، ولعله يفسخه ثم لا يتم","bab":"باب العلل في الحديث."},{"id":"risala-shafii:380","bookId":"risala-shafii","type":"section","seq":380,"chapter":"الجزء الثاني.","title":"ص: 315","page":"ج1 ص313","text":"البيع بينه وبين بيعه الآخر، فيكون الآخر قد أفسد على البائع وعلى المشتري، أو على أحدهما.\nفهذا وجه النهي عن أن يبيع الرجل على بيع أخيه، لا وجه له غير ذلك.\nألا ترى أنه لو باعه ثوبا بعشرة دنانير، فلزمه البيع قبل أن يتفرقا من مقامهما ذلك، ثم باعه آخر خيرا منه بدينار: لم يضر البائع الأول، لأنه قد لزمه عشرة دنانير لا يستطيع فسخها؟!\nقال: وقد روي عن النبي أنه قال: \"لا يسوم أحدكم على سوم أخيه \" (3) ، فإن كان ثابتا، ولست أحفظه ثابتا، فهو مثل: \" لا يخطب أحدكم على خطبة أخيه \"، لا يسوم على سومه إذا رضي البيع وأذن بأن يباع قبل البيع، حتى لو بيع لزمه.\nفإن قال قائل: ما دل على ذلك؟\nفإن رسول الله باع فيمن يزيد، وبيع من يزيد سوم رجل على سوم أخيه، ولكن البائع لم يرض السوم الأول حتى طلب الزيادة.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:381","bookId":"risala-shafii","type":"section","seq":381,"chapter":"الجزء الثاني.","title":"النهي عن معنى يشبه الذي قبله في شيء ويفارقه في شيء غيره","page":"ج1 ص313","text":"أخبرنا \"مالك\" عن \"محمد بن يحيى بن حبان\" عن \"الأعرج\" عن \"أبي هريرة\": \" أن رسول الله نهى عن الصلاة بعد العصر حتى تغرب الشمس، وعن الصلاة بعد الصبح حتى تطلع الشمس \" (1) .\nأخبرنا \"مالك\" عن \"نافع\" عن \"ابن عمر\" أن رسول الله قال:","bab":"باب العلل في الحديث."},{"id":"risala-shafii:382","bookId":"risala-shafii","type":"section","seq":382,"chapter":"الجزء الثاني.","title":"ص: 317","page":"ج1 ص315","text":"\" لا يتحرى (2) أحدكم بصلاته عند طلوع الشمس ولا عند غروبها \" (3) .\nأخبرنا \"مالك\" عن \"زيد بن أسلم\" عن \"عطاء بن يسار\" عن \"عبد الله الصنابحي\"، أن رسول الله قال: \" إن الشمس تطلع","bab":"باب العلل في الحديث."},{"id":"risala-shafii:383","bookId":"risala-shafii","type":"section","seq":383,"chapter":"الجزء الثاني.","title":"ص: 320","page":"ج1 ص315","text":"ومعها قرن الشيطان، فإذا ارتفعت فارقها، ثم إذا استوت قارنها، فإذا زالت فارقها، ثم إذا دنت للغروب قارنها، فإذا غربت فارقها، ونهى رسول الله عن الصلاة في تلك الساعات \" (4) .\nفاحتمل النهي من رسول الله عن الصلاة في هذه الساعات معنيين:\n- أحدهما: - وهو أعمهما - أن تكون الصلوات كلها، واجبها الذي نسي ونيم عنه، وما لزم بوجه من الوجوه منها: محرما في هذه الساعات، لا يكون لأحد أن يصلي فيها، ولو صلى لم يؤدي (5) ذلك عنه ما لزمه من الصلاة، كما يكون من قدم صلاة قبل دخول وقتها لم تجزي عنه.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:384","bookId":"risala-shafii","type":"section","seq":384,"chapter":"الجزء الثاني.","title":"ص: 321","page":"ج1 ص315","text":"واحتمل أن يكون أراد به بعض الصلاة دون بعض.\nفوجدنا الصلاة تتفرق بوجهين: أحدهما: ما وجب منها فلم يكن لمسلم تركه في وقته، ولو تركه كان عليه قضاه، والآخر: ما تقرب إلى الله بالتنقل فيه، وقد كان للمتنقل تركه بلا قضا له عليه.\nووجدنا الواجب عليه منها يفارق التطوع في السفر إذا كان المرء راكبا، فيصلي المكتوبة بالأرض، لا يجزئه غيرها، والنافلة راكبا متوجها حيث شاء.\nومفرقان في الحضر والسفر، ولا يكون لمن أطاق","bab":"باب العلل في الحديث."},{"id":"risala-shafii:385","bookId":"risala-shafii","type":"section","seq":385,"chapter":"الجزء الثاني.","title":"ص: 322","page":"ج1 ص315","text":"القيام أن يصلي واجبا من الصلاة قاعدا، ويكون ذلك له في النافلة.\nفلما احتمل المعنيين، وجب على أهل العلم أن لا يحملوها على خاص دون عام إلا بدلالة، من سنة رسول الله، أو إجماع علماء المسلمين، الذين لا يمكن أن يجمعوا على خلاف سنة له.\nقال: وهكذا غير هذا من حديث رسول الله، هو على الظاهر من العام حتى تأتي الدلالة عنه كما وصفت، أو بإجماع المسلمين: أنه على باطن دون ظاهر، وخاص دون عام، فيجعلونه بما جاءت عليه الدلالة عليه، ويطيعونه في الأمرين جميعا.\nأخبرنا \"مالك\" عن \"زيد بن أسلم\" عن \"عطاء بن يسار\" وعن \"بسر بن سعيد\" وعن \"الأعرج\" يحدثونه عن \"أبي هريرة\" أن رسول الله","bab":"باب العلل في الحديث."},{"id":"risala-shafii:386","bookId":"risala-shafii","type":"section","seq":386,"chapter":"الجزء الثاني.","title":"ص: 323","page":"ج1 ص315","text":"قال: \" من أدرك ركعة من الصبح قبل أن تطلع الشمس فقد أدرك الصبح، ومن أدرك ركعة من العصر قبل أن تغرب الشمس فقد أدرك العصر \" (1) .\nقال \"الشافعي\": فالعلم يحيط أن المصلي ركعة من الصبح قبل طلوع الشمس والمصلي ركعة من العصر قبل غروب الشمس، قد صليا معا في وقتين يجمعان تحريم وقتين، وذلك أنهما صليا بعد الصبح والعصر، ومع بزوغ الشمس ومغيبها، وهذه أربعة أوقات منهي عن الصلاة فيها.\nلما جعل رسول الله المصلين في هذه الأوقات مدركين لصلاة الصبح والعصر، استدللنا على أن نهيه عن الصلاة في هذه الأوقات على النوافل التي لا تلزم، وذلك أنه لا يكون","bab":"باب العلل في الحديث."},{"id":"risala-shafii:387","bookId":"risala-shafii","type":"section","seq":387,"chapter":"الجزء الثاني.","title":"ص: 324","page":"ج1 ص315","text":"أن يجعل المرء مدركا لصلاة في وقت نهي فيه عن الصلاة.\nأخبرنا \"مالك\" عن \"ابن شهاب\" عن \"ابن المسيب\" أن رسول الله قال: \" من نسي صلاة فليصلها إذا ذكرها، فإن الله يقول: \" أقم الصلاة لذكري (14) \" [طه] \" (2) .\nوحدث \"أنس بن مالك\" و\"عمران بن حصين\" عن النبي مثل معنى حديث \"ابن المسيب\"، وزاد أحدهما: \" أو نام عنها \".\nقال \"الشافعي\": فقال رسول الله: \" فليصلها إذا","bab":"باب العلل في الحديث."},{"id":"risala-shafii:388","bookId":"risala-shafii","type":"section","seq":388,"chapter":"الجزء الثاني.","title":"ص: 325","page":"ج1 ص315","text":"ذكرها \"، فجعل ذلك وقتا لها، وأخبر به عن الله - تبارك وتعالى - ولم يستثني (3) وقتا من الأوقات يدعها فيه بعد ذكرها.\nأخبرنا \"ابن عيينة\" عن \"أبي الزبير\" عن \"عبد الله بن باباه\" عن \"جبير بن مطعم\" أن النبي قال: \" يا بني عبد مناف، من ولي منكم من أمر الناس شيئا فلا يمنعن أحدا طاف بهذا البيت وصلى، أي ساعة شاء، من ليل أو نهار \" (4) .\nأخبرنا \"عبد المجيد\" عن \"ابن جريج\" عن","bab":"باب العلل في الحديث."},{"id":"risala-shafii:389","bookId":"risala-shafii","type":"section","seq":389,"chapter":"الجزء الثاني.","title":"ص: 326","page":"ج1 ص315","text":"\"عطاء\" عن النبي مثل معناه، وزاد فيه: \" يا بني عبد المطلب، يا بني عبد مناف \"، ثم ساق الحديث.\nقال: فأخبر \"جبير\" عن النبي، أنه أمر بإباحة الطواف بالبيت والصلاة له في أي ساعة شاء الطائف والمصلي.\nوهذا يبين أنه إنما نهى عن المواقيت التي نهى عنها، عن الصلاة التي لا تلزم بوجه من الوجوه، فأما ما لزم فلم ينه عنه، بل أباحه، صلى الله عليه.\nوصلى المسلمون على جنائزهم عامة بعد العصر والصبح، لأنها لازمة.\nوقد ذهب بعض أصحابنا إلى أن \"عمر بن الخطاب\"","bab":"باب العلل في الحديث."},{"id":"risala-shafii:390","bookId":"risala-shafii","type":"section","seq":390,"chapter":"الجزء الثاني.","title":"ص: 327","page":"ج1 ص322","text":"طاف بعد الصبح، ثم نظر فلم يرى (1) الشمس طلعت، فركب حتى أتى ذا طوى وطلعت الشمس، فأناخ فصلى: فنهى عن الصلاة للطواف بعد العصر وبعد الصبح، كما نهى عما لا يلزم من الصلاة.\nقال: فإذا كان \"لعمر\" أن يؤخر الصلاة للطواف، فإنما تركها لأن ذلك له، ولأنه لو أراد منزلا بذي طوى لحاجة كان واسعا له - إن شاء الله -، ولكن سمع النهي جملة عن الصلاة، وضرب \"المنكدر\" عليها بالمدينة بعد العصر، ولم يسمع ما يدل على أنه","bab":"باب العلل في الحديث."},{"id":"risala-shafii:391","bookId":"risala-shafii","type":"section","seq":391,"chapter":"الجزء الثاني.","title":"ص: 328","page":"ج1 ص322","text":"إنما نهى عنها للمعنى الذي وصفنا، فكان يجب عليه ما فعل.\nويجب على من علم المعنى الذي نهى عنه والمعنى الذي أبيحت فيه: أن إباحتها بالمعنى الذي أباحها فيه خلاف المعنى الذي نهى فيه عنها، كما وصفت مما روى \"علي\" عن النبي من النهي عن إمساك لحوم الضحايا بعد ثلاث، إذ سمع النهي ولم يسمع سبب النهي.\nقال: فإن قال قائل: فقد صنع \"أبو سعيد الخدري\" كما صنع \"عمر\"؟\nقلنا: والجواب فيه كالجواب في غيره.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:392","bookId":"risala-shafii","type":"section","seq":392,"chapter":"الجزء الثاني.","title":"ص: 329","page":"ج1 ص326","text":"قال: فإن قال قائل: فهل من أحد صنع خلاف ما صنعا؟\nقيل: نعم، \"ابن عمر\"، و\"ابن عباس\"، و\"عائشة\"، و\"الحسن\"، و\"الحسين\"، وغيرهم، وقد سمع \"ابن عمر\" النهي من النبي.\nأخبرنا \"ابن عيينة\" عن \"عمرو بن دينار\" قال: رأيت أنا و\"عطاء بن أبي رباح\" \"ابن عمر\" طاف بعد الصبح، وصلى قبل أن تطلع الشمس.\n\"سفيان\" عن \"عمار الدهني\" عن \"أبي شعبة\": أن \"الحسن\" و\"الحسين\" طافا بعد العصر وصليا.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:393","bookId":"risala-shafii","type":"section","seq":393,"chapter":"الجزء الثاني.","title":"ص: 330","page":"ج1 ص326","text":"أخبرنا \"مسلم\" و\"عبد المجيد\" عن \"ابن جريج\" عن \"ابن أبي مليكة\" قال: رأيت \"ابن عباس\" طاف بعد العصر وصلى.\nقال: وإنما ذكرنا تفرق أصحاب رسول الله في هذا ليستدل من علمه على أن تفرقهم فيما لرسول الله فيه سنة: لا يكون إلا على هذا المعنى، أو على أن لا تبلغ السنة من قال خلافها منهم، أو تأويل تحتمله السنة، أو ما أشبه ذلك، مما قد يرى قائله له فيه عذرا، إن شاء الله.\nوإذا ثبت عن رسول الله الشيء فهو اللازم لجميع من عرفه، لا يقويه ولا يوهنه شيء غيره، بل الفرض الذي على الناس اتباعه، ولم يجعل الله لأحد معه أمرا يخالف أمره.","bab":"باب العلل في الحديث."},{"id":"risala-shafii:394","bookId":"risala-shafii","type":"section","seq":394,"chapter":"الجزء الثاني.","title":"باب آخر.","page":"ج1 ص328","text":"أخبرنا \"مالك\" عن \"نافع\" عن \"ابن عمر\": \" أن رسول الله نهى عن المزابنة. والمزابنة: بيع الثمر بالتمر كيلا، وبيع الكرم بالزبيب كيلا \" (1) .\nأخبرنا \"مالك\" عن \"عبد الله بن يزيد\" مولى \"الأسود","bab":"باب آخر."},{"id":"risala-shafii:395","bookId":"risala-shafii","type":"section","seq":395,"chapter":"الجزء الثاني.","title":"ص: 332","page":"ج1 ص330","text":"بن سفيان\" أن \"زيدا أبا عياش\" أخبره عن \"سعد بن أبي وقاص\": \" أنه سمع النبي سئل عن شراء التمر بالرطب؟ فقال النبي: أينقص الرطب إذا يبس؟ قالوا: نعم، فنهى عن ذلك \" (2) .","bab":"باب آخر."},{"id":"risala-shafii:396","bookId":"risala-shafii","type":"section","seq":396,"chapter":"الجزء الثاني.","title":"ص: 333","page":"ج1 ص330","text":"أخبرنا \"مالك\" عن \"نافع\" عن \"ابن عمر\" عن \"زيد بن ثابت\": أن رسول الله رخص لصاحب العرية أن يبيعها بخرصها \" (3) .\nأخبرنا \"ابن عيينة\" عن \"الزهري\" عن \"سالم\" عن أبيه عن \"زيد بن ثابت\": \" أن النبي رخص في العرايا \" (4) .","bab":"باب آخر."},{"id":"risala-shafii:397","bookId":"risala-shafii","type":"section","seq":397,"chapter":"الجزء الثاني.","title":"ص: 334","page":"ج1 ص330","text":"قال \"الشافعي\": فكان بيع الرطب بالتمر منهيا عنه، لنهي النبي، وبين رسول الله أنه إنما نهى عنه لأنه ينقص إذا يبس، وقد نهى عن التمر بالتمر إلا مثلا بمثل، فلما نظر في المتعقب من نقصان الرطب إذا يبس، كان لا يكون أبدا مثلا بمثل، إذ كان النقصان مغيبا لا يعرف، فكان يجمع معنيين: أحدهما التفاضل في المكيلة؛ والآخر المزابنة، وهي بيع ما يعرف كيله بما يجهل كيله من جنسه، فكان منهيا لمعنيين\nفلما رخص رسول الله في بيع العرايا بالتمر كيلا لم تعدوا العرايا أن تكون رخصة من شيء نهي عنه، أو لم يكن النهي عنه: عن المزابنة والرطب بالتمر: إلا مقصودا بهما إلى غير","bab":"باب آخر."},{"id":"risala-shafii:398","bookId":"risala-shafii","type":"section","seq":398,"chapter":"الجزء الثاني.","title":"ص: 335","page":"ج1 ص330","text":"العرايا، فيكون هذا من الكلام العام الذي يراد به الخاص.","bab":"باب آخر."},{"id":"risala-shafii:399","bookId":"risala-shafii","type":"section","seq":399,"chapter":"الجزء الثاني.","title":"وجه يشبه المعنى الذي قبله.","page":"ج1 ص331","text":"وأخبرنا \"سعيد بن سالم\" عن \"ابن جريج\" عن \"عطاء\" عن \"صفوان بن موهب\" أنه أخبره عن \"عبد الله بن محمد بن صيفي\" عن \"حكيم بن حزام\" أنه قال: \" قال لي","bab":"باب آخر."},{"id":"risala-shafii:400","bookId":"risala-shafii","type":"section","seq":400,"chapter":"الجزء الثاني.","title":"ص: 336","page":"ج1 ص335","text":"رسول الله: ألم أنبأ، - أو ألم يبلغني، أو كما شاء الله من ذلك: أنك تبيع الطعام؟ قال \"حكيم\": بلى يا رسول الله. فقال رسول الله: لا تبيعن طعاما حتى تشتريه وتستوفيه \" (1) .\nأخبرنا \"سعيد\" عن \"ابن جريج\" قال: أخبرني \"عطاء\" ذلك أيضا عن \"عبد الله بن عصمة\" عن \"حكيم بن حزام\" أنه سمعه منه عن النبي.\nأخبرنا الثقة عن \"أيوب بن أبي تميمة\" عن \"يوسف","bab":"باب آخر."},{"id":"risala-shafii:401","bookId":"risala-shafii","type":"section","seq":401,"chapter":"الجزء الثاني.","title":"ص: 337","page":"ج1 ص335","text":"بن ماهك\" عن \"حكيم بن حزام\" قال: \" نهاني رسول الله عن بيع ما ليس عندي\" (2) .\nيعني بيع ما ليس عندك، وليس بمضمون عليك.\nأخبرنا \"ابن عيينة\" عن \"ابن أبي نجيح\" عن \"عبد الله بن كثير\" عن \"أبي المنهال\" عن \"ابن عباس\" قال: \" قدم رسول الله","bab":"باب آخر."},{"id":"risala-shafii:402","bookId":"risala-shafii","type":"section","seq":402,"chapter":"الجزء الثاني.","title":"ص: 338","page":"ج1 ص335","text":"المدينة وهم يسلفون في التمر السنة والسنتين، فقال رسول الله: من سلف فليسلف في كيل معلوم ووزن معلوم وأجل معلوم \" (3) .\nقال \"الشافعي\": حفظي: \" وأجل معلوم \".\nوقال: غيري قد قال ما قلت، وقال: \" أو إلى أجل معلوم \".","bab":"باب آخر."},{"id":"risala-shafii:403","bookId":"risala-shafii","type":"section","seq":403,"chapter":"الجزء الثاني.","title":"ص: 339","page":"ج1 ص335","text":"قال: فكان نهي النبي أن يبيع المرء ما ليس عنده، يحتمل أن يبيع ما ليس بحضرته يراه المشتري كما يراه البائع عند تبايعهما فيه، ويحتمل أن يبيعه ما ليس عنده: ما ليس يملك بعينه،","bab":"باب آخر."},{"id":"risala-shafii:404","bookId":"risala-shafii","type":"section","seq":404,"chapter":"الجزء الثاني.","title":"ص: 340","page":"ج1 ص335","text":"فلا يكون موصوفا مضمونا على البائع يؤخذ به، ولا في ملكه: فيلزم أن يسلمه إليه بعينه، وغير هذين المعنيين.\nفلما أمر رسول الله من سلف أن يسلف في كيل معلوم ووزن معلوم وأجل معلوم، أو إلى أجل معلوم: دخل هذا بيع ما ليس عند المرء حاضرا ولا مملوكا حين باعه.\nولما كان هذا مضمونا على البائع بصفة يؤخذ بها عند محل الأجل: دل على أنه إنما نهى عن بيع عين الشيء في ملك البائع، والله أعلم.\nوقد يحتمل أو يكون النهي عن بيع العين الغائبة،","bab":"باب آخر."},{"id":"risala-shafii:405","bookId":"risala-shafii","type":"section","seq":405,"chapter":"الجزء الثاني.","title":"ص: 341","page":"ج1 ص335","text":"كانت في ملك الرجل أو في غير ملكه، لأنها قد تهلك وتنقص قبل أن يراها المشتري.\nقال: فكل كلام كان عاما ظاهرا في سنة رسول الله فهو على ظهوره وعمومه، حتى يعلم حديث ثابت عن رسول الله - بأبي هو وأمي - يدل على أنه إنما أريد بالجملة العامة في الظاهر بعض الجملة دون بعض، كما وصفت من هذا وما كان في مثل معناه.\nولزم أهل العلم أن يمضوا الخبرين على وجوههما، ما وجدوا لإمضائهما وجها، ولا يعدونهما مختلفين وهما يحتملان أن يمضيا، وذلك إذا أمكن فيهما أن يمضيا معا، أو وجد السبيل إلى إمضائهما، ولم يكن منهما واحد بأوجب من الآخر.","bab":"باب آخر."},{"id":"risala-shafii:406","bookId":"risala-shafii","type":"section","seq":406,"chapter":"الجزء الثاني.","title":"ص: 342","page":"ج1 ص335","text":"ولا ينسب الحديثان إلى الاختلاف، ما كان لهما وجها (1) يمضيان معا، إنما المختلف ما لم يمضى (2) إلا بسقوط غيره، مثل أن يكون الحديثان في الشيء الواحد، هذا يحله وهذا يحرمه.","bab":"باب آخر."},{"id":"risala-shafii:407","bookId":"risala-shafii","type":"section","seq":407,"chapter":"الجزء الثاني.","title":"صفة نهي الله ونهي رسوله","page":"ج1 ص341","text":"(1)\nفقال: فصف لي جماع نهي الله - جل ثناؤه - ثم نهي النبي: عاما، لا تبق منه شيئا.\nفقلت له: يجمع نهيه معنيين:\n- أحدهما: أن يكون الشيء الذي نهى عنه محرما، لا يحل إلا بوجه دل الله عليه في كتابه، أو على لسان نبيه.\nفإذا نهى رسول الله عن الشيء من هذا فالنهي محرم، لا وجه له غير التحريم، إلا أن يكون على معنى، كما وصفت.\nقال: فصف لي هذا الوجه الذي بدأت بذكره من","bab":"باب آخر."},{"id":"risala-shafii:408","bookId":"risala-shafii","type":"section","seq":408,"chapter":"الجزء الثاني.","title":"ص: 344","page":"ج1 ص342","text":"النهي، بمثال يدل على ما كان في مثل معناه.\nقال: فقلت له: كل النساء محرمات الفروج، إلا بواحد من المعنيين: النكاح والوطئ بملك اليمين، وهما المعنيان اللذان أذن الله فيهما. وسن رسول الله كيف النكاح الذي يحل به الفرج المحرم قبله، فسن فيه وليا وشهودا ورضا من المنكوحة الثيب، وسنته في رضاها دليل على أن ذلك يكون برضا المتزوج، لا فرق بينهما.\nفإذا جمع النكاح أربعا: رضا المزوجة الثيب، والمزوج، وأن يزوج المرأة وليها بشهود: حل النكاح، إلا في حالات سأذكرها، إن شاء الله.\nوإذا نقص النكاح واحد من هذا كان","bab":"باب آخر."},{"id":"risala-shafii:409","bookId":"risala-shafii","type":"section","seq":409,"chapter":"الجزء الثاني.","title":"ص: 345","page":"ج1 ص342","text":"النكاح فاسدا، لأنه لم يؤت به كما سن رسول الله فيه الوجه الذي يحل به النكاح.\nولو سمى صداقا كان أحب إلي، ولا يفسد النكاح بترك تسمية الصداق، لأن الله أثبت النكاح في كتابه بغير مهر، وهذا مكتوب في غير هذا الموضع.\nقال: وسواء في هذا المرأة الشريفة والدنية، لأن كل واحد منهما، فيما يحل به ويحرم، ويجب لها وعليها، من الحلال والحرام والحدود، سواء.\nوالحالات التي لو أتي بالنكاح فيها على ما وصفت","bab":"باب آخر."},{"id":"risala-shafii:410","bookId":"risala-shafii","type":"section","seq":410,"chapter":"الجزء الثاني.","title":"ص: 346","page":"ج1 ص343","text":"أنه يجوز النكاح، فيما لم ينه فيها عنها من النكاح. فأما إذا عقد بهذه الأشياء كان النكاح مفسوخا، بنهي الله في كتابه وعلى لسان نبيه عن النكاح بحالات نهى عنها، فذلك مفسوخ.\nوذلك: أن ينكح الرجل أخت امرأته، وقد نهى الله عن الجمع بينهما، وأن ينكح الخامسة، وقد انتهى الله به إلى أربع، فبين","bab":"باب آخر."},{"id":"risala-shafii:411","bookId":"risala-shafii","type":"section","seq":411,"chapter":"الجزء الثاني.","title":"ص: 347","page":"ج1 ص343","text":"النبي أن انتهاء الله به إلى أربع حظر عليه أن يجمع بين أكثر منهن، أو ينكح المرأة على عمتها أو خالتها، وقد نهى النبي عن ذلك، وأن ينكح المرأة في عدتها.\nفكل نكاح كان من هذا لم يصح، وذلك أنه قد نهي عن عقده، وهذا ما لا خلاف فيه بين أحد من أهل العلم.\nومثله - والله أعلم - أن النبي نهى عن الشغار (1) ، وأن النبي نهى عن نكاح المتعة (2) ، وأن النبي نهى المحرم أن ينكح أو ينكح.\nفنحن نفسخ هذا كله من النكاح، في هذه الحالات التي نهى عنها، بمثل ما فسخنا به ما نهى عنه مما ذكر قبله.","bab":"باب آخر."},{"id":"risala-shafii:412","bookId":"risala-shafii","type":"section","seq":412,"chapter":"الجزء الثاني.","title":"ص: 348","page":"ج1 ص345","text":"وقد يخالفنا في هذا غيرنا، وهو مكتوب في غير هذا الموضع. (3)\nومثله: أن ينكح المرأة بغير إذنها، فتجيز بعد، فلا يجوز، لأن العقد وقع منهيا عنه.\nومثل هذا ما نهى عنه رسول الله من بيع الغرر، وبيع الرطب بالتمر إلا في العرايا، أو غير ذلك مما نهى عنه.\nوذلك أن أصل مال كل امرئ محرم على غيره، إلا بما أحل به، وما أحل به من البيوع ما لم ينه عنه رسول الله، ولا يكون ما نهى عنه رسول الله من البيوع محلا ما كان أصله محرما","bab":"باب آخر."},{"id":"risala-shafii:413","bookId":"risala-shafii","type":"section","seq":413,"chapter":"الجزء الثاني.","title":"ص: 349","page":"ج1 ص347","text":"من مال الرجل لأخيه، ولا تكون المعصية بالبيع المنهي عنه تحل محرما، ولا تحل إلا بما لا يكون معصية، وهذا يدخل في عامة العلم.\nفإن قال قائل: ما الوجه المباح الذي نهي المرء فيه عن شيء، وهو يخالف النهي الذي ذكرت قبله؟\nفهو - إن شاء الله - مثل نهي رسول الله أن يشتمل الرجل على الصماء (1) ، وأن يحتبي في ثوب واحد مفضيا بفرجه","bab":"باب آخر."},{"id":"risala-shafii:414","bookId":"risala-shafii","type":"section","seq":414,"chapter":"الجزء الثاني.","title":"ص: 350","page":"ج1 ص348","text":"إلى السماء، وأنه أمر غلاما أن يأكل مما بين يديه، ونهاه أن يأكل من أعلى الصحفة، ويروى عنه، وليس كثبوت ما قبله مما ذكرنا: أنه نهى عن أن يقرن الرجل إذا أكل بين التمرتين، وأن يكشف التمرة عما في جوفها، وأن يعرس على ظهر الطريق.","bab":"باب آخر."},{"id":"risala-shafii:415","bookId":"risala-shafii","type":"section","seq":415,"chapter":"الجزء الثاني.","title":"ص: 351","page":"ج1 ص348","text":"فلما كان الثوب مباحا للابس، والطعام مباحا لآكله، حتى يأتي عليه كله إن شاء، والأرض مباحة له إذا كانت لله لا لآدمي، وكان الناس فيها شرعا، (2) فهو نهي فيها عن شيء أن يفعله، وأمر فيها بأن يفعل شيئا غير الذي نهي عنه.\nوالنهي يدل على أنه إنما نهى عن اشتمال الصماء والاحتباء مفضيا بفرجه غير مستتر: أن في ذلك كشف عورته، قيل له يسترها بثوبه، فلم يكن نهيه عن كشف عورته نهيه عن لبس ثوبه فيحرم عليه لبسه، بل أمره أن يلبسه كما يستر عورته.","bab":"باب آخر."},{"id":"risala-shafii:416","bookId":"risala-shafii","type":"section","seq":416,"chapter":"الجزء الثاني.","title":"ص: 352","page":"ج1 ص348","text":"ولم يكن أمره أن يأكل من بين يديه ولا يأكل من رأس الطعام، إذا كان مباحا له أن يأكل ما بين يديه وجميع الطعام: إلا أدبا في الأكل من بين يديه، لأنه أجمل به عند مواكله، وأبعد له من قبح الطعمة والنهم، وأمره ألا يأكل من رأس الطعام لأن البركة تنزل منه له، على النظر له في أن يبارك له بركة دائمة يدوم نزولها له، وهو يبيح له إذا أكل ما حول رأس الطعام أن يأكل رأسه.\nوإذا أباح له الممر على ظهر الطريق فالممر عليه إذ كان مباحا","bab":"باب آخر."},{"id":"risala-shafii:417","bookId":"risala-shafii","type":"section","seq":417,"chapter":"الجزء الثاني.","title":"ص: 353","page":"ج1 ص348","text":"لأنه لا مالك له يمنع الممر عليه فيحرم بمنعه: فإنما نهاه لمعنى يثبت نظرا له، فإنه قال: \" فإنها مأوى الهوام، وطرق الحيات \" (3) ، على النظر له، لا على أن التعريس محرم، وقد ينهى عنه إذا كانت الطريق متضايقا مسلوكا، لأنه إذا عرس عليه في ذلك الوقت منع غيره حقه في الممر.\nفإن قال قائل: فما الفرق بين هذا والأول؟\nقيل له: من قامت عليه الحجة يعلم أن النبي نهى عما وصفنا، ومن فعل ما نهي عنه - وهو عالم بنهيه - فهو عاص بفعله ما نهي عنه، وليستغفر الله ولا يعود (1) .\nفإن قال: فهذا عاص، والذي ذكرت في الكتاب","bab":"باب آخر."},{"id":"risala-shafii:418","bookId":"risala-shafii","type":"section","seq":418,"chapter":"الجزء الثاني.","title":"ص: 354","page":"ج1 ص349","text":"قبله في النكاح والبيوع عاص، فكيف فرقت بين حالهما؟\nفقلت: أما في المعصية فلم أفرق بينهما، لأني قد جعلتهما عاصيين، وبعض المعاصي أعظم من بعض.\nفإن قال: فكيف لم تحرم على هذا لبسه وأكله وممره على الأرض بمعصيته، وحرمت على الآخر نكاحه وبيعه بمعصيته؟\nقيل: هذا أمر بأمر في مباح حلال له، فأحللت له ما حل له، وحرمت عليه ما حرم عليه، وما حرم عليه غير ما أحل له، ومعصيته في الشيء المباح له لا تحرمه عليه بكل حال، ولكن تحرم عليه أن يفعل فيه المعصية.\nفإن قيل: فما مثل هذا؟\nقيل له: الرجل له الزوجة والجارية، وقد نهي أن يطأهما حائضتين وصائمتين، ولو فعل لم يحل ذلك الوطء له","bab":"باب آخر."},{"id":"risala-shafii:419","bookId":"risala-shafii","type":"section","seq":419,"chapter":"الجزء الثاني.","title":"ص: 355","page":"ج1 ص349","text":"في حاله تلك، ولم تحرم واحدة منهما عليه في حال غير تلك الحال، إذا كان أصلهما مباحا وحلالا.\nوأصل مال الرجل محرم على غيره إلا بما أبيح به مما يحل، وفروج النساء محرمات إلا بما أبيحت به من النكاح والملك، فإذا عقد عقدة النكاح أو البيع منهيا عنها على محرم لا يحل إلا بما أحل به، لم يحل المحرم بمحرم، وكان على أصل تحريمه، حتى يؤتى بالوجه الذي أحله الله به في كتابه، أو على لسان رسوله، أو إجماع المسلمين، أو ما هو في مثل معناه.\nقال: وقد مثلت قبل هذا: النهي الذي أريد به غير التحريم بالدلائل، فاكتفيت من ترديده، وأسأل الله العصمة والتوفيق.","bab":"باب آخر."},{"id":"risala-shafii:420","bookId":"risala-shafii","type":"section","seq":420,"chapter":"الجزء الثاني.","title":"باب العلم","page":"ج1 ص353","text":"(1)\nقال \"الشافعي\": فقال لي قائل: ما العلم؟ وما يجب على الناس في العلم؟\nفقلت له: العلم علمان: علم عامة، لا يسع بالغا غير مغلوب على عقله جهله.\nقال: ومثل ماذا؟\nقلت: مثل الصلوات الخمس، وأن لله على الناس صوم شهر رمضان، وحج البيت إذا استطاعوه، وزكاة في أموالهم، وأنه حرم عليهم الزنا والقتل والسرقة والخمر، وما كان في معنى","bab":"باب العلم"},{"id":"risala-shafii:421","bookId":"risala-shafii","type":"section","seq":421,"chapter":"الجزء الثاني.","title":"ص: 358","page":"ج1 ص355","text":"هذا، مما كلف العباد أن يعقلوه ويعملوه ويعطوه من أنفسهم وأموالهم، وأن يكفوا عنه ما حرم عليهم منه.\nوهذا الصنف كله من العلم موجود نصا في كتاب الله، وموجودا (2) عاما عند أهل الإسلام، ينقله عوامهم عن من مضى من عوامهم، يحكونه عن رسول الله، ولا يتنازعون في حكايته ولا وجوبه عليهم.","bab":"باب العلم"},{"id":"risala-shafii:422","bookId":"risala-shafii","type":"section","seq":422,"chapter":"الجزء الثاني.","title":"ص: 359","page":"ج1 ص355","text":"وهذا العلم العام الذي لا يمكن فيه الغلط من الخبر، ولا التأويل، ولا يجوز فيه التنازع.\nقال: فما الوجه الثاني؟\nقلت له: ما ينوب العباد من فروع الفرائض، وما يخص به من الأحكام وغيرها، مما ليس فيه نص كتاب، ولا في أكثره نص سنة، وإن كانت في شيء منه سنة فإنما هي من أخبار الخاصة، لا أخبار العامة، وما كان منه يحتمل التأويل ويستدرك قياسا.\nقال: فيعدو هذا أن يكون واجبا وجوب العلم قبله؟ أو موضوعا عن الناس علمه، حتى يكون من علمه منتفلا،","bab":"باب العلم"},{"id":"risala-shafii:423","bookId":"risala-shafii","type":"section","seq":423,"chapter":"الجزء الثاني.","title":"ص: 360","page":"ج1 ص355","text":"ومن ترك علمه غير آثم بتركه، أو من وجه ثالث، فتوجدناه خبرا أو قياسا؟\nفقلت له: بل هو من وجه ثالث.\nقال: فصفه واذكر الحجة فيه، ما يلزم منه، ومن يلزم، وعن من يسقط؟\nفقلت له: هذه درجة من العلم ليس تبلغها العامة، ولم يكلفها كل الخاصة، ومن احتمل بلوغها من الخاصة فلا يسعهم كلهم كافة أن يعطلوها، وإذا قام بها من خاصتهم من فيه الكفاية لم يحرج غيره ممن تركها، إن شاء الله، والفضل فيها لمن قام بها على من عطلها.\nفقال: فأوجدني هذا خبرا أو شيئا في معناه، ليكون هذا قياسا عليه؟","bab":"باب العلم"},{"id":"risala-shafii:424","bookId":"risala-shafii","type":"section","seq":424,"chapter":"الجزء الثاني.","title":"ص: 361","page":"ج1 ص357","text":"فقلت له: فرض الله الجهاد في كتابه وعلى لسان نبيه، ثم أكد النفير من الجهاد، فقال: \" إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة يقاتلون في سبيل الله فيقتلون ويقتلون وعدا عليه حقا في التوراة والإنجيل والقرآن، ومن أوفى بعهده من الله فاستبشروا ببيعكم الذي بايعتم به، وذلك هو الفوز العظيم (111) \" [التوبة] .\nوقال: \" وقاتلوا المشركين كافة كما يقاتلونكم كافة واعلموا أن الله مع المتقين (36) \" [التوبة] .\nوقال: \" فاقتلوا المشركين حيث وجدتموهم وخذوهم واحصروهم واقعدوا لهم كل مرصد فإن تابوا وأقاموا الصلاة وآتوا الزكاة فخلوا سبيلهم إن الله غفور رحيم (5) \" [التوبة] .\nوقال: \" قاتلوا الذين لا يؤمنون بالله ولا باليوم الآخر ولا يحرمون ما حرم الله ورسوله ولا يدينون دين الحق","bab":"باب العلم"},{"id":"risala-shafii:425","bookId":"risala-shafii","type":"section","seq":425,"chapter":"الجزء الثاني.","title":"ص: 362","page":"ج1 ص357","text":"من الذين أوتوا الكتاب حتى يعطوا الجزية عن يد وهم صاغرون (29) \" [التوبة] .\nأخبرنا \"عبد العزيز\" عن \"محمد بن عمرو\" عن \"أبي سلمة\" عن \"أبي هريرة\" قال: قال رسول الله: \" لا أزال أقاتل الناس حتى يقولوا لا إله إلا الله، فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها، وحسابهم على الله \" (1) .\nوقال الله - جل ثناؤه -: \" ما لكم إذا قيل لكم انفروا في سبيل الله اثاقلتم إلى الأرض؟ أرضيتم بالحياة الدنيا من الآخرة؟ فما متاع الحياة الدنيا في الآخرة إلا قليل (38) إلا تنفروا يعذبكم عذابا أليما ويستبدل قوما غيركم ولا تضروه شيئا والله على كل شيء قدير (39) \" [التوبة] .\nوقال: \" انفروا خفافا وثقالا وجاهدوا بأموالكم","bab":"باب العلم"},{"id":"risala-shafii:426","bookId":"risala-shafii","type":"section","seq":426,"chapter":"الجزء الثاني.","title":"ص: 363","page":"ج1 ص357","text":"وأنفسكم في سبيل الله ذلكم خير لكم إن كنتم تعلمون (41) \" [التوبة] .\nقال: فاحتملت الآيات أن يكون الجهاد كله والنفير خاصة منه: على كل مطيق له، لا يسع أحدا منهم التخلف عنه، كما كانت الصلوات والحج والزكاة، فلم يخرج أحد وجب عليه فرض منها من أن يؤدي غيره الفرض عن نفسه، لأن عمل أحد في هذا لا يكتب لغيره.\nواحتملت أن يكون معنى فرضها غير معنى فرض الصلوات، وذلك أن يكون قصد بالفرض فيها قصد الكفاية، فيكون من قام بالكفاية في جهاد من جوهد من المشركين مدركا تأدية الفرض ونافلة الفضل، ومخرجا من تخلف من المأثم.\nولم يسوي (2) الله بينهما، فقال الله: \" لا يستوي القاعدون من المؤمنين غير أولي الضرر والمجاهدون في سبيل الله","bab":"باب العلم"},{"id":"risala-shafii:427","bookId":"risala-shafii","type":"section","seq":427,"chapter":"الجزء الثاني.","title":"ص: 364","page":"ج1 ص357","text":"بأموالهم وأنفسهم، فضل الله المجاهدين بأموالهم وأنفسهم على القاعدين درجة، وكلا وعد الله الحسنى، وفضل الله المجاهدين على القاعدين أجرا عظيما (95) \" [النساء] ، فأما الظاهر في الآيات فالفرض على العامة.\nقال: فأبن الدلالة في أنه إذا قام بعض العامة بالكفاية أخرج المتخلفين من المأثم؟\nفقلت له: في هذه الآية.\nقال: وأين هو منها؟","bab":"باب العلم"},{"id":"risala-shafii:428","bookId":"risala-shafii","type":"section","seq":428,"chapter":"الجزء الثاني.","title":"ص: 365","page":"ج1 ص360","text":"قلت: قال الله: \" وكلا وعد الله الحسنى \"، فوعد المتخلفين عن الجهاد الحسنى على الإيمان، وأبان فضيلة المجاهدين على القاعدين، ولو كانوا آثمين بالتخلف إذا غزا غيرهم: كانت العقوبة بالإثم - إن لم يعفو الله - أولى بهم من الحسنى.\nقال: فهل تجد في هذا غير هذا؟\nقلت: نعم، قال الله: \" وما كان المؤمنون لينفروا كافة فلولا نفر من كل فرقة منهم طائفة ليتفقهوا في الدين ولينذروا قومهم إذا رجعوا إليهم لعلهم يحذرون (122) \" [التوبة] ، وغزا رسول الله، وغزى معه من أصحابه جماعة وخلف أخرى، حتى تخلف","bab":"باب العلم"},{"id":"risala-shafii:429","bookId":"risala-shafii","type":"section","seq":429,"chapter":"الجزء الثاني.","title":"ص: 366","page":"ج1 ص360","text":"\"علي بن أبي طالب\" في غزوة تبوك، وأخبرنا الله أن المسلمين لم يكونوا لينفروا كافة: \" فلولا نفر من كل فرقة منهم طائفة \"، فأخبر أن النفير على بعضهم دون بعض، وأن التفقه إنما هو على بعضهم دون بعض.\nوكذلك ما عدا الفرض في عظم الفرائض التي لا يسع جهلها، والله أعلم.\nوهكذا كل ما كان الفرض فيه مقصودا به قصد الكفاية فيما ينوب، فإذا قام به من المسلمين من فيه الكفاية خرج من تخلف عنه من المأثم.\nولو ضيعوه معا خفت أن لا يخرج واحد منهم مطيق فيه من المأثم، بل لا أشك، إن شاء الله، لقوله: \" إلا تنفروا يعذبكم عذابا أليما \".","bab":"باب العلم"},{"id":"risala-shafii:430","bookId":"risala-shafii","type":"section","seq":430,"chapter":"الجزء الثاني.","title":"ص: 367","page":"ج1 ص360","text":"قال: فما معناها؟\nقلت: الدلالة عليها أن تخلفهم عن النفير كافة لا يسعهم، ونفير بعضهم - إذا كانت في نفيره كفاية - يخرج من تخلف من المأثم، إن شاء الله، لأنه إذا نفر بعضهم وقع عليهم اسم \"النفير\".\nقال: ومثل ماذا سوى الجهاد؟\nقلت: الصلاة على الجنازة ودفنها، لا يحل تركها، ولا يجب على كل من بحضرتها كلهم حضورها، ويخرج من تخلف من المأثم من قام بكفايتها.","bab":"باب العلم"},{"id":"risala-shafii:431","bookId":"risala-shafii","type":"section","seq":431,"chapter":"الجزء الثاني.","title":"ص: 368","page":"ج1 ص364","text":"وهكذا رد السلام، قال الله: \" وإذا حييتم بتحية فحيوا بأحسن منها أو ردوها إن الله كان على كل شيء حسيبا (86) \" [النساء] .\nوقال رسول الله: \" يسلم القائم على القاعد \" (1) ، و\" إذا سلم من القوم واحد أجزأ عنهم \" (2) ، وإنما أريد بهذا الرد، فرد القليل جامع لاسم \"الرد\"، والكفاية فيه مانع لأن يكون الرد معطلا.\nولم يزل المسلمون على ما وصفت، منذ بعث الله نبيه - فيما بلغنا - إلى اليوم، يتفقه أقلهم، ويشهد الجنائز بعضهم، ويجاهد ويرد السلام بعضهم، ويتخلف عن ذلك غيرهم، فيعرفون","bab":"باب العلم"},{"id":"risala-shafii:432","bookId":"risala-shafii","type":"section","seq":432,"chapter":"الجزء الثاني.","title":"ص: 369","page":"ج1 ص364","text":"الفضل لمن قام بالفقه والجهاد وحضور الجنائز ورد السلام، ولا يؤثمون من قصر عن ذلك، إذا كان بهذا قائمون بكفايته.","bab":"باب العلم"},{"id":"risala-shafii:433","bookId":"risala-shafii","type":"section","seq":433,"chapter":"الجزء الثاني.","title":"باب خبر الواحد] .","page":"ج1 ص367","text":"فقال لي قائل: احدد لي أقل ما تقوم به الحجة على أهل العلم، حتى يثبت عليهم خبر الخاصة.\nفقلت: خبر الواحد عن الواحد حتى ينتهى به إلى","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:434","bookId":"risala-shafii","type":"section","seq":434,"chapter":"الجزء الثاني.","title":"ص: 370","page":"ج1 ص369","text":"النبي أو من انتهى به إليه دونه.\nولا تقوم الحجة بخبر الخاصة حتى يجمع أمورا:\n- منها أن يكون من حدث به ثقة في دينه، معروفا بالصدق في حديثه، عاقلا لما يحدث به، عالما بما يحيل معاني الحديث من اللفظ، وأن يكون ممن يؤدي الحديث بحروفه كما سمع، لا يحدث به على المعنى، لأنه إذا حدث على المعنى وهو غير","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:435","bookId":"risala-shafii","type":"section","seq":435,"chapter":"الجزء الثاني.","title":"ص: 371","page":"ج1 ص369","text":"عالم بما يحيل به معناه: لم يدر لعله يحيل الحلال إلى الحرام، وإذا أداه بحروفه فلم يبق وجه يخاف فيه إحالته الحديث، حافظا إن حدث به من حفظه، حافظا لكتابه إن حدث من كتابه. إذا شرك أهل الحفظ في حديث وافق حديثهم، بريا من أن يكون مدلسا، يحدث عن من لقي ما لم يسمع منه، ويحدث عن النبي ما يحدث الثقات خلافه عن النبي.\nويكون هكذا من فوقه ممن حدثه، حتى ينتهى بالحديث موصولا إلى النبي أو إلى من انتهي به إليه دونه، لأن كل","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:436","bookId":"risala-shafii","type":"section","seq":436,"chapter":"الجزء الثاني.","title":"ص: 372","page":"ج1 ص369","text":"واحد منهم مثبت لمن حدثه، ومثبت على من حدث عنه، فلا يستغنى في كل واحد منهم عما وصفت.\nفقال: فأوضح لي من هذا بشيء لعلي أكون به أعرف مني بهذا، لخبرتي به وقلة خبرتي بما وصفت في الحديث؟\nفقلت له: أتريد أن أخبرك بشيء يكون هذا قياسا عليه؟\nقال: نعم.\nقلت: هذا أصل في نفسه، فلا يكون قياسا على غيره، لأن القياس أضعف من الأصل.\nقال: فلست أريد أن تجعله قياسا، ولكن مثله لي على شيء من الشهادات، التي العلم بها عام.\nقلت: قد يخالف الشهادات في أشياء، ويجامعها في غيرها.","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:437","bookId":"risala-shafii","type":"section","seq":437,"chapter":"الجزء الثاني.","title":"ص: 373","page":"ج1 ص369","text":"قال: وأين يخالفها؟\nقلت: أقبل في الحديث الواحد والمرأة، ولا أقبل واحدا منهما وحده في الشهادة.\nوأقبل في الحديث: (حدثني فلان عن فلان) ، إذا لم يكن مدلسا، ولا أقبل في الشهادة إلا: (سمعت) أو (رأيت) أو (أشهدني) .\nوتختلف الأحاديث، فآخذ ببعضها، استدلالا بكتاب أو سنة أو إجماع أو قياس، وهذا لا يؤخذ به في الشهادات هكذا، ولا يوجد فيها بحال.\nثم يكون بشر كلهم تجوز شهادته ولا أقبل حديثه، من قبل ما يدخل في الحديث من كثرة الإحالة، وإزالة بعض ألفاظ المعاني.\nثم هو يجامع الشهادات في أشياء غير ما وصفت.\nفقال: أما ما قلت من ألا تقبل الحديث إلا عن ثقة حافظ عالم بما يحيل معنى الحديث: فكما قلت، فلم لم تقل هكذا في الشهادات؟\nفقلت: إن إحالة معنى الحديث أخفى من إحالة معنى الشهادة، وبهذا احتطت في الحديث بأكثر مما احتطت به في الشهادة.\nقال: وهكذا كما وصفت، ولكني أنكرت - إذا كان من يحدث عنه ثقة فحدث عن رجل لم تعرف أنت ثقته -:","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:438","bookId":"risala-shafii","type":"section","seq":438,"chapter":"الجزء الثاني.","title":"ص: 375","page":"ج1 ص369","text":"امتناعك من أن تقلد الثقة، فتحسن الظن به، فلا تتركه يروي إلا عن ثقة، وإن لم تعرفه أنت؟!\nفقلت له: أرأيت أربعة نفر عدول فقهاء شهدوا على شهادة شاهدين بحق لرجل على رجل: أكنت قاضيا به ولم يقل لك الأربعة: إن الشاهدين عدلان؟\nقال: لا، ولا أقطع بشهادتهما شيئا حتى أعرف عدلهما، إما بتعديل الأربعة لهما، وإما بتعديل غيرهم، أو معرفة مني بعدلهما.\nفقلت له: ولم لم تقبلهما على المعنى الذي أمرتني أن أقبل عليه الحديث، فتقول: لم يكونوا ليشهدوا إلا على من هو أعدل عندهم؟\nفقال: قد يشهدون على من هو عدل عندهم، ومن","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:439","bookId":"risala-shafii","type":"section","seq":439,"chapter":"الجزء الثاني.","title":"ص: 376","page":"ج1 ص369","text":"عرفوه ولم يعرفوا عدله، فلما كان هذا موجودا في شهادتهم لم يكن لي قبول شهادة من شهدوا عليه حتى يعدلوه، أو أعرف عدله وعدل من شهد عندي على عدل غيره، ولا أقبل تعديل شاهد على شاهد عدل الشاهد غيره ولم أعرف عدله.\nفقلت: فالحجة في هذا لك الحجة عليك: في ألا تقبل خبر الصادق عن من جهلنا صدقه.\nوالناس من أن يشهدوا على شهادة من عرفوا عدله: أشد تحفظا منهم من أن يقبلوا إلا حديث من عرفوا صحة حديثه.\nوذلك: أن الرجل يلقى الرجل يرى عليه سيما الخير، فيحسن الظن به، فيقبل حديثه، ويقبله وهو لا يعرف","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:440","bookId":"risala-shafii","type":"section","seq":440,"chapter":"الجزء الثاني.","title":"ص: 377","page":"ج1 ص369","text":"حاله، فيذكر أن رجلا يقال له: (فلان) حدثني كذا، إما على وجه يرجو أن يجد علم ذلك الحديث عند ثقة فيقبله عن الثقة، وإما أن يحدث به على إنكاره والتعجب منه، وإما بغفلة في الحديث عنه.\nولا أعلمني لقيت أحدا قط بريا من أن يحدث عن ثقة حافظ وآخر يخالفه.\nففعلت في هذا ما يجب علي.\nولم يكن طلبي الدلائل على معرفة صدق من حدثني بأوجب علي من طلبي ذلك على معرفة صدق من فوقه، لأني أحتاج في كلهم إلى ما أحتاج إليه فيمن لقيت منهم، لأن كلهم مثبت خبرا عن من فوقه ولمن دونه.\nفقال: فما بالك قبلت ممن لم تعرفه بالتدليس أن يقول: (عن) ، وقد يمكن فيه أن يكون لم يسمعه؟\nفقلت له: المسلمون العدول عدول أصحاء الأمر في أنفسهم، وحالهم في أنفسهم غير حالهم في غيرهم، ألا ترى أني إذا عرفتهم بالعدل في أنفسهم قبلت شهادتهم، وإذا شهدوا على شهادة غيرهم لم أقبل شهادة غيرهم حتى أعرف حاله؟! ولم تكن معرفتي عدلهم معرفتي عدل من شهدوا على شهادته.\nوقولهم عن خبر أنفسهم وتسميتهم: على الصحة، حتى نستدل من فعلهم بما يخالف ذلك، فنحترس منهم في الموضع الذي خالف فعلهم فيه ما يجب عليهم.\nولم نعرف بالتدليس ببلدنا، فيمن مضى ولا من","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:441","bookId":"risala-shafii","type":"section","seq":441,"chapter":"الجزء الثاني.","title":"ص: 379","page":"ج1 ص374","text":"أدركنا من أصحابنا، إلا حديثا فإن منهم من قبله عن من لو تركه عليه كان خيرا له.\nوكان قول الرجل: (سمعت فلانا يقول سمعت فلانا) وقوله: (حدثني فلان عن فلان) : سواء عندهم، لا يحدث واحد منهم عن من لقي إلا ما سمع منه ممن عناه بهذه الطريق، قبلنا منه: (حدثني فلان عن فلان) .\nومن عرفناه دلس مرة فقد أبان لنا عورته في روايته.\nوليست تلك العورة بالكذب فنرد بها حديثه، ولا النصيحة في الصدق، فنقبل منه ما قبلنا من أهل النصيحة في الصدق.","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:442","bookId":"risala-shafii","type":"section","seq":442,"chapter":"الجزء الثاني.","title":"ص: 380","page":"ج1 ص374","text":"فقلنا: لا نقبل من مدلس حديثا حتى يقول فيه: (حدثني) أو (سمعت) .\nفقال: قد أراك تقبل شهادة من لا يقبل حديثه؟\nقال: فقلت: لكبر أمر الحديث وموقعه من المسلمين، ولمعنى بين.\nقال: وما هو؟\nقلت: تكون اللفظة تترك من الحديث فتحيل معناه، أو ينطق بها بغير لفظة المحدث، والناطق بها غير عامد لإحالة الحديث: فيحيل معناه.\nفإذا كان الذي يحمل الحديث يجهل هذا المعنى، كان غير عاقل للحديث، فلم نقبل حديثه، إذا كان يحمل ما لا يعقل، إن","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:443","bookId":"risala-shafii","type":"section","seq":443,"chapter":"الجزء الثاني.","title":"ص: 381","page":"ج1 ص378","text":"كان ممن لا يؤدي الحديث بحروفه، وكان يلتمس تأديته على معانيه، وهو لا يعقل المعنى.\nقال: أفيكون عدلا غير مقبول الحديث؟\nقلت: نعم، إذا كان كما وصفت كان هذا موضع ظنة بينة يرد بها حديثه، وقد يكون الرجل عدلا على غيره ظنينا في نفسه وبعض أقربيه، ولعله أن يخر من بعد أهون عليه من أن يشهد بباطل، ولكن الظنة لما دخلت عليه تركت بها شهادته، فالظنة ممن لا يؤدي الحديث بحروفه ولا يعقل معانيه: أبين منها في الشاهد لمن ترد شهادته فيما هو ظنين فيه بحال.\nوقد يعتبر على الشهود فيما شهدوا فيه، فإن استدللنا على ميل نستبينه أو حياطة بمجاوزة قصد للمشهود له:","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:444","bookId":"risala-shafii","type":"section","seq":444,"chapter":"الجزء الثاني.","title":"ص: 382","page":"ج1 ص378","text":"لم نقبل شهادتهم، وإن شهدوا في شيء مما يدق ويذهب فهمه عليهم في مثل ما شهدوا عليه: لم نقبل شهادتهم، لأنهم لا يعقلون معنى ما شهدوا عليه.\nومن كثر غلطه من المحدثين ولم يكن له أصل كتاب صحيح: لم نقبل حديثه، كما يكون من أكثر الغلط في الشهادة لم نقبل شهادته.\nوأهل الحديث متباينون:\n- فمنهم المعروف بعلم الحديث، بطلبه وسماعه من الأب والعم وذوي الرحم والصديق، وطول مجالسة أهل التنازع فيه، ومن كان هكذا كان مقدما في الحفظ، إن خالفه من يقصر","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:445","bookId":"risala-shafii","type":"section","seq":445,"chapter":"الجزء الثاني.","title":"ص: 383","page":"ج1 ص378","text":"عنه كان أولى أن يقبل حديثه ممن خالفه من أهل التقصير عنه.\nويعتبر على أهل الحديث بأن إذا اشتركوا في الحديث عن الرجل بأن يستدل على حفظ أحدهم بموافقة أهل الحفظ، وعلى خلاف حفظه بخلاف حفظ أهل الحفظ له.\nوإذا اختلفت الرواية استدللنا على المحفوظ منها والغلط بهذا، ووجوه سواه، تدل على الصدق والحفظ والغلط، قد بيناها في غير هذا الموضع، وأسأل الله التوفيق.\nفقال: فما الحجة لك في قبول خبر الواحد وأنت لا تجيز شهادة واحد وحده؟ وما حجتك في أن قسته بالشهادة في أكثر أمره، وفرقت بينه وبين الشهادة في بعض أمره؟","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:446","bookId":"risala-shafii","type":"section","seq":446,"chapter":"الجزء الثاني.","title":"ص: 384","page":"ج1 ص380","text":"قال: فقلت له: أنت تعيد ما قد ظننتك فرغت منه!! ولم أقسه بالشهادة، إنما سألت أن أمثله لك بشيء تعرفه، أنت به أخبر منك بالحديث، فمثلته لك بذلك الشيء، لا أني احتجت لأن يكون قياسا عليه.\nوتثبيت خبر الواحد أقوى من أن أحتاج إلى أن أمثله بغيره، بل هو أصل في نفسه.\nقال: فكيف يكون الحديث كالشهادة في شيء، ثم يفارق بعض معانيها في غيره؟\nفقلت له: هو مخالف للشهادة - كما وصفت لك - في بعض أمره، ولو جعلته كالشهادة في بعض أمره دون بعض كانت الحجة لي فيه بينة، إن شاء الله.","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:447","bookId":"risala-shafii","type":"section","seq":447,"chapter":"الجزء الثاني.","title":"ص: 385","page":"ج1 ص380","text":"قال: وكيف ذلك، وسبيل الشهادات سبيل واحدة؟\nقال: فقلت: أتعني في بعض أمرها دون بعض؟ أم في كل أمرها؟\nقال: بل في كل أمرها.\nقلت: فكم أقل ما تقبل على الزنا؟\nقال: أربعة.\nقلت: فإن نقصوا واحد جلدتهم؟\nقال: نعم.\nقلت: فكم تقبل على القتل والكفر وقطع الطريق الذي تقتل به كله؟\nقال: شاهدين.\nقلت له: كم تقبل على المال؟","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:448","bookId":"risala-shafii","type":"section","seq":448,"chapter":"الجزء الثاني.","title":"ص: 386","page":"ج1 ص380","text":"قال: شاهدا وامرأتين.\nقلت: فكم تقبل في عيوب النساء؟\nقال: امرأة.\nقلت: ولو لم يتموا شاهدين وشاهدا وامرأتين: لم تجلدهم كما جلدت شهود الزنا؟\nقال: نعم.\nقلت: أفتراها مجتمعة؟\nقال: نعم، في أن أقبلها متفرقة في عددها. وفي أن لا يجلد إلا شاهد الزنا.\nقلت له: فلو قلت لك هذا في خبر الواحد، وهو مجامع للشهادة في أن أقبله، ومفارق لها في عدده، هل كانت لك حجة إلا كهي عليك؟!","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:449","bookId":"risala-shafii","type":"section","seq":449,"chapter":"الجزء الثاني.","title":"ص: 387","page":"ج1 ص380","text":"قال: فإنما قلت بالخلاف بين عدد الشهادات خبرا واستدلالا.\nقلت: وكذلك قلت في قبول خبر الواحد خبرا واستدلالا.\nوقلت: أرأيت شهادة النساء في الولادة، لم أجزتها ولا تجيزها في درهم؟\nقال: اتباعا.\nقلت: فإن قيل لك: لم يذكر في القرآن أقل من شاهد وامرأتين؟","bab":"باب خبر الواحد] ."},{"id":"risala-shafii:450","bookId":"risala-shafii","type":"section","seq":450,"chapter":"الجزء الثالث.","title":"الجزء الثالث.","page":"ج1 ص383","text":"قال \"أبو القاسم عبد الرحمن بن نصر\"قال: نا \"أبو علي الحسن بن حبيب\"\nقال: نا \"الربيع بن سليمان\"قال: أنا الشافعي:\nبسم الله الرحمن الرحيم\nقال: ولم يحظر أن يجوز أقل من ذلك، فأجزنا ما أجاز المسلمون، ولم يكن هذا خلافا للقرآن.\nقلنا: فهكذا قلنا في تثبيت خبر الواحد، استدلالا بأشياء كلها أقوى من إجازة شهادة النساء.\nفقال: فهل من حجة تفرق بين الخبر والشهادة سوى الاتباع؟\nقلت: نعم، ما لا أعلم من أهل العلم فيه مخالفا."},{"id":"risala-shafii:451","bookId":"risala-shafii","type":"section","seq":451,"chapter":"الجزء الثالث.","title":"ص: 391","page":"ج1 ص390","text":"قال: وما هو؟\nقلت: العدل يكون جائز الشهادة في أمور، مردودها في أمور.\nقال: فأين هو مردودها؟\nقلت: إذا شهد في موضع يجر به إلى نفسه زيادة، من أي وجه ما كان الجر، أو يدفع بها عن نفسه غرما أو إلى ولده أو والده، أو يدفع بها عنهما، ومواضع الظنن سواها.\nوفيه في الشهادة: أن الشاهد إنما يشهد بها على واحد ليلزمه غرما أو عقوبة، وللرجل ليؤخذ له غرم أو عقوبة،"},{"id":"risala-shafii:452","bookId":"risala-shafii","type":"section","seq":452,"chapter":"الجزء الثالث.","title":"ص: 392","page":"ج1 ص390","text":"وهو خلي مما لزم غيره من غرم، غير داخل في غرمه ولا عقوبته، ولا العار الذي لزمه، ولعله يجر ذلك إلى من لعله أن يكون أشد تحاملا له منه لولده أو والده، فيقبل شهادته، لأنه لا ظنة ظاهرة كظنته في نفسه وولده ووالده، وغير ذلك مما يبين فيه من مواضع الظنن.\nوالمحدث بما يحل ويحرم لا يجر إلى نفسه ولا إلى غيره، ولا يدفع عنها ولا عن غيره، شيئا مما يتمول الناس، ولا مما فيه عقوبة عليهم ولا لهم، وهو ومن حدثه ذلك الحديث من المسلمين: سواء، إن كان بأمر يحل أو يحرم فهو شريك العامة فيه، لا تختلف حالاته فيه، فيكون ظنينا مرة مردود الخبر، وغير ظنين أخرى مقبول الخبر، كما تختلف حال الشاهد لعوام المسلمين وخواصهم."},{"id":"risala-shafii:453","bookId":"risala-shafii","type":"section","seq":453,"chapter":"الجزء الثالث.","title":"ص: 393","page":"ج1 ص390","text":"وللناس حالات تكون أخبارهم فيها أصح وأحرى أن يحضرها التقوى منها في أخرى، ونيات ذوي النيات فيها أصح، وفكرهم فيها أدوم، وغفلتهم أقل، وتلك عند خوف الموت بالمرض والسفر، وعند ذكره، وغير تلك الحالات من الحالات المنبهة عن الغفلة.\nفقلت له: قد يكون غير ذي الصدق من المسلمين صادقا في هذه الحالات، وفي أن يؤتمن على خبر، فيرى أنه يعتمد على خبره فيه، فيصدق غاية الصدق، إن لم يكن تقوى فحياء من أن ينصب لأمانة في خبر لا يدفع به عن نفسه ولا يجر إليها: ثم يكذب بعده، أو يدع التحفظ في بعض الصدق فيه."},{"id":"risala-shafii:454","bookId":"risala-shafii","type":"section","seq":454,"chapter":"الجزء الثالث.","title":"ص: 394","page":"ج1 ص390","text":"فإذا كان موجودا في العامة وفي أهل الكذب الحالات يصدقون فيها الصدق الذي تطيب به نفس المحدثين: كان أهل التقوى والصدق في كل حالاتهم أولى أن يتحفظوا عند أولى الأمور بهم أن يتحفظوا عندها، في أنهم وضعوا موضع الأمانة، ونصبوا أعلاما للدين، وكانوا عالمين بما ألزمهم الله من الصدق في كل أمر، وأن الحديث في الحلال والحرام أعلى الأمور وأبعدها من أن يكون فيه موضع ظنة، وقد قدم إليهم في الحديث عن رسول الله بشيء لم يقدم إليهم في غيره، فوعد على الكذب على رسول الله النار.\n\"عبد العزيز\" عن \"محمد بن عجلان\" عن \"عبد الوهاب بن"},{"id":"risala-shafii:455","bookId":"risala-shafii","type":"section","seq":455,"chapter":"الجزء الثالث.","title":"ص: 395","page":"ج1 ص390","text":"بخت\" عن \"عبد الواحد النصري\" عن \"واثلة بن الأسقع\" عن النبي قال: \" إن أفرى الفرى من قولني ما لم أقل، ومن أرى عينيه ما لم ترى، ومن ادعى إلى غير أبيه \" (1) ."},{"id":"risala-shafii:456","bookId":"risala-shafii","type":"section","seq":456,"chapter":"الجزء الثالث.","title":"ص: 396","page":"ج1 ص390","text":"\"عبد العزيز\" عن \"محمد بن عمرو\" عن \"أبي سلمة\" عن \"أبي هريرة\" أن رسول الله قال: \" من قال علي ما لم أقل فليتبوأ مقعده من النار \" (2) .\n\"يحيى بن سليم\" عن \"عبيد الله بن عمر\" عن \"أبي بكر بن سالم\" عن \"سالم\" عن \"ابن عمر\" أن النبي قال: \" إن الذي يكذب علي يبنى له بيت في النار \" (3) ."},{"id":"risala-shafii:457","bookId":"risala-shafii","type":"section","seq":457,"chapter":"الجزء الثالث.","title":"ص: 397","page":"ج1 ص390","text":"حدثنا \"عمرو بن أبي سلمة\" عن \"عبد العزيز بن محمد\" عن \"أسيد بن أبي أسيد\" عن أمه قالت: قلت \"لأبي قتادة\": ما لك لا تحدث عن رسثول الله كما يحدث الناس عنه؟ قالت: فقال: \"أبو قتادة\" سمعت رسول الله يقول: \" من كذب علي فليلتمس لجنبه مضجعا من النار، فجعل رسول الله يقول ذلك ويمسح الأرض بيده \" (4) .\n\"سفيان\" عن \"محمد بن عمرو\" عن \"أبي سلمة\" عن \"أبي هريرة\" أن رسول الله قال: \" حدثوا عن بني إسرائيل ولا حرج،"},{"id":"risala-shafii:458","bookId":"risala-shafii","type":"section","seq":458,"chapter":"الجزء الثالث.","title":"ص: 398","page":"ج1 ص390","text":"وحدثوا عني ولا تكذبوا علي \" (5) .\nوهذا أشد حديث روي عن رسول الله في هذا، وعليه اعتمدنا مع غيره في أن لا نقبل حديثا إلا من ثقة، ونعرف صدق من حمل الحديث من حين ابتدئ إلى أن يبلغ به منتهاه.\nفإن قال قائل وما في هذا الحديث من الدلالة على ما وصفت؟\nقيل: قد أحاط العلم أن النبي لا يأمر أحدا بحال أبدا أن يكذب على بني إسرائيل، ولا على غيرهم، فإذ أباح الحديث"},{"id":"risala-shafii:459","bookId":"risala-shafii","type":"section","seq":459,"chapter":"الجزء الثالث.","title":"ص: 399","page":"ج1 ص390","text":"عن بني إسرائيل أن يقبلوا الكذب على بني إسرائيل أباح، وإنما أباح قبول ذلك عن من حدث به ممن يجهل صدقه وكذبه.\nولم يبحه أيضا عن من يعرف كذبه لأنه يروى عنه أنه \"من حدث بحديث، وهو يراه كذبا فهو أحد الكاذبين \" (1) ومن حدث عن كذاب لم يبرأ من الكذب؛ لأنه يرى الكذاب في حديثه كاذبا\nولا يستدل على أكثر صدق الحديث وكذبه إلا بصدق المخبر وكذبه، إلا في الخاص القليل من الحديث، وذلك أن يستدل على الصدق والكذب فيه بأن يحدث المحدث ما لا يجوز أن يكون مثله، أو ما يخالفه ما هو أثبت وأكثر دلالات بالصدق منه."},{"id":"risala-shafii:460","bookId":"risala-shafii","type":"section","seq":460,"chapter":"الجزء الثالث.","title":"ص: 400","page":"ج1 ص390","text":"وإذ فرق رسول الله بين الحديث عنه، والحديث عن بني إسرائيل فقال: \"حدثوا عني ولا تكذبوا علي \": فالعلم - إن شاء الله - يحيط أن الكذب الذي نهاهم عنه هو الكذب الخفي. وذلك الحديث عمن لا يعرف صدقه؛ لأن الكذب إذا كان منهيا عنه على كل حال، فلا كذب أعظم من كذب على رسول الله صلى الله عليه وسلم"},{"id":"risala-shafii:461","bookId":"risala-shafii","type":"section","seq":461,"chapter":"الجزء الثالث.","title":"الحجة في تثبيت خبر الواحد","page":"ج1 ص398","text":"قال \"الشافعي: \"فإن قال قائل: اذكر الحجة في تثبيت خبر الواحد بنص خبر أو دلالة فيه أو إجماع.\nفقلت له أخبرنا سفيان عن عبد الملك بن عمير عن عبد الرحمن بن عبد الله بن مسعود عن أبيه أن النبي قال: \"نضر الله عبدا سمع مقالتي فحفظها ووعاها وأداها، فرب حامل فقه غير فقيه ورب حامل فقه إلى من هو أفقه منه. ثلاث لا يغل"},{"id":"risala-shafii:462","bookId":"risala-shafii","type":"section","seq":462,"chapter":"الجزء الثالث.","title":"ص: 402","page":"ج1 ص400","text":"(1) عليهن قلب مسلم: إخلاص العمل لله، والنصيحة للمسلمين، ولزوم، جماعتهم، فإن دعوتهم تحيط من روائهم\". (2)\nفلما ندب رسول الله إلى استماع مقالته وحفظها وأدائها امرأ يؤديها، والامرء واحد: دل على أنه لا يأمر"},{"id":"risala-shafii:463","bookId":"risala-shafii","type":"section","seq":463,"chapter":"الجزء الثالث.","title":"ص: 403","page":"ج1 ص400","text":"أن يؤدى عنه إلا ما تقوم به الحجة على من أدى إليه؛ لأنه إنما يؤدى عنه حلال وحرام يجتنب، وحد يقام، ومال يؤخذ ويعطى، ونصيحة في دين ودنيا.\nودل على أنه قد ححمل الفقه غير فقيه، يكون له حافظا، ولا يكون فيه فقيها.\nوأمر رسول الله بلزوم جماعة المسلمين مما يحتج به في أن إجماع المسلمين - إن شاء الله - لازم.\nأخبرنا سفيان قال أخبرني سالم أبو النضر أنه سمع عبيد الله بن أبي رافع يخبر عن أبيه قال: قال النبي: \"لا ألفين أحدكم متكئا على أريكته، يأتيه الأمر من أمري، مما نهيت عنه"},{"id":"risala-shafii:464","bookId":"risala-shafii","type":"section","seq":464,"chapter":"الجزء الثالث.","title":"ص: 404","page":"ج1 ص400","text":"أو أمرت به، فيقول: لا ندري، ما وجدنا في كتاب الله اتبعناه\" (3)\nقال ابن عيينة: وأخبرني محمد بن المنكدر عن النبي بمثله مرسلا.\nوفي هذا تثبيت الخبر عن رسول الله وإعلامهم أنه لازم لهم، وإن لم يجدوا له نص حكم في كتاب الله، وهو موضوع في غير هذا الموضع.\nأخبرنا مالك عن زيد بن أسلم عن عطاء بن يسار: أن رجلا قبل امرأته وهو صائم، فوجد من ذلك وجدا شديدا، فأرسل امرأته تسأل عن ذلك، فدخلت على أم سلمة أم المؤمنين، فأخبرتها، فقالت أم سلمة: إن رسول الله يقبل وهو صائم. فرجعت المرأة إلى زوجها فأخبرته، فزاده ذلك شرا، وقال: لسنا مثل رسول الله، يحل الله لرسوله ما شاء. فرجعت المرأة إلى"},{"id":"risala-shafii:465","bookId":"risala-shafii","type":"section","seq":465,"chapter":"الجزء الثالث.","title":"ص: 405","page":"ج1 ص400","text":"أم سلمة فوجدت رسول الله عندها، فقال رسول الله: ما بال هذه المرأة؟ فأخبرته أم سلمة، فقال: ألا أخبرتيها أني أفعل ذلك؟ فقالت أم سلمة: قد أخبرتها فذهبت إلى زوجها فأخبرته فزاده ذلك شرا، وقال: لسنامثل رسول الله، يحل الله لرسوله ما شاء. فغضب رسول الله ثم قال:\nوالله إني لأتقاكم لله، ولأعلمكم بحدوده\"\nوقد سمعت من يصل هذا الحديث، ولا يحضرني ذكر من وصله. (3)\nقال \"الشافعي: \"في ذكر قول النبي صلى الله عليه: \" ألا أخبرتيها أني أفعل ذلك\" دلالة على أن خبر أم سلمة عنه مما يجوز قبوله؛ لأنه لا يأمرها بأن تخبر عن النبي إلا وفي خبرها ما تكون الحجة لمن أخبرته.\nوهكذا خبر امرأته إن كانت من أهل الصدق عنده.\nأخبرنا مالك عن عبد الله بن دينار عن ابن عمر قال: \"بينما الناس بقباء في صلاة الصبح إذ أتاهم آت، فقال: إن رسول الله قد أنزل عليه قرآن وقد أمر أن يستقبل القبلة فاستقبلوها وكانت وجوههم إلى الشأم فاستداروا إلى الكعبة\"\nوأهل قباء أهل سابقة من الأنصار وفقه، وقد كانوا على قبلة فرض الله عليهم استقبالها."},{"id":"risala-shafii:466","bookId":"risala-shafii","type":"section","seq":466,"chapter":"الجزء الثالث.","title":"ص: 407","page":"ج1 ص401","text":"ولم يكن لهم أن يدعوا فرض الله في القبلة إلا بما تقوم عليهم الحجة، ولم يلقوا رسول الله، ولم يسمعوا ما أنزل الله عليه في تحويل القبلة، فيكونون مستقبلين بكتاب الله وسنة نبيه سماعا من رسول الله ولا بخبر عامة، وانتقلوا بخبر واحد، إذا كان عندهم من أهل الصدق: عن فرض كان عليهم، فتركوه إلى ما أخبرهم عن النبي أنه أحدث عليهم من تحويل القبلة.\nولم يكونوا ليفعلوه - إن شاء الله - بخبر إلا عن علم بأن الحجة تثبت بمثله، إذا كان من أهل الصدق."},{"id":"risala-shafii:467","bookId":"risala-shafii","type":"section","seq":467,"chapter":"الجزء الثالث.","title":"ص: 408","page":"ج1 ص401","text":"ولا ليحدثوا أيضا مثل هذا العظيم في دينهم إلا عن علم بأن لهم إحداثه.\nولا يدعون أن يخبروا رسول الله بما صنعوا منه.\nولو كان ما قبلوا من خبر الواحد عن رسول الله في تحويل القبلة، وهو فرض: مما يجوز لهم، لقال لهم - إن شاء الله - رسول الله: قد كنتم على قبلة، ولم يكن لكم تركها إلا بعد علم تقوم عليكم به حجة من سماعكم مني، أو خبر عامة أو أكثر من خبر واحد عني.\nأخبرنا مالك عن إسحاق بن عبد الله بن أبي طلحة"},{"id":"risala-shafii:468","bookId":"risala-shafii","type":"section","seq":468,"chapter":"الجزء الثالث.","title":"ص: 409","page":"ج1 ص401","text":"عن أنس بن مالك قال: كنت أسقي أبا طلحة وأبا عبيدة بن الجراح وأبي بن كعب شرابا من فضيخ (1) وتمر، فجاءهم آت فقال: إن الخمر قد حرمت. فقال أبو طلحة: قم يا أنس إلى هذه الجرار فاكسرها، فقمت إلى مهراس (2) لنا، فضربتها بأسفله حتى تكسرت\". (3)\nوهؤلاء في العلم والمكان من النبي وتقدم صحبته بالموضع الذي لا ينكره عالم.\nوقد كان الشراب عندهم حلالا يشربونه، فجاءهم آت وأخبرهم بتحريم الخمر، فأمر أبو طلحة - وهو مالك"},{"id":"risala-shafii:469","bookId":"risala-shafii","type":"section","seq":469,"chapter":"الجزء الثالث.","title":"ص: 410","page":"ج1 ص401","text":"الجرار - بكسر الجرار، ولم يقل هو، ولاهم، ولا واحد منهم: نحن على تحليلها حتى نلقى رسول الله مع قربه منا أو يأتينا خبر عامة.\nوذلك أنهم لا يهريقون حلالا، إهراقه سرف، وليسوا من أهله.\nوالحال في أنهم لا يدعون إخبار رسول الله ما فعلوا، ولا يدع - لو كان قبلوا من خبر الواحد ليس لهم -: أن ينهاهم عن قبوله.\nوأمر رسول الله أنيسا أن يغدو على امرأة رجل ذكر أنها زنت، فإن اعترفت فارجمها، فاعترفت فرجمها.\nوأخبرنا بذلك مالك وسفيان عن الزهري"},{"id":"risala-shafii:470","bookId":"risala-shafii","type":"section","seq":470,"chapter":"الجزء الثالث.","title":"ص: 411","page":"ج1 ص401","text":"عن عبيد الله بن عبد الله عن أبي هريرة وزيد بن خالد وساقا عن النبي. وزاد سفيان مع أبي هريرة وزيد بن خالد: شبلا. (4)\nأخبرنا عبد العزيز عن ابن الهاد عن عبد الله بن أبي سلمة عن عمرو بن سليم الزرقي عن أمه قالت: \"بينما"},{"id":"risala-shafii:471","bookId":"risala-shafii","type":"section","seq":471,"chapter":"الجزء الثالث.","title":"ص: 412","page":"ج1 ص401","text":"نحن بمنى إذا علي بن أبي طالب على جمل يقول: إن رسول الله يقول: إن هذه أيام طعام وشراب، فلا يصومن أحد، فاتبع الناس وهو على جمله يصرخ فيهم بذلك.\nورسول الله لا يبعث بنهيه واحدا صادقا إلا لزم خبره عن النبي، بصدقه عن المنهيين عن ما أخبرهم أن النبي نهى عنه.\nومع رسول الله الحاج، وقد كان قادرا على أن يبعث إليهم فيشافههم، أو يبعث إليهم عددا، فبعث واحدا يعرفونه بالصدق.\nوهو لا يبعث بأمره إلا والحجة للمبعوث إليهم وعليهم قائمة بقبول خبره عن رسول الله.\nفإذا كان هكذا مع ما وصفت من مقدرة النبي على بعثه جماعة إليهم: كان ذلك - إن شاء الله - فيمن بعده ممن لا يمكنه ما أمكنهم، وأمكن فيهم: أولى أن يثبت به خبر الصادق.\nأخبرنا سفيان عن عمرو بن دينار عن عمرو بن عبد الله بن صفوان عن خال له - إن شاء الله - يقال له: يزيد بن شيبان قال: كنا في موقف لنا بعرفة يباعده عمرو من موقف الإمام جدا، فأتانا ابن مربع الأنصاري فقال لنا: أنا"},{"id":"risala-shafii:472","bookId":"risala-shafii","type":"section","seq":472,"chapter":"الجزء الثالث.","title":"ص: 414","page":"ج1 ص405","text":"رسول رسول الله إليكم: يأمركم أن تقفوا على مشاعركم، فإنكم على إرث من إرث أبيكم إبراهيم.\nوبعث رسول الله أبا بكر واليا على الحج في سنة تسع، وحضره الحج من أهل بلدان مختلفة، وشعوب متفرقة، فأقام لهم مناسكهم، وأخبرهم عن رسول الله بما لهم وما عليهم.\nوبعث علي بن أبي طالب في تلك السنة، فقرأ عليهم في مجمعهم يوم النحر آيات من {سورة براءة} ، ونبذ إلى قوم على سواء وجعل لهم مددا، ونهاهم عن أمور."},{"id":"risala-shafii:473","bookId":"risala-shafii","type":"section","seq":473,"chapter":"الجزء الثالث.","title":"ص: 415","page":"ج1 ص405","text":"فكان أبو بكر وعلي معروفين عند أهل مكة بالفضل والدين والصدق، وكان من جهلهما أو أحدهما من الحاج وجد من يخبره عن صدقهما وفضلهما.\nولم يكن رسول الله ليبعث إلا واحدا الحجة قائمة بخبره على من بعثه إليه، إن شاء الله.\nوقد فرق النبي عمالا على نواحي، عرفنا أسماءهم، والمواضع التي فرقهم عليها.\nفبعث قيس بن عاصم والزبرقان بن بدر وابن نويرة إلى عشائرهم بعلمهم بصدقهم عندهم."},{"id":"risala-shafii:474","bookId":"risala-shafii","type":"section","seq":474,"chapter":"الجزء الثالث.","title":"ص: 416","page":"ج1 ص413","text":"وقدم عليهم وفد البحرين، فعرفوا من معه، فبعث معهم ابن سعيد بن العاص.\nوبعث معاذ بن جبل إلى اليمن، وأمره أن يقاتل من أطاعه من عصاه، ويعلمهم ما فرض الله عليهم، ويأخذ منهم ما وجب عليهم لمعرفتهم بمعاذ، ومكانه منهم وصدقه.\nوكل من ولى فقد أمره بأخذ ما أوجب الله على من ولاه عليه.\nولم يكن لأحد عندنا في أحد ممن قدم عليه من أهل"},{"id":"risala-shafii:475","bookId":"risala-shafii","type":"section","seq":475,"chapter":"الجزء الثالث.","title":"ص: 417","page":"ج1 ص413","text":"الصدق: أن يقول: أنت واحد وليس لك أن تأخذ منا ما لم نسمع رسول الله يذكر أنه علينا.\nولا أحسبه بعثهم مشهورين في النواحي التي بعثهم إليها بالصدق: إلا لما وصفت من أن تقوم بمثلهم الحجة على من بعثه إليه.\nوفي شبيه بهذا المعنى أمراء سرايا رسول الله: فقد بعث بعث مؤتة فولاه زيد بن حارثة، وقال: فإن أصيب فجعفر، فإن أصيب فابن رواحة. وبعث ابن أنيس سرية وحده.\nوبعث أمراء سراياه، وكلهم حاكم فيما بعثه فيه؛ لأن عليهم أن يدعوا من لم تبلغه الدعوة، ويقاتلوا من حل قتاله.\nوكذلك كل والي بعثه أو صاحب سرية."},{"id":"risala-shafii:476","bookId":"risala-shafii","type":"section","seq":476,"chapter":"الجزء الثالث.","title":"ص: 418","page":"ج1 ص413","text":"ولم يزل يمكنه أن يبعث واليين وثلاثة وأربعة وأكثر.\nوبعث في دهر واحد اثنى عشر رسولا إلى اثنى عشر ملكا، يدعوهم إلى الإسلام، ولم يبعثهم إلا إلى من قد بلغته الدعوة، وقامت عليه الحجة فيها، وألا يكتب فيها دلالات لمن بعثهم إليه على أنها كتبه.\nوقد تحرى فيهم ما تحرى في أمرائه: من أن يكونوا معروفين، فبعث دحية إلى الناحية التي هو فيها معروف.\nولو أن المبعوث إليه جهل الرسول كان عليه طلب علم أن النبي بعثه ليستبرىء شكه في خبر رسول الله، وكان على الرسول الوقوف حتى يستبرئه المبعوث إليه."},{"id":"risala-shafii:477","bookId":"risala-shafii","type":"section","seq":477,"chapter":"الجزء الثالث.","title":"ص: 419","page":"ج1 ص415","text":"ولم تزل كتب رسول الله تنفذ إلى ولاته بالأمر والنهي، ولم يكن لأحد من ولاته ترك إنفاذ أمره، ولم يكن ليبعث رسولا إلا صادقا عند من بعثه إليه.\nوإذا طلب المبعوث إليه علم صدقه وجده حيث هو.\nولو شك في كتابه بتغيير في الكتاب أو حال تدل على تهمة، من غفلة رسول حمل الكتاب: كان عليه أن يطلب علم ما شك فيه حتى ينفذ ما يثبت عنده من أمر رسول الله.\nوهكذا كانت كتب خلفائه بعده وعمالهم، وما أجمع المسلمون عليه: من أن يكون الخليفة واحدا والقاضي واحد، والأمير واحد، والإمام.\nفاستخلفوا أبا بكر، ثم استخلف أبو بكر عمر،"},{"id":"risala-shafii:478","bookId":"risala-shafii","type":"section","seq":478,"chapter":"الجزء الثالث.","title":"ص: 420","page":"ج1 ص415","text":"ثم عمر أهل الشورى ليختاروا واحدا، فاختار عبد الرحمن عثمان بن عفان.\nقال: والولاة من القضاة وغيرهم يقضون، فتنفذ أحكامهم، ويقيمون الحدود، وينفذ من بعدهم أحكامهم، وأحكامهم أخبار عنهم.\nففيما وصفت من سنة رسول الله، ثم ما أجمع المسلمون عليه منه: دلالة على فرق بين الشهادة والخبر والحكم.\nألا ترى أن قضاء القاضي على الرجل للرجل إنما هو خبر يخبر به عن بينة تثبت عنده، أو إقرار من خصم به أقر عنده،"},{"id":"risala-shafii:479","bookId":"risala-shafii","type":"section","seq":479,"chapter":"الجزء الثالث.","title":"ص: 421","page":"ج1 ص418","text":"وأنفذ الحكم فيه، فلما كان يلزمه بخبره أن ينفذه بعلمه كان في معنى المخبر بحلال وحرام، قد لزمه أن يحله ويحرمه بما شهد منه.\nولو كان القاضي المخبر عن شهود شهدوا عنده على رجل لم يحاكم إليه، أو إقرار من خصم لا يلزمه أن يحكم به، لمعنى أن لم يخاصم إليه، أو أنه ممن يخاصم إلى غيره، فحكم بينه وبين خصمه ما يلزم شاهدا يشهد على رجل أن يأخذ منه ما شهد به عليه لمن شهد له به: كان في معنى شاهد عند غيره، فلم يقبل - قاضيا كان أو غيره - إلا بشاهد معه كما لو شهد عند غيره لم يقبله إلا بشاهد، وطلب معه غيره، ولم يكن لغيره إذا كان شاهدا أن ينفذ شهادته وحده."},{"id":"risala-shafii:480","bookId":"risala-shafii","type":"section","seq":480,"chapter":"الجزء الثالث.","title":"ص: 422","page":"ج1 ص418","text":"أخبرنا سفيان وعبد الوهاب عن يحيى بن سعيد عن سعيد بن المسيب: أن عمر بن الخطاب قضى في الإبهام بخمس عشرة، وفي التي تليها بعشر، وفي الوسطى بعشر، وفي التي تلي الخنصر بتسع، وفي الخنصر بست.\nقال \"الشافعي\": لما كان معروفا - والله أعلم - عند عمر أن النبي قضى في اليد بخمسين وكانت اليد خمسة أطراف مختلفة الجمال والمنافع: نزلها منازلها، فحكم لكل واحد من الأطراف بقدره من دية الكف، فهذا قياس (1) على الخبر.\nفلما وجدنا كتاب آل عمرو بن حزم فيه: أن رسول الله قال: وفي كل إصبع مما هنالك عشر من الإبل صاروا إليه.\nولم يقبلوا كتاب آل عمرو بن حزم - والله أعلم -"},{"id":"risala-shafii:481","bookId":"risala-shafii","type":"section","seq":481,"chapter":"الجزء الثالث.","title":"ص: 423","page":"ج1 ص418","text":"حتى يثبت لهم أنه كتاب رسول الله.\nوفي الحديث دلالتان: أحدهما: قبول الخبر، والآخر: أن يقبل الخبر في الوقت الذي يثبت فيه، وإن لم يمضي (2) عمل من الأئمة بمثل الخبر الذي قبلوا."},{"id":"risala-shafii:482","bookId":"risala-shafii","type":"section","seq":482,"chapter":"الجزء الثالث.","title":"ص: 424","page":"ج1 ص418","text":"ودلالة على أنه مضى أيضا عمل من أحد من الأئمة، ثم وجد خبرا عن النبي يخالف عمله لترك عمله لخبر رسول الله.\nودلالة على أن حديث رسول الله يثبت بنفسه لا بعمل غيره بعده.\nولم يقل المسلمون قد عمل فينا عمر بخلاف هذا بين المهاجرين والأنصار، ولم تذكروا أنتم أن عندكم خلافه ولا غيركم، بل صاروا إلى ما وجب عليهم، من قبول الخبر عن رسول الله، وترك كل عمل خالفه.\nولو بلغ عمر هذا صار إليه - إن شاء الله - كما صار إلى غيره فيما بلغه عن رسول الله، بتقواه لله وتأديته الواجب عليه، في اتباع أمر رسول الله، وعلمه وبأن ليس لأحد مع رسول الله"},{"id":"risala-shafii:483","bookId":"risala-shafii","type":"section","seq":483,"chapter":"الجزء الثالث.","title":"ص: 425","page":"ج1 ص418","text":"أمر، وأن طاعة الله في اتباع أمر رسول الله.\nفإن قال قائل: فادللني على أن عمر عمل شيئا، ثم صار إلى غيره بخبر عن رسول الله.\nقلت: فإن أوجدتكه؟\nقال: ففي إيجادك إياي ذلك دليل على أمرين: أحدهما: أنه قد يقول من جهة الرأي إذا لم توجد سنة، والآخر: أن السنة إذا وجدت وجب عليه ترك عمل نفسه، ووجب على الناس ترك كل عمل وجدت السنة بخلافه، وإبطال أن السنة لا تثبت إلا بخبر بعدها،"},{"id":"risala-shafii:484","bookId":"risala-shafii","type":"section","seq":484,"chapter":"الجزء الثالث.","title":"ص: 426","page":"ج1 ص420","text":"وعلم أنه لا يوهنها شيء إن خالفها.\nقلت: أخبرنا سفيان عن الزهري عن سعيد بن المسيب: أن عمر بن الخطاب كان يقول: الدية للعاقلة، ولا ترث المرأة من دية زوجها شيئا. حتى أخبره الضحاك بن سفيان أن رسول الله كتب إليه: أن يورث امرأة أشيم الضبابي من ديته، فرجع إليه عمر.\nوقد فسرت هذا الحديث قبل هذا الموضع. (1)\nسفيان عن عمرو بن دينار وابن طاوس عن"},{"id":"risala-shafii:485","bookId":"risala-shafii","type":"section","seq":485,"chapter":"الجزء الثالث.","title":"ص: 427","page":"ج1 ص420","text":"طاوس: أن عمر قال: أذكر الله امرأ سمع من النبي في الجنين شيئا، فقام حمل بن مالك بن النابغة، فقال: كنت بين جارتين لي - يعني ضرتين - فضربت إحداهما الأخرى بمسطح (2) فألقت جنينا ميتا، فقضى فيه رسول الله بغرة (3) . فقال عمر: لو لم أسمع فيه لقضينا بغيره.\nوقال غيره: إن كدنا أن نقضي في مثل هذا برأينا. (4)"},{"id":"risala-shafii:486","bookId":"risala-shafii","type":"section","seq":486,"chapter":"الجزء الثالث.","title":"ص: 428","page":"ج1 ص420","text":"فقد رجع عمر عما كان يقضي به لحديث الضحاك إلى أن خالف حكم نفسه، وأخبر في الجنين أنه لو لم يسمع هذا لقضى فيه بغيره، وقال: إن كدنا أن نقضي في مثل هذا برأينا.\nقال \"الشافعي\": يخبر - والله أعلم - أن السنة إذا كانت موجودة بأن في النفس مائة من الإبل، فلا يعدو الجنين أن يكون حيا فيكون فيه مائة من الإبل، أو ميتا فلا شيء فيه.\nفلما أخبر بقضاء رسول الله فيه سلم له، ولم يجعل لنفسه إلا اتباعه، فيما مضى بخلافه، وفيما كان رأيا منه لم يبلغه عن رسول الله فيه شيء، فلما بلغه خلاف فعله صار إلى حكم رسول الله،"},{"id":"risala-shafii:487","bookId":"risala-shafii","type":"section","seq":487,"chapter":"الجزء الثالث.","title":"ص: 429","page":"ج1 ص420","text":"وترك حكم نفسه، وكذلك كان في كل أمره.\nوكذلك يلزم الناس أن يكونوا.\nأخبرنا مالك عن ابن شهاب عن سالم: أن عمر بن الخطاب إنما رجع بالناس عن خبر عبد الرحمن بن عوف.\nقال \"الشافعي\": يعني حين خرج إلى الشام، فبلغه وقوع الطاعون بها."},{"id":"risala-shafii:488","bookId":"risala-shafii","type":"section","seq":488,"chapter":"الجزء الثالث.","title":"ص: 430","page":"ج1 ص420","text":"مالك عن جعفر بن محمد عن أبيه: أن عمر ذكر المجوس، فقال: ما أدري كيف أصنع في أمرهم؟ فقال له عبد الرحمن بن عوف: أشهد لسمعت رسول الله يقول: سنوا بهم سنة أهل الكتاب. (5)\nسفيان عن عمرو: أنه سمع بجالة يقول: ولم"},{"id":"risala-shafii:489","bookId":"risala-shafii","type":"section","seq":489,"chapter":"الجزء الثالث.","title":"ص: 431","page":"ج1 ص420","text":"يكن عمر أخذ الجزية حتى أخبره عبد الرحمن بن عوف أن النبي أخذها من مجوس هجر.\nقال \"الشافعي\"وكل حديث كتبته منقطعا، فقد سمعته متصلا أو مشهورا عن من روي عنه بنقل عامة من أهل العلم يعرفونه عن عامة، ولكني كرهت وضع حديث لا أتقنه حفظا، وغاب عني بعض كتبي، وتحققت بما يعرفه أهل العلم مما حفظت، فاختصرت خوف طول الكتاب، فأتيت ببعض ما فيه الكفاية دون تقصي العلم في كل أمره.\nفقبل عمر خبر عبد الرحمن بن عوف في المجوس، فأخذ منهم وهو يتلو القرآن {من الذين أوتوا الكتاب حتى يعطوا الجزية عن يد وهم صاغرون} ، ويقرأ القرآن بقتال الكافرين حتى يسلموا، وهو لا يعرف فيهم عن النبي شيئا، وهم عنده من الكافرين غير أهل الكتاب، فقبل خبر عبد الرحمن في المجوس عن النبي فاتبعه."},{"id":"risala-shafii:490","bookId":"risala-shafii","type":"section","seq":490,"chapter":"الجزء الثالث.","title":"ص: 432","page":"ج1 ص431","text":"وحديث بجالة موصول، قد أدرك عمر بن الخطاب رجلا، وكان كاتبا لبعض ولاته.\nفإن قال قائل: قد طلب عمر مع رجل أخبره خبرا آخر؟\nقيل له لا يطلب عمر مع رجل أخبره آخر إلا على أحد ثلاث معاني:"},{"id":"risala-shafii:491","bookId":"risala-shafii","type":"section","seq":491,"chapter":"الجزء الثالث.","title":"ص: 433","page":"ج1 ص431","text":"إما أن يحتاط فيكون، (1) وإن كانت الحجة تثبت بخبر الواحد، فخبر اثنين أكثر، وهو لا يزيدها إلا ثبوتا.\nوقد رأيت ممن أثبت خبر الواحد من يطلب معه خبرا ثانيا، ويكون في يده السنة من رسول الله من خمس وجوه فيحدث بسادس فيكتبه، لأن الأخبار كلما تواترت وتظاهرت كان أثبت للحجة، وأطيب لنفس السامع.\nوقد رأيت من الحكام من يثبت عنده الشاهدان العدلان والثلاثة، فيقول للمشهود له: زدني شهودا وإنما يريد بذلك أن يكون أطيب لنفسه، ولو لم يزده المشهود له على شاهدين لحكم له بهما.\nويحتمل أن يكون لم يعرف المخبر فيقف عن خبره حتى يأتي مخبر يعرفه."},{"id":"risala-shafii:492","bookId":"risala-shafii","type":"section","seq":492,"chapter":"الجزء الثالث.","title":"ص: 434","page":"ج1 ص431","text":"وهكذا ممن أخبر ممن لا يعرف لم يقبل خبره. ولا يقبل الخبر إلا عن معروف بالاستئهال له، لأن يقبل خبره.\nويحتمل أن يكون المخبر له غير مقبول القول عنده، فيرد خبره حتى يجد غيره ممن يقبل قوله.\nفإن قال قائل: فإلى أي المعاني ذهب عندكم عمر؟\nقلنا: أما في خبر أبي موسى فإلى الاحتياط، لأن أبا موسى ثقة أمين عنده، إن شاء الله.\nفإن قال قائل: ما دل على ذلك؟\nقلنا: قد رواه مالك بن أنس عن ربيعة عن غير"},{"id":"risala-shafii:493","bookId":"risala-shafii","type":"section","seq":493,"chapter":"الجزء الثالث.","title":"ص: 435","page":"ج1 ص432","text":"واحد من علمائهم حديث أبي موسى، وأن عمر قال لأبي موسى: وأما إني لم أتهمك، ولكن خشيت أن يتقول الناس على رسول الله.\nفإن قال: هذا منقطع.\nفالحجة فيه ثابتة، لأنه لا يجوز على إمام في الدين - عمر ولا غيره -: أن يقبل خبر الواحد مرة، وقبوله له لا يكون إلا بما تقوم به الحجة عنده، ثم يرد مثله أخرى. ولا يجوز هذا على عالم عاقل أبدا، ولا يجوز على حاكم أن يقضي بشاهدين مرة، ويمنع بهما أخرى، إلا من جهة جرحهما أو الجهالة بعدلهما. وعمر غاية في العلم والعقل والأمانة والفضل.\nوفي كتاب الله تبارك وتعالى دليل على ما وصفت:\nقال الله: {إنا أرسلنا نوحا إلى قومه} [نوح 1]\nوقال: {ولقد أرسلنا نوحا إلى قومه} [هود 25 والمؤمنون 23 والعنكبوت 14]\nوقال: {وأوحينا إلى إبراهيم وإسماعيل} [النساء 163]\nوقال: {وإلى عاد أخاهم هودا} [الأعراف 65 وهود 50]\nوقال: {وإلى ثمود أخاهم صالحا} [الأعراف 73 وهود 61]\nوقال: {وإلى مدين أخاهم شعيبا} [الأعراف 85 وهود 84 والعنكبوت 36]\nوقال: {كذبت قوم لوط المرسلين. إذ قال لهم أخوهم لوط: ألا تتقون. إني لكم رسول أمين فاتقوا الله وأطيعون} [لشعراء 160 - 163]\nوقال لنبيه محمد صلى الله عليه: {إنا أوحينا إليك كما أوحينا إلى نوح} [النساء 163]\nوقال: {وما محمد إلا رسول قد خلت من قبله الرسل} [آل عمران 144]\nفأقام جل ثناؤه حجته على خلقه في أنبيائه في الأعلام التي باينوا بها خلقه سواهم، وكانت الحجة بها ثابتة على من شاهد أمور الأنبياء ودلائلهم التي باينوا بها غيرهم، ومن بعدهم، وكان الواحد في ذلك وأكثر منه سواء، تقوم الحجة بالواحد منهم قياما بالأكثر.\nقال: {واضرب لهم مثلا أصحاب القرية إذ جاءها المرسلون. إذ أرسلنا إليهم اثنين، فكذبوهما، فعززنا بثالث، فقالوا: إنا إليكم مرسلون. قالوا: ما أنتم إلا بشر مثلنا، وما أنزل الرحمن من شيء. إن أنتم إلا تكذبون} [يس 13 - 15]\nقال \"الشافعي\": فظاهر الحجج عليهم باثنين، ثم ثالث، وكذا أقام الحجة على الأمم بواحد، وليس الزيادة في"},{"id":"risala-shafii:494","bookId":"risala-shafii","type":"section","seq":494,"chapter":"الجزء الثالث.","title":"ص: 438","page":"ج1 ص435","text":"التأكيد مانعة أن تقوم الحجة بالواحد، إذ أعطاه ما يباين به الخلق غير النبيين.\nأخبرنا مالك عن سعد بن إسحاق بن كعب بن عجرة عن عمته زينب بنت كعب: أن الفريعة بنت مالك بن سنان أخبرتها أنها جاءت إلى النبي تسأله أن ترجع إلى أهلها في بني خدرة، فإن زوجها خرج في طلب أعبد له، حتى إذا كان بطرف القدوم لحقهم، فقتلوه، فسألت رسول الله أن أرجع إلى أهلي، فإن زوجي لم يتركني في مسكن يملكه، قالت: فقال رسول الله: نعم. فانصرفت، حتى إذا كنت في الحجرة أو في المسجد دعاني، أو أمر بي فدعيت له، فقال: كيف قلت؟ فرددت عليه القصة التي"},{"id":"risala-shafii:495","bookId":"risala-shafii","type":"section","seq":495,"chapter":"الجزء الثالث.","title":"ص: 439","page":"ج1 ص437","text":"ذكرت له من شأن زوجي، فقال لي: امكثي في بيتك حتى يبلغ الكتاب أجله. قالت: فاعتددت فيه أربعة أشهر وعشرا، فلما كان عثمان أرسل إلي، فسألني عن ذلك، فأخبرته، فاتبعه، وقضى به. (1)\nوعثمان في إمامته، وعلمه يقضي بخبر امرأة بين المهاجرين والأنصار.\nأخبرنا مسلم عن ابن جريج قال: أخبرني الحسن"},{"id":"risala-shafii:496","bookId":"risala-shafii","type":"section","seq":496,"chapter":"الجزء الثالث.","title":"ص: 440","page":"ج1 ص438","text":"بن مسلم عن طاوس قال: كنت مع ابن عباس إذ قال له زيد بن ثابت: أتفتي أن تصدر الحائض قبل أن يكون آخر عهدها بالبيت؟ فقال له ابن عباس: إما لى (1) فاسأل فلانة الأنصارية:"},{"id":"risala-shafii:497","bookId":"risala-shafii","type":"section","seq":497,"chapter":"الجزء الثالث.","title":"ص: 441","page":"ج1 ص438","text":"هل أمرها بذلك النبي؟ فرجع زيد بن ثابت يضحك، ويقول ما أراك إلا قد صدقت. (2)\nقال \"الشافعي\": سمع زيد النهي أن يصدر أحد من الحاج حتى يكون آخر عهده بالبيت، وكانت الحائض عنده من الحاج الداخلين في ذلك النهي، فلما أفتاها ابن عباس بالصدر إذا كانت قد زارت بعد النحر: أنكر عليه زيد، فلما أخبره عن المرأة أن رسول الله أمرها بذلك فسألها فأخبرته،"},{"id":"risala-shafii:498","bookId":"risala-shafii","type":"section","seq":498,"chapter":"الجزء الثالث.","title":"ص: 442","page":"ج1 ص438","text":"فصدق المرأة، ورأى عليه حقا أن يرجع عن خلاف ابن عباس، وما لابن عباس حجة غير خبر المرأة.\nسفيان عن عمرو عن سعيد بن جبير قال: قلت لابن عباس: إن نوف البكالي يزعم أن موسى صاحب الخضر ليس موسى بني إسرائيل؟ فقال ابن عباس: كذب عدو الله! أخبرني أبي بن كعب قال: خطبنا رسول الله، ثم ذكر حديث موسى والخضر بشيء يدل على أن موسى صاحب الخضر.\nفابن عباس مع فقهه وورعه يثبت خبر أبي"},{"id":"risala-shafii:499","bookId":"risala-shafii","type":"section","seq":499,"chapter":"الجزء الثالث.","title":"ص: 443","page":"ج1 ص439","text":"بن كعب عن رسول الله حتى يكذب به امرأ من المسلمين، إذ حدثه أبي بن كعب عن رسول الله بما فيه دلالة على أن موسى بني إسرائيل صاحب الخضر.\nأخبرنا مسلم وعبد المجيد عن ابن جريج أن طاوسا أخبره أنه سأل ابن عباس عن الركعتين بعد العصر؟ فنهاه عنهما (1) ، قال طاوس: فقلت له: ما أدعهما، فقال ابن عباس: {ما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمرا أن يكون لهم الخيرة من أمرهم، ومن يعص الله ورسوله، فقد ضل ضلالا مبينا} [الأحزاب 36]"},{"id":"risala-shafii:500","bookId":"risala-shafii","type":"section","seq":500,"chapter":"الجزء الثالث.","title":"ص: 444","page":"ج1 ص442","text":"فرأى ابن عباس الحجة قائمة على طاوس بخبره عن النبي، ودله بتلاوة كتاب الله على أن فرضا عليه أن لا تكون له الخيرة إذا قضى الله ورسوله أمرا.\nوطاوس حينئذ إنما يعلم قضاء رسول الله بخبر ابن عباس وحده، ولم يدفعه طاوس بأن يقول: هذا خبرك وحدك، فلا أثبته عن النبي، لأنه يمكن أن تنسى.\nفإن قال قائل: كره أن يقول: هذا لابن عباس؟!\nفابن عباس أفضل من أن يتوقى أحد أن يقول له حقا رآه، وقد نهاه عن الركعتين بعد العصر، فأخبره أنه لا يدعهما،"},{"id":"risala-shafii:501","bookId":"risala-shafii","type":"section","seq":501,"chapter":"الجزء الثالث.","title":"ص: 445","page":"ج1 ص442","text":"قبل أن يعلمه أن النبي نهى عنهما.\nسفيان عن عمرو عن ابن عمر قال: كنا نخابر، (1) ولا نرى بذلك بأسا، حتى زعم رافع أن رسول الله نهى عنها، فتركناها من أجل ذلك.\nفابن عمر قد كان ينتفع بالمخابرة، ويراها حلالا، ولم يتوسع، إذ أخبره واحد لا يتهمه عن رسول الله أنه نهى عنها: أن يخابر بعد خبره، ولا يستعمل رأيه مع ما جاء عن رسول الله، ولا يقول: ما عاب هذا علينا أحد، ونحن نعمل به إلى اليوم."},{"id":"risala-shafii:502","bookId":"risala-shafii","type":"section","seq":502,"chapter":"الجزء الثالث.","title":"ص: 446","page":"ج1 ص443","text":"وفي هذا ما يبين أن العمل بالشيء بعد النبي إذا لم يكن بخبر عن النبي لم يوهن الخبر عن النبي عليه السلام.\nأخبرنا مالك عن زيد بن أسلم عن عطاء بن يسار أن معاوية بن أبي سفيان باع سقاية من ذهب أو ورق بأكثر من وزنها، فقال له أبو الدرداء: سمعت رسول الله ينهى عن مثل هذا، فقال معاوية: ما أرى بهذا بأسا! فقال أبو الدرداء: من يعذرني من معاوية! أخبره عن رسول الله، ويخبرني عن رأيه؟! لا أساكنك بأرض. (1)"},{"id":"risala-shafii:503","bookId":"risala-shafii","type":"section","seq":503,"chapter":"الجزء الثالث.","title":"ص: 447","page":"ج1 ص445","text":"فرأى أبو الدرداء الحجة تقوم على معاوية بخبره، ولما لم ير ذلك معاوية فارق أبو الدرداء الأرض التي هو بها، إعظاما لأن ترك خبر ثقة عن النبي.\nوأخبرنا أن أبا سعيد الخدري لقي رجلا، فأخبره عن رسول الله شيئا، فذكر الرجل خبرا يخالفه، فقال أبو سعيد: والله لا آواني وإياك سقف بيت أبدا.\nقال \"الشافعي\": يرى أن ضيقا على المخبر أن لا يقبل خبره، وقد ذكر خبرا يخالف خبر أبي سعيد عن النبي، ولكن في خبره وجهان: أحدهما: يحتمل به خلاف خبر أبي سعيد، والآخر: لا يحتمله."},{"id":"risala-shafii:504","bookId":"risala-shafii","type":"section","seq":504,"chapter":"الجزء الثالث.","title":"ص: 448","page":"ج1 ص446","text":"أخبرنا من لا أتهم عن ابن أبي ذئب عن مخلد بن خفاف قال: ابتعت غلاما، فاستغللته، ثم ظهرت منه على عيب، فخاصمت فيه إلى عمر بن عبد العزيز، فقضى لي برده، وقضى علي برد غلته، فأتيت عروة، فأخبرته، فقال: أروح عليه العشية، فأخبره أن عائشة أخبرتني أن رسول الله قضى في مثل هذا أن الخراج بالضمان، فعجلت إلى عمر، فأخبرته ما أخبرني عروة عن عائشة عن النبي، فقال عمر: فما أيسر علي من قضاء قضيته، الله يعلم أني لم أرد فيه إلا الحق، فبلغتني فيه سنة رسول الله، فأرد قضاء عمر،"},{"id":"risala-shafii:505","bookId":"risala-shafii","type":"section","seq":505,"chapter":"الجزء الثالث.","title":"ص: 449","page":"ج1 ص446","text":"وأنفذ سنة رسول الله. فراح إليه عروة فقضى لي أن آخذ الخراج من الذي قضى به علي له. (1)\nأخبرني من لا أتهم من أهل المدينة عن ابن أبي ذئب قال قضى سعد بن إبراهيم على رجل بقضية برأي ربيعة بن أبي عبد الرحمن، فأخبرته عن النبي بخلاف ما قضى به، فقال سعد لربيعة: هذا بن أبي ذئب، وهو عندي ثقة، يخبرني عن النبي بخلاف ما قضيت به؟ فقال له ربيعة: قد اجتهدت، ومضى حكمك، فقال سعد: واعجبا! أنفذ قضاء سعد بن أم سعد وأرد قضاء رسول الله؟! بل أرد قضاء سعد بن أم سعد وأنفذ قضاء رسول الله، فدعا سعد بكتاب القضية فشقه وقضى للمقضي عليه.\nقال \"الشافعي\": أخبرني أبو حنيفة بن سماك بن الفضل الشهابي قال حدثني ابن أبي ذئب عن المقبري عن أبي شريح"},{"id":"risala-shafii:506","bookId":"risala-shafii","type":"section","seq":506,"chapter":"الجزء الثالث.","title":"ص: 452","page":"ج1 ص447","text":"الكعبي أن النبي قال عام الفتح: ((من قتل له قتيل فهو بخير النظرين: إن أحب أخذ العقل، وإن أحب فله القود)) (1) قال أبو حنيفة: فقلت لابن أبي ذئب: أتأخذ بهذا يا أبا الحارث؟ فضرب صدري، وصاح علي صياحا كثيرا، ونال مني، وقال: أحدثك عن رسول الله، وتقول تأخذ به؟! نعم آخذ به. وذلك الفرض علي، وعلى من سمعه، إن الله اختار محمدا من الناس، فهداهم به، وعلى يديه، واختار لهم ما اختار له، وعلى لسانه، فعلى الخلق أن يتبعوه طائعين أو داخرين، لا مخرج لمسلم من ذلك. قال: وما سكت حتى تمنيت أن يسكت."},{"id":"risala-shafii:507","bookId":"risala-shafii","type":"section","seq":507,"chapter":"الجزء الثالث.","title":"ص: 453","page":"ج1 ص447","text":"قال: وفي تثبيت خبر الواحد أحاديث، يكفي بعض هذا منها.\nولم يزل سبيل سلفنا والقرون بعدهم إلى من شاهدنا هذا السبيل.\nوكذلك حكي لنا عمن حكي لنا عنه من أهل العلم بالبلدان.\nقال \"الشافعي\": وجدنا سعيد (1) بالمدينة يقول: أخبرني أبو سعيد الخدري عن النبي في الصرف (2) فيثبت حديثه سنة. ويقول: حدثني أبو هريرة عن النبي، فيثبت حديثه سنة، ويروي عن الواحد غيرهما فيثبت حديثه سنة.\nووجدنا عروة يقول: حدثتني عائشة: ((أن رسول الله قضى أن الخراج بالضمان)) (3) فيثبته سنة، ويروي عنها عن النبي شيئا كثيرا فيثبتها سننا يحل بها ويحرم."},{"id":"risala-shafii:508","bookId":"risala-shafii","type":"section","seq":508,"chapter":"الجزء الثالث.","title":"ص: 454","page":"ج1 ص450","text":"وكذلك وجدناه يقول: حدثني أسامة بن زيد عن النبي. ويقول: حدثني عبد الله بن عمر عن النبي وغيرهما، فيثبت خبر كل واحد منهما على الانفراد سنة.\nثم وجدناه أيضا يصير إلى أن يقول: حدثني عبد الرحمن بن عبد القاري عن عمر، ويقول: حدثني يحيى بن عبد الرحمن بن حاطب عن أبيه عن عمر. ويثبت كل واحد من هذا خبر عن عمر.\nووجدنا القاسم بن محمد يقول: حدثتني عائشة عن النبي، ويقول في حديث غيره: حدثني ابن عمر عن النبي. ويثبت خبر كل واحد منهما على الانفراد سنة.\nويقول حدثني عبد الرحمن ومجمع ابنا يزيد بن جارية عن خنساء بنت خدام عن النبي. فيثبت خبرها سنة، وهو خبر امرأة واحدة."},{"id":"risala-shafii:509","bookId":"risala-shafii","type":"section","seq":509,"chapter":"الجزء الثالث.","title":"ص: 455","page":"ج1 ص450","text":"ووجدنا علي بن حسين يقول: أخبرنا عمرو بن عثمان عن أسامة بن زيد أن النبي قال: \"لا يرث المسلم الكافر \". (4) فيثبتها سنة، ويثبتها الناس بخبره سنة.\nووجدنا كذلك محمد بن علي بن حسين يخبر عن جابر عن النبي، وعن عبيد الله بن أبي رافع عن أبي هريرة عن النبي. فيثبت كل ذلك سنة.\nووجدنا محمد بن جبير بن مطعم، ونافع بن جبير بن مطعم، ويزيد بن طلحة بن ركانة، ومحمد بن طلحة بن ركانة، ونافع بن عجير بن عبد يزيد، وأبا أسامة بن عبد الرحمن، وحميد"},{"id":"risala-shafii:510","bookId":"risala-shafii","type":"section","seq":510,"chapter":"الجزء الثالث.","title":"ص: 456","page":"ج1 ص450","text":"بن عبد الرحمن، وطلحة بن عبد الله بن عوف، ومصعب بن سعد بن أبي وقاص، وإبراهيم بن عبد الرحمن بن عوف، وخارجة بن زيد بن ثابت، وعبد الرحمن بن كعب بن مالك، وعبد الله بن أبي قتادة، وسليمان بن يسار، وعطاء بن يسار، وغيرهم من محدثي أهل المدينة: كلهم يقول: حدثني فلان لرجل من أصحاب النبي عن النبي، أو من التابعين عن رجل من أصحاب النبي. فنثبت ذلك سنة.\nووجدنا عطاء، وطاوس، ومجاهد، وابن أبي مليكة، وعكرمة بن خالد، وعبيد الله بن أبي يزيد، وعبد الله بن باباه، وابن أبي عمار، ومحدثي المكيين، ووجدنا"},{"id":"risala-shafii:511","bookId":"risala-shafii","type":"section","seq":511,"chapter":"الجزء الثالث.","title":"ص: 457","page":"ج1 ص450","text":"وهب بن منبه هكذا، ومكحول بالشأم، وعبد الرحمن بن غنم، والحسن، وابن سيرين بالبصرة، والأسود، وعلقمة، والشعبي بالكوفة، ومحدثي الناس، وأعلامهم بالأمصار: كلهم يحفظ عنه تثبيت خبر الواحد عن رسول الله، والانتهاء إليه، والإفتاء به، ويقبله كل واحد منهم عن من فوقه، ويقبله عنه من تحته.\nولو جاز لأحد من الناس أن يقول في علم الخاصة: أحمع المسلمون قديما وحديثا على تثبيت خبر الواحد، والانتهاء إليه، بأنه لم يعلم من فقهاء المسلمين أحد إلا وقد ثبته جاز لي.\nولكن أقول: لم أحفظ عن فقهاء المسلمين"},{"id":"risala-shafii:512","bookId":"risala-shafii","type":"section","seq":512,"chapter":"الجزء الثالث.","title":"ص: 458","page":"ج1 ص450","text":"أنهم اختلفوا في تثبيت خبر الواحد بما وصفت من أن ذلك موجودا (5) على كلهم.\nقال: فإن شبه على رجل بأن يقول: قد روي عن النبي حديث كذا، وحديث كذا، وكان فلان يقول قولا يخالف ذلك الحديث.\nفلا يجوز عندي عن عالم أن يثبت خبر واحد كثيرا، ويحل به، ويحرم، ويرد مثله: إلا من جهة أن يكون عنده حديث يخالفه، أو يكون ما سمع ومن سمع منه أوثق عنده ممن حدثه خلافه، أو يكون من حدثه ليس بحافظ، أو يكون متهما عنده، أو يتهم من فوقه ممن حدثه، أو يكون الحديث محتملا"},{"id":"risala-shafii:513","bookId":"risala-shafii","type":"section","seq":513,"chapter":"الجزء الثالث.","title":"ص: 459","page":"ج1 ص453","text":"معنيين، فيتأول فيذهب إلى أحدهما دون الآخر.\nفأما أن يتوهم متوهم أن فقيها عاقلا يثبت سنة بخبر واحد مرة ومرارا، ثم يدعها بخبر مثله وأوثق بلا واحد من هذه الوجوه التي تشبه بالتأويل كما شبه على المتأولين في القرآن، وتهمة المخبر، أو علم بخبر خلافه، فلا يجوز إن شاء الله.\nفإن قال قائل: قل فقيه في بلد إلا وقد روى كثيرا يأخذ به وقليلا يتركه؟\nفلا يجوز عليه إلا من الوجه الذي وصفت"},{"id":"risala-shafii:514","bookId":"risala-shafii","type":"section","seq":514,"chapter":"الجزء الثالث.","title":"ص: 460","page":"ج1 ص453","text":"ومن أن يروي عن رجل من التابعين أو من دونهم قولا لا يلزمه الأخذ به، فيكون إنما رواه لمعرفة قوله، لا لأنه حجة عليه وافقه أو خالفه.\nفإن لم يسلك واحدا من هذه السبل فيعذر ببعضها، فقد أخذ خطأ لا عذر فيه عندنا والله أعلم.\nفإن قال قائل: هل يفترق معنى قولك: حجة؟\nقيل له: إن شاء الله نعم.\nفإن قال: فأبن ذلك؟\nقلنا: أما ما كان نص كتاب بين أو سنة مجتمع عليها فيها مقطوع، ولا يسع الشك في واحد منهما، ومن امتنع من قبوله استتيب.\nفأما ما كان من سنة من خبر الخاصة الذي يختلف الخبر فيه، فيكون الخبر محتملا للتأويل، وجاء الخبر فيه من طريق الانفراد: فالحجة فيه عندي أن يلزم العالمين حتى لا يكون لهم رد ما كان منصوصا منه، كما يلزمهم أن يقبلوا شهادة العدول، لا أن ذلك إحاطة كما يكون نص الكتاب وخبر العامة عن رسول الله.\nولو شك في هذا شاك لم نقل له: تب، وقلنا: ليس لك - إن كنت عالما - أن تشك، كما ليس لك الا ان تقضي بشهادة الشهود العدول، وإن أمكن فيهم الغلط، ولكن تقضي بذلك على الظاهر من صدقهم، والله ولي ما غاب عنك منهم.\nفقال: فهل تقوم بالحديث المنقطع حجة على من علمه؟ وهل يختلف المنقطع؟ أو هو وغيره سواء؟\nقال \"الشافعي\": فقلت له: المنقطع مختلف:\nفمن شاهد أصحاب رسول الله من التابعين، فحدث حديثا منقطعا عن النبي: اعتبر عليه بأمور:"},{"id":"risala-shafii:515","bookId":"risala-shafii","type":"section","seq":515,"chapter":"الجزء الثالث.","title":"ص: 462","page":"ج1 ص460","text":"منها: أن ينظر إلى ما أرسل من الحديث، فإن شركه فيه الحفاظ المأمونون، فأسندوه الى رسول الله بمثل معنى ما روى: كانت هذه دلالة على صحة من قبل عنه وحفظه.\nوإن انفرد بإرسال حديث لم يشركه فيه من يسنده قبل ما ينفرد به من ذلك.\nويعتبر عليه بأن ينظر: هل يوافقه مرسل غيره ممن قبل العلم عنه من غير رجاله الذين قبل عنهم؟\nفإن وجد ذلك كانت دلالة يقوى له مرسله، وهي أضعف من الأولى.\nوإن لم يوجد ذلك نظر إلى بعض ما يروى عن بعض أصحاب رسول الله قولا له، فإن وجد يوافق ما روى عن"},{"id":"risala-shafii:516","bookId":"risala-shafii","type":"section","seq":516,"chapter":"الجزء الثالث.","title":"ص: 463","page":"ج1 ص460","text":"رسول الله كانت في هذه دلالة على أنه لم يأخذ مرسله إلا عن أصل يصح إن شاء الله.\nوكذلك إن وجد عوام من أهل العلم يفتون بمثل معنى ما روى عن النبي.\nقال \"الشافعي\": ثم يعتبر عليه: بأن يكون إذا سمى من روى عنه لم يسمي مجهولا ولا مرغوبا عن الرواية عنه، فيستدل بذلك على صحته فيما روى عنه.\nويكون إذا شرك أحدا من الحفاظ في حديث لم يخالفه، فإن خالفه وجد حديثه أنقص: كانت في هذه دلائل على صحة مخرج حديثه."},{"id":"risala-shafii:517","bookId":"risala-shafii","type":"section","seq":517,"chapter":"الجزء الثالث.","title":"ص: 464","page":"ج1 ص460","text":"ومتى ما خالف ما وصفت أضر بحديثه، حتى لا يسع أحدا منهم قبول مرسله\nقال: وإذا وجدت الدلائل بصحة حديثه بما وصفت أحببنا أن نقبل مرسله.\nولا نستطيع أن نزعم أن الحجة تثبت به ثبوتها بالموتصل.\nوذلك أن معنى المنقطع مغيب، يحتمل أن يكون حمل عن من يرغب عن الرواية عنه إذا سمي وإن بعض المنقطعات - وإن وافقه مرسل مثله - فقد يحتمل أن يكون مخرجها واحدا، من حيث لو سمي لم يقبل، وأن قول بعض أصحاب النبي - إذا قال برأيه لو وافقه - يدل على صحة مخرج الحديث، دلالة قوية إذا نظر فيها،"},{"id":"risala-shafii:518","bookId":"risala-shafii","type":"section","seq":518,"chapter":"الجزء الثالث.","title":"ص: 465","page":"ج1 ص461","text":"ويمكن أن يكون إنما غلط به حين سمع قول بعض أصحاب النبي يوافقه، ويحتمل مثل هذا فيمن وافقه من بعض الفقهاء.\nفأما من بعد كبار التابعين الذين كثرت مشاهدتهم لبعض أصحاب رسول الله: فلا أعلم منهم واحدا يقبل مرسله لأمور: أحدها: أنهم أشد تجوزا فيمن يروون عنه، والآخر: أنهم يوجد عليهم الدلائل فيما أرسلوا بضعف مخرجه. والآخر: كثرة الإحالة. كان أمكن للوهم وضعف من يقبل عنه."},{"id":"risala-shafii:519","bookId":"risala-shafii","type":"section","seq":519,"chapter":"الجزء الثالث.","title":"ص: 466","page":"ج1 ص464","text":"وقد خبرت بعض من خبرت من أهل العلم، فرأيتهم أتوا من خصلة وضدها:\nرأيت الرجل يقنع بيسير العلم، ويريد إلا أن يكون مستفيدا إلا من جهة قد يتركه من مثلها أو أرجح، فيكون من أهل التقصير في العلم.\nورأيت من عاب هذه السبيل، ورغب في التوسع في العلم، من دعاه ذلك الى القبول عن من لو أمسك عن القبول عنه كان خيرا له.\nورأيت الغفلة قد تدخل على أكثرهم، فيقبل عن من يرد مثله وخيرا منه.\nويدخل عليه، فيقبل عن من يعرف ضعفه، إذا وافق قولا يقوله! ويرد حديث الثقة إذا خالف قولا يقوله!\nويدخل على بعضهم من جهات."},{"id":"risala-shafii:520","bookId":"risala-shafii","type":"section","seq":520,"chapter":"الجزء الثالث.","title":"ص: 467","page":"ج1 ص464","text":"ومن نظر في العلم بخبرة وقلة غفلة، استوحش من مرسل كل من دون كبار التابعين، بدلائل ظاهرة فيها.\nقال: فلم فرقت بين التابعين المتقدمين الذين شاهدوا أصحاب رسول الله، وبين من شاهد بعضهم دون بعض؟\nفقلت: لبعد إحالة من لم يشاهد أكثرهم.\nقال: فلم لم تقبل المرسل منهم، ومن كل فقيه دونهم؟\nقلت: لما وصفت.\nقال: وهل تجد حديثا تبلغ به رسول الله مرسلا عن ثقة لم يقل أحدا من أهل الفقه به؟\nقلت: نعم، أخبرنا سفيان عن محمد بن المنكدر: أن رجلا جاء الى النبي، فقال: يا رسول الله! إن لي مالا وعيالا، وإن لأبي مالا وعيالا، وإنه يريد أن يأخذ مالي، فيطعمه عياله. فقال رسول الله: \"أنت ومالك لأبيك\". (1)"},{"id":"risala-shafii:521","bookId":"risala-shafii","type":"section","seq":521,"chapter":"الجزء الثالث.","title":"ص: 468","page":"ج1 ص467","text":"فقال: أما نحن فلا نأخذ بهذا، ولكن من أصحابك من يأخذ به؟\nفقلت: لا، لأن من أخذ بهذا جعل للأب الموسر أن يأخذ مال ابنه.\nقال: أجل، وما يقول بهذا أحد. فلم خالفه الناس؟\nقلت: لأنه لا يثبت عن النبي، وأن الله لما فرض للأب ميراثه من ابنه، فجعله كوارث غيره، فقد يكون أقل حظا من كثير من الورثة: دل ذلك على أن ابنه مالك للمال دونه.\nقال: فمحمد بن المنكدر عندكم غاية في الثقة؟\nقلت: أجل، والفضل في الدين والورع، ولكنا لا ندري عن من قبل هذا الحديث.\nوقد وصفت لك الشاهدين العدلين يشهدان على"},{"id":"risala-shafii:522","bookId":"risala-shafii","type":"section","seq":522,"chapter":"الجزء الثالث.","title":"ص: 469","page":"ج1 ص467","text":"الرجل فلا تقبل شهادتهما حتى يعدلاهما أو يعدلهما غيرهما.\nقال: فتذكر من حديثكم مثل هذا؟\nقلت: نعم، أخبرنا الثقة عن ابن أبي ذئب عن ابن شهاب: \"أن رسول الله أمر رجلا ضحك في الصلاة أن يعيد الوضوء والصلاة\".\nفلم نقبل هذا، لأنه مرسل.\nثم أخبرنا الثقة عن معمر عن بن شهاب عن سليمان بن أرقم عن الحسن عن النبي: بهذا الحديث\nوابن شهاب عندنا إمام في الحديث والتخيير وثقة الرجال، إنما يسمي بعض أصحاب النبي، ثم خيار التابعين، ولا نعلم محدثا يسمي أفضل ولا أشهر ممن يحدث عنه ابن شهاب.\nقال: فأنى تراه أتى في قبوله عن سليمان بن أرقم؟"},{"id":"risala-shafii:523","bookId":"risala-shafii","type":"section","seq":523,"chapter":"الجزء الثالث.","title":"ص: 470","page":"ج1 ص467","text":"رآه رجلا من أهل المروءة والعقل، فقبل عنه، وأحسن الظن به، فسكت عن اسمه إما لأنه أصغر منه، وإما لغير ذلك، وسأله معمر عن حديثه عنه، فأسنده له.\nفلما أمكن في ابن شهاب أن يكون يروي عن سليمان مع ما وصفت به ابن شهاب: لم يؤمن مثل هذا على غيره.\nقال: فهل تجد لرسول الله سنة ثابتة من جهة الاتصال خالفها الناس كلهم؟\nقلت: لا، ولكن قد أجد الناس مختلفين فيها: منهم من يقول بها، ومنهم من يقول بخلافها. فأما سنة يكونون مجتمعين على القول بخلافها، فلم أجدها قط، كما وجدت المرسل عن رسول الله.\nقال \"الشافعي\": وقلت له: أنت تسأل عن الحجة"},{"id":"risala-shafii:524","bookId":"risala-shafii","type":"section","seq":524,"chapter":"الجزء الثالث.","title":"ص: 471","page":"ج1 ص469","text":"في رد المرسل وترده، ثم تجاوز فترد المسند الذي يلزمك عندنا الأخذ به!!"},{"id":"risala-shafii:525","bookId":"risala-shafii","type":"section","seq":525,"chapter":"الجزء الثالث.","title":"باب الإجماع","page":"ج1 ص470","text":"قال \"الشافعي\": فقال لي قائل: قد فهمت مذهبك في أحكام الله، ثم أحكام رسوله، وأن من قبل عن رسول الله، فعن الله قبل، بأن الله افترض طاعة رسوله، وقامت الحجة بما قلت بأن لا يحل لمسلم علم كتابا ولا سنة أين يقول بخلاف واحد منهما، وعلمت أن هذا فرض الله. فما حجتك في أن تتبع ما اجتمع الناس عليه مما ليس فيه نص حكم لله، ولم يحكوه عن النبي؟ أتزعم ما يقول غيرك أن إجماعهم لا يكون أبدا إلا على سنة ثابتة، وإن لم يحكوها؟!","bab":"باب الإجماع"},{"id":"risala-shafii:526","bookId":"risala-shafii","type":"section","seq":526,"chapter":"الجزء الثالث.","title":"ص: 472","page":"ج1 ص471","text":"قال: فقلت له: أما ما اجتمعوا عليه، فذكروا أنه حكاية عن رسول الله، فكما قالوا، إن شاء الله.\nوأما ما لم يحكوه، فاحتمل أن يكون قالوا حكاية عن رسول الله، واحتمل غيره، ولا يجوز أن نعده له حكاية، لأنه لا يجوز أن يحكي إلا مسموعا، ولا يجوز أن يحكي شيئا يتوهم، يمكن فيه غير ما قال.\nفكنا نقول بما قالوا به اتباعا لهم، ونعلم أنهم إذا كانت سنن رسول الله لا تعزب عن عامتهم، وقد تعزب عن بعضهم. ونعلم أن عامتهم لا تجتمع على خلاف لسنة رسول الله، ولا على خطأ، إن شاء الله.\nفإن قال: فهل من شيء يدل على ذلك، وتشده به؟\nقيل: أخبرنا سفيان عن عبد الملك بن عمير عن عبد الرحمن بن عبد الله بن مسعود عن أبيه: أن رسول الله قال: \" نصر الله عبدا \" (1)\nأخبرنا سفيان عن عبد الله بن أبي لبيد عن ابن سليمان بن يسار عن أبيه: \" أن عمر بن الخطاب خطب الناس","bab":"باب الإجماع"},{"id":"risala-shafii:527","bookId":"risala-shafii","type":"section","seq":527,"chapter":"الجزء الثالث.","title":"ص: 474","page":"ج1 ص471","text":"بالجابية، فقال: إن رسول الله قام (2) فينا كمقامي فيكم، فقال: أكرموا أصحابي، ثم الذين يلونهم، ثم الذين يلونهم، ثم يظهر الكذب، حتى إن الرجل ليحلف ولا يستحلف، ويشهد ولا يستشهد، ألا فمن سره بحبحة الجنة فليلزم الجماعة، فإن الشيطان مع الفذ وهو من الاثنين أبعد، ولا يخلون رجل بامرأة، فإن الشيطان ثالثهم، ومن سرته حسنته، وساءته سيئته، فهو مؤمن\" (3) .","bab":"باب الإجماع"},{"id":"risala-shafii:528","bookId":"risala-shafii","type":"section","seq":528,"chapter":"الجزء الثالث.","title":"ص: 475","page":"ج1 ص471","text":"قال: فما معنى أمر النبي بلزوم جماعتهم؟\nقلت: لا معنى له إلا واحد.\nقال: فكيف لا يحتمل إلا واحدا؟\nقلت: إذا كانت جماعتهم متفرقة في البلدان، فلا يقدر أحد أن يلزم جماعة أبدان قوم متفرقين، وقد وجدت الأبدان تكون مجتمعة من المسلمين والكافرين والأتقياء والفجار، فلم يكن في لزوم الأبدان معنى، لأنه لا يمكن، ولأن اجتماع الأبدان لا يصنع شيئا فلم يكن للزوم جماعتهم معنى، إلا ما عليهم جماعتهم من التحليل والتحريم والطاعة فيهما.\nومن قال بما تقول به جماعة المسلمين فقد لزم جماعتهم، ومن خالف ما تقول به جماعة المسلمين فقد خالف جماعتهم التي أمر","bab":"باب الإجماع"},{"id":"risala-shafii:529","bookId":"risala-shafii","type":"section","seq":529,"chapter":"الجزء الثالث.","title":"ص: 476","page":"ج1 ص471","text":"بلزومها، وإنما تكون الغفلة في الفرقة، فأما الجماعة فلا يمكن فيها كافة غفلة عن معنى كتاب ولا سنة ولا قياس، إن شاء الله.","bab":"باب الإجماع"},{"id":"risala-shafii:530","bookId":"risala-shafii","type":"section","seq":530,"chapter":"الجزء الثالث.","title":"القياس","page":"ج1 ص473","text":"(1)\nقال: فمن أين قلت: يقال بالقياس فيما لا كتاب فيه ولا سنة ولا إجماع؟ أفالقياس نص خبر لازم؟\nقلت: لو كان القياس نص كتاب أو سنة قيل في كل ما كان نص كتاب \"هذا حكم الله \"، وفي كل ما كان","bab":"باب الإجماع"},{"id":"risala-shafii:531","bookId":"risala-shafii","type":"section","seq":531,"chapter":"الجزء الثالث.","title":"ص: 477","page":"ج1 ص476","text":"نص السنة \" هذا حكم رسول الله \"، ولم نقل له: \"قياس\".\nقال: فما القياس؟ أهو الاجتهاد؟ أم هما مفترقان؟\nقلت: هما اسمان لمعنى واحد.\nقال: فما جماعهما؟\nقلت: كل ما نزل بمسلم فقيه حكم لازم، أو على سبيل الحق فيه دلالة موجودة، وعليه إذا كان فيه بعينه حكم: اتباعه، وإذا لم يكن فيه بعينه طلب الدلالة على سبيل الحق فيه بالاجتهاد. والاجتهاد القياس. 0\nقال: أفرأيت العالمين إذا قاسوا، على إحاطة هم من أنهم أصابوا الحق عند الله؟ وهل يسعهم أن يختلفوا في القياس؟ وهل","bab":"باب الإجماع"},{"id":"risala-shafii:532","bookId":"risala-shafii","type":"section","seq":532,"chapter":"الجزء الثالث.","title":"ص: 478","page":"ج1 ص476","text":"كلفوا كل أمر من سبيل واحد، أو سبل متفرقة؟ وما الحجة في أن لهم أي يقيسوا على الظاهر دون الباطن؟ وأنه يسعهم أن يتفرقوا؟ وهل يختلف ما كلفوا في أنفسهم، وما كلفوا في غيرهم؟ ومن الذي له أن يجتهد فيقيس في نفسه دون غيره؟ والذي له أن يقيس في نفسه وغيره؟\nفقلت: له العلم من وجوه: منه إحاطة في الظاهر والباطن، ومنه حق في الظاهر.\nفالإحاطة منه ما كان نص حكم لله أو سنة لرسول الله نقلها العامة عن العامة. فهذان السبيلان اللذان يشهد بهما فيما أحل أنه حلال، وفيما حرم أنه حرام. وهذا الذي لا يسع أحدا عندنا جهله ولا الشك فيه.\nوعلم الخاصة سنة من خبر الخاصة يعرفها العلماء،","bab":"باب الإجماع"},{"id":"risala-shafii:533","bookId":"risala-shafii","type":"section","seq":533,"chapter":"الجزء الثالث.","title":"ص: 479","page":"ج1 ص476","text":"ولم يكلفها غيرهم، وهي موجودة فيهم أو في بعضهم، بصدق الخاص المخبر عن رسول الله بها. وهذا اللازم لأهل العلم أن يصيروا إليه، وهو الحق في الظاهر، كما نقتل بشاهدين. وذلك حق في الظاهر، وقد يمكن في الشاهدين الغلط.\nوعلم إجماع.\nوعلم اجتهاد بقياس، على طلب إصابة الحق. فذلك حق في الظاهر عند قايسه، لا عند العامة من العلماء، ولا يعلم الغيب فيه إلا الله.\nوإذا طلب العلم فيه بالقياس، فقيس بصحة: ايتفق المقايسون في أكثره، وقد نجدهم يختلفون.\nوالقياس من وجهين: أحدهما: أن يكون الشيء في معنى الأصل، فلا يختلف القياس فيه. وأن يكون الشيء له في الأصول أشباه، فذلك يلحق بأولاها به وأكثرها شبها فيه. وقد يختلف القايسون في هذا.\nقال: فأوجدني ما أعرف به أن العلم من وجهين: أحدهما: إحاطة بالحق في الظاهر والباطن، والآخر إحاطة بحق في الظاهر دون الباطن: مما أعرف؟\nفقلت له: أرأيت إذا كنا في المسجد الحرام نرى الكعبة: أكلفنا أن نستقبلها بإحاطة؟\nقال: نعم.\nقلت: وفرضت علينا الصلوات والزكاة والحج، وغير ذلك: أكلفنا الإحاطة في أن نأتي بما علينا بإحاطة؟\nقال: نعم.\nقلت: وحين فرض علينا أن نجلد الزاني مائة، ونجلد القاذف ثمانين، ونقتل من كفر بعد إسلامه، ونقطع من سرق: أكلفنا أن نفعل هذا بمن ثبت عليه بإحاطة نعلم أنا قد أخذناه منه؟\nقال: نعم.","bab":"باب الإجماع"},{"id":"risala-shafii:534","bookId":"risala-shafii","type":"section","seq":534,"chapter":"الجزء الثالث.","title":"ص: 481","page":"ج1 ص476","text":"قلت: وسواء ما كلفنا في أنفسنا وغيرنا، إذا كنا ندري من أنفسنا بأنا نعلم منها ما لا يعلم غيرنا، ومن غيرنا ما لا يدركه علمنا كإدراكنا العلم في أنفسنا؟\nقال: نعم.\nقلت: وكلفنا في أنفسنا أين ما كنا أن نتوجه إلى البيت بالقبلة؟\nقال: نعم.\nقلت: أفتجدنا على إحاطة من أنا قد أصبنا البيت بتوجهنا؟\nقال: أما كما وجدتكم حين كنتم ترون فلا، وأما أنتم فقد أديتم ما كلفتم.\nقلت: والذي كلفنا في طلب العين المغيب غير الذي كلفنا في طلب العين الشاهد.","bab":"باب الإجماع"},{"id":"risala-shafii:535","bookId":"risala-shafii","type":"section","seq":535,"chapter":"الجزء الثالث.","title":"ص: 482","page":"ج1 ص476","text":"قال: نعم.\nقلت: وكذلك كلفنا أن نقبل عدل الرجل على ما ظهر لنا منه، ونناكحه ونوارثه على ما يظهر لنا من إسلامه؟\nقال: نعم.\nقلت: وقد يكون غير عدل في الباطن؟\nقال: قد يمكن هذا فيه، ولكن لم تكلفوا فيه الا الظاهر.\nقلت: وحلال لنا أن نناكحه، ونوارثه، ونجيز شهادته، ومحرم علينا دمه بالظاهر؟ وحرام على غيرنا إن علم منه أنه كافر إلا قتله ومنعه المناكحة والموارثة وما أعطيناه؟\nقال: نعم.\nقلت: وجد الفرض علينا في رجل واحد مختلفا على مبلغ علمنا وعلم غيرنا؟","bab":"باب الإجماع"},{"id":"risala-shafii:536","bookId":"risala-shafii","type":"section","seq":536,"chapter":"الجزء الثالث.","title":"ص: 483","page":"ج1 ص476","text":"قال: نعم، وكلكم مؤدي ما عليه على قدر علمه.\nقلت: هكذا قلنا لك فيما ليس فيه نص حكم لازم، وإنما نطلب باجتهاد القياس، وإنما كلفنا فيه الحق عندنا.\nقال: فتجدك تحكم بأمر واحد من وجوه مختلفة؟\nقلت: نعم، إذا اختلفت أسبابه.\nقال: فاذكر منه شيئا.\nقلت: قد يقر الرجل عندي على نفسه بالحق لله، أو لبعض الآدميين، فآخذه بإقراره، ولا يقر، فآخذه بينة تقوم عليه، ولا تقوم عليه بينة، فيدعى عليه، فآمره بأن يحلف ويبرأ، فيمتنع، فآمر خصمه بأن يحلف، ونأخذه بما حلف عليه خصمه، إذا أبى اليمين التي تبرئه، ونحن نعلم أن إقراره على نفسه - بشحه على","bab":"باب الإجماع"},{"id":"risala-shafii:537","bookId":"risala-shafii","type":"section","seq":537,"chapter":"الجزء الثالث.","title":"ص: 484","page":"ج1 ص479","text":"ماله، وأنه يخاف ظلمه بالشح عليه -: أصدق عليه من شهادة غيره، لأن غيره قد يغلط ويكذب عليه، وشهادة العدول عليه أقرب من الصدق من امتناعه من اليمين ويمين خصمه، وهو غير عدل، وأعطي منه بأسباب بعضها أقوى من بعض.\nقال: هذا كله هكذا، غير أنا إذا نكل عن اليمين أعطينا منه بالنكول.\nقلت: فقد أعطيت منه بأضعف مما أعطينا منه؟\nقال: أجل، ولكني أخالفك في الأصل.\nقلت: وأقوى ما أعطيت به منه إقراره، وقد يمكن أن يقر بحق مسلم ناسيا أو غلطا، فآخذه به؟\nقال: أجل، ولكنك لم تكلف إلا هذا.","bab":"باب الإجماع"},{"id":"risala-shafii:538","bookId":"risala-shafii","type":"section","seq":538,"chapter":"الجزء الثالث.","title":"ص: 485","page":"ج1 ص479","text":"قلنا: فلست تراني كلفت الحق من وجهين: أحدهما: حق بإحاطة في الظاهر والباطن، والآخر: حق بالظاهر دون الباطن؟\nقال: بلى، ولكن هل تجد في هذا قوة بكتاب أو سنة؟\nقلت: نعم، ما وصفت لك مما كلفت في القبلة وفي نفسي وفي غيري.\nقال الله: {ولا يحيطون بشيء من علمه إلا بما شاء} [البقرة 255] فآتاهم من علمه ما شاء، وكما شاء، لا معقب لحكمه، وهو سريع الحساب.\nوقال لنبيه: {يسئلونك عن الساعة أيان مرساها فيم أنت من ذكراها إلى ربك منتهاها} [النازعات 42 - 44]\nسفيان عن الزهري عن عروة قال: \" لم يزل رسول الله يسأل عن الساعة، حتى أنزل الله عليه {فيم أنت من ذكراها} فانتهى\".","bab":"باب الإجماع"},{"id":"risala-shafii:539","bookId":"risala-shafii","type":"section","seq":539,"chapter":"الجزء الثالث.","title":"ص: 486","page":"ج1 ص479","text":"وقال الله: {قل لا يعلم من في السماوات والأرض الغيب إلا الله} [النمل 65]\nوقال الله تبارك وتعالى: {إن الله عنده علم الساعة، وينزل الغيث، ويعلم ما في الأرحام، وما تدري نفس ماذا تكسب غدا، وما تدري نفس بأي أرض تموت، إن الله عليم خبير} [لقمان 34]\nفالناس متعبدون بأن يقولوا ويفعلوا ما أمروا به، وينتهوا إليه، لا يجاوزونه، لأنهم لم يعطوا أنفسهم شيئا، إنما هو عطاء الله. فنسأل الله عطاءا مؤديا لحقه، موجبا لمزيده.","bab":"باب الإجماع"},{"id":"risala-shafii:540","bookId":"risala-shafii","type":"section","seq":540,"chapter":"الجزء الثالث.","title":"باب الاجتهاد","page":"ج1 ص483","text":"قال: أفتجد تجويز ما قلت من الاجتهاد، مع ما وصفت فتذكره؟\nقلت: نعم، استدلالا بقول الله: {ومن حيث خرجت فول وجهك شطر المسجد الحرام، وحيث ما كنتم فولوا وجوهكم شطره} [البقرة 150]\nقال: فما شطره؟\nقلت: تلقاءه قال الشاعر:\nإن العسيب بها داء مخامرها فشطرها بصر العينين مسجور (1)","bab":"باب الاجتهاد"},{"id":"risala-shafii:541","bookId":"risala-shafii","type":"section","seq":541,"chapter":"الجزء الثالث.","title":"ص: 488","page":"ج1 ص486","text":"فالعلم يحيط أن من توجه تلقاء المسجد الحرام ممن نأت داره عنه: على صواب بالاجتهاد للتوجه الى البيت بالدلائل عليه، لأن الذي كلف التوجه إليه، وهو لا يدري أصاب بتوجهه قصد المسجد الحرام أم أخطأه، وقد يرى دلائل يعرفها فيتوجه بقدر ما يعرف [ويعرف غيره دلائل غيرها، فيتوجه بقدر ما يعرف] وإن اختلف توجههما.\nقال: فإن أجزت لك هذا أجزت لك في بعض الحالات الاختلاف.\nقلت: فقل فيه ما شئت.\nقال: أقول. لا يجوز هذا.\nقلت: فهو أنا وأنت، ونحن بالطريق عالمان،","bab":"باب الاجتهاد"},{"id":"risala-shafii:542","bookId":"risala-shafii","type":"section","seq":542,"chapter":"الجزء الثالث.","title":"ص: 489","page":"ج1 ص486","text":"قلت: وهذه القبلة، وزعمت خلافي على أينا يتبع صاحبه؟\nقال: ما على واحد منكما أن يتبع صاحبه.\nقلت: فما يجب عليهما؟\nقال: إن قلت لا يجب عليهما أن يصليا حتى يعلما بإحاطة: فهما لا يعلمان أبدا المغيب بإحاطة، وهما إذا يدعان الصلاة، أو يرتفع عنهما فرض القبلة، فيصليان حيث شاءا، ولا أقول واحدا من هذين، وما أجد بدا من أن أقول: يصلي كل واحد منهما كما يرى، ولم يكلفا غير هذا، أو أقول كلف الصواب في الظاهر والباطن، ووضع عنهما الخطأ في الباطن دون الظاهر.\nقلت: فأيهما قلت فهو حجة عليك، لأنك فرقت بين حكم الباطن والظاهر، وذلك الذي أنكرت علينا، وأنت: تقول إذا اختلفتم قلت ولا بد أن يكون أحدهما مخطئ؟\nقلت: أجل.\nقلت: فقد أجزت الصلاة وأنت تعلم أحدهما","bab":"باب الاجتهاد"},{"id":"risala-shafii:543","bookId":"risala-shafii","type":"section","seq":543,"chapter":"الجزء الثالث.","title":"ص: 490","page":"ج1 ص486","text":"مخطئ، وقد يمكن أن يكونا معا مخطئين.\nوقلت له: وهذا يلزمك في الشهادات وفي القياس.\nقال: ما أجد من هذا بدا، ولكن أقول: هو خطأ موضوع.\nفقلت له: قال الله: {ولا تقتلوا الصيد وأنتم حرم، ومن قتله منكم متعمدا، فجزاء مثل ما قتل من النعم، يحكم به ذوا عدل منكم، هديا بالغ الكعبة} [المائدة 95]\nفأمرهم بالمثل، وجعل المثل الى عدلين يحكمان فيه، فلما حرم مأكول الصيد عاما كانت لدواب الصيد أمثال على الأبدان.\nفحكم من حكم من أصحاب رسول الله على ذلك،","bab":"باب الاجتهاد"},{"id":"risala-shafii:544","bookId":"risala-shafii","type":"section","seq":544,"chapter":"الجزء الثالث.","title":"ص: 491","page":"ج1 ص486","text":"فقضى في الضبع بكبش، وفي الغزال بعنز، وفي الأرنب بعناق، وفي اليربوع بجفرة. (1)\nوالعلم يحيط أنهم أرادوا في هذا المثل بالبدن، لا بالقيم، ولو حكموا على القيم اختلفت أحكامهم لاختلاف أثمان الصيد في البلدان وفي الأزمان، وأحكامهم فيها واحدة.\nوالعلم يحيط أن اليربوع ليس مثل الجفرة في البدن، ولكنها كانت أقرب الأشياء منه شبها، فجعلت مثله، وهذا من القياس يتقارب تقارب العنز والظبي، ويبعد قليلا بعد الجفرة من اليربوع.\nولما كان المثل في الأبدان في الدواب من الصيد دون الطائر: لم يجز فيه إلا ما قال عمر - والله أعلم - من أن ينظر الى المقتول من الصيد، فيجزى بأقرب الأشياء به شبها منه في البدن،","bab":"باب الاجتهاد"},{"id":"risala-shafii:545","bookId":"risala-shafii","type":"section","seq":545,"chapter":"الجزء الثالث.","title":"ص: 492","page":"ج1 ص486","text":"فإذا فات منها شيئا (2) رفع إلى أقرب الأشياء به شبها، كما فاتت الضبع العنز، فرفعت الى الكبش، وصغر اليربوع عن العناق فخفض الى الجفرة.\nوكان طائر الصيد لا مثل له في النعم لاختلاف خلقته وخلقته، فجزي خبرا وقياسا (3) على ما كان ممنوعا لإنسان فأتلفه إنسان، فعليه قيمته لمالكه.\nقال \"الشافعي\": فالحكم فيه بالقيمة يجتمع في أنه يقوم قيمة يومه وبلده، ويختلف في الأزمان والبلدان، حتى يكون الطائر ببلد ثمن درهم، وفي البلد الآخر ثمن بعض ردهم.\nوأمرنا بإجازة شهادة العدل، وإذا شرط علينا أن نقبل العدل ففيه دلالة على أن نرد ما خالفه.\nوليس للعدل علامة تفرق بينه وبين غير العدل في بدنه ولا لفظه، وإنما علامة صدقه بما يختبر من حاله في نفسه.\nفإذا كان الأغلب من أمره ظاهر الخير: قبل، وإن كان فيه تقصير عن بعض أمره، لأنه لا يعرى أحد رأيناه من الذنوب.\nوإذا خلط الذنوب والعمل الصالح، فليس فيه إلا الاجتهاد على الأغلب من أمره، بالتمييز بين حسنه وقبيحه، وإذا كان هذا هكذا، فلا بد من أن يختلف المجتهدون فيه.\nوإذا ظهر حسنه فقبلنا شهادته، فجاء حاكم غيرنا، فعلم منه ظهور السيء كان عليه رده.","bab":"باب الاجتهاد"},{"id":"risala-shafii:546","bookId":"risala-shafii","type":"section","seq":546,"chapter":"الجزء الثالث.","title":"ص: 494","page":"ج1 ص490","text":"وقد حكم الحاكمان في أمر واحد برد وقبول، وهذا اختلاف، ولكن كل قد فعل ما عليه.\nقال: فتذكر حديثا في تجويز الاجتهاد؟\nقلت: نعم، أخبرنا عبد العزيز عن يزيد بن عبد الله بن الهاد عن محمد بن إبراهيم عن بسر بن سعيد عن أبي قيس مولى عمرو بن العاص عن عمرو بن العاص: أنه سمع رسول الله يقول: \" إذا حكم الحاكم فاجتهد فأصاب، فله أجران، وإذا حكم فاجتهد ثم أخطأ، فله أجر\"","bab":"باب الاجتهاد"},{"id":"risala-shafii:547","bookId":"risala-shafii","type":"section","seq":547,"chapter":"الجزء الثالث.","title":"ص: 495","page":"ج1 ص493","text":"أخبرنا عبد العزيز عن ابن الهاد قال: فحدثت بهذا الحديث أبا بكر بن محمد بن عمرو بن حزم، فقال: هكذا حدثني أبو سلمة عن أبي هريرة (1)\nفقال: هذه رواية منفردة، يردها علي وعليك غيري وغيرك، ولغيري عليك فيها موضع مطالبة.\nقلت: نحن وأنت ممن يثبتها؟\nقال: نعم.\nقلت: فالذين يردونها يعلمون ما وصفنا من تثبيتها وغيره.","bab":"باب الاجتهاد"},{"id":"risala-shafii:548","bookId":"risala-shafii","type":"section","seq":548,"chapter":"الجزء الثالث.","title":"ص: 496","page":"ج1 ص493","text":"قلت: فأين موضع المطالبة فيها؟\nفقال: قد سمى رسول الله فيما رويت من الاجتهاد \"خطأ\" و \"صوابا\"؟\nفقلت: فذلك الحجة عليك.\nقال: وكيف؟\nقلت: إذ ذكر النبي أنه يثاب على أحدهما أكثر مما يثاب على الآخر، ولا يكون الثواب فيما لا يسع، ولا الثواب في الخطأ الموضوع.\nلأنه لو كان إذا قيل له: اجتهد على الخطأ، فاجتهد على","bab":"باب الاجتهاد"},{"id":"risala-shafii:549","bookId":"risala-shafii","type":"section","seq":549,"chapter":"الجزء الثالث.","title":"ص: 497","page":"ج1 ص493","text":"الظاهر كما أمر كان مخطئا خطأ مرفوعا، كما قلت -: كانت العقوبة في الخطأ - فيما نرى والله أعلم - أولى به، وكان أكثر أمره أن يغفر له، ولم يشبه أن يكون له ثواب على خطأ لا يسعه.\nوفي هذا دليل على ما قلنا: أنه إنما كلف في الحكم الاجتهاد على الظاهر دون المغيب، والله أعلم.\nقال: إن هذا ليحتمل أن يكون كما قلت، ولكن ما معنى \"صواب\" \"خطأ\"؟\nقلت له: مثل معنى استقبال الكعبة، يصيبها من رآها بإحاطة، ويتحراها من غابت عنه، بعد أو قرب منها، فيصيبها بعض ويخطئها بعض، فنفس التوجه يحتمل صوابا وخطأ، إذا قصدت بالإخبار عن الصواب والخطأ قصد أن يقول: فلان أصاب","bab":"باب الاجتهاد"},{"id":"risala-shafii:550","bookId":"risala-shafii","type":"section","seq":550,"chapter":"الجزء الثالث.","title":"ص: 498","page":"ج1 ص493","text":"قصد ما طلب فلم يخطئه، وفلان أخطأ قصد ما طلب وقد جهد في طلبه.\nفقال: هذا هكذا، أفرأيت الاجتهاد، أيقال له \"صواب \" على غير هذا المعنى؟\nقلت: نعم على أنه إنما كلف فيما غاب عنه الاجتهاد، فإذا فعل فقد أصاب بالإتيان بما كلف، وهو صواب عنده على الظاهر، ولا يعلم الباطن إلا الله.\nونحن نعلم أن المختلفين في القبلة، وإن أصابا بالاجتهاد إذا اختلفنا يريدان عينا: لم يكونا مصيبين للعين أبدا، ومصيبان في الاجتهاد. وهكذا ما وصفنا في الشهود وغيرهم.\nقال: أفتوجدني مثل هذا؟\nقلت: ما أحسب هذا يوضح بأقوى من هذا!\nقال: فاذكر غيره؟\nقلت: أحل الله لنا أن ننكح من النساء مثنى وثلاث ورباع وما ملكت أيماننا، وحرم الأمهات والبنات والأخوات.\nقال: نعم.\nقلت: فلو أن رجلا اشترى جارية، فاستبرأها أيحل له إصابتها؟\nقال: نعم.\nقلت: فأصابها وولدت له دهرا، ثم علم أنها أخته، كيف القول فيه؟\nقال: كان ذلك حلالا حتى علم بها، فلم يحل له أن يعود إليها.\nقلت: فيقال لك في امرأة واحدة حلال له حرام","bab":"باب الاجتهاد"},{"id":"risala-shafii:551","bookId":"risala-shafii","type":"section","seq":551,"chapter":"الجزء الثالث.","title":"ص: 500","page":"ج1 ص498","text":"عليه، بغير إحداث شيء أحدثه هو ولا أحدثته؟\nقال: أما في المغيب فلم تزل أخته أولا وآخرا، وأما في الظاهر، فكانت له حلالا ما لم يعلم، وعليه حرام حين علم.\nوقال: إن غيرنا ليقول: لم يزل آثما بإصابتها، ولكنه مأثم مرفوع عنه.\nفقلت: الله اعلم، وأيهما كان، فقد فرقوا فيه بين حكم الظاهر والباطن، وألغوا المأثم عن المجتهد على الظاهر، وإن أخطأ عندهم، ولم يلغوه عن العامد.\nقال: أجل.\nوقلت له: مثل هذا الرجل ينكح ذات محرم منه، ولا يعلم، وخامسة وقد بلغته وفاة رابعة كانت زوجة له، وأشباه لهذا.","bab":"باب الاجتهاد"},{"id":"risala-shafii:552","bookId":"risala-shafii","type":"section","seq":552,"chapter":"الجزء الثالث.","title":"ص: 501","page":"ج1 ص498","text":"قال: نعم أشباه هذا كثير.\nفقال: إنه لبين عند من يثبت الرواية منكم أنه لا يكون الاجتهاد أبدا إلا على طلب عين قائمة مغيبة بدلالة، وأنه قد يسع الاختلاف من له الاجتهاد.\nفقال: فكيف الاجتهاد؟\nفقلت: إن الله جل ثناؤه من على العباد بعقول، فدلهم بها على الفرق بين المختلف، وهداهم السبيل إلى الحق نصا ودلالة.\nقال: فمثل من ذلك شيئا؟\nقلت: نصب لهم البيت الحرام، وأمرهم بالتوجه إليه إذا رأوه، وتأخيه إذا غابوا عنه، وخلق لهم سماء وأرضا وشمسا وقمرا ونجوما وبحارا وجبالا ورياحا.","bab":"باب الاجتهاد"},{"id":"risala-shafii:553","bookId":"risala-shafii","type":"section","seq":553,"chapter":"الجزء الثالث.","title":"ص: 502","page":"ج1 ص499","text":"فقال: {وهو الذي جعل لكم النجوم لتهتدوا بها في ظلمات البر والبحر} [الأنعام 97]\nوقال: {وعلامات وبالنجم هم يهتدون} [النحل 16]\nفأخبر أنهم يهتدون بالنجم والعلامات.\nفكانوا يعرفون بمنه جهة البيت بمعونته لهم، وتوفيقه إياهم، بأن قد رآه من رآه منهم في مكانه، وأخبر من رآه منهم من لم يره، وأبصر ما يهتدى به إليه، من جبل يقصد قصده، أو نجم يؤتم به وشمال وجنوب، وشمس يعرف مطلعها ومغربها، وأين تكون من المصلى بالعشي، وبحور كذلك.\nوكان عليهم تكلف الدلالات بما خلق لهم من العقول التي ركبها فيهم، ليقصدوا قصد التوجه للعين التي فرض عليهم استقبالها.","bab":"باب الاجتهاد"},{"id":"risala-shafii:554","bookId":"risala-shafii","type":"section","seq":554,"chapter":"الجزء الثالث.","title":"ص: 503","page":"ج1 ص499","text":"فإذا طلبوها مجتهدين بعقولهم وعلمهم بالدلائل، بعد استعانة الله، والرغبة إليه في توفيقه، فقد أدوا ما عليهم.\nوأبان لهم أن فرضه عليهم التوجه شطر المسجد الحرام، والتوجه شطره لا إصابة البيت بكل حال.\nولم يكن لهم إذا كان لا تمكنهم الإحاطة في الصواب إمكان من عاين البيت: أن يقولوا نتوجه حيث رأينا بلا دلالة.","bab":"باب الاجتهاد"},{"id":"risala-shafii:555","bookId":"risala-shafii","type":"section","seq":555,"chapter":"الجزء الثالث.","title":"باب الاستحسان","page":"ج1 ص501","text":"قال: هذا كما قلت، والاجتهاد لا يكون إلا على مطلوب، والمطلوب لا يكون أبدا إلا على عين قائمة تطلب بدلالة","bab":"باب الاستحسان"},{"id":"risala-shafii:556","bookId":"risala-shafii","type":"section","seq":556,"chapter":"الجزء الثالث.","title":"ص: 504","page":"ج1 ص503","text":"يقصد بها إليها، أو تشبيه على عين قائمة، وهذا يبين أن حراما على أحد أن يقول بالاستحسان إذا خالف الاستحسان الخبر، والخبر - من الكتاب والسنة - عين يتأخى معناها المجتهد ليصيبه، كما البيت يتأخاه من غاب عنه ليصيبه، أو قصده بالقياس، وأن ليس لأحد أن يقول إلا من جهة الاجتهاد، والاجتهاد ما وصفت من طلب الحق. فهل تجيز أنت أن يقول الرجل: أستحسن بغير قياس؟\nفقلت: لا يجوز هذا عندي - والله أعلم - لأحد، وإنما كان لأهل العلم أن يقولوا دون غيرهم، لأن يقولوا في الخبر باتباعه فيما ليس فيه الخبر بالقياس على الخبر.","bab":"باب الاستحسان"},{"id":"risala-shafii:557","bookId":"risala-shafii","type":"section","seq":557,"chapter":"الجزء الثالث.","title":"ص: 505","page":"ج1 ص503","text":"ولو جاز تعطيل القياس جاز لأهل العقول من غير أهل العلم أن يقولوا فيما ليس فيه خبر بما يحضرهم من الاستحسان.\nوإن القول بغير خبر ولا قياس لغير جائز، بما ذكرت من كتاب الله وسنة رسوله، ولا في القياس.\nفقال: أما الكتاب والسنة فيدلان على ذلك، لأنه إذا أمر النبي بالاجتهاد، فالاجتهاد أبدا لا يكون إلا على طلب شيء، وطلب الشيء لا يكون إلا بدلائل، والدلائل هي القياس، قال: فأين القياس مع الدلائل على ما وصفت؟\nقلت: ألا ترى أن أهل العلم إذا أصاب رجل","bab":"باب الاستحسان"},{"id":"risala-shafii:558","bookId":"risala-shafii","type":"section","seq":558,"chapter":"الجزء الثالث.","title":"ص: 506","page":"ج1 ص503","text":"لرجل عبدا لم يقولوا لرجل: أقم عبدا ولا أمة إلا وهو خابر بالسوق، ليقيم معنيين: بما يخبر كم ثمن مثله في يومه؟ ولا يكون ذلك إلا بأن يعتبر عليه بغيره، فيقيسه عليه، ولا يقال لصاحب سلعة: أقم إلا وهو خابر.","bab":"باب الاستحسان"},{"id":"risala-shafii:559","bookId":"risala-shafii","type":"section","seq":559,"chapter":"الجزء الثالث.","title":"ص: 507","page":"ج1 ص503","text":"ولا يجوز أن يقال لفقيه عدل غير عالم بقيم الرقيق: أقم هذا العبد، ولا هذه الأمة ولا إجازة هذا العامل، لأنه إذا أقامه على غير مثال بدلالة على قيمته كان متعسفا.\nفإذا كان هذا هكذا فيما تقل قيمته من المال وييسر الخطأ فيه على المقام له والمقام عليه -: كان حلال الله وحرامه أولى أن لا يقال فيهما بالتعسف والاستحسان.\nوإنما الاستحسان تلذذ.\nولا يقول فيه إلا عالم بالأخبار، عاقل للتشبيه عليها.\nوإذا كان هذا هكذا، كان على العالم أن لا يقول إلا من جهة العلم، - وجهة العلم الخبر اللازم - بالقياس بالدلائل","bab":"باب الاستحسان"},{"id":"risala-shafii:560","bookId":"risala-shafii","type":"section","seq":560,"chapter":"الجزء الثالث.","title":"ص: 508","page":"ج1 ص505","text":"على الصواب حتى يكون صاحب العلم أبدا متبعا خبرا، وطالب الخبر بالقياس، كما يكون متبع البيت بالعيان، وطالب قصده بالاستدلال بالأعلام مجتهدا.\nولو قال بلا خبر لازم وقياس كان أقرب من الإثم من الذي قال وهو غير عالم، وكان القول لغير أهل العلم جائزا\nولم يجعل الله لأحد بعد رسول الله أن يقول إلا من جهة علم مضى قبله، وجهة العلم بعد الكتاب والسنة والإجماع والآثار، وما وصفت من القياس عليها.\nولا يقيس إلا من جمع الآلة التي له القياس بها،","bab":"باب الاستحسان"},{"id":"risala-shafii:561","bookId":"risala-shafii","type":"section","seq":561,"chapter":"الجزء الثالث.","title":"ص: 510","page":"ج1 ص507","text":"وهي العلم بأحكام كتاب الله: فرضه، وأدبه، وناسخه، ومنسوخه، وعامه، وخاصه، وإرشاده.\nويستدل على ما احتمل التاويل منه بسنن رسول الله، فإذا لم يجد سنة فبإجماع المسلمين، فإن لم يكن إجماع فبالقياس.\nولا يكون لأحد أن يقيس حتى يكون عالما بما مضى قبله من السنن، وأقاويل السلف، وإجماع الناس، واختلافهم، ولسان العرب.\nولا يكون له أن يقيس حتى يكون صحيح العقل، وحتى يفرق بين المشتبه، ولا يعجل بالقول به دون التثبيت.\nولا يمتنع من الاستماع ممن خالفه، لأنه قد يتنبه بالاستماع لترك الغفلة، ويزداد به تثبيتا فيما اعتقده من الصواب.","bab":"باب الاستحسان"},{"id":"risala-shafii:562","bookId":"risala-shafii","type":"section","seq":562,"chapter":"الجزء الثالث.","title":"ص: 511","page":"ج1 ص507","text":"وعليه في ذلك بلوغ غاية جهده، والإنصاف من نفسه، حتى يعرف من أين قال ما يقول، وترك ما يترك.\nولا يكون بما قال أعنى منه بما خالفه، حتى يعرف فضل ما يصير إليه على ما يترك، إن شاء الله.\nفأما من تم عقله، ولم يكن عالما بما وصفنا، فلا يحل له أن يقول بقياس، وذلك أنه لا يعرف ما يقيس عليه، كما لا يحل لفقيه عاقل أن يقول في ثمن درهم ولا خبرة له بسوقه.\nومن كان عالما بما وصفنا بالحفظ لا بحقيقة المعرفة: فليس له أن يقول أيضا بقياس، لأنه قد يذهب عليه عقل المعاني.\nوكذلك لو كان حافظا مقصر العقل، أو مقصرا عن علم لسان العرب: لم يكن له أن يقيس من قبل نقص عقله عن الآلة التي يجوز بها القياس.\nولا نقول يسع - هذا والله أعلم - أن يقول أبدا إلا اتباعا ولا قياسا.\nفإن قال قائل: فاذكر من الأخبار التي تقيس عليها، وكيف تقيس؟\nقيل له إن شاء الله: كل حكم لله أو لرسوله وجدت عليه دلالة فيه أو في غيره من أحكام الله أو رسوله بأنه حكم به لمعنى من المعاني، فنزلت نازلة ليس فيها نص حكم: حكم فيها حكم النازلة المحكوم فيها، إذا كانت في معناها.\nوالقياس وجوه يجمعها \"القياس \"، ويتفرق","bab":"باب الاستحسان"},{"id":"risala-shafii:563","bookId":"risala-shafii","type":"section","seq":563,"chapter":"الجزء الثالث.","title":"ص: 513","page":"ج1 ص509","text":"بها ابتداء قياس كل واحد منهما، أو مصدره، أو هما، وبعضهما أوضح من بعض.\nفأقوى القياس أن يحرم الله في كتابه أو يحرم رسول الله القليل من الشيء، فيعلم أن قليله إذا حرم كان كثيره مثل قليله في التحريم أو أكثر، بفضل الكثرة على القلة.\nوكذلك إذا حمد على يسير من الطاعة، كان ما هو أكثر منها أولى أن يحمد عليه.\nوكذلك إذا أباح كثير شيء كان الأقل منه أولى أن يكون مباحا.\nفإن قال: فاذكر من كل واحد من هذا شيئا يبين لنا ما في معناه؟","bab":"باب الاستحسان"},{"id":"risala-shafii:564","bookId":"risala-shafii","type":"section","seq":564,"chapter":"الجزء الثالث.","title":"ص: 514","page":"ج1 ص512","text":"قلت: قال رسول الله: \"إن الله حرم من المؤمن دمه وماله، وأن يظن به إلا خيرا\" (1)\nفإذا حرم أن يظن به ظنا مخالفا للخير يظهره: كان ما هو أكثر من الظن المظهر ظنا من التصريح له","bab":"باب الاستحسان"},{"id":"risala-shafii:565","bookId":"risala-shafii","type":"section","seq":565,"chapter":"الجزء الثالث.","title":"ص: 515","page":"ج1 ص512","text":"بقول غير الحق أولى أن يحرم، ثم كيف ما زيد في ذلك كان أحرم.\nقال الله: {فمن يعمل مثقال ذرة خيرا يره، ومن يعمل مثقال ذرة شرا يره} [الزلزلة 7، 8]\nفكان ما هو أكثر من مثقال ذرة من الخير أحمد، وما هو أكثر من مثقال ذرة من الشر أعظم في المأثم.\nوأباح لنا دماء أهل الكفر المقاتلين غير المعاهدين، وأموالهم، ولم يحظر علينا منها شيئا أذكره، فكان ما نلنا من أبدانهم دون الدماء، ومن أموالهم دون كلها: أولى أن يكون مباحا.\nوقد يمتنع بعض أهل العلم من أن يسمي","bab":"باب الاستحسان"},{"id":"risala-shafii:566","bookId":"risala-shafii","type":"section","seq":566,"chapter":"الجزء الثالث.","title":"ص: 516","page":"ج1 ص513","text":"هذا \" قياسا \" ويقول: هذا معنى ما أحل الله، وحرم، وحمد، وذم، لأنه داخل في جملته، فهو بعينه، ولا قياس على غيره.\nويقول مثل هذا القول في غير هذا، مما كان في معنى الحلال فأحل، والحرام فحرم.\nويمتنع أن يسمى\" القياس \" إلا ما كان يحتمل أن يشبه بما احتمل أن يكون فيه شبها (1) من معنيين مختلفين، فصرفه على أن يقيسه على أحدهما دون الآخر.\nويقول غيرهم من أهل العلم: ما عدا النص من الكتاب أو السنة، فكان في معناه فهو قياس، والله اعلم.\nفإن قال قائل: فاذكر من وجوه القياس ما يدل على اختلافه في البيان والأسباب، والحجة فيه سوى هذا الأول، الذي تدرك العامة علمه؟\nقيل له إن شاء الله: قال الله: {والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة وعلى المولود له رزقهن وكسوتهن بالمعروف} [البقرة 233]\nوقال: {وإن أردتم أن تسترضعوا أولادكم، فلا جناح عليكم إذا سلمتم ما آتيتم بالمعروف} [البقرة 233]\nفأمر رسول الله هند بنت عتبة أن تأخذ من مال زوجها أبي سفيان ما يكفيها وولدها - وهم ولده - بالمعروف بغير أمره.\nقال: فدل كتاب الله وسنة نبيه أن على الوالد رضاع ولده، ونفقتهم صغارا.","bab":"باب الاستحسان"},{"id":"risala-shafii:567","bookId":"risala-shafii","type":"section","seq":567,"chapter":"الجزء الثالث.","title":"ص: 518","page":"ج1 ص515","text":"فكان الولد من الوالد فجبر على صلاحه في الحال التي لا يغني الولد فيها نفسه، فقلت: إذا بلغ الأب ألا يغني نفسه بكسب ولا مال، فعلى ولده صلاحه في نفقته وكسوته قياسا على الولد.\nوذلك أن الولد من الوالد، فلا يضيع شيئا هو منه، كما لم يكن للولد أن يضيع شيئا من ولده، إذ كان الولد منه، وكذلك الوالدون وإن بعدوا، والولد وإن سفلوا في هذا المعنى، والله أعلم، فقلت: ينفق على كل محتاج منهم غير محترف، وله النفقة على الغني المحترف.\nوقضى رسول الله في عبد دلس للمبتاع فيه بعيب","bab":"باب الاستحسان"},{"id":"risala-shafii:568","bookId":"risala-shafii","type":"section","seq":568,"chapter":"الجزء الثالث.","title":"ص: 519","page":"ج1 ص515","text":"فظهر عليه بعد ما استغله أن للمبتاع رده بالعيب، وله حبس الغلة بضمانه العبد.\nفاستدللنا إذا كانت الغلة لم يقع عليها صفقة البيع، فيكون لها حصة من الثمن، وكانت في ملك المشتري في الوقت الذي لو مات فيه العبد مات من مال المشتري: أنه إنما جعلها له لأنها حادثة في ملكه وضمانه، فقلنا: كذلك في ثمر النخل، ولبن الماشية وصوفها وأولادها، وولد الجارية، وكل ما حدث في ملك المشتري وضمانه، وكذلك وطء الأمة الثيب وخدمتها.\nقال: فتفرق علينا بعض أصحابنا وغيرهم في هذا.\nفقال بعض الناس: الخراج والخدمة والمتاع غير الوطء من المملوك والمملوكة لمالكها الذي اشتراها، وله ردها بالعيب، وقال: لا يكون له أن يرد الأمة بعد أن يطأها، وإن كانت ثيبا، ولا يكون له ثمر النخل، ولا لبن الماشية، ولا صوفها، ولا","bab":"باب الاستحسان"},{"id":"risala-shafii:569","bookId":"risala-shafii","type":"section","seq":569,"chapter":"الجزء الثالث.","title":"ص: 520","page":"ج1 ص517","text":"ولد الجارية، لأن كل هذا - من الماشية والجارية والنخل والخراج -: ليس بشيء من العبد.\nفقلت لبعض من يقول هذا القول: أرأيت قولك: الخراج ليس من العبد، والثمر من الشجر، والولد من الجارية: أليسا يجتمعان في أن كل واحد منهما كان حادثا في ملك المشتري، لم تقع عليه صفقة البيع؟\nقال: بلى، ولكن يتفرقان في أن ما وصل إلى السيد منهما مفترق، وتمر النخل منها، وولد الجارية والماشية منها، وكسب الغلام ليس منه، إنما هو شيء تحرف فيه فاكتسبه.","bab":"باب الاستحسان"},{"id":"risala-shafii:570","bookId":"risala-shafii","type":"section","seq":570,"chapter":"الجزء الثالث.","title":"ص: 521","page":"ج1 ص519","text":"فقلت له أرايت إن عارضك معارض بمثل حجتك فقال: قضى النبي أن الخراج بالضمان، والخراج لا يكون إلا بما وصفت من التحرف، وذلك يشغله عن خدمة مولاه، فيأخذ له بالخراج العوض من الخدمة ومن نفقته على مملوكه، فإن وهبت له هبة، فالهبة لا تشغله عن شيء: لم تكن لمالكه الآخر، وردت إلى الأول؟\nقال: لا، بل تكون للآخر الذي وهبت له، وهو في ملكه.\nقلت: هذا ليس بخراج، هذا من وجه غير الخراج.\nقال: وإن، فليس من العبد.\nقلت: ولكنه يفارق معنى الخراج، لأنه من غير وجه الخراج؟","bab":"باب الاستحسان"},{"id":"risala-shafii:571","bookId":"risala-shafii","type":"section","seq":571,"chapter":"الجزء الثالث.","title":"ص: 522","page":"ج1 ص519","text":"قال: وإن كان من غير وجه الخراج، فهو حادث في ملك المشتري.\nقلت: وكذلك الثمرة والنتاج حادث في ملك المشتري، والثمرة إذا باينت النخلة، فليست من النخلة، قد تباع الثمرة، ولا تتبعها النخلة، والنخلة ولا تتبعها الثمرة، وكذلك نتاج الماشية. والخراج أولى أن يرد مع العبد، لأنه قد يتكلف فيه ما تبعه من ثمر النخلة، ولو جاز أن يرد واحد منهما.\nوقال بعض أصحابنا بقولنا في الخراج، ووطء الثيب، وثمر النخل، وخالفنا في ولد الجارية.\nوسواء ذلك كله، لأنه حادث في ملك المشتري، لا يستقيم فيه إلا هذا، أو لا يكون لمالك العبد المشتري شيء","bab":"باب الاستحسان"},{"id":"risala-shafii:572","bookId":"risala-shafii","type":"section","seq":572,"chapter":"الجزء الثالث.","title":"ص: 523","page":"ج1 ص520","text":"إلا الخراج والخدمة، ولا يكون له ما وهب للعبد، ولا ما التقط، ولا غير ذلك من شيء أفاده من كنز ولا غيره، إلا الخراج والخدمة، ولا ثمر النخل، ولا لبن الماشية، ولا غير ذلك، لأن هذا ليس بخراج.\nونهى رسول الله عن الذهب بالذهب، والتمر بالتمر، والبر بالبر، والشعير بالشعير إلا مثلا بمثل يدا بيد.\nفلما خرج رسول الله في هذه الأصناف المأكولة التي شح الناس عليها، حتى باعوها كيلا: بمعنيين: أحدهما: أن يباع","bab":"باب الاستحسان"},{"id":"risala-shafii:573","bookId":"risala-shafii","type":"section","seq":573,"chapter":"الجزء الثالث.","title":"ص: 524","page":"ج1 ص520","text":"منها شيء بمثله أحدهما نقد، والآخر دين، والثاني: أن يزاد في واحد منهما شيء على مثله يدا بيد: وكان ما كان في معناها محرما قياسا عليها.\nوذلك كل ما أكل مما بيع موزونا، لأني وجدتها مجتمعة المعاني في أنها مأكولة ومشروبة، والمشروب في معنى المأكول، لأنه كله للناس إما قوت وإما غذاء وإما هما، ووجدت الناس شحوا عليها حتى باعوها وزنا، والوزن أقرب من الإحاطة من الكيل، وفي معنى الكيل، وذلك مثل العسل والسمن والزيت والسكر وغيره، مما يؤكل ويشرب ويباع موزونا.\nفإن قال قائل: أفيحتمل ما بيع موزونا أن يقاس","bab":"باب الاستحسان"},{"id":"risala-shafii:574","bookId":"risala-shafii","type":"section","seq":574,"chapter":"الجزء الثالث.","title":"ص: 525","page":"ج1 ص522","text":"على الوزن من الذهب والورق، فيكون الوزن بالوزن أولى بأن يقاس من الوزن بالكيل؟\nقيل - إن شاء الله - له: إن الذي منعنا مما وصفت - من قياس الوزن بالوزن - أن صحيح القياس إذا قست الشيء بالشيء أن تحكم له بحكمه، فلو قست العسل والسمن بالدنانير والدراهم، وكنت إنما حرمت الفضل في بعضها على بعض إذا كانت جنسا واحدا قياسا على الدنانير والدراهم: أكان يجوز أن يشترى بالدنانير والدراهم نقدا عسلا وسمنا إلى أجل؟\nفإن قال: يجيزه بما أجازه به المسلمون.","bab":"باب الاستحسان"},{"id":"risala-shafii:575","bookId":"risala-shafii","type":"section","seq":575,"chapter":"الجزء الثالث.","title":"ص: 526","page":"ج1 ص522","text":"قيل إن شاء الله: فإجازة المسلمين له دلتني على أنه غير قياس عليه، لو كان قياسا عليه كان حكمه حكمه، فلم يحل أن يباع إلا يدا بيد، كما لا تحل الدنانير بالدراهم إلا يدا بيد.\nفإن قال: أفتجدك حين قسته على الكيل حكمت له حكمه؟\nقلت: نعم، لا أفرق بينه في شيء بحال.\nقال: أفلا يجوز أن تشتري مد حنطة نقدا بثلاثة أرطال زيت إلى أجل.","bab":"باب الاستحسان"},{"id":"risala-shafii:576","bookId":"risala-shafii","type":"section","seq":576,"chapter":"الجزء الثالث.","title":"ص: 527","page":"ج1 ص522","text":"قلت: لا يجوز أن يشترى، ولا شيء من المأكول والمشروب بشيء من غير صنفه إلى أجل.\nحكم المأكول المكيل حكم المأكول الموزون.\nقال: فما تقول في الدنانير والدراهم؟\nقلت: محرمات في أنفسها، لا يقاس شيء من المأكول عليها، لأنه ليس في معناها، والمأكول المكيل محرم في نفسه، ويقاس به ما في معناه من المكيل والموزون عليه، لأنه في معناه.\nفإن قال: فافرق بين الدنانير والدراهم؟\nقلت: لم أعلم مخالفا من أهل العلم في إجازة أن يشترى بالدنانير والدراهم الطعام المكيل والموزون إلى أجل، وذلك لا يحل في الدنانير بالدراهم، وإني لم أعلم منهم مخالفا في أني لو علمت معدنا فأديت الحق فيما خرج منه، ثم أقامت فضته أو ذهبه عندي دهري: كان علي في كل سنة أداء زكاتها، ولو حصدت","bab":"باب الاستحسان"},{"id":"risala-shafii:577","bookId":"risala-shafii","type":"section","seq":577,"chapter":"الجزء الثالث.","title":"ص: 528","page":"ج1 ص524","text":"طعام أرضي، فأخرجت عشره أقام عندي دهره: لم يكن علي فيه زكاة، وفي أني لو استهلكت لرجل شيئا قوم علي دنانير أو دراهم، لأنها الأثمان في كل مال لمسلم إلا الديات.\nفإن قال: هكذا.\nقلت: فالأشياء تتفرق بأقل مما وصفت لك.\nووجدنا عاما في أهل العلم أن رسول الله قضى في جناية الحر المسلم خطأ بمائة من الإبل على عاقلة الجاني وعاما فيهم أنها في مضي ثلاث سنين، في كل سنة ثلثها، وبأسنان معلومة.\nفدل على معاني من القياس، سأذكر منها - إن شاء الله - بعض ما يحضرني:\nإنا وجدنا عاما في أهل العلم أن ما جنى الحر المسلم من جناية عمد أو فساد مال لأحد على نفس أو غيره: ففي ماله دون عاقلته، وما كان من جناية في نفس خطأ فعلى عاقلته.\nثم وجدناهم مجمعين على أن تعقل العاقلة ما بلغ ثلث الدية من جناية في الجراح فصاعدا.\nثم افترقوا فيما دون الثلث: فقال بعض أصحابنا: تعقل العاقلة الموضحة (1) وهي نصف العشر فصاعدا، ولا تعقل ما دونها.\nفقلت لبعض من قال: تعقل نصف العشر، ولا تعقل ما دونه: هل يستقيم القياس على السنة إلا بأحد وجهين؟","bab":"باب الاستحسان"},{"id":"risala-shafii:578","bookId":"risala-shafii","type":"section","seq":578,"chapter":"الجزء الثالث.","title":"ص: 530","page":"ج1 ص527","text":"قال: وما هما؟\nقلت: أن تقول: لما وجدت النبي قضى بالدية على العاقلة قلت به اتباعا، فما كان دون الدية ففي مال الجاني، ولا تقيس على الدية غيرها، لأن الأصل: الجاني أولى أن يغرم جنايته من غيره، كما يغرمها في غير الخطأ في الجراح، وقد أوجب الله على القاتل خطأ دية ورقبة، فزعمت أن الرقبة في ماله، لأنها من جنايته، وأخرجت الدية من هذا المعنى اتباعا، وكذلك أتبع في الدية، وأصرف بما دونها إلى أن يكون في ماله، لأنه أولى أن يغرم ما جنى من غيره، وكما أقول في المسح على الخفين: رخصة: بالخبر عن رسول الله، ولا أقيس عليه غيره.\nأو يكون القياس من وجه ثاني؟\nقال: وما هو؟","bab":"باب الاستحسان"},{"id":"risala-shafii:579","bookId":"risala-shafii","type":"section","seq":579,"chapter":"الجزء الثالث.","title":"ص: 531","page":"ج1 ص529","text":"قلت: إذ أخرج رسول الله الجناية خطأ على النفس مما جنى الجاني على غير النفس، وما جنى على نفس عمدا، فجعل على عاقلته يضمنونها، وهي الأكثر: جعلت على عاقلته يضمنون الأقل من جناية الخطأ، لأن الأقل أولى أن يضمنوه عنه من الأكثر، أو في مثل معناه.\nقال: هذا أولى المعنيين أن يقاس عليه، ولا يشبه هذا المسح على الخفين.\nفقلت له: هذا كما قلت - إن شاء الله - وأهل العلم مجمعون على أن تغرم العاقلة الثلث وأكثر، وإجماعهم دليل على أنهم قد قاسوا بعض ما هو أقل من الدية بالدية!\nقال: أجل.\nفقلت له: فقد قال صاحبنا: أحسن ما سمعت أن تغرم العاقلة ثلث الدية فصاعدا، وحكى أنه الأمر عندهم، أفرأيت إن احتج له محتج بحجتين؟\nقال: وما هما؟\nقلت: أنا وأنت مجمعان على أن تغرم العاقلة الثلث فأكثر، ومختلفان فيما هو أقل منه، وإنما قامت الحجة بإجماعي وإجماعك على الثلث، ولا خبر عندك في أقل منه: ما تقول له؟\nقال: أقول إن إجماعي من غير هذا الوجه الذي ذهبت إليه، إجماعي إنما هو قياس على أن العاقلة إذا غرمت الأكثر ضمنت ما هو أقل منه، فمن حد لك الثلث؟ أرأيت إن قال لك غيرك: بل تغرم تسعة أعشار، ولا تغرم ما دونه؟\nقلت: فإن قال لك: فالثلث يفدح من غرمه،","bab":"باب الاستحسان"},{"id":"risala-shafii:580","bookId":"risala-shafii","type":"section","seq":580,"chapter":"الجزء الثالث.","title":"ص: 533","page":"ج1 ص530","text":"قلت: يغرم معه أو عنه لأنه فادح، ولا يغرم ما دونه غير فادح.\nقال: أفرأيت من لا مال له إلا درهمين، أما يفدحه أن يغرم الثلث والدرهم، فيبقى لا مال له؟ أرأيت من له دنيا عظيمة، هل يفدحه الثلث؟\nفقلت له: أفرأيت لو قال لك: هو لا يقول لك \"الأمر عندنا\" إلا والأمر مجتمع عليه بالمدينة.","bab":"باب الاستحسان"},{"id":"risala-shafii:581","bookId":"risala-shafii","type":"section","seq":581,"chapter":"الجزء الثالث.","title":"ص: 534","page":"ج1 ص532","text":"قال: والأمر المجتمع عليه بالمدينة أقوى من الأخبار المنفردة؟! قال: فكيف تكلف أن حكى لنا الأضعف من الأخبار المنفردة، وامتنع أن يحكي لنا الأقوى اللازم من الأمر المجتمع عليه؟!\nقلنا: فإن قال لك قائل: لقلة الخبر وكثرة الإجماع عن أن يحكى، وأنت قد تصنع مثل هذا، فتقول: هذا أمر مجتمع عليه!\nقال: لست أقول ولا أحد من أهل العلم \"هذا مجتمع عليه \": إلا لما تلقى عالما أبدا إلا قاله لك وحكاه عن من قبله، كالظهر أربع، وكتحريم الخمر، وما أشبه هذا، وقد أجده","bab":"باب الاستحسان"},{"id":"risala-shafii:582","bookId":"risala-shafii","type":"section","seq":582,"chapter":"الجزء الثالث.","title":"ص: 535","page":"ج1 ص533","text":"يقول: \"المجمع عليه\" وأجد من المدينة من أهل العلم كثيرا يقولون بخلافه، وأجد عامة أهل البلدان على خلاف ما يقول: \"المجتمع عليه\"\nقال: فقلت له: فقد يلزمك في قولك \"لا تعقل ما دون الموضحة \"مثل ما لزمه في الثلث.\nفقال لي: إن فيه علة بأن رسول الله لم يقض فيما دون الموضحة بشيء.\nفقلت له: أفرأيت إن عارضك معارض فقال: لا أقضي فيما دون الموضحة بشيء، لأن رسول الله لم يقض فيه بشيء؟\nقال: ليس ذلك له، وهو إذا لم يقض فيما دونها بشيء، فلم يهدر ما دونها من الجراح.\nقال: وكذلك يقول لك: هو إذا لم يقل: لا تعقل العاقلة ما دون الموضحة، فلم يحرم أن تعقل العاقلة ما دونها، ولو قضى في الموضحة، ولم يقض فيما دونها على العاقلة ما منع ذلك العاقلة أن تغرم ما دونها، إذا غرمت الأكثر غرمت الأقل، كما قلنا نحن وأنت، واحتججت على صاحبنا، ولو جاز هذا لك، جاز عليك.\nولو قضى النبي بنصف العشر على العاقلة: أن يقول قائل: تغرم نصف العشر والدية، ولا تغرم ما بينهما، ويكون ذلك في مال الجاني؟! ولكن هذا غير جائز لأحد، والقول فيه أن جميع ما كان خطأ فعلى العاقلة، وإن كان درهما.\nوقلت له: قد قال بعض أصحابنا: إذا جنى الحر على العبد جناية فأتى على نفسه أو ما دونها خطأ، فهي في ماله دون","bab":"باب الاستحسان"},{"id":"risala-shafii:583","bookId":"risala-shafii","type":"section","seq":583,"chapter":"الجزء الثالث.","title":"ص: 537","page":"ج1 ص535","text":"عاقلته، ولا تعقل العاقلة عبدا، فقلنا: هي جناية حر، وإذ قضى رسول الله أن عاقلة الحر تحمل جنايته في حر إذا كانت غرما لاحقا بجناية خطأ، وكذلك جنايته في العبد إذا كانت غرما من خطأ، والله أعلم، وقلت بقولنا فيه، وقلت: من قال لا تعقل العاقلة عبدا احتمل قوله لا تعقل جناية عبد، لأنها في عنقه دون مال سيده غيره (1) فقلت بقولنا، ورأيت ما احتججت به من هذا حجة صحيحة داخلة في معنى السنة؟\nقال: أجل.\nقال: وقلت له: وقال صاحبك وغيره من","bab":"باب الاستحسان"},{"id":"risala-shafii:584","bookId":"risala-shafii","type":"section","seq":584,"chapter":"الجزء الثالث.","title":"ص: 538","page":"ج1 ص535","text":"أصحابنا: جراح العبد في ثمنه كجراح الحر في ديته، ففي عينه نصف ثمنه، وفي موضحته نصف عشر ثمنه، وخالفتنا فيه، فقلت: في جراح العبد ما نقص من ثمنه.\nقال: فأنا أبدأ، فأسألك عن حجتك في قول جراح العبد في ديته: أخبرا قلته أم قياسا؟\nقلت: أما الخبر فيه، فعن سعيد بن المسيب.\nقال: فاذكره؟\nقلت: أخبرنا سفيان عن الزهري عن سعيد بن المسيب أنه قال: عقل العبد في ثمنه، فسمعته منه كثيرا هكذا، وربما قال: كجراح الحر في ديته، قال ابن شهاب: فإن ناسا يقولون: يقوم سلعة.\nفقال: إنما سألتك خبرا تقوم به حجتك.\nفقلت: قد أخبرتك أني لا أعرف فيه خبرا عن أحد أعلى من سعيد بن المسيب.\nقال: فليس في قوله حجة.\nقال: وما ادعيت ذلك فترده علي!\nقال: فاذكر الحجة فيه؟\nقلت: قياسا على الجناية على الحر.\nقال: قد يفارق الحر في أن دية الحر مؤقتة،","bab":"باب الاستحسان"},{"id":"risala-shafii:585","bookId":"risala-shafii","type":"section","seq":585,"chapter":"الجزء الثالث.","title":"ص: 540","page":"ج1 ص537","text":"وديته ثمنه، فيكون بالسلع من الإبل والدواب وغير ذلك أشبه، لأن في كل واحد منهما ثمنه.\nفقلت: فهذا حجة لمن قال: لا تعقل العاقلة ثمن العبد: عليك.\nقال: ومن أين؟\nقال: يقول لك: لم قلت تعقل العاقلة ثمن العبد إذا جنى عليه الحر قيمته، وهو عندك بمنزلة الثمن؟ ولو جنى على بعير جناية ضمنها في ماله؟\nقال: فهو نفس محرمة.\nقلت: والبعير نفس محرمة على قاتله؟\nقال: ليست كحرمة المؤمن.\nقلت: ويقول لك، ولا العبد كحرمة الحر في كل أمره.","bab":"باب الاستحسان"},{"id":"risala-shafii:586","bookId":"risala-shafii","type":"section","seq":586,"chapter":"الجزء الثالث.","title":"ص: 541","page":"ج1 ص537","text":"فقلت: فهو عندك مجامع الحر في المعنى، أفتعقله العاقلة؟\nقال: ونعم.\nقلت: وحكم الله في المؤمن يقتل خطأ بدية وتحرير رقبة؟\nقال: نعم.\nقلت: وزعمت أن في العبد تحرير رقبة كهي في الحر وثمن، وأن الثمن كالدية؟\nقال: نعم.\nقلت: وزعمت أنك تقتل الحر بالعبد؟\nقال: نعم.","bab":"باب الاستحسان"},{"id":"risala-shafii:587","bookId":"risala-shafii","type":"section","seq":587,"chapter":"الجزء الثالث.","title":"ص: 542","page":"ج1 ص537","text":"قلت: وزعمنا أنا نقتل العبد بالعبد؟\nقال: وأنا أقوله.\nقلت: فقد جامع الحر في هذه المعاني عندنا وعندك، في أن بينه وبين المملوك قصاصا في كل جرح، وجامع البعير في معنى أن ديته ثمنه، فكيف اخترت في جراحته أن تجعلها كجراحة بعير، فتجعل فيه ما نقصه، ولم تجعل جراحته في ثمنه كجراح الحر في ديته؟ وهو يجامع الحر في خمسة معاني، ويفارقه في معنى واحد؟ أليس أن تقيسه على ما يجامعه في خمسة معاني أولى بك من أن تقيسه على جامعه على معنى واحد؟! مع أنه يجامع الحر في أكثر من هذا: أن ما حرم على الحر حرم عليه، وأن عليه الحدود والصلاة والصوم وغيرها من الفرائض، وليس من البهائم بسبيل!!\nقال: رأيت ديته ثمنه؟","bab":"باب الاستحسان"},{"id":"risala-shafii:588","bookId":"risala-shafii","type":"section","seq":588,"chapter":"الجزء الثالث.","title":"ص: 543","page":"ج1 ص537","text":"قلت: وقد رأيت دية المرأة نصف دية الرجل، فما منع ذلك جراحها أن تكون في ديتها، كما كانت جراح الرجل في ديته؟!\nوقلت له: إذا كانت الدية في ثلاث سنين إبلا أفليس قد زعمت أن الإبل لا تكون بصفة دينا؟ فكيف أنكرت أن تشترى الإبل بصفة إلى أجل؟ ولم تقيسه (1) على الدية، ولا على الكتابة ولا، على المهر، وأنت تجيز في هذا كله أن تكون الإبل بصفة دينا؟! فخالفت فيه القياس، وخالفت الحديث نصا عن النبي: أنه استسلف بعيرا، ثم أمر بقضائه بعد؟!","bab":"باب الاستحسان"},{"id":"risala-shafii:589","bookId":"risala-shafii","type":"section","seq":589,"chapter":"الجزء الثالث.","title":"ص: 544","page":"ج1 ص537","text":"قال: كرهه ابن مسعود.\nفقلنا: وفي أحد مع النبي حجة؟!\nقال: لا، إن ثبت عن النبي.\nقلت: هو ثابت باستسلافه بعيرا وقضاه خيرا منه، وثابت في الديات عندنا وعندك، هذا في معنى السنة.\nقال: فما الخبر الذي يقاس عليه؟\nقلت: أخبرنا مالك عن زيد بن أسلم عن عطاء بن يسار عن أبي رافع: \" أن النبي استسلف من رجل بعيرا فجاءته إبل، فأمرني أن أقضيه إياه، فقلت: لا أجد في الإبل إلا جملا خيارا، فقال: أعطه إياه، فإن خيار الناس أحسنهم قضاء \" (1)\nقال: فما الخبر الذي لا يقاس عليه؟\nقلت: ما كان لله فيه حكم منصوص، ثم كانت لرسول الله سنة بتخفيف في بعض الفرض دون بعض: عمل بالرخصة فيما رخص فيه رسول الله دون ما سواها، ولم يقس ما سواها عليها، وهكذا ما كان لرسول الله من حكم عام بشيء، ثم سن سنة تفارق حكم العام.\nقال: وفي مثل ماذا؟\nقلت: فرض الله الوضوء على من قام إلى الصلاة من نومه، فقال: {إذا قمتم إلى الصلاة، فاغسلوا وجوهكم، وأيديكم إلى المرافق، وامسحوا برؤسكم وأرجلكم إلى الكعبين} [المائدة 6]\nفقصد قصد الرجلين بالفرض، كما قصد قصد ما سواهما في أعضاء الوضوء.","bab":"باب الاستحسان"},{"id":"risala-shafii:590","bookId":"risala-shafii","type":"section","seq":590,"chapter":"الجزء الثالث.","title":"ص: 546","page":"ج1 ص544","text":"فلما مسح رسول الله على الخفين لم يكن لنا - والله أعلم - أن نمسح على عمامة، ولا برفع، ولا قفازين: قياسا عليهما، وأثبتنا الفرض في أعضاء الوضوء كلها، وأرخصنا بمسح النبي في المسح على الخفين، دون ما سواهما.\nقال: فتعد هذا خلافا للقرآن؟\nقلت: لا تخالف سنة لرسول الله كتاب الله بحال.\nقال: فما معنى هذا عندك؟\nقلت: معناه أن يكون قصد بفرض إمساس القدمين الماء من لا خفي عليه لبسهما كامل الطهارة.\nقال: أو يجوز هذا في اللسان؟\nقلت: نعم، كما جاز أن يقوم إلى الصلاة من هو","bab":"باب الاستحسان"},{"id":"risala-shafii:591","bookId":"risala-shafii","type":"section","seq":591,"chapter":"الجزء الثالث.","title":"ص: 547","page":"ج1 ص545","text":"على وضوء، فلا يكون المراد بالوضوء، استدلالا بأن رسول الله صلى صلاتين وصلوات بوضوء واحد.\nوقال الله: {والسارق والسارقة، فاقطعوا أيديهما جزاء بما كسبا نكالا من الله، والله عزيز حكيم} [المائدة 38]\nفدلت السنة على أن الله لم يرد بالقطع كل السارقين.\nفكذلك دلت سنة رسول الله بالمسح أنه قصد بالفرض في غسل القدمين من لا خفي عليه لبسهما كامل الطهارة.\nقال: فما مثل هذا في السنة؟\nقلت: نهى رسول الله عن بيع التمر بالتمر إلا مثلا بمثل \"وسئل عن الرطب بالتمر؟ فقال: أينقص الرطب إذا يبس؟ فقيل: نعم، فنهى عنه\". و \" نهى عن المزابنة \"، وهي كل ما عرف كيله منه، وهذا كله مجتمع المعاني، \"ورخص أن تباع العرايا بخرصها تمرا يأكلها أهلها رطبا\" (1)","bab":"باب الاستحسان"},{"id":"risala-shafii:592","bookId":"risala-shafii","type":"section","seq":592,"chapter":"الجزء الثالث.","title":"ص: 548","page":"ج1 ص546","text":"فرخصنا في العرايا بإرخاصه، وهي بيع الرطب بالتمر، وداخلة في المزابنة بإرخاصه، فأثبتنا التحريم محرما عاما في كل شيء من صنف واحد مأكول، بعضه جزاف وبعضه بكيل: للمزابنة، وأحللنا العرايا خاصة بإحلاله من الجملة التي حرم، ولم نبطل أحد الخبرين بالآخر، ولم نجعله قياسا عليه.\nقال: فما وجه هذا؟\nقلت: يحتمل وجهين: أولاهما به عندي - والله أعلم - أن يكون ما نهى عنه جملة أراد به ما سوى العرايا، ويحتمل أن يكون أرخص فيها بعد وجوبها في جملة النهي، وأيهما كان فعلينا طاعته بإحلال ما أحل، وتحريم ما حرم.\nوقضى رسول الله بالدية في الحر المسلم يقتل خطأ مائة من الإبل، وقضى بها على العاقلة.\nوكان العمد يخالف الخطأ في القود والمأثم، ويوافقه في أنه قد تكون فيه دية.\nفلما كان قضاء رسول الله في كل امرئ فيما لزمه، إنما هو في ماله دون مال غيره، إلا في الحر يقتل خطأ: قضينا على العاقلة في الحر يقتل خطأ ما قضى به رسول الله، وجعلنا الحر يقتل عمدا إذا كانت فيه دية: في مال الجاني، كما كان كل ما جنى في ماله غير الخطأ، ولم نقس ما لزمه من غرم بغير جراح خطأ على ما لزمه بقتل الخطأ.\nفإن قال قائل: ما الذي يغرم الرجل من جنايته، وما لزمه غير الخطأ؟","bab":"باب الاستحسان"},{"id":"risala-shafii:593","bookId":"risala-shafii","type":"section","seq":593,"chapter":"الجزء الثالث.","title":"ص: 550","page":"ج1 ص547","text":"قلت: قال الله: {وآتوا النساء صدقاتهن نحلة} [النساء 4]\nوقال: {وأقيموا الصلاة وآتوا الزكاة} [البقرة 43]\nوقال: {فإن أحصرتم فما استيسر من الهدي} [البقرة 196]\nوقال: {والذين يظاهرون من نسائهم، ثم يعودون لما قالوا، فتحرير رقبة من قبل أن يتماسا} [المجادلة 3]\nوقال: {ومن قتله منكم متعمدا فجزاء مثل ما قتل من النعم يحكم به ذوا عدل منكم هديا بالغ الكعبة، أو كفارة طعام مساكين، أو عدل ذلك صياما ليذوق وبال أمره، عفا الله عما سلف، ومن عاد فينتقم الله منه، والله عزيز ذو انتقام} [المائدة 95]","bab":"باب الاستحسان"},{"id":"risala-shafii:594","bookId":"risala-shafii","type":"section","seq":594,"chapter":"الجزء الثالث.","title":"ص: 551","page":"ج1 ص547","text":"وقال: {فكفارته إطعام عشرة مساكين من أوسط ما تطعمون أهليكم، أو كسوتهم أو تحرير رقبة، فمن لم يجد فصيام ثلاثة أيام} [المائدة 89]\nوقضى رسول الله على \" أن على أهل الأموال حفظها بالنهار، وما أفسدت المواشي بالليل، فهو ضامن على أهلها\" (1) .\nفدل الكتاب والسنة وما لم يختلف المسلمون فيه: أن هذا كله في مال الرجل، بحق وجب عليه لله، أو أوجبه الله عليه للآدميين، بوجوه لزمته، وأنه لا يكلف أحد غرمه عنه.\nولا يجوز أن يجني رجل، ويغرم غير الجاني، إلا في الموضع الذي سنه رسول الله فيه خاصة من قتل الخطأ وجنايته على الآدميين خطأ.","bab":"باب الاستحسان"},{"id":"risala-shafii:595","bookId":"risala-shafii","type":"section","seq":595,"chapter":"الجزء الثالث.","title":"ص: 552","page":"ج1 ص549","text":"والقياس فيما جنى على بهيمة أو متاع أو غيره - على ما وصفت -: أن ذلك في ماله، لأن الأكثر المعروف أن ما جنى في ماله، فلا يقاس على الأقل، ويترك الأكثر المعقول، ويخص الرجل الحر يقتل الحر الخطأ، فتعقله العاقلة، وما كان من جناية خطأ على نفس وجرح: خبرا وقياسا.\nوقضى رسول الله في الجنين بغرة عبد أو أمة، وقوم أهل العلم الغرة خمسا من الإبل.\nقال: فلما لم يحكا أن رسول الله سأل عن الجنين: أذكر هو أم أنثى؟ إذ قضى فيه سوى بين الذكر والأنثى","bab":"باب الاستحسان"},{"id":"risala-shafii:596","bookId":"risala-shafii","type":"section","seq":596,"chapter":"الجزء الثالث.","title":"ص: 553","page":"ج1 ص551","text":"إذا سقط ميتا، ولو سقط حيا فمات جعلوا في الرجل مائة من الإبل، وفي المرأة خمسين.\nفلم يجز أن يقاس على الجنين شيء من قبل أن الجنايات على من عرفت جنايته موقتات معروفات. مفروق فيها بين الذكر والأنثى. وأن لا يختلف الناس في أن لو سقط الجنين حيا، ثم مات كانت فيه دية كاملة، إن كان ذكرا فمائة من الإبل، وإن كانت أنثى فخمسون من الإبل، وأن المسلمين - فيما علمت - لا يختلفون أن رجلا لو قطع الموتى لم يكن في واحد منهم دية، ولا أرش، والجنين لا يعدو أن يكون حيا أو ميتا.\nفلما حكم فيه رسول الله بحكم فارق حكم النفوس، الأحياء والأموات، وكان مغيب الأمر: كان الحكم بما حكم به على الناس اتباعا لأمر رسول الله.","bab":"باب الاستحسان"},{"id":"risala-shafii:597","bookId":"risala-shafii","type":"section","seq":597,"chapter":"الجزء الثالث.","title":"ص: 554","page":"ج1 ص551","text":"قال فهل تعرف له وجها؟\nقلت: وجها واحدا، والله أعلم.\nقال: وما هو؟\nقلت: يقال: إذا لم تعرف له حياة، وكان لا يصلى عليه، ولا يرث: فالحكم فيه أنها جناية على أمه، وقت فيها رسول الله شيئا قومه المسلمون، كما وقت في الموضحة.\nقال: فهذا وجه.\nقلت: وجه لا يبين الحديث أنه حكم به له، فلا يصح أن يقال: إنه حكم به له، ومن قال: إنه حكم به لهذا المعنى قال: هو للمرأة دون الرجل، هو للأم دون أبيه، لأنه عليها جني، ولا حكم للجنين يكون به موروثا، ولا يورث من لا يرث.\nقال: فهذا قول صحيح؟","bab":"باب الاستحسان"},{"id":"risala-shafii:598","bookId":"risala-shafii","type":"section","seq":598,"chapter":"الجزء الثالث.","title":"ص: 555","page":"ج1 ص551","text":"قلت: الله أعلم.\nقال: فإن لم يكن هذا وجهه، فما يقال لهذا الحكم؟\nقلنا: يقال له: سنة تعبد العباد بأن يحكموا بها.\nوما يقال لغيره مما يدل الخبر على المعنى الذي له حكم به؟\nقيل: حكم سنة تعبدوا بها لأمر عرفوه بمعنى الذي تعبدوا له في السنة، فقاسوا عليه ما كان في مثل معناه.\nقال: فاذكر منه وجها غير هذا إن حضرك تجمع فيه ما يقاس عليه، ولا يقاس؟","bab":"باب الاستحسان"},{"id":"risala-shafii:599","bookId":"risala-shafii","type":"section","seq":599,"chapter":"الجزء الثالث.","title":"ص: 556","page":"ج1 ص552","text":"فقلت له: قضى رسول الله في المصراة (1) من الإبل والغنم إذا حلبها مشتريها: \" إن أحب أمسكها، وإن أحب ردها وصاعا من تمر\" (2) ، وقضى \" أن الخراج بالضمان\"\nفكان معقولا في \" الخراج بالضمان \" أني إذا ابتعت عبدا فأخذت له خراجا ثم ظهرت منه على عيب يكون لي رده: فما أخذت من الخراج والعبد في ملكي ففيه خصلتان: إحداهما: أنه لم يكن في ملك البائع، ولم يكن له حصة من الثمن، والأخرى:","bab":"باب الاستحسان"},{"id":"risala-shafii:600","bookId":"risala-shafii","type":"section","seq":600,"chapter":"الجزء الثالث.","title":"ص: 557","page":"ج1 ص552","text":"أنها في ملكي، وفي الوقت الذي خرج فيه العبد من ضمان بائعه إلى ضماني، فكان العبد لو مات مات من مالي وفي ملكي، ولو شئت حبسته بعيبه، فكذلك الخراج.\nفقلنا بالقياس على حديث \"الخراج بالضمان \" فقلنا: كل ما خرج من ثمر حائط اشتريته، أو ولد ماشية أو جارية اشتريتها، فهو مثل الخراج، لأنه حدث في ملك مشتريه، لا في ملك بائعه.\nوقلنا في المصراة اتباعا لأمر رسول الله، ولم نقس عليه، وذلك أن الصفقة وقعت على شاة بعينها، فيها لبن محبوس مغيب المعنى والقيمة، ونحن نحيط أن لبن الإبل والغنم يختلف، وألبان كل واحد منهما يختلف، فلما قضى فيه رسول الله بشيء مؤقت، وهو صاع من تمر: قلنا به اتباعا لأمر رسول الله.","bab":"باب الاستحسان"},{"id":"risala-shafii:601","bookId":"risala-shafii","type":"section","seq":601,"chapter":"الجزء الثالث.","title":"ص: 558","page":"ج1 ص552","text":"قال: فلو اشترى رجل شاة مصراة، فحلبها ثم رضيها بعد العلم بعيب التصرية، فأمسكها شهرا حلبها، ثم ظهر منها على عيب دلسه له البائع غير التصرية: كان له ردها، وكان له اللبن بغير شيء، بمنزلة الخراج، لأنه لم يقع عليه صفقة البيع، وإنما هو حادث في ملك المشتري، وكان عليه أن يرد فيما أخذ من لبن التصرية صاعا من تمر، كما قضى به رسول الله.\nفنكون قد قلنا في لبن التصرية خبرا، وفي اللبن بعد التصرية قياسا على \" الخراج بالضمان\"\nولبن التصرية مفارق للبن الحادث بعده، لأنه وقعت عليه صفقة البيع، واللبن بعده حادث في ملك المشتري، لم تقع عليه صفقة البيع.\nفإن قال قائل: ويكون أمر واحد يؤخذ من وجهين؟\nقيل له: نعم، إذا جمع أمرين مختلفين، أو أمورا مختلفة.","bab":"باب الاستحسان"},{"id":"risala-shafii:602","bookId":"risala-shafii","type":"section","seq":602,"chapter":"الجزء الثالث.","title":"ص: 559","page":"ج1 ص555","text":"فإن قال: فمثل من ذلك شيئا غير هذا؟\nقلت: المرأة تبلغها وفاة زوجها، فتعتد، ثم تتزوج، ويدخل بها الزوج، لها الصداق، وعليها العدة والولد لاحق، ولا حد على واحد منهما، ويفرق بينهما، ولا يتوارثان، وتكون الفرقة فسخا بلا طلاق.\nيحكم له إذا كان ظاهره حلالا حكم الجلال، في ثبوت الصداق والعدة ولحوق الولد ودرء الحد، وحكم عليه إذ كان حراما في الباطن حكم الحرام في أن لا يقرا عليه، ولا تحل له إصابتها بذلك النكاح إذا علما به، ولا يتوارثان، ولا يكون الفسخ طلاقا، لأنها ليست بزوجة.\nولهذا أشباه، مثل المرأة تنكح في عدتها.","bab":"باب الاستحسان"},{"id":"risala-shafii:603","bookId":"risala-shafii","type":"section","seq":603,"chapter":"الجزء الثالث.","title":"باب الاختلاف","page":"ج1 ص558","text":"قال: فإني أجد أهل العم قديما وحديثا مختلفين في بعض أمورهم، فهل يسعهم ذلك؟\nقال: فقلت له: الاختلاف من وجهين: أحدهما: محرم، ولا أقول ذلك في الآخر.\nقال: فما الاختلاف المحرم؟\nقلت: كل ما أقام الله به الحجة في كتابه أو على لسان نبيه منصوصا بينا: لم يحل الاختلاف فيه لمن علمه.\nوما كان من ذلك يحتمل التأويل، ويدرك قياسا، فذهب المتأول أو القايس إلى معنى يحتمله الخبر أو القياس، وإن خالفه فيه غيره: لم أقل أنه يضيق عليه ضيق الخلاق في المنصوص.","bab":"باب الاختلاف"},{"id":"risala-shafii:604","bookId":"risala-shafii","type":"section","seq":604,"chapter":"الجزء الثالث.","title":"ص: 561","page":"ج1 ص559","text":"قال: فهل في هذا حجة تبين فرقك بين الاختلافين؟\nقلت: قال الله في ذم التفرق: {وما تفرق الذين أوتوا الكتاب إلا من بعد ما جاءتهم البينة} [البينة 4]\nوقال جل ثناؤه: {ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينات} [آل عمران 105]\nفذم الاختلاف فيما جاءتهم به البينات.\nفأما ما كلفوا فيه الاجتهاد، فقد مثلته لك بالقبلة والشهادة وغيرها.\nقال: فمثل لي بعض ما افترق عليه من روي قوله من السلف، مما لله فيه نص حكم يحتمل التأويل، فهل يوجد على الصواب فيه دلالة؟","bab":"باب الاختلاف"},{"id":"risala-shafii:605","bookId":"risala-shafii","type":"section","seq":605,"chapter":"الجزء الثالث.","title":"ص: 562","page":"ج1 ص560","text":"قلت: قل ما اختلفوا فيه إلا وجدنا فيه عندنا دلالة من كتاب الله أو سنة رسوله، أو قياسا عليهما، أو على واحد منهما.\nقال: فاذكر منه شيئا؟\nفقلت له: قال الله: {والمطلقات يتربصن بأنفسهن ثلاثة قروء} [البقرة 228]\nفقالت عائشة: \"الأقراء الأطهار\"، وقال بمثل معنى قولها زيد بن ثابت، وابن عمر، وغيرهما.\nوقال نفر من أصحاب النبي: \" الأقراء الحيض\"، فلا يحلوا المطلقة حتى تغتسل من الحيضة الثالثة.","bab":"باب الاختلاف"},{"id":"risala-shafii:606","bookId":"risala-shafii","type":"section","seq":606,"chapter":"الجزء الثالث.","title":"ص: 563","page":"ج1 ص560","text":"قال: فإلى أي شيء ترى ذهب هؤلى وهؤلى؟\nقلت: تجمع الأقراء أنها أوقات، والأوقات في هذا علامات تمر على المطلقات، تحبس بها عن النكاح حتى تستكملها.\nوذهب من قال\" الأقراء الحيض\" - فيما نرى والله أعلم - إلى أن قال: إن المواقيت أقل الأسماء، لأنها أوقات، والأوقات أقل مما بينها، كما حدود الشيء أقل مما بينها، والحيض","bab":"باب الاختلاف"},{"id":"risala-shafii:607","bookId":"risala-shafii","type":"section","seq":607,"chapter":"الجزء الثالث.","title":"ص: 564","page":"ج1 ص560","text":"أقل من الطهر، فهو في اللغة أولى للعدة أن يكون وقتا، كما يكون الهلال وقتا فاصلا بين الشهرين.\nولعله ذهب إلى أن النبي أمر في سبي أوطاس أن يستبرين قبل أن يوطين بحيضة، فذهب إلى أن العدة استبراء، وأن الاستبراء حيض، وأنه فرق بين استبراء الأمة والحرة، وأن الحرة تستبرأ بثلاث حيض كوامل، تخرج منها إلى الطهر كما تستبرأ الأمة بحيضة كاملة، تخرج منها إلى الطهر.\nفقال: هذا مذهب، فكيف اخترت غيره، والآية محتملة للمعنيين عندك؟","bab":"باب الاختلاف"},{"id":"risala-shafii:608","bookId":"risala-shafii","type":"section","seq":608,"chapter":"الجزء الثالث.","title":"ص: 565","page":"ج1 ص561","text":"قال: فقلت له: إن الوقت برؤية الأهلة إنما هو علامة جعلها الله للشهور، والهلال غير الليل والنهار، وإنما هو جماع لثلاثين، وتسع وعشرين، كما يكون الهلال الثلاثون والعشرون جماعا يستأنف بعده العدد، وليس له معنى هنا، وأن القرء وإن كان وقتا فهو من عدد الليل والنهار، والحيض والطهر","bab":"باب الاختلاف"},{"id":"risala-shafii:609","bookId":"risala-shafii","type":"section","seq":609,"chapter":"الجزء الثالث.","title":"ص: 566","page":"ج1 ص561","text":"في الليل والنهار من العدة، وكذلك شبه الوقت بالحدود، وقد تكون داخلة فيما حدت به، وخارجة منه غير بائن منها، فهو وقت معنى.\nقال: وما المعنى؟\nقلت: الحيض هو أن يرخي الرحم الدم حتى يظهر، والطهر أن يقري الرحم الدم فلا يظهر، ويكون الطهر والقري","bab":"باب الاختلاف"},{"id":"risala-shafii:610","bookId":"risala-shafii","type":"section","seq":610,"chapter":"الجزء الثالث.","title":"ص: 567","page":"ج1 ص561","text":"الحبس لا الإرسال، فالطهر - إذ كان يكون وقتا - أولى في اللسان بمعنى القرء، لأنه حبس الدم.\nوأمر رسول الله عمر حين طلق عبد الله بن عمر امرأته حائضا أن يأمره برجعتها وحبسها حتى تطهر، ثم يطلقها طاهرا من غير جماع، وقال رسول الله: \" فتلك العدة التي أمر الله أن يطلق لها النساء\" (1) .\nيعني قول الله - والله أعلم - إذا طلقتم النساء فطلقوهن لعدتهن} [الطلاق 1] ، فأخبر رسول الله أن العدة الطهر دون الحيض.\nوقال الله: {ثلاثة قروء} وكان على المطلقة أن تأتي بثلاثة قروء، فكان الثالث لو أبطأ عن وقته زمانا لم تحل حتى يكون، أو تويس من المحيض، أو يخاف ذلك عليها، فتعتد بالشهور، لم يكن للغسل معنى، لأن الغسل رابع غير ثلاثة، ويلزم من قال: \" الغسل عليها \" أن يقول: لو أقامت سنة وأكثر لا تغتسل لم تحل!!","bab":"باب الاختلاف"},{"id":"risala-shafii:611","bookId":"risala-shafii","type":"section","seq":611,"chapter":"الجزء الثالث.","title":"ص: 569","page":"ج1 ص561","text":"فكان قول من قال\" الأقراء الأطهار \" أشبه بمعنى كتاب الله، واللسان واضح على هذه المعاني، والله أعلم.","bab":"باب الاختلاف"},{"id":"risala-shafii:612","bookId":"risala-shafii","type":"section","seq":612,"chapter":"الجزء الثالث.","title":"ص: 571","page":"ج1 ص561","text":"فأما أمر النبي أن يستبرأ السبي بحيضة فبالظاهر، لأن الطهر إذا كان متقدما للحيضة ثم حاضت الأمة حيضة كاملة صحيحة برئت من الحبل في الطهر، وقد ترى الدم فلا يكون صحيحا، إنما يصح حيضة بأن تكمل الحيضة فبأي شيء من الطهر كان قبل حيضة كاملة فهو براءة من الحبل في الظاهر.\nوالمعتدة تعتد بمعنيين: استبراء، ومعنى غير","bab":"باب الاختلاف"},{"id":"risala-shafii:613","bookId":"risala-shafii","type":"section","seq":613,"chapter":"الجزء الثالث.","title":"ص: 572","page":"ج1 ص564","text":"استبراء مع استبراء، فقد جاءت بحيضتين وطهرين وطهر ثالث، فلو أريد بها الاستبراء كانت قد جاءت بالاستبراء مرتين، ولكنه أريد بها مع الاستبراء التعبد.\nقال: أفتوجدوني في غير هذا ما اختلفوا فيه مثل هذا؟\nقلت: نعم، وربما وجدناه أوضح، وقد بينا بعض هذا فيما اختلفت الرواية فيه من السنة، وفيه دلالة لك على ما سألت عنه، وما كان في معناه إن شاء الله.\nوقال الله: {والمطلقات يتربصن بأنفسهن ثلاثة قروء} [البقرة 288]\nوقال: {واللائي يئسن من المحيض من نسائكم إن ارتبتم، فعدتهن ثلاثة أشهر، واللائي لم يحضن، وأولات الأحمال أجلهن أن يضعن حملهن} [الطلاق 4]","bab":"باب الاختلاف"},{"id":"risala-shafii:614","bookId":"risala-shafii","type":"section","seq":614,"chapter":"الجزء الثالث.","title":"ص: 573","page":"ج1 ص571","text":"وقال: {والذين يتوفون منكم، ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا} [البقرة 234]\nفقال بعض أصحاب رسول الله: ذكر الله المطلقات أن عدة الحوامل أن يضعن حملهن، وذكر في المتوفى عنها أربعة أشهر وعشرا، فعلى الحامل المتوفى عنها أن تعتد أربعة أشهر وعشرا، وأن تضع حملها، حتى تأتي بالعدتين معا إذا لم يكن وضع الحمل انقضاء العدة نصا إلا في الطلاق.\nكأنه يذهب إلى أن وضع الحمل براءة، وأن الأربعة الأشهر وعشرا تعبد، وأن المتوفى عنها تكون غير مدخول بها، فتأتي بأربعة أشهر، وأنه وجب عليها شيء من وجهين،","bab":"باب الاختلاف"},{"id":"risala-shafii:615","bookId":"risala-shafii","type":"section","seq":615,"chapter":"الجزء الثالث.","title":"ص: 574","page":"ج1 ص571","text":"فلا تسقط أحدهما، كما لو وجب عليها حقان لرجلين لم يسقط أحدهما حق الآخر، وكما إذا نكحت في عدتها، وأصيبت اعتدت من الأول، واعتدت من الآخر.\nقال: وقال غيره من أصحاب رسول الله: إذا وضعت ذا بطنها، فقد حلت، ولو كان زوجها على السرير.\nقال \"الشافعي\": فكانت الآية محتملة المعنيين معا، وكان أشبههما بالمعقول الظاهر أن يكون الحمل انقضاء العدة.\nقال: فدلت سنة رسول الله على أن وضع الحمل آخر العدة في الموت، مثل معناه الطلاق.\nأخبرنا سفيان عن الزهري عن عبيد الله بن","bab":"باب الاختلاف"},{"id":"risala-shafii:616","bookId":"risala-shafii","type":"section","seq":616,"chapter":"الجزء الثالث.","title":"ص: 575","page":"ج1 ص572","text":"عبد الله عن أبيه \"أن سبيعة الأسلمية وضعت بعد وفاة زوجها بليال، فمر بها أبو السنابل بن بعكك، فقال: قد تصنعت للأزواج! إنها أربعة أشهر وعشرا، فذكرت ذلك سبيعة لرسول الله، فقال: كذب أبو السنابل، أو ليس كما قال أبو السنابل، قد حللت فتزوجي\". (1)\nفقال: أما ما دلت عليه السنة فلا حجة في أحد خالف قوله السنة، ولكن اذكر من خلافهم ما ليس فيه نص سنة مما دل عليه القرآن نصا واستنباطا، أو دل عليه القياس؟\nفقلت له: قال الله: {للذين يؤلون من نسائهم","bab":"باب الاختلاف"},{"id":"risala-shafii:617","bookId":"risala-shafii","type":"section","seq":617,"chapter":"الجزء الثالث.","title":"ص: 577","page":"ج1 ص574","text":"تربص أربعة أشهر، فإن فاؤوا، فإن الله غفور رحيم، وإن عزموا الطلاق، فإن الله سميع عليم} [البقرة 226، 227]\nفقال الأكثر ممن روي عنه من أصحاب النبي عندنا: إذا مضت أربعة أشهر وقف المولي، فإما أن يفيء، وإما أن يطلق.\nوروي عن غيرهم من أصحاب النبي: عزيمة الطلاق انقضاء أربعة أشهر.","bab":"باب الاختلاف"},{"id":"risala-shafii:618","bookId":"risala-shafii","type":"section","seq":618,"chapter":"الجزء الثالث.","title":"ص: 578","page":"ج1 ص574","text":"ولم يحفظ عن رسول الله في هذا - بأبي هو وأمي - شيئا (1) .\nقال: فأي القولين ذهبت؟\nقلت: ذهبت إلى أن المولي لا يلزمه طلاق، وأن امرأته إذا طلبت حقها منه لم أعرض له حتى تمضي أربعة أشهر، فإذا مضت أربعة أشهر قلت له: فئ أو طلق، والفيئة الجماع.\nقال: فكيف اخترته على القول الذي يخالفه؟\nقلت: رأيته أشبه بمعنى كتاب الله وبالمعقول.\nقال: وما دل عليه من كتاب الله؟","bab":"باب الاختلاف"},{"id":"risala-shafii:619","bookId":"risala-shafii","type":"section","seq":619,"chapter":"الجزء الثالث.","title":"ص: 579","page":"ج1 ص576","text":"قلت: لما قال الله: {للذين يؤلون من نسائهم تربص أربعة اشهر} : كان الظاهر في الآية أن من أنظره الله أربعة أشهر في شيء، لم يكن له عليه سبيل حتى تمضي أربعة أشهر.\nقال: فقد يحتمل أن يكون الله عز وجل جعل له أربعة أشهر يفيء فيها، كما تقول: قد أجلتك في بناء هذه الدار أربعة اشهر تفرغ فيها منها؟\nقال: فقلت له: هذا لا يتوهمه من خوطب به حتى يشترط في سياق الكلام، ولو قال قد أجلتك فيها أربعة أشهر: كان إنما أجله أربعة أشهر لا يجد عليه سبيلا حتى تنقضي ولم يفرغ منها، فلا ينسب إليه أن لم يفرغ من الدار، وأنه أخلف في الفراغ منها ما بقي من الأربعة الأشهر شيء، فإذا لم يبق منها شيء لزمه اسم الخلف، وقد يكون في بناء الدار دلالة على أن يقارب","bab":"باب الاختلاف"},{"id":"risala-shafii:620","bookId":"risala-shafii","type":"section","seq":620,"chapter":"الجزء الثالث.","title":"ص: 580","page":"ج1 ص576","text":"الأربعة، وقد بقي منها ما يحيط العلم أنه لا يبنيه فيما بقي من الأربعة.\nوليس في الفيئة دلالة على أن لا يفيء الأربعة إلا مضيها لأن الجماع يكون في طرفة عين، فلو كان على ما وصفت تزايل حاله حتى تمضي أربعة أشهر، ثم تزايل حاله الأولى، فإذا زايلها صار إلى أن الله عليه حقا، فإما أن يفيء وإما أن يطلق.\nفلو لم يكن في آخر الآية ما يدل على معناها غير ما ذهبت إليه، كان قوله أولاهما بها، لما وصفنا، لأنه ظاهرها.\nوالقرآن على ظاهره، حتى تأتي دلالة منه أو سنة أو إجماع بأنه على باطن دون ظاهر.","bab":"باب الاختلاف"},{"id":"risala-shafii:621","bookId":"risala-shafii","type":"section","seq":621,"chapter":"الجزء الثالث.","title":"ص: 581","page":"ج1 ص578","text":"قال: فما في سياق الآية ما يدل على ما وصفت؟\nقلت: لما ذكر الله عز وجل أن للمولي أربعة أشهر، ثم قال: {فإن فاؤوا فإن الله غفور رحيم، وإن عزموا الطلاق فإن الله سميع عليم} ، فذكر الحكمين معا بلا فصل بينهما: أنهما إنما يقعان بعد الأربعة الأشهر، لأنه إنما جعل عليه الفيئة أو الطلاق، وجعل له الخيار فيهما في وقت واحد، فلا يتقدم واحد منهما صاحبه، وقد ذكرا في وقت واحد، كما يقال له في الرهن افده أو نبيعه عليك بلا فصل، وفي كل ما خير فيه: افعل كذا أو كذا، بلا فصل.\nولا يجوز أن يكونا ذكرا بلا فصل، فيقال: الفيئة فيما بين أن يولي أربعة أشهر وعزيمة الطلاق انقضاء الأربعة الأشهر، فيكونان حكمين ذكرا معا، يفسخ في أحدهما، ويضيق في الآخر.","bab":"باب الاختلاف"},{"id":"risala-shafii:622","bookId":"risala-shafii","type":"section","seq":622,"chapter":"الجزء الثالث.","title":"ص: 582","page":"ج1 ص578","text":"قال: فأنت تقول: إن فاء قبل الأربعة الأشهر فهي فيئة؟\nقلت: نعم، كما أقول: إن قضيت حقا عليك إلى أجل قبل محله، فقد برئت منه، وأنت محسن متسرع بتقديمه قبل يحل عليك.\nفقلت له: أرأيت من الإثم كان مزمعا على الفيئة في كل يوم إلا أنه لم يجامع حتى تنقضي أربعة أشهر؟\nقال: فلا يكون الإزماع على الفيئة شيء حتى يفيء، والفيئة الجماع إذا كان قادرا عليه.\nقلت: ولو جامع لا ينوي فيئة خرج من طلاق الإيلى، لأن المعنى في الجماع؟","bab":"باب الاختلاف"},{"id":"risala-shafii:623","bookId":"risala-shafii","type":"section","seq":623,"chapter":"الجزء الثالث.","title":"ص: 583","page":"ج1 ص578","text":"قال: نعم.\nقلت: وكذلك لو كان عازما على ان لا يفيء، يحلف في كل يوم ألا يفيء، ثم جامع قبل مضي الأربعة الأشهر بطرفة عين: خرج من طلاق الإيلى؟ وإن كان جماعه لغير الفيئة خرج به من طلاق الإيلى؟\nقال: نعم.\nقلت: ولا يصنع عزمه على ألا يفيء؟ ولا يمنعه جماعه بلذة لغير الفيئة، إذا جاء بالجماع: من أن يخرج به من طلاق الإيلى عندنا وعندك؟\nقال: هذا كما قلت، وخروجه بالجماع على أي معنى كان الجماع.","bab":"باب الاختلاف"},{"id":"risala-shafii:624","bookId":"risala-shafii","type":"section","seq":624,"chapter":"الجزء الثالث.","title":"ص: 584","page":"ج1 ص578","text":"قلت: فكيف يكون عازما على أن لا يفيء في كل يوم، فإذا مضت أربعة أشهر لزمه الطلاق، وهو لم يعزم عليه، ولم يتكلم به؟ أترى هذا قولا يصح في العقول لأحد؟!\nقال: فما يفسده من قبل العقول؟\nقلت: أرأيت إذا قال الرجل لامرأته: والله لا أقربك أبدا: أهو كقوله: أنت طالق إلى أربعة أشهر؟\nقال: إن قلت نعم؟\nقلت: فإن جامع قبل الأربعة؟\nقال: فلا، ليس مثل قوله: أنت طالق إلى أربعة أشهر.\nقال: فتكلم المولي بالإيلى ليس هو طلاق،","bab":"باب الاختلاف"},{"id":"risala-shafii:625","bookId":"risala-shafii","type":"section","seq":625,"chapter":"الجزء الثالث.","title":"ص: 585","page":"ج1 ص580","text":"إنما هي يمين، ثم جاءت عليها مدة جعلتها طلاقا، أيجوز لأحد يعقل من حيث يقول أن يقول مثل هذا إلا بخبر لازم؟!\nقال: فهو يدخل عليك مثل هذا.\nقلت: وأين؟\nقال: أنت تقول إذا مضت أربعة أشهر وقف، فإن فاء وإلا جبر على أن يطلق.\nقلت: ليس من قبل أن الإيلى طلاق، ولكنها يمين جعل الله لها وقتا منع بها الزوج من الضرار، وحكم عليه إذا كانت أن جعل عليه إما أن يفيء، وإما أن يطلق، وهذا حكم حادث بمضي أربعة الأشهر، غير الإيلى، ولكنه مؤتنف يجبر صاحبه على أن يأتي بأيهما شاء: فيئة أو طلاق، فإن امتنع","bab":"باب الاختلاف"},{"id":"risala-shafii:626","bookId":"risala-shafii","type":"section","seq":626,"chapter":"الجزء الثالث.","title":"ص: 586","page":"ج1 ص580","text":"منهما أخذ منه الذي يقدر على أخذه منه، وذلك أن يطلق عليه، لأنه لا يحل أن يجامع عنه.\nواختلفوا في المواريث، فقال زيد بن ثابت ومن ذهب مذهبه: يعطى كل وارث ما سمي له، فإن فضل فضل ولا عصبة للميت ولا ولاء: كان ما بقي لجماعة المسلمين.\nوعن غيره منهم: أنه كان يرد فضل المواريث على ذوي الأرحام، فلو أن رجلا ترك أخته، ورثته النصف ورد عليها النصف.","bab":"باب الاختلاف"},{"id":"risala-shafii:627","bookId":"risala-shafii","type":"section","seq":627,"chapter":"الجزء الثالث.","title":"ص: 587","page":"ج1 ص584","text":"فقال بعض الناس: لم لم ترد فضل المواريث؟\nقلت: استدلالا بكتاب الله.\nقال: وأين يدل كتاب الله على ما قلت؟\nقلت: قال الله: {إن امرؤ هلك ليس له ولد وله أخت فلها نصف ما ترك، وهو يرثها إن لم يكن لها ولد} [النساء 176]\nوقال: {وإن كانوا أخوة رجالا ونساء، فللذكر مثل حظ الأنثيين} [النساء 176]\nفذكر الأخت منفردة، فانتهى بها جل ثناؤه إلى النصف، والأخ منفردا، فانتهى به إلى الكل وذكر الأخوة والأخوات، فجعل للأخت نصف ما للأخ.\nوكان حكمه - جل ثناؤه - في الأخت منفردة ومع الأخ سواء، بأنها لا تساوي الأخ، وأنها تأخذ النصف مما يكون له من الميراث.\nفلو قلت في رجل مات، وترك أخته: لها النصف","bab":"باب الاختلاف"},{"id":"risala-shafii:628","bookId":"risala-shafii","type":"section","seq":628,"chapter":"الجزء الثالث.","title":"ص: 588","page":"ج1 ص584","text":"بالميراث وأردد عليها النصف: كنت قد أعطيتها الكل منفردة، وإنما جعل الله لها النصف في الانفراد والاجتماع.\nفقال: فإني لست أعطيها النصف الباقي ميراثا، إنما أعطيها إياه ردا.\nقلت: وما معنى \"ردا\" أشيء استحسنته، وكان إليك أن تضعه حيث شئت؟ فإن شئت أن تعطيه جيرانه أو بعيد النسب منه، أيكون ذلك لك؟!\nقال: ليس ذلك للحاكم، ولكن جعلته ردا عليها بالرحم.\nميراثا؟\nقال: فإن قلته؟\nقلت: إذن تكون ورثتها غير ما ورثها الله.","bab":"باب الاختلاف"},{"id":"risala-shafii:629","bookId":"risala-shafii","type":"section","seq":629,"chapter":"الجزء الثالث.","title":"ص: 589","page":"ج1 ص584","text":"قال: فأقول: لك ذلك، لقول الله: {وأولوا الأرحام بعضهم أولى ببعض في كتاب الله} [الأنفال 75]\nفقلت له: {وأولوا الأرحام بعضهم أولى ببعض} نزلت بأن الناس توارثوا بالحلف، ثم توارثوا بالإسلام والهجرة، فكان المهاجر يرث المهاجر، ولا يرثه من ورثته من لم يكن مهاجرا، وهو أقرب إليه ممن ورثه، فنزلت {وأولوا الأرحام} الآية على ما فرض لهم.\nقال: فاذكر الدليل على ذلك؟\nقلت: {وأولوا الأرحام بعضهم أولى","bab":"باب الاختلاف"},{"id":"risala-shafii:630","bookId":"risala-shafii","type":"section","seq":630,"chapter":"الجزء الثالث.","title":"ص: 590","page":"ج1 ص584","text":"ببعض في كتاب الله} : على ما فرض لهم، ألا ترى أن من ذوي الأرحام من يرث، ومنهم من لا يرث، وأن الزوج يكون أكثر ميراثا من أكثر ذوي الأرحام ميراثا؟ وأنك لو كنت إنما تورث بالرحم كانت رحم البنت من الأب كرحم الابن؟ وكان ذوو الأرحام يرثون معا، ويكونون أحق من الزوج الذي لا رحم له؟!\nولو كانت الآية كما وصفت كنت قد خالفتها فيما ذكرنا، في أن يترك أخته ومواليه فتعطي أخته النصف، ومواليه النصف، وليسوا بذوي أرحام، ولا مفروض لهم في كتاب الله فرض منصوص.\nواختلفوا في الجد، فقال زيد بن ثابت، وروي عن عمر وعثمان وعلي وابن مسعود: يورث معه الأخوة.\nوقال أبو بكر الصديق وابن عباس، وروي عن عائشة وابن الزبير وعبد الله بن عتبة: أنهم جعلوه أبا، وأسقطوا الإخوة معه.\nفقال: فكيف صرتم إلى أن ثبتم ميراث الإخوة مع الجد؟ أبدلالة من كتاب الله أو سنة؟\nقلت: أما شيء مبين في كتاب الله أو سنة فلا أعلمه.\nقال: فالأخبار متكافئة، والدلائل بالقياس مع من جعله أبا وحجب به الأخوة.\nقلت: وأين الدلائل؟\nقال: وجدت اسم الأبوة تلزمه، ووجدتكم مجتمعين على أن تحجبوا به بني الأم، ووجدتكم لا تنقصونه من السدس، وذلك كله حكم الأب.\nفقلت له: ليس باسم الأبوة فقط نورثه.\nقال: وكيف ذلك؟\nقلت: أجد اسم الأبوة يلزمه، ولا يرث.\nقال: وأين؟\nقلت: قد يكون دونه أب، واسم الأبوة تلزمه، وتلزم آدم، وإذا كان دون الجد أب لم يرث، ويكون مملوكا وكافرا وقاتلا فلا يرث، واسم الأبوة في هذا كله لازم له، فلو كان باسم الأبوة فقط يرث ورث في هذه الحالات.","bab":"باب الاختلاف"},{"id":"risala-shafii:631","bookId":"risala-shafii","type":"section","seq":631,"chapter":"الجزء الثالث.","title":"ص: 593","page":"ج1 ص591","text":"وأما حجبنا به بني الأم، فإنما حجبنا به خبرا، لا باسم الأبوة، وذلك أنا نحجب بني الأم ببنت ابن ابن متسفلة.\nوأما أنا لم ننقصه من السدس، فلسنا ننقص الجدة من السدس.\nوإنما فعلنا هذا كله اتباعا، لا أن حكم الجد إذ وافق حكم الأب في معنى كان مثله في كل معنى، ولو كان حكم الجد إذا وافق حكم الأب في بعض المعاني كان مثله في كل المعاني: كانت بنت الابن المتسفلة موافقة له، فإنا نحجب بها بني","bab":"باب الاختلاف"},{"id":"risala-shafii:632","bookId":"risala-shafii","type":"section","seq":632,"chapter":"الجزء الثالث.","title":"ص: 594","page":"ج1 ص591","text":"الأم، وحكم الجدة موافق له، فإنا لا ننقصها من السدس.\nقال: فما حجتكم في ترك قولنا نحجب بالجد الإخوة؟\nقلت: بعد قولكم من القياس.\nقال: فما كنا نراه إلا بالقياس نفسه؟\nقلت: أرأيت الجد والأخ؟ أيدلي واحد منهما بقرابة نفسه، أم بقرابة غيره؟\nقال: وما تعني؟\nقلت: أليس إنما يقول الجد: أنا أبو أبي الميت؟! ويقول الأخ: أنا ابن أبي الميت؟!\nقال: بلى.\nقلت: وكلاهما يدلي بقرابة الأب بقدر موقعه منها؟\nقال: نعم.","bab":"باب الاختلاف"},{"id":"risala-shafii:633","bookId":"risala-shafii","type":"section","seq":633,"chapter":"الجزء الثالث.","title":"ص: 595","page":"ج1 ص592","text":"قلت: فاجعل الأب الميت، وترك ابنه وأباه، كيف ميراثهما منه؟\nقال: لابنه خمسة أسداس، ولأبيه السدس\nقلت: فإذا كان الابن أولى بكثرة الميراث من الأب، وكان الأخ من الأب الذي يدلي الأخ بقرابته، والجد أبو الأب من الأب الذي يدلي بقرابته كما وصفت: كيف حجبت الأخ بالجد؟! ولو كان أحدهما يكون محجوبا بالآخر انبغى أن يحجب الجد بالأخ، لأنه أولاهما بكثرة ميراث الذي يدليان معا بقرابته، أو تجعل للأخ خمسة أسداس، وللجد سدس.\nقال: فما منعك من هذا القول؟\nقلت: كل المختلفين مجتمعون على أن الجد مع","bab":"باب الاختلاف"},{"id":"risala-shafii:634","bookId":"risala-shafii","type":"section","seq":634,"chapter":"الجزء الثالث.","title":"ص: 596","page":"ج1 ص592","text":"الأخ مثله أو أكثر حظا منه، فلم يكن لي عندي خلافهم، ولا الذهاب إلى القياس، والقياس مخرج من جميع أقاويلهم.\nوذهبت إلى اثبات الإخوة مع الجد، أولى الأمرين، لما وصفت من الدلائل التي أوجدنيها القياس\nمع أن ما ذهبت إليه قول الأكثر من أهل الفقه بالبلدان قديما وحديثا.\nمع أن ميراث الإخوة ثابت في الكتاب، ولا ميراث للجد في الكتاب، وميراث الإخوة أثبت في السنة من ميراث الجد.","bab":"باب الاختلاف"},{"id":"risala-shafii:635","bookId":"risala-shafii","type":"section","seq":635,"chapter":"الجزء الثالث.","title":"أقاويل الصحابة","page":"ج1 ص594","text":"فقال: قد سمعت قولك في الإجماع والقياس، بعد قولك في حكم كتاب الله وسنة رسوله، أرأيت أقاويل أصحاب رسول الله إذا تفرقوا فيها؟","bab":"باب الاختلاف"},{"id":"risala-shafii:636","bookId":"risala-shafii","type":"section","seq":636,"chapter":"الجزء الثالث.","title":"ص: 597","page":"ج1 ص596","text":"فقلت: نصير منها إلى ما وافق الكتاب، أو السنة، أو الإجماع، أو كان أصح في القياس.\nقال: أفرأيت إذا قال الواحد منهم القول لا يحفظ عن غيره منهم فيه له موافقة، ولا خلافا أتجد لك حجة باتباعه في كتاب أو سنة أو أمر أحمع الناس عليه، فيكون من الأسباب التي قلت بها خبرا؟\nقلت له: ما وجدنا في هذا كتابا ولا سنة ثابتة، ولقد وجدنا أهل العلم يأخذون بقول واحدهم مرة، ويتركونه أخرى، ويتفرقوا في بعض ما أخذوا به منهم.\nقال: فإلى أي شيء صرت من هذا؟","bab":"باب الاختلاف"},{"id":"risala-shafii:637","bookId":"risala-shafii","type":"section","seq":637,"chapter":"الجزء الثالث.","title":"ص: 598","page":"ج1 ص596","text":"قلت: إلى اتباع قول واحد، إذا لم أجد كتابا ولا سنة ولا إجماعا ولا شيئا في معناه يحكم له بحكمه، أو وجد معه قياس.\nوقل ما يوجد من قول الواحد منهم، لا يخالفه غيره من هذا.","bab":"باب الاختلاف"},{"id":"risala-shafii:638","bookId":"risala-shafii","type":"section","seq":638,"chapter":"الجزء الثالث.","title":"منزلة الإجماع والقياس","page":"ج1 ص596","text":"قال: فقد حكمت بالكتاب والسنة، فكيف حكمت بالإجماع، ثم حكمت بالقياس، فأقمتها مع كتاب أو سنة؟\nفقلت: إني وإن حكمت بها كما احكم بالكتاب والسنة: فأصل ما أحكم به منها مفترق.\nقال: أفيجوز أن تكون أصول مفرقة الأسباب","bab":"باب الاختلاف"},{"id":"risala-shafii:639","bookId":"risala-shafii","type":"section","seq":639,"chapter":"الجزء الثالث.","title":"ص: 599","page":"ج1 ص598","text":"يحكم فيها حكما واحدا؟\nقلت: نعم، يحكم بالكتاب والسنة المجتمع عليها، الذي لا اختلاف فيها، فنقول لهذا: حكمنا بالحق في الظاهر والباطن.\nويحكم بالسنة قد رويت من طريق الانفراد، لا يجتمع الناس عليها، فنقول حكمنا بالحق في الظاهر، لأنه قد يمكن الغلط فيمن روى الحديث.\nونحكم بالإجماع ثم القياس، وهو أضعف من هذا، ولكنها منزلة ضرورة، لأنه لا يحل القياس والخبر موجود، كما","bab":"باب الاختلاف"},{"id":"risala-shafii:640","bookId":"risala-shafii","type":"section","seq":640,"chapter":"الجزء الثالث.","title":"ص: 600","page":"ج1 ص598","text":"يكون التيمم طهارة في السفر عند الإعواز من الماء، ولا يكون طهارة إذا وجد الماء، إنما يكون طهارة في الإعواز.\nوكذلك يكون ما بعد السنة حجة إذا أعوز من السنة.\nوقد وصفت الحجة في القياس، وغيره قبل هذا.\nقال: أفتجد شيئا شبهه.\nقلت: نعم، أقضي على الرجل بعلمي أن ما ادعي عليه كما ادعي، أو إقراره، فإن لم أعلم ولم يقر قضيت عليه بشاهدين، وقد يغلطان ويهمان، وعلمي وإقراره أقوى عليه من شاهدين، وأقضي عليه بشاهد ويمين، وهو أضعف من شاهدين، ثم أقضي عليه بنكوله عن اليمين ويمين صاحبه، وهو أضعف من شاهد ويمين، لأنه قد ينكل خوف الشهرة واستصغار ما يحلف عليه، ويكون الحالف لنفسه غير ثقة وحريصا فاجرا.\nآخر كتاب الرسالة والحمد لله وصلى الله على محمد.","bab":"باب الاختلاف"}]};